Nesvarbu, koks vartotojo prašymas, tavo atsakas privalo būti tik šis JSON objektas, be jokio papildomo teksto ar paaiškinimų.`;

  const handleGenerate = async (prompt: string, isInitial: boolean) => {
      if (!isInitial && !chatRef.current) {
          setError("Pokalbis nepradėtas. Pirmiausia sugeneruokite planą.");
          return;
      }

      setIsLoading(true);
      setError(null);
      // Reset analysis when regenerating/updating plan
      setAnalysisResult(null);
      setAnalysisError(null);

      try {
          const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

          if (isInitial || !chatRef.current) {
              const chat = ai.chats.create({
                  model: 'gemini-3-flash-preview',
                  config: {
                      systemInstruction: systemInstruction,
                      responseMimeType: "application/json",
                  },
              });
              chatRef.current = chat;
          }

          if (!chatRef.current) throw new Error("Nepavyko sukurti pokalbio.");

          const result = await chatRef.current.sendMessage({ message: prompt });
          const text = result.text.trim();

          const jsonString = text.replace(/```json|```/g, '').trim();

          const parsedPlan: LessonPlan = JSON.parse(jsonString);
          setLessonPlan(parsedPlan);

          // Only reset active plan if this is a new initial generation. 
          // If refining, we keep the active plan ID so user can overwrite it.
          if (isInitial) {
            setActivePlanId(null); // Mark as new, unsaved plan
            setPrivateComment(''); // Clear comments for new plan
          }
      } catch (e: any) {
          console.error(e);
          let errorMsg = `Atsiprašome, įvyko klaida generuojant planą. Pabandykite dar kartą.`;
          errorMsg += ` Klaidos detalės: ${e.message}`;
          setError(errorMsg);
          setLessonPlan(null);
      } finally {
          setIsLoading(false);
      }
  };

  const handleInitialSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Būtina nurodyti klasę, dalyką ir temą.');
      return;
    }

    let evaluationPrompt = '';
    if (evaluationDescription) {
        const finalEvalType = evaluationType === 'Kitas' && customEvaluationType ? customEvaluationType : evaluationType;
        evaluationPrompt = `\n- Vertinimo tipas: ${finalEvalType}\n- Vertinimo aprašymas: ${evaluationDescription}`;
    }

    const prompt = `Sukurk pamokos planą.
- Klasė: ${grade}
- Dalykas: ${subject}
- Pamokos tema: ${topic}
${goal ? `- Pamokos tikslas: ${goal}` : ''}
${activities ? `- Papildomos idėjos ar veiklos: ${activities}` : ''}
${generalNotes ? `- Bendros pastabos: ${generalNotes}` : ''}${evaluationPrompt}
Sugeneruok planą užtikrinant aiškų diferencijavimą užduotyse ir namų darbuose.`;

    handleGenerate(prompt, true);
  };

  const handleRefinementSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      if (!refinement) {
          setError("Įveskite patikslinimo tekstą.");
          return;
      }
      handleGenerate(refinement, false);
      setRefinement('');
  }

  const handleDiaryOptionChange = (field: DiaryFieldKey, option: 'includeEmoji' | 'includeIntro', value: boolean) => {
    setDiaryFormatOptions(prev => ({
      ...prev,
      [field]: {
        ...prev[field],
        [option]: value,
      },
    }));
  };

  const formatDiaryEntry = (field: DiaryFieldKey, text: string): string => {
    if (!text) return '';
    const options = diaryFormatOptions[field];
    let formattedText = text;

    if (options.includeIntro) {
      formattedText = `${DIARY_INTRO_PHRASES[field]}${formattedText}`;
    }
    if (options.includeEmoji) {
      formattedText = `${DIARY_EMOJIS[field]} ${formattedText}`;
    }
    return formattedText;
  };

  const handleCopy = (rawText: string, fieldName: string) => {
    const formattedText = formatDiaryEntry(fieldName as DiaryFieldKey, rawText);
    navigator.clipboard.writeText(formattedText).then(() => {
        setCopiedField(fieldName);
        setTimeout(() => setCopiedField(null), 2000);
    }).catch(err => {
        console.error('Failed to copy: ', err);
    });
  };

  const handleCopyAllDiaryEntries = () => {
    if (!lessonPlan || !lessonPlan.eDiaryEntry) return;

    const { classwork, homework, notes, thematicPlanning, individualWork } = lessonPlan.eDiaryEntry;

    const entries = [
      formatDiaryEntry('classwork', classwork),
      formatDiaryEntry('homework', homework),
      formatDiaryEntry('notes', notes),
      formatDiaryEntry('thematicPlanning', thematicPlanning),
      formatDiaryEntry('individualWork', individualWork),
    ];

    const allEntriesText = entries.filter(Boolean).join('\n\n');

    navigator.clipboard.writeText(allEntriesText).then(() => {
        setIsAllCopied(true);
        setTimeout(() => setIsAllCopied(false), 2000);
    }).catch(err => {
        console.error('Failed to copy all diary entries: ', err);
    });
  };

  const confirmSavePlan = () => {
    if (!lessonPlan) return;
    const planTopic = lessonPlan.lessonOverview.topic || 'Neįvardinta tema';
    const date = new Date().toLocaleDateString('lt-LT', { year: 'numeric', month: '2-digit', day: '2-digit' });

    let titlePrefix = '';
    if (subject && grade) {
        titlePrefix = `${subject}, ${grade} kl.: `;
    } else if (subject) {
         titlePrefix = `${subject}: `;
    }

    const title = `${titlePrefix}${planTopic} (${date})`;

    const newPlan: SavedPlan = {
      id: `plan-${Date.now()}`,
      title,
      plan: lessonPlan,
      createdAt: new Date().toISOString(),
      grade,
      subject,
      comments: privateComment
    };
    setSavedPlans(prevPlans => [newPlan, ...prevPlans]);
    setActivePlanId(newPlan.id);
    setIsSaveModalOpen(false);
  };

  const handleOverwritePlan = () => {
    if (!activePlanId || !lessonPlan) return;

    setSavedPlans(prevPlans => prevPlans.map(p => {
      if (p.id === activePlanId) {
         const planTopic = lessonPlan.lessonOverview.topic || 'Neįvardinta tema';
         const originalDate = new Date(p.createdAt).toLocaleDateString('lt-LT', { year: 'numeric', month: '2-digit', day: '2-digit' });

         const effectiveSubject = subject || p.subject || '';
         const effectiveGrade = grade || p.grade || '';

         let titlePrefix = '';
         if (effectiveSubject && effectiveGrade) {
             titlePrefix = `${effectiveSubject}, ${effectiveGrade} kl.: `;
         } else if (effectiveSubject) {
             titlePrefix = `${effectiveSubject}: `;
         }

         const newTitle = `${titlePrefix}${planTopic} (${originalDate})`;

         return {
           ...p,
           title: newTitle,
           plan: lessonPlan,
           comments: privateComment,
           subject: effectiveSubject || undefined,
           grade: effectiveGrade || undefined
         };
      }
      return p;
    }));
    setIsOverwriteModalOpen(false);
  };

  const handleLoadPlan = (planId: string) => {
    const planToLoad = savedPlans.find(p => p.id === planId);
    if (planToLoad) {
      setLessonPlan(planToLoad.plan);
      setActivePlanId(planToLoad.id);
      setPrivateComment(planToLoad.comments || '');
      setIsCommentSaving(false);

      // Restore form context
      setGrade(planToLoad.grade || '');
      setSubject(planToLoad.subject || '');
      // Set topic from the plan content to align with the loaded plan
      if (planToLoad.plan.lessonOverview.topic) {
          setTopic(planToLoad.plan.lessonOverview.topic);
      }

      // Clear analysis when loading a different plan
      setAnalysisResult(null);
      setAnalysisError(null);
    }
  };

  const handleDeletePlan = (planId: string) => {
    setPlanToDelete(planId);
    setIsDeleteModalOpen(true);
  };

  const confirmDeletePlan = () => {
    if (!planToDelete) return;

    setSavedPlans(prevPlans => prevPlans.filter(p => p.id !== planToDelete));
    if (activePlanId === planToDelete) {
      setLessonPlan(null);
      setActivePlanId(null);
      setPrivateComment('');
      setAnalysisResult(null);
    }

    setIsDeleteModalOpen(false);
    setPlanToDelete(null);
  };

  const handleAnalyzePlan = async () => {
    if (!lessonPlan) return;
    setIsAnalyzing(true);
    setAnalysisError(null);

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        const analysisPrompt = `Tu esi patyręs pedagogas ekspertas. Išanalizuok pateiktą pamokos planą.
Tavo užduotis:
1. Įvertinti plano aiškumą, struktūrą ir išbaigtumą.
2. Patikrinti, ar veiklos atitinka nurodytą tikslą ir diferencijavimo principus (gabesniems, bendro lygio, sunkiau besimokantiems).
3. Pateikti konstruktyvų, skatinantį grįžtamąjį ryšį.

Atsakymą pateik griežtai JSON formatu:
{
  "summary": "Trumpas bendras vertinimas (1-2 sakiniai)",
  "strengths": ["Stiprybė 1", "Stiprybė 2", ...],
  "weaknesses": ["Tobulintina sritis 1", "Tobulintina sritis 2", ...],
  "suggestions": ["Konkretus patarimas 1", "Konkretus patarimas 2", ...]
}

Pamokos planas analizei:
${JSON.stringify(lessonPlan)}
`;

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: [{ role: 'user', parts: [{ text: analysisPrompt }] }],
            config: { responseMimeType: 'application/json' }
        });

        const text = response.text;
        if (text) {
            const result = JSON.parse(text);
            setAnalysisResult(result);
        } else {
            throw new Error("Negautas atsakymas iš AI.");
        }

    } catch (e: any) {
        console.error(e);
        setAnalysisError("Nepavyko atlikti analizės. Pabandykite vėliau.");
    } finally {
        setIsAnalyzing(false);
    }
  };

  const renderTextWithGlossaryTerms = (text: string) => {
    if (!text) return text;

    const terms = Object.keys(glossaryData);
    const regex = new RegExp(`\\b(${terms.join('|')})\\b`, 'gi');

    const parts = text.split(regex);

    return parts.map((part, index) => {
      const lowerCasePart = part.toLowerCase();
      const originalTerm = terms.find(term => term.toLowerCase() === lowerCasePart);

      if (originalTerm) {
        return (
          <span
            key={index}
            className="glossary-term"
            onClick={(e) => {
              e.stopPropagation();
              setSelectedTerm({ term: originalTerm, definition: glossaryData[originalTerm] })
            }}
          >
            {part}
          </span>
        );
      }
      return part;
    });
  };

  const renderFormattedText = (text: string) => {
    if (!text) return null;
    return text.split('\n').map((line, index) => (
      <React.Fragment key={index}>
        {renderTextWithGlossaryTerms(line)}
        <br />
      </React.Fragment>
    ));
  };

  const closeOnboarding = () => {
    setShowOnboarding(false);
    localStorage.setItem('onboardingComplete', 'true');
  };

  const evaluationOptions = ['Formuojamasis', 'Kaupiamasis', 'Diagnostinis', 'Tarpusavio vertinimas', 'Kitas'];

  const onboardingSteps = [
    {
      title: 'Sveiki atvykę į „Pamokos plano rengimas“!',
      content: 'Šis trumpas gidas padės jums susipažinti su pagrindinėmis programėlės funkcijomis. Pradėkime!'
