                <div className="modal-actions">
                    <button onClick={() => setIsOverwriteModalOpen(false)} className="button-secondary">Atšaukti</button>
                    <button onClick={handleOverwritePlan} className="button-primary">Perrašyti</button>
                </div>
            </div>
        </div>
      )}
      {isSaveModalOpen && (
        <div className="modal-overlay" onClick={() => setIsSaveModalOpen(false)}>
