        setShowOnboarding(true);
    }

    // Load saved plans from local storage
    try {
        const storedPlans = localStorage.getItem('savedLessonPlans');
        if (storedPlans) {
            setSavedPlans(JSON.parse(storedPlans));
        }
    } catch (error) {
        console.error("Nepavyko įkelti planų iš vietinės saugyklos:", error);
    }
  }, []);

  useEffect(() => {
    // Save plans to local storage whenever they change
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (error) {
      console.error("Nepavyko išsaugoti planų vietinėje saugyloje:", error);
    }
  }, [savedPlans]);

  useEffect(() => {
    if (!activePlanId) {
        return; // Don't save if no plan is active
    }

    // Indicate that saving is pending/in-progress
    setIsCommentSaving(true);

    // Clear previous timeout
    if (commentSaveTimeoutRef.current) {
        clearTimeout(commentSaveTimeoutRef.current);
    }

    // Set a new timeout to save after a delay
    commentSaveTimeoutRef.current = window.setTimeout(() => {
        setSavedPlans(prevPlans => {
            const planIndex = prevPlans.findIndex(p => p.id === activePlanId);
            if (planIndex === -1) {
                return prevPlans; // Plan not found, do nothing
            }

            const currentPlan = prevPlans[planIndex];
            // Avoid unnecessary state update if comments haven't changed
            if (currentPlan.comments === privateComment || (!currentPlan.comments && privateComment === '')) {
                return prevPlans;
            }

            const updatedPlan = { ...currentPlan, comments: privateComment };
            const newPlans = [...prevPlans];
            newPlans[planIndex] = updatedPlan;
            return newPlans;
        });
        setIsCommentSaving(false);
    }, 500); // 500ms debounce delay

    // Cleanup on unmount or when dependencies change
    return () => {
        if (commentSaveTimeoutRef.current) {
            clearTimeout(commentSaveTimeoutRef.current);
        }
    };
  }, [privateComment, activePlanId, setSavedPlans]);


