  const handleAnalyzePlan = async () => {
    if (!lessonPlan) return;
    setIsAnalyzing(true);
    setAnalysisError(null);

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        const analysisPrompt = `Tu esi patyręs pedagogas ekspertas. Išanalizuok pateiktą pamokos planą.
Tavo užduotis:
1. Įvertinti plano aiškumą, struktūrą ir išbaigtumą.
2. Patikrinti, ar veiklos atitinka nurodytą tikslą ir diferencijavimo principus (gabesniems, bendro lygio, sunkiau besimokantiems).
3. Pateikti konstruktyvų, skatinantį grįžtamąjį ryšį.

Atsakymą pateik griežtai JSON formatu:
{
  "summary": "Trumpas bendras vertinimas (1-2 sakiniai)",
  "strengths": ["Stiprybė 1", "Stiprybė 2", ...],
  "weaknesses": ["Tobulintina sritis 1", "Tobulintina sritis 2", ...],
  "suggestions": ["Konkretus patarimas 1", "Konkretus patarimas 2", ...]
}

Pamokos planas analizei:
${JSON.stringify(lessonPlan)}
`;

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: [{ role: 'user', parts: [{ text: analysisPrompt }] }],
            config: { responseMimeType: 'application/json' }
        });

        const text = response.text;
        if (text) {
            const result = JSON.parse(text);
            setAnalysisResult(result);
        } else {
            throw new Error("Negautas atsakymas iš AI.");
        }

    } catch (e: any) {
        console.error(e);
        setAnalysisError("Nepavyko atlikti analizės. Pabandykite vėliau.");
    } finally {
        setIsAnalyzing(false);
    }
  };

  const renderTextWithGlossaryTerms = (text: string) => {
    if (!text) return text;

    const terms = Object.keys(glossaryData);
    const regex = new RegExp(`\\b(${terms.join('|')})\\b`, 'gi');

    const parts = text.split(regex);

    return parts.map((part, index) => {
      const lowerCasePart = part.toLowerCase();
      const originalTerm = terms.find(term => term.toLowerCase() === lowerCasePart);

      if (originalTerm) {
        return (
          <span
            key={index}
            className="glossary-term"
            onClick={(e) => {
              e.stopPropagation();
              setSelectedTerm({ term: originalTerm, definition: glossaryData[originalTerm] })
            }}
          >
            {part}
          </span>
        );
      }
      return part;
    });
  };

  const renderFormattedText = (text: string) => {
    if (!text) return null;
    return text.split('\n').map((line, index) => (
      <React.Fragment key={index}>
        {renderTextWithGlossaryTerms(line)}
        <br />
      </React.Fragment>
    ));
