                <div className="form-group">
                <div className="label-wrapper">
                    <label htmlFor="topic">Pamokos tema <span className="required">*</span></label>
                    <div className="tooltip">
                        <span className="tooltip-icon">ⓘ</span>
                        <p className="tooltip-text">Kuo konkretesnė tema, tuo geresnis planas. Pvz., 'Veiksmažodžių asmenavimas', 'Rudens peizažas'.</p>
                    </div>
                </div>
                <input type="text" id="topic" value={topic} onChange={(e) => setTopic(e.target.value)} placeholder="pvz., Trupmenų sudėtis, K. Donelaičio 'Metai'" required/>
                </div>
                <div className="form-group">
                <div className="label-wrapper">
                    <label htmlFor="goal">Pamokos tikslas ir uždaviniai (nebūtina)</label>
                    <div className="tooltip">
                        <span className="tooltip-icon">ⓘ</span>
                        <p className="tooltip-text">Nebūtina, bet padeda sukurti tikslesnį planą. Galite nurodyti, ką mokiniai išmoks arba gebės atlikti.</p>
                    </div>
                </div>
                <textarea id="goal" value={goal} onChange={(e) => setGoal(e.target.value)} placeholder="Aprašykite, ką mokiniai turėtų žinoti, suprasti ar gebėti padaryti po šios pamokos. Pvz., 'Mokiniai gebės atpažinti ir įvardinti pagrindines K. Donelaičio poemos 'Metai' temos.'"></textarea>
                </div>
                <div className="form-group">
                <div className="label-wrapper">
                    <label htmlFor="activities">Papildomos idėjos ar veiklos (nebūtina)</label>
                    <div className="tooltip">
                        <span className="tooltip-icon">ⓘ</span>
                        <p className="tooltip-text">Pateikite savo idėjų, kurias asistentas galėtų išplėtoti. Pvz., 'Darbas grupėse su plakatais', 'Debatai'.</p>
                    </div>
                </div>
                <textarea id="activities" value={activities} onChange={(e) => setActivities(e.target.value)} placeholder="Pasiūlykite metodų, žaidimų ar kitų veiklų, kurias norėtumėte įtraukti. Pvz., 'Diskusija porose apie metų laikų svarbą', 'Interaktyvi viktorina su Kahoot!'"></textarea>
                </div>
                <div className="form-group">
                <div className="label-wrapper">
                    <label htmlFor="generalNotes">Bendros pastabos mokytojui (nebūtina)</label>
                    <div className="tooltip">
                        <span className="tooltip-icon">ⓘ</span>
                        <p className="tooltip-text">Vieta Jūsų asmeniniams priminimams: reikalingos priemonės, organizaciniai klausimai ir pan.</p>
                    </div>
                </div>
                <textarea id="generalNotes" value={generalNotes} onChange={(e) => setGeneralNotes(e.target.value)} placeholder="Įrašykite bet kokius priminimus sau: reikalingos priemonės, organizaciniai klausimai ir kt. Pvz., 'Paruošti 5 lapus su užduotimis grupėms.'"></textarea>
                </div>
                <div className="form-group">
                    <div className="label-wrapper">
                        <label>Vertinimas ir įsivertinimas (nebūtina)</label>
                        <div className="tooltip">
                            <span className="tooltip-icon">ⓘ</span>
                            <p className="tooltip-text">Aprašykite, kaip vertinsite mokinius. Pvz., 'Mokiniai vertins vieni kitų darbus', 'Užduoties atlikimas vertinamas kaupiamuoju balu'.</p>
                        </div>
                    </div>
                    <div className="radio-group">
                        {evaluationOptions.map((option) => (
                            <div key={option} className="radio-option">
                                <input
                                    type="radio"
                                    id={`eval-${option}`}
                                    name="evaluationType"
                                    value={option}
                                    checked={evaluationType === option}
                                    onChange={(e) => setEvaluationType(e.target.value)}
                                />
                                <label htmlFor={`eval-${option}`}>{option}</label>
                            </div>
                        ))}
                    </div>
                    {evaluationType === 'Kitas' && (
                        <div className="form-group" style={{ marginTop: '0.75rem' }}>
                            <label htmlFor="custom-eval-type" className="sr-only">Jūsų vertinimo tipas</label>
                            <input
                                type="text"
                                id="custom-eval-type"
                                value={customEvaluationType}
                                onChange={(e) => setCustomEvaluationType(e.target.value)}
                                placeholder="Įveskite savo vertinimo tipą, pvz., savęs įsivertinimas"
                            />
                        </div>
                    )}
                    <textarea
                        id="evaluation"
                        value={evaluationDescription}
                        onChange={(e) => setEvaluationDescription(e.target.value)}
                        placeholder="Nurodykite vertinimo kriterijus ar būdus. Pvz., 'Už teisingai atliktus 3 iš 5 pratimo veiksmus mokinys gaus kaupiamąjį tašką.' arba 'Mokiniai stebės vieni kitų pristatymus ir pateiks grįžtamąjį ryšį pagal pateiktus kriterijus.'"
                        style={{ marginTop: '0.75rem' }}
                    ></textarea>
                </div>
                <button type="submit" disabled={isLoading} className="generate-button">
                {isLoading && !lessonPlan ? <div className="spinner"></div> : null}
                Pateikti pamokos aprašą
                </button>
            </form>
            <div className="saved-plans-container">
                <h3>Išsaugoti planai</h3>
                <div className="search-container">
                     <input 
                        type="text" 
                        placeholder="🔍 Ieškoti pagal pavadinimą, dalyką ar klasę..." 
                        value={searchQuery} 
                        onChange={(e) => setSearchQuery(e.target.value)} 
                        className="search-input"
                     />
                </div>
                {filteredPlans.length > 0 ? (
                <ul className="saved-plans-list">
                    {filteredPlans.map(plan => (
                    <li key={plan.id} className={plan.id === activePlanId ? 'active' : ''} onClick={() => handleLoadPlan(plan.id)}>
                        <span className="plan-title">
                        {plan.title}
                        <small>{new Date(plan.createdAt).toLocaleDateString('lt-LT')}</small>
                        </span>
                        <button onClick={(e) => { e.stopPropagation(); handleDeletePlan(plan.id); }} className="delete-button" aria-label="Ištrinti planą">✖</button>
                    </li>
                    ))}
                </ul>
                ) : (
                <p className="no-saved-plans">
                    {savedPlans.length > 0 ? "Planų nerasta pagal paiešką." : "Išsaugotų planų nėra."}
                </p>
                )}
            </div>
            </div>
        <div className="results-container">
            {isLoading && !lessonPlan && (
                <div className="loading-overlay">
                    <div className="spinner-large"></div>
                    <p>Generuojamas planas...</p>
                </div>
            )}
            {!isLoading && !lessonPlan && !error && (
                <div className="welcome-message">
                    <h2>Sveiki, mokytojau!</h2>
                    <p>Užpildykite formą ir aš padėsiu jums sukurti pamokos planą. Jūsų darbas įkvepia!</p>
                </div>
            )}
            {error && <div className="error-message">{error}</div>}
            {lessonPlan && (
                <>
                  <div className="export-container">
                    <button 
                        onClick={handleAnalyzePlan} 
                        disabled={isAnalyzing} 
                        className="analysis-button"
                    >
                        {isAnalyzing ? (
                            <>
                                <div className="spinner"></div> Analizuojama...
                            </>
                        ) : (
                            'Analizuoti planą 🔍'
                        )}
                    </button>
                    {activePlanId === null ? (
                    <button onClick={() => setIsSaveModalOpen(true)} className="save-button">
                        Išsaugoti planą 💾
                    </button>
                    ) : (
                    <button onClick={() => setIsOverwriteModalOpen(true)} className="save-button">
                        Atnaujinti planą 💾
                    </button>
                    )}
                  </div>

                  {analysisError && <div className="error-message">{analysisError}</div>}

                  {analysisResult && (
                    <div className="card analysis-card">
                        <h3>🔍 Plano analizė ir rekomendacijos</h3>
                        <p className="analysis-summary"><strong>Apibendrinimas:</strong> {analysisResult.summary}</p>

                        <div className="analysis-section">
                            <h4>✅ Stipriosios pusės</h4>
                            <ul>
                                {analysisResult.strengths.map((item, idx) => (
                                    <li key={idx}>{item}</li>
                                ))}
                            </ul>
                        </div>

                        <div className="analysis-section">
                            <h4>⚠️ Tobulintinos sritys</h4>
                            <ul>
                                {analysisResult.weaknesses.map((item, idx) => (
                                    <li key={idx}>{item}</li>
                                ))}
                            </ul>
                        </div>

                        <div className="analysis-section">
                            <h4>💡 Praktiniai patarimai</h4>
                            <ul>
                                {analysisResult.suggestions.map((item, idx) => (
                                    <li key={idx}>{item}</li>
                                ))}
                            </ul>
                        </div>
                    </div>
                  )}

                  <div className="lesson-plan" id="lesson-plan-content">
                      {lessonPlan.generalNotes && (
                        <div className="card general-notes-card">
                          <h3>📌 Bendros pastabos</h3>
                          <p>{renderFormattedText(lessonPlan.generalNotes)}</p>
                        </div>
                      )}
                      <div className="card lesson-overview-card">
                          <h3>📖 Pamokos apžvalga</h3>
                          <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                          <p><strong>Tikslas ir uždaviniai:</strong> {renderFormattedText(lessonPlan.lessonOverview.goal)}</p>
                          <p><strong>Pagrindiniai gebėjimai (pagal Bendrąsiąs Programas):</strong> {renderFormattedText(lessonPlan.lessonOverview.competencies)}</p>
                          <p><strong>Vertinimas:</strong> {renderFormattedText(lessonPlan.lessonOverview.evaluation)}</p>
                      </div>
                      <div className="card lesson-activities-card">
                          <h3>🎨 Diferencijuotos pamokos veiklos</h3>
                          <p><strong>🚀 Gabesniems mokiniams:</strong> {renderFormattedText(lessonPlan.lessonActivities.gifted)}</p>
                          <p><strong>🙂 Bendro lygio mokiniams:</strong> {renderFormattedText(lessonPlan.lessonActivities.general)}</p>
                          <p><strong>🌱 Pagalbos reikalingiems mokiniams:</strong> {renderFormattedText(lessonPlan.lessonActivities.struggling)}</p>
                          {lessonPlan.lessonActivities.itTools && (
                            <p><strong>💻 IT Įrankiai:</strong> {renderFormattedText(lessonPlan.lessonActivities.itTools)}</p>
                          )}
                      </div>
                      <div className="card homework-card">
                          <h3>📚 Diferencijuoti namų darbai</h3>
                          <p><strong>🎯 Tikslas ir sąsajos:</strong> {renderFormattedText(lessonPlan.homework.purpose)}</p>
                          <p><strong>🚀 Gabesniems mokiniams:</strong> {renderFormattedText(lessonPlan.homework.gifted)}</p>
                          <p><strong>🙂 Bendro lygio mokiniams:</strong> {renderFormattedText(lessonPlan.homework.general)}</p>
                          <p><strong>🌱 Pagalbos reikalingiems mokiniams:</strong> {renderFormattedText(lessonPlan.homework.struggling)}</p>
                      </div>
                      {lessonPlan.eDiaryEntry && (
                          <div className="card ediary-card">
                              <h3>✍️ Siūlomas įrašas el. dienynui</h3>
                              <div className="copy-all-container">
                                  <button
                                      onClick={handleCopyAllDiaryEntries}
                                      className={`copy-all-button ${isAllCopied ? 'copied' : ''}`}
                                  >
                                      {isAllCopied ? 'Viskas nukopijuota!' : 'Kopijuoti viską į el. dienyną'}
                                  </button>
                              </div>
                              <div className="diary-entry">
                                  <label>Klasės darbas:</label>
                                  <div className="diary-field">
                                      <p>{formatDiaryEntry('classwork', lessonPlan.eDiaryEntry.classwork)}</p>
                                      <button onClick={() => handleCopy(lessonPlan.eDiaryEntry.classwork, 'classwork')} className={`copy-button ${copiedField === 'classwork' ? 'copied' : ''}`}>
                                          {copiedField === 'classwork' ? 'Nukopijuota!' : 'Kopijuoti'}
                                      </button>
                                  </div>
                                  <div className="diary-options">
                                    <div className="checkbox-option-small">
                                      <input type="checkbox" id="emoji-classwork" checked={diaryFormatOptions.classwork.includeEmoji} onChange={(e) => handleDiaryOptionChange('classwork', 'includeEmoji', e.target.checked)} />
                                      <label htmlFor="emoji-classwork">Pridėti jaustuką</label>
                                    </div>
                                    <div className="checkbox-option-small">
                                      <input type="checkbox" id="intro-classwork" checked={diaryFormatOptions.classwork.includeIntro} onChange={(e) => handleDiaryOptionChange('classwork', 'includeIntro', e.target.checked)} />
                                      <label htmlFor="intro-classwork">Pridėti įžangą</label>
                                    </div>
                                  </div>
                              </div>
                              <div className="diary-entry">
                                  <label>Namų darbai:</label>
                                  <div className="diary-field">
                                      <p>{formatDiaryEntry('homework', lessonPlan.eDiaryEntry.homework)}</p>
                                      <button onClick={() => handleCopy(lessonPlan.eDiaryEntry.homework, 'homework')} className={`copy-button ${copiedField === 'homework' ? 'copied' : ''}`}>
                                          {copiedField === 'homework' ? 'Nukopijuota!' : 'Kopijuoti'}
                                      </button>
                                  </div>
                                  <div className="diary-options">
                                    <div className="checkbox-option-small">
                                      <input type="checkbox" id="emoji-homework" checked={diaryFormatOptions.homework.includeEmoji} onChange={(e) => handleDiaryOptionChange('homework', 'includeEmoji', e.target.checked)} />
                                      <label htmlFor="emoji-homework">Pridėti jaustuką</label>
                                    </div>
                                    <div className="checkbox-option-small">
                                      <input type="checkbox" id="intro-homework" checked={diaryFormatOptions.homework.includeIntro} onChange={(e) => handleDiaryOptionChange('homework', 'includeIntro', e.target.checked)} />
                                      <label htmlFor="intro-homework">Pridėti įžangą</label>
                                    </div>
                                  </div>
                              </div>
                              <div className="diary-entry">
                                  <label>Pastabos apie pamoką:</label>
                                  <div className="diary-field">
                                      <p>{formatDiaryEntry('notes', lessonPlan.eDiaryEntry.notes)}</p>
                                      <button onClick={() => handleCopy(lessonPlan.eDiaryEntry.notes, 'notes')} className={`copy-button ${copiedField === 'notes' ? 'copied' : ''}`}>
                                          {copiedField === 'notes' ? 'Nukopijuota!' : 'Kopijuoti'}
                                      </button>
                                  </div>
                                  <div className="diary-options">
                                    <div className="checkbox-option-small">
                                      <input type="checkbox" id="emoji-notes" checked={diaryFormatOptions.notes.includeEmoji} onChange={(e) => handleDiaryOptionChange('notes', 'includeEmoji', e.target.checked)} />
                                      <label htmlFor="emoji-notes">Pridėti jaustuką</label>
                                    </div>
                                    <div className="checkbox-option-small">
                                      <input type="checkbox" id="intro-notes" checked={diaryFormatOptions.notes.includeIntro} onChange={(e) => handleDiaryOptionChange('notes', 'includeIntro', e.target.checked)} />
                                      <label htmlFor="intro-notes">Pridėti įžangą</label>
                                    </div>
                                  </div>
                              </div>
                              <div className="diary-entry">
                                  <label>Teminis planavimas:</label>
                                  <div className="diary-field">
                                      <p>{formatDiaryEntry('thematicPlanning', lessonPlan.eDiaryEntry.thematicPlanning)}</p>
                                      <button onClick={() => handleCopy(lessonPlan.eDiaryEntry.thematicPlanning, 'thematicPlanning')} className={`copy-button ${copiedField === 'thematicPlanning' ? 'copied' : ''}`}>
                                          {copiedField === 'thematicPlanning' ? 'Nukopijuota!' : 'Kopijuoti'}
                                      </button>
                                  </div>
                                  <div className="diary-options">
                                    <div className="checkbox-option-small">
                                      <input type="checkbox" id="emoji-thematicPlanning" checked={diaryFormatOptions.thematicPlanning.includeEmoji} onChange={(e) => handleDiaryOptionChange('thematicPlanning', 'includeEmoji', e.target.checked)} />
                                      <label htmlFor="emoji-thematicPlanning">Pridėti jaustuką</label>
                                    </div>
                                    <div className="checkbox-option-small">
                                      <input type="checkbox" id="intro-thematicPlanning" checked={diaryFormatOptions.thematicPlanning.includeIntro} onChange={(e) => handleDiaryOptionChange('thematicPlanning', 'includeIntro', e.target.checked)} />
                                      <label htmlFor="intro-thematicPlanning">Pridėti įžangą</label>
                                    </div>
                                  </div>
                              </div>
                              <div className="diary-entry">
                                  <label>Individualus darbas:</label>
                                  <div className="diary-field">
                                      <p>{formatDiaryEntry('individualWork', lessonPlan.eDiaryEntry.individualWork)}</p>
                                      <button onClick={() => handleCopy(lessonPlan.eDiaryEntry.individualWork, 'individualWork')} className={`copy-button ${copiedField === 'individualWork' ? 'copied' : ''}`}>
                                          {copiedField === 'individualWork' ? 'Nukopijuota!' : 'Kopijuoti'}
                                      </button>
                                  </div>
                                  <div className="diary-options">
                                    <div className="checkbox-option-small">
                                      <input type="checkbox" id="emoji-individualWork" checked={diaryFormatOptions.individualWork.includeEmoji} onChange={(e) => handleDiaryOptionChange('individualWork', 'includeEmoji', e.target.checked)} />
                                      <label htmlFor="emoji-individualWork">Pridėti jaustuką</label>
                                    </div>
                                    <div className="checkbox-option-small">
                                      <input type="checkbox" id="intro-individualWork" checked={diaryFormatOptions.individualWork.includeIntro} onChange={(e) => handleDiaryOptionChange('individualWork', 'includeIntro', e.target.checked)} />
                                      <label htmlFor="intro-individualWork">Pridėti įžangą</label>
                                    </div>
                                  </div>
                              </div>
                          </div>
                      )}
                      <div className="card motivation-card">
                          <h3>💖 Ačiū tau, mokytojau!</h3>
                          <p>{lessonPlan.motivation}</p>
                      </div>
                      {activePlanId && (
                        <div className="card private-comments-card">
                          <h3>
                              📝 Privačios pastabos
                              {isCommentSaving && (
                                  <span style={{ fontSize: '0.9rem', fontWeight: 'normal', marginLeft: '1rem', color: 'var(--text-color-light)' }}>
                                      Įrašoma...
                                  </span>
                              )}
                          </h3>
                          <p className="comment-description">Šios pastabos matomos tik jums ir išsaugomos kartu su planu.</p>
                          <textarea
                            value={privateComment}
                            onChange={(e) => setPrivateComment(e.target.value)}
                            placeholder="Įrašykite savo asmeninius priminimus, refleksijas ar idėjas..."
                            className="comment-textarea"
                          />
                        </div>
                      )}
                      {(
                        <div className="refinement-container">
                            <h3>Norite kažką pakeisti?</h3>
                            <form onSubmit={handleRefinementSubmit} className="refinement-form">
                                <input 
                                    type="text" 
                                    value={refinement}
                                    onChange={(e) => setRefinement(e.target.value)}
                                    placeholder="pvz., 'Sutrumpink namų darbus', 'Pridėk daugiau kūrybinių užduočių'" 
                                    disabled={isLoading}
                                />
                                <button type="submit" disabled={isLoading}>
                                    {isLoading ? <div className="spinner"></div> : 'Atnaujinti pamokos aprašą'}
                                </button>
                            </form>
                        </div>
                      )}
                  </div>
                </>
            )}
        </div>
      </main>
      {selectedTerm && (
        <div className="modal-overlay" onClick={() => setSelectedTerm(null)}>
          <div className="modal-content glossary-modal" onClick={(e) => e.stopPropagation()}>
            <button className="modal-close-button" onClick={() => setSelectedTerm(null)}>&times;</button>
            <h3>{selectedTerm.term}</h3>
            <p>{selectedTerm.definition}</p>
          </div>
        </div>
      )}
      {showOnboarding && (
        <div className="modal-overlay">
          <div className="modal-content onboarding-modal">
            <div className="onboarding-step-content">
                <h3>{onboardingSteps[onboardingStep].title}</h3>
                <p>{onboardingSteps[onboardingStep].content}</p>
            </div>
            <div className="onboarding-dots">
                {onboardingSteps.map((_, index) => (
                    <span
                        key={index}
                        className={`dot ${onboardingStep === index ? 'active' : ''}`}
                    ></span>
                ))}
            </div>
            <div className="onboarding-nav">
                {onboardingStep < onboardingSteps.length - 1 && (
                    <button onClick={closeOnboarding} className="button-secondary">Praleisti</button>
                )}
                 <div>
                    {onboardingStep > 0 && (
                        <button onClick={() => setOnboardingStep(s => s - 1)} className="button-secondary">Atgal</button>
                    )}
                    {onboardingStep < onboardingSteps.length - 1 ? (
                        <button onClick={() => setOnboardingStep(s => s + 1)} className="button-primary">Toliau</button>
                    ) : (
                        <button onClick={closeOnboarding} className="button-primary">Užbaigti</button>
                    )}
                </div>
            </div>
          </div>
        </div>
      )}
      {isDeleteModalOpen && (
        <div className="modal-overlay" onClick={() => setIsDeleteModalOpen(false)}>
            <div className="modal-content delete-modal" onClick={(e) => e.stopPropagation()}>
                <button className="modal-close-button" onClick={() => setIsDeleteModalOpen(false)}>&times;</button>
                <h2>Patvirtinkite ištrynimą</h2>
                <p className="delete-modal-description">Ar tikrai norite visam laikui ištrinti šį pamokos planą? Šio veiksmo anuliuoti negalima.</p>
                <div className="modal-actions">
                    <button onClick={() => setIsDeleteModalOpen(false)} className="button-secondary">Atšaukti</button>
                    <button onClick={confirmDeletePlan} className="button-danger">Ištrinti</button>
                </div>
            </div>
        </div>
      )}
      {isOverwriteModalOpen && (
        <div className="modal-overlay" onClick={() => setIsOverwriteModalOpen(false)}>
            <div className="modal-content delete-modal" onClick={(e) => e.stopPropagation()}>
                <button className="modal-close-button" onClick={() => setIsOverwriteModalOpen(false)}>&times;</button>
                <h2>Patvirtinkite atnaujinimą</h2>
                <p className="delete-modal-description">Ar tikrai norite perrašyti šį išsaugotą pamokos planą? Ankstesnė versija bus prarasta.</p>
                <div className="modal-actions">
                    <button onClick={() => setIsOverwriteModalOpen(false)} className="button-secondary">Atšaukti</button>
                    <button onClick={handleOverwritePlan} className="button-primary">Perrašyti</button>
                </div>
            </div>
        </div>
      )}
      {isSaveModalOpen && (
        <div className="modal-overlay" onClick={() => setIsSaveModalOpen(false)}>
            <div className="modal-content delete-modal" onClick={(e) => e.stopPropagation()}>
                <button className="modal-close-button" onClick={() => setIsSaveModalOpen(false)}>&times;</button>
                <h2>Patvirtinkite išsaugojimą</h2>
                <p className="delete-modal-description">Ar tikrai norite išsaugoti šį pamokos planą kaip naują įrašą?</p>
                <div className="modal-actions">
                    <button onClick={() => setIsSaveModalOpen(false)} className="button-secondary">Atšaukti</button>
                    <button onClick={confirmSavePlan} className="button-primary">Išsaugoti</button>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

const container = document.getElementById('root');
const root = createRoot(container!);
root.render(<App />);

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';

interface EDiaryEntry {
  classwork: string;
  homework: string;
  notes: string;
  thematicPlanning: string;
  individualWork: string;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: string;
  };
  lessonActivities: {
    gifted: string;
    general: string;
    struggling: string;
    itTools?: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
}

interface AnalysisResult {
  summary: string;
  strengths: string[];
  weaknesses: string[];
  suggestions: string[];
}

const glossaryData: { [key: string]: string } = {
  'Diferencijuotos': 'Tai mokymo strategija, kai mokytojas pritaiko ugdymo turinį, procesą, aplinką ir vertinimą, atsižvelgdamas į skirtingus mokinių mokymosi poreikius, gebėjimus ir interesus.',
  'Diferencijuoti': 'Tai mokymo strategija, kai mokytojas pritaiko ugdymo turinį, procesą, aplinką ir vertinimą, atsižvelgdamas į skirtingus mokinių mokymosi poreikius, gebėjimus ir interesus.',
  'Formuojamasis vertinimas': 'Nuolatinis vertinimas pamokoje, skirtas stebėti mokinio pažangą, suprasti jo mokymosi sunkumus ir laiku suteikti pagalbą. Jo tikslas – gerinti mokymąsi, o ne rašyti pažymį.',
  'Kaupiamasis vertinimas': 'Vertinimo būdas, kai per tam tikrą laikotarpį surinkti mokinio pasiekimų įrodymai (pvz., taškai už užduotis, aktyvumą) sumuojami į vieną bendrą įvertinimą (pažymį).',
  'Diagnostinis vertinimas': 'Vertinimas, atliekamas temos ar kurso pradžioje, siekiant nustatyti esamas mokinių žinias, gebėjimus ir supratimą. Padeda mokytojui planuoti tolesnį mokymą.',
  'Kompetencijos': 'Gebėjimas atlikti tam tikrą veiklą, remiantis įgytomis žiniomis, įgūdžiais, vertybėmis ir požiūriais. Lietuvos ugdymo sistemoje išskiriamos kelios pagrindinės kompetencijos (pvz., komunikavimo, pažinimo, socialinė, pilietinė).',
  'Gebėjimai': 'Mokinio įgytos žinios ir įgūdžiai, leidžiantys jam sėkmingai atlikti tam tikras užduotis ar veiklas. Gebėjimai yra kompetencijų sudedamoji dalis.',
  'Scaffolding': 'Mokymosi pastoliai – paramos teikimas mokiniui, padedant jam atlikti užduotį, kurios jis pats dar negali įveikti.',
  'Metakognicija': 'Mąstymas apie savo mąstymo procesus, padedantis kontroliuoti ir vertinti savo mokymąsi.'
};

const topicSuggestions: { [key: string]: string[] } = {
  'matematika': ['Interaktyvūs uždaviniai', 'Matematiniai žaidimai', 'Uždavinių sprendimas porose', 'Geometrinių figūrų konstravimas'],
  'lietuvių': ['Kūrybinis rašymas', 'Teksto analizė grupėse', 'Debatai', 'Vaidmenų žaidimai'],
  'istorija': ['Laiko juostos kūrimas', 'Istorinių šaltinių analizė', 'Virtuali kelionė laiku', 'Diskusija apie priežastis ir pasekmes'],
  'gamta': ['Eksperimentų atlikimas', 'Stebėjimų dienoraštis', 'Gamtos objektų klasifikavimas', 'Aplinkosaugos projektas'],
};

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [generalNotes, setGeneralNotes] = useState('');
  const [refinement, setRefinement] = useState('');

  const [evaluationType, setEvaluationType] = useState('Formuojamasis');
  const [customEvaluationType, setCustomEvaluationType] = useState('');
  const [evaluationDescription, setEvaluationDescription] = useState('');

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [isAllCopied, setIsAllCopied] = useState(false);

  const [selectedTerm, setSelectedTerm] = useState<{ term: string; definition: string; } | null>(null);
  const [showOnboarding, setShowOnboarding] = useState(false);
  const [onboardingStep, setOnboardingStep] = useState(0);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [privateComment, setPrivateComment] = useState('');
  const [isCommentSaving, setIsCommentSaving] = useState(false);

  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [planToDelete, setPlanToDelete] = useState<string | null>(null);
  const [isOverwriteModalOpen, setIsOverwriteModalOpen] = useState(false);
  const [isSaveModalOpen, setIsSaveModalOpen] = useState(false);

  const [analysisResult, setAnalysisResult] = useState<AnalysisResult | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisError, setAnalysisError] = useState<string | null>(null);

  const [searchQuery, setSearchQuery] = useState('');
  const [activeSuggestions, setActiveSuggestions] = useState<string[]>([]);

  const [diaryFormatOptions, setDiaryFormatOptions] = useState({
    classwork: { includeEmoji: false, includeIntro: false },
    homework: { includeEmoji: false, includeIntro: false },
    notes: { includeEmoji: false, includeIntro: false },
    thematicPlanning: { includeEmoji: false, includeIntro: false },
    individualWork: { includeEmoji: false, includeIntro: false },
  });

  type DiaryFieldKey = keyof typeof diaryFormatOptions;

  const DIARY_EMOJIS: Record<DiaryFieldKey, string> = {
    classwork: '📚',
    homework: '🏡',
    notes: '📝',
    thematicPlanning: '🗓️',
    individualWork: '🧑‍🏫',
  };

  const DIARY_INTRO_PHRASES: Record<DiaryFieldKey, string> = {
    classwork: 'Šiandien pamokoje: ',
    homework: 'Namų darbai: ',
    notes: 'Svarbi informacija: ',
    thematicPlanning: 'Tema pagal ilgalaikį planą: ',
    individualWork: 'Pastabos apie individualų darbą: ',
  };

  const chatRef = useRef<Chat | null>(null);
  const commentSaveTimeoutRef = useRef<number | null>(null);

  useEffect(() => {
    const onboardingComplete = localStorage.getItem('onboardingComplete');
    if (!onboardingComplete) {
        setShowOnboarding(true);
    }

    try {
        const storedPlans = localStorage.getItem('savedLessonPlans');
        if (storedPlans) {
            setSavedPlans(JSON.parse(storedPlans));
        }
    } catch (error) {
        console.error("Nepavyko įkelti planų iš vietinės saugyklos:", error);
    }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (error) {
      console.error("Nepavyko išsaugoti planų vietinėje saugyloje:", error);
    }
  }, [savedPlans]);

  // Topic-based suggestions
  useEffect(() => {
    const lowerTopic = topic.toLowerCase();
    const lowerSubject = subject.toLowerCase();
    let found = false;
    for (const key in topicSuggestions) {
      if (lowerTopic.includes(key) || lowerSubject.includes(key)) {
        setActiveSuggestions(topicSuggestions[key]);
        found = true;
        break;
      }
    }
    if (!found) setActiveSuggestions([]);
  }, [topic, subject]);

  useEffect(() => {
    if (!activePlanId) return;

    setIsCommentSaving(true);
    if (commentSaveTimeoutRef.current) {
        clearTimeout(commentSaveTimeoutRef.current);
    }

    commentSaveTimeoutRef.current = window.setTimeout(() => {
        setSavedPlans(prevPlans => {
            const planIndex = prevPlans.findIndex(p => p.id === activePlanId);
            if (planIndex === -1) return prevPlans;

            const currentPlan = prevPlans[planIndex];
            if (currentPlan.comments === privateComment) return prevPlans;

            const updatedPlan = { ...currentPlan, comments: privateComment };
            const newPlans = [...prevPlans];
            newPlans[planIndex] = updatedPlan;
            return newPlans;
        });
        setIsCommentSaving(false);
    }, 500);

    return () => {
        if (commentSaveTimeoutRef.current) {
            clearTimeout(commentSaveTimeoutRef.current);
        }
    };
  }, [privateComment, activePlanId]);

  const systemInstruction = `Tu esi ekspertas pedagogas ir pamokų planavimo asistentas, puikiai išmanantis Lietuvos bendrąsias ugdymo programas. Tavo tikslas - padėti mokytojams kurti išsamius, strukturuotus ir diferencijuotus pamokų planus.
SVARBU: Atsižvelk į nurodytą pamokos tipą (Įvadinė, Įtvirtinimo, Apibendrinamoji, Vertinamoji) ir atitinkamai pritaikyk veiklas.

Atsakas privalo būti JSON formatu:
{
  "generalNotes": "Bendros pastabos, komentarai ar priminimai mokytojui.",
  "lessonType": "Pamokos tipas",
  "lessonOverview": {
    "topic": "Pamokos tema",
    "goal": "Pamokos tikslas ir uždaviniai",
    "competencies": "Pagrindiniai gebėjimai",
    "evaluation": "Vertinimo aprašymas"
  },
  "lessonActivities": {
    "gifted": "Veiklos gabesniems.",
    "general": "Veiklos bendro lygio mokiniams.",
    "struggling": "Veiklos pagalbos reikalingiems.",
    "itTools": "Rekomendacijos IT įrankiams."
  },
  "homework": {
    "purpose": "Namų darbų tikslas.",
    "gifted": "Užduotis gabesniems.",
    "general": "Užduotis bendram lygiui su žingsnis po žingsnio instrukcijomis.",
    "struggling": "Užduotis pagalbos reikalingiems su atraminiais pavyzdžiais."
  },
  "eDiaryEntry": {
    "classwork": "Klasės darbai įrašui.",
    "homework": "Namų darbai įrašui.",
    "notes": "Pastabos įrašui.",
    "thematicPlanning": "Tema iš plano.",
    "individualWork": "Individualus darbas."
  },
  "motivation": "Motyvuojanti žinutė."
}
Atsakyk TIK JSON formatu lietuvių kalba.`;

  const handleGenerate = async (prompt: string, isInitial: boolean) => {
      setIsLoading(true);
      setError(null);
      setAnalysisResult(null);

      try {
          const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
          if (isInitial || !chatRef.current) {
              chatRef.current = ai.chats.create({
                  model: 'gemini-3-flash-preview',
                  config: { systemInstruction, responseMimeType: "application/json" },
              });
          }

          if (!chatRef.current) throw new Error("Nepavyko sukurti pokalbio.");

          const result = await chatRef.current.sendMessage({ message: prompt });
          const text = result.text.trim();
          const jsonString = text.replace(/```json|```/g, '').trim();
          const parsedPlan: LessonPlan = JSON.parse(jsonString);

          // Ensure lessonType is preserved if provided in prompt but maybe lost in model output
          if (isInitial && lessonType) parsedPlan.lessonType = lessonType;

          setLessonPlan(parsedPlan);
          if (isInitial) {
            setActivePlanId(null);
            setPrivateComment('');
          }
      } catch (e: any) {
          setError(`Klaida generuojant planą: ${e.message}`);
          setLessonPlan(null);
      } finally {
          setIsLoading(false);
      }
  };

  const handleInitialSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Būtina nurodyti klasę, dalyką ir temą.');
      return;
    }

    let evaluationPrompt = '';
    if (evaluationDescription) {
        const finalEvalType = evaluationType === 'Kitas' && customEvaluationType ? customEvaluationType : evaluationType;
        evaluationPrompt = `\n- Vertinimo tipas: ${finalEvalType}\n- Vertinimo aprašymas: ${evaluationDescription}`;
    }

    const prompt = `Sukurk pamokos planą.
- Klasė: ${grade}
- Dalykas: ${subject}
- Pamokos tema: ${topic}
- Pamokos tipas: ${lessonType || 'Nenurodyta'}
${goal ? `- Pamokos tikslas: ${goal}` : ''}
${activities ? `- Papildomos idėjos: ${activities}` : ''}
${generalNotes ? `- Bendros pastabos: ${generalNotes}` : ''}${evaluationPrompt}
Užtikrink aiškų diferencijavimą.`;

    handleGenerate(prompt, true);
  };

  const handleRefinementSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      if (!refinement) return;
      handleGenerate(refinement, false);
      setRefinement('');
  }

  const handleDiaryOptionChange = (field: DiaryFieldKey, option: 'includeEmoji' | 'includeIntro', value: boolean) => {
    setDiaryFormatOptions(prev => ({ ...prev, [field]: { ...prev[field], [option]: value } }));
  };

  const formatDiaryEntry = (field: DiaryFieldKey, text: string): string => {
    if (!text) return '';
    const options = diaryFormatOptions[field];
    let formattedText = text;
    if (options.includeIntro) formattedText = `${DIARY_INTRO_PHRASES[field]}${formattedText}`;
    if (options.includeEmoji) formattedText = `${DIARY_EMOJIS[field]} ${formattedText}`;
    return formattedText;
  };

  const handleCopy = (rawText: string, fieldName: string) => {
    const formattedText = formatDiaryEntry(fieldName as DiaryFieldKey, rawText);
    navigator.clipboard.writeText(formattedText).then(() => {
        setCopiedField(fieldName);
        setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const handleCopyAllDiaryEntries = () => {
    if (!lessonPlan || !lessonPlan.eDiaryEntry) return;
    const entries = [
      formatDiaryEntry('classwork', lessonPlan.eDiaryEntry.classwork),
      formatDiaryEntry('homework', lessonPlan.eDiaryEntry.homework),
      formatDiaryEntry('notes', lessonPlan.eDiaryEntry.notes),
      formatDiaryEntry('thematicPlanning', lessonPlan.eDiaryEntry.thematicPlanning),
      formatDiaryEntry('individualWork', lessonPlan.eDiaryEntry.individualWork),
    ];
    const allEntriesText = entries.filter(Boolean).join('\n\n');
    navigator.clipboard.writeText(allEntriesText).then(() => {
        setIsAllCopied(true);
        setTimeout(() => setIsAllCopied(false), 2000);
    });
  };

  const confirmSavePlan = () => {
    if (!lessonPlan) return;
    const planTopic = lessonPlan.lessonOverview.topic || 'Neįvardinta tema';
    const date = new Date().toLocaleDateString('lt-LT');
    const title = `${subject || ''} ${grade || ''}: ${planTopic} (${date})`;
    const newPlan: SavedPlan = {
      id: `plan-${Date.now()}`,
      title,
      plan: lessonPlan,
      createdAt: new Date().toISOString(),
      grade,
      subject,
      lessonType: lessonPlan.lessonType || lessonType,
      comments: privateComment
    };
    setSavedPlans(prevPlans => [newPlan, ...prevPlans]);
    setActivePlanId(newPlan.id);
    setIsSaveModalOpen(false);
  };

  const handleOverwritePlan = () => {
    if (!activePlanId || !lessonPlan) return;
    setSavedPlans(prevPlans => prevPlans.map(p => {
      if (p.id === activePlanId) {
         return {
           ...p,
           plan: lessonPlan,
           comments: privateComment,
           lessonType: lessonPlan.lessonType || lessonType
         };
      }
      return p;
    }));
    setIsOverwriteModalOpen(false);
  };

  const handleLoadPlan = (planId: string) => {
    const planToLoad = savedPlans.find(p => p.id === planId);
    if (planToLoad) {
      setLessonPlan(planToLoad.plan);
      setActivePlanId(planToLoad.id);
      setPrivateComment(planToLoad.comments || '');
      setGrade(planToLoad.grade || '');
      setSubject(planToLoad.subject || '');
      setTopic(planToLoad.plan.lessonOverview.topic || '');
      setLessonType(planToLoad.lessonType || '');
    }
  };

  const handleAnalyzePlan = async () => {
    if (!lessonPlan) return;
    setIsAnalyzing(true);
    setAnalysisError(null);
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const analysisPrompt = `Išanalizuok šį pamokos planą kaip ekspertas pedagogas. Pateik JSON:
{ "summary": "vertinimas", "strengths": [], "weaknesses": [], "suggestions": [] }
Planą: ${JSON.stringify(lessonPlan)}`;
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: [{ role: 'user', parts: [{ text: analysisPrompt }] }],
            config: { responseMimeType: 'application/json' }
        });
        setAnalysisResult(JSON.parse(response.text));
    } catch (e) {
        setAnalysisError("Nepavyko atlikti analizės.");
    } finally {
        setIsAnalyzing(false);
    }
  };

  const renderTextWithGlossaryTerms = (text: string) => {
    if (!text) return text;
    const terms = Object.keys(glossaryData);
    const regex = new RegExp(`\\b(${terms.join('|')})\\b`, 'gi');
    const parts = text.split(regex);
    return parts.map((part, index) => {
      const lowerCasePart = part.toLowerCase();
      const originalTerm = terms.find(term => term.toLowerCase() === lowerCasePart);
      if (originalTerm) {
        return (
          <span
            key={index}
            className="glossary-term"
            onClick={(e) => {
              e.stopPropagation();
              setSelectedTerm({ term: originalTerm, definition: glossaryData[originalTerm] })
            }}
          >
            {part}
          </span>
        );
      }
      return part;
    });
  };

  const renderFormattedText = (text: string) => {
    if (!text) return null;
    return text.split('\n').map((line, index) => (
      <React.Fragment key={index}>
        {renderTextWithGlossaryTerms(line)}
        <br />
      </React.Fragment>
    ));
  };

  const closeOnboarding = () => {
    setShowOnboarding(false);
    localStorage.setItem('onboardingComplete', 'true');
  };

  const lessonTypeOptions: LessonCategory[] = ['Įvadinė', 'Įtvirtinimo', 'Apibendrinamoji', 'Vertinamoji'];

  const filteredPlans = savedPlans.filter(plan => {
    const query = searchQuery.toLowerCase();
    return plan.title.toLowerCase().includes(query) || (plan.subject && plan.subject.toLowerCase().includes(query));
  });

  const handleUpdateNotes = (newNotes: string) => {
    if (!lessonPlan) return;
    setLessonPlan({ ...lessonPlan, generalNotes: newNotes });
  };

  const injectSuggestion = (suggestion: string) => {
    setActivities(prev => prev ? `${prev}\n- ${suggestion}` : `- ${suggestion}`);
  };

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>Jūsų pagalbininkas kūrybiškoms ir efektyvioms pamokoms</p>
        <div className="header-buttons">
            <button onClick={() => { setOnboardingStep(0); setShowOnboarding(true); }} className="external-link-button">Kaip naudotis?</button>
            <a href="https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos" target="_blank" rel="noopener noreferrer" className="external-link-button">BP nuoroda</a>
        </div>
      </header>
      <main className="main-content">
            <div className="form-container">
            <h2>Pamokos informacija</h2>
            <form onSubmit={handleInitialSubmit}>
                <div className="form-group">
                  <label>Pamokos tipas</label>
                  <select value={lessonType} onChange={(e) => setLessonType(e.target.value as LessonCategory)} style={{width: '100%', padding: '0.75rem', borderRadius: '8px', border: '1px solid var(--border-color)'}}>
                    <option value="">-- Pasirinkite tipą --</option>
                    {lessonTypeOptions.map(t => <option key={t} value={t}>{t}</option>)}
                  </select>
                </div>
                <div className="form-group">
                <label>Klasė / Grupė *</label>
                <input type="text" value={grade} onChange={(e) => setGrade(e.target.value)} placeholder="pvz., 5b klasė" required />
                </div>
                <div className="form-group">
                <label>Dalykas *</label>
                <input type="text" value={subject} onChange={(e) => setSubject(e.target.value)} placeholder="pvz., Matematika" required/>
                </div>
                <div className="form-group">
                <label>Pamokos tema *</label>
                <input type="text" value={topic} onChange={(e) => setTopic(e.target.value)} placeholder="pvz., Trupmenų sudėtis" required/>
                {activeSuggestions.length > 0 && (
                  <div className="suggestions-box" style={{marginTop: '0.5rem', display: 'flex', flexWrap: 'wrap', gap: '5px'}}>
                    <span style={{fontSize: '0.8rem', color: '#888', width: '100%'}}>Pasiūlymai:</span>
                    {activeSuggestions.map(s => (
                      <button key={s} type="button" onClick={() => injectSuggestion(s)} className="suggestion-pill" style={{fontSize: '0.75rem', padding: '2px 8px', borderRadius: '12px', background: '#e1f5fe', border: 'none', cursor: 'pointer'}}>{s}</button>
                    ))}
                  </div>
                )}
                </div>
                <div className="form-group">
                <label>Tikslas (nebūtina)</label>
                <textarea value={goal} onChange={(e) => setGoal(e.target.value)} placeholder="Mokiniai gebės..."></textarea>
                </div>
                <div className="form-group">
                <label>Veiklos idėjos (nebūtina)</label>
                <textarea value={activities} onChange={(e) => setActivities(e.target.value)} placeholder="pvz., darbas grupėse"></textarea>
                </div>
                <div className="form-group">
                    <label>Vertinimas</label>
                    <select value={evaluationType} onChange={(e) => setEvaluationType(e.target.value)} style={{width: '100%', marginBottom: '10px', padding: '0.75rem', borderRadius: '8px', border: '1px solid var(--border-color)'}}>
                        {['Formuojamasis', 'Kaupiamasis', 'Diagnostinis', 'Kitas'].map(opt => <option key={opt} value={opt}>{opt}</option>)}
                    </select>
                    <textarea value={evaluationDescription} onChange={(e) => setEvaluationDescription(e.target.value)} placeholder="Vertinimo detalės..."></textarea>
                </div>
                <button type="submit" disabled={isLoading} className="generate-button">
                  {isLoading && !lessonPlan ? <div className="spinner"></div> : null} Pateikti aprašą
                </button>
            </form>
            <div className="saved-plans-container">
                <h3>Išsaugoti planai</h3>
                <input type="text" placeholder="Ieškoti..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} className="search-input" />
                <ul className="saved-plans-list">
                    {filteredPlans.map(plan => (
                    <li key={plan.id} className={plan.id === activePlanId ? 'active' : ''} onClick={() => handleLoadPlan(plan.id)}>
                        <span className="plan-title">
                        {plan.title}
                        {plan.lessonType && <span className="type-tag" style={{fontSize: '0.7rem', color: 'var(--primary-color)', fontWeight: 'bold'}}>[{plan.lessonType}]</span>}
                        </span>
                        <button onClick={(e) => { e.stopPropagation(); handleDeletePlan(plan.id); }} className="delete-button">✖</button>
                    </li>
                    ))}
                </ul>
            </div>
            </div>

        <div className="results-container">
            {isLoading && !lessonPlan && <div className="loading-overlay"><div className="spinner-large"></div><p>Generuojama...</p></div>}
            {lessonPlan && (
                <>
                  <div className="export-container">
                    <button onClick={handleAnalyzePlan} disabled={isAnalyzing} className="analysis-button">Analizuoti 🔍</button>
                    <button onClick={() => activePlanId ? setIsOverwriteModalOpen(true) : setIsSaveModalOpen(true)} className="save-button">Išsaugoti 💾</button>
                  </div>
                  {analysisResult && (
                    <div className="card analysis-card">
                        <h3>Analizė</h3>
                        <p>{analysisResult.summary}</p>
                    </div>
                  )}
                  <div className="lesson-plan">
                      <div className="card general-notes-card">
                          <h3>📌 Bendros pastabos (Redaguojama)</h3>
                          <textarea 
                            value={lessonPlan.generalNotes} 
                            onChange={(e) => handleUpdateNotes(e.target.value)} 
                            className="notes-edit-area"
                            style={{width: '100%', minHeight: '80px', background: 'transparent', border: '1px dashed #ccc', padding: '10px', fontFamily: 'inherit'}}
                          />
                      </div>
                      <div className="card lesson-overview-card">
                          <h3>📖 Apžvalga [{lessonPlan.lessonType || lessonType}]</h3>
                          <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                          <p><strong>Tikslas:</strong> {renderFormattedText(lessonPlan.lessonOverview.goal)}</p>
                          <p><strong>Gebėjimai:</strong> {renderFormattedText(lessonPlan.lessonOverview.competencies)}</p>
                          <p><strong>Vertinimas:</strong> {renderFormattedText(lessonPlan.lessonOverview.evaluation)}</p>
                      </div>
                      <div className="card lesson-activities-card">
                          <h3>🎨 Veiklos</h3>
                          <p><strong>Gabesniems:</strong> {renderFormattedText(lessonPlan.lessonActivities.gifted)}</p>
                          <p><strong>Bendra:</strong> {renderFormattedText(lessonPlan.lessonActivities.general)}</p>
                          <p><strong>Pagalba:</strong> {renderFormattedText(lessonPlan.lessonActivities.struggling)}</p>
                      </div>
                      <div className="card homework-card">
                          <h3>📚 Namų darbai</h3>
                          <p><strong>Tikslas:</strong> {renderFormattedText(lessonPlan.homework.purpose)}</p>
                          <p><strong>Bendra:</strong> {renderFormattedText(lessonPlan.homework.general)}</p>
                          <p><strong>Pagalba:</strong> {renderFormattedText(lessonPlan.homework.struggling)}</p>
                      </div>
                      <div className="card motivation-card"><h3>💖 Ačiū</h3><p>{lessonPlan.motivation}</p></div>
                      {activePlanId && (
                        <div className="card private-comments-card">
                          <h3>📝 Pastabos {isCommentSaving && <span>...</span>}</h3>
                          <textarea value={privateComment} onChange={(e) => setPrivateComment(e.target.value)} className="comment-textarea" />
                        </div>
                      )}
                  </div>
                </>
            )}
        </div>
      </main>
      {selectedTerm && (
        <div className="modal-overlay" onClick={() => setSelectedTerm(null)}>
          <div className="modal-content glossary-modal" onClick={(e) => e.stopPropagation()}>
            <button className="modal-close-button" onClick={() => setSelectedTerm(null)}>&times;</button>
            <h3>{selectedTerm.term}</h3>
            <p>{selectedTerm.definition}</p>
          </div>
        </div>
      )}
      {isDeleteModalOpen && (
        <div className="modal-overlay" onClick={() => setIsDeleteModalOpen(false)}>
            <div className="modal-content delete-modal" onClick={(e) => e.stopPropagation()}>
                <button onClick={confirmDeletePlan} className="button-danger">Ištrinti</button>
            </div>
        </div>
      )}
      {isOverwriteModalOpen && (
        <div className="modal-overlay" onClick={() => setIsOverwriteModalOpen(false)}>
            <div className="modal-content" onClick={(e) => e.stopPropagation()}>
                <button onClick={handleOverwritePlan} className="button-primary">Perrašyti</button>
            </div>
        </div>
      )}
      {isSaveModalOpen && (
        <div className="modal-overlay" onClick={() => setIsSaveModalOpen(false)}>
            <div className="modal-content" onClick={(e) => e.stopPropagation()}>
                <button onClick={confirmSavePlan} className="button-primary">Išsaugoti</button>
            </div>
        </div>
      )}
    </div>
  );
};

const container = document.getElementById('root');
const root = createRoot(container!);
root.render(<App />);

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';

interface EDiaryEntry {
  classwork: string;
  homework: string;
  notes: string;
  thematicPlanning: string;
  individualWork: string;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: string;
  };
  lessonActivities: {
    gifted: string;
    general: string;
    struggling: string;
    itTools?: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
}

interface AnalysisResult {
  summary: string;
  strengths: string[];
  weaknesses: string[];
  suggestions: string[];
}

const glossaryData: { [key: string]: string } = {
  'Diferencijuotos': 'Tai mokymo strategija, kai mokytojas pritaiko ugdymo turinį, procesą, aplinką ir vertinimą, atsižvelgdamas į skirtingus mokinių mokymosi poreikius, gebėjimus ir interesus.',
  'Diferencijuoti': 'Tai mokymo strategija, kai mokytojas pritaiko ugdymo turinį, procesą, aplinką ir vertinimą, atsižvelgdamas į skirtingus mokinių mokymosi poreikius, gebėjimus ir interesus.',
  'Formuojamasis vertinimas': 'Nuolatinis vertinimas pamokoje, skirtas stebėti mokinio pažangą, suprasti jo mokymosi sunkumus ir laiku suteikti pagalbą. Jo tikslas – gerinti mokymąsi, o ne rašyti pažymį.',
  'Kaupiamasis vertinimas': 'Vertinimo būdas, kai per tam tikrą laikotarpį surinkti mokinio pasiekimų įrodymai (pvz., taškai už užduotis, aktyvumą) sumuojami į vieną bendrą įvertinimą (pažymį).',
  'Diagnostinis vertinimas': 'Vertinimas, atliekamas temos ar kurso pradžioje, siekiant nustatyti esamas mokinių žinias, gebėjimus ir supratimą. Padeda mokytojui planuoti tolesnį mokymą.',
  'Kompetencijos': 'Gebėjimas atlikti tam tikrą veiklą, remiantis įgytomis žiniomis, įgūdžiais, vertybėmis ir požiūriais. Lietuvos ugdymo sistemoje išskiriamos kelios pagrindinės kompetencijos (pvz., komunikavimo, pažinimo, socialinė, pilietinė).',
  'Gebėjimai': 'Mokinio įgytos žinios ir įgūdžiai, leidžiantys jam sėkmingai atlikti tam tikras užduotis ar veiklas. Gebėjimai yra kompetencijų sudedamoji dalis.',
  'Scaffolding': 'Mokymosi pastoliai – paramos teikimas mokiniui, padedant jam atlikti užduotį, kurios jis pats dar negali įveikti.',
  'Metakognicija': 'Mąstymas apie savo mąstymo procesus, padedantis kontroliuoti ir vertinti savo mokymąsi.'
};

const topicSuggestions: { [key: string]: string[] } = {
  'matematika': ['Interaktyvūs uždaviniai', 'Matematiniai žaidimai', 'Uždavinių sprendimas porose', 'Geometrinių figūrų konstravimas'],
  'lietuvių': ['Kūrybinis rašymas', 'Teksto analizė grupėse', 'Debatai', 'Vaidmenų žaidimai'],
  'istorija': ['Laiko juostos kūrimas', 'Istorinių šaltinių analizė', 'Virtuali kelionė laiku', 'Diskusija apie priežastis ir pasekmes'],
  'gamta': ['Eksperimentų atlikimas', 'Stebėjimų dienoraštis', 'Gamtos objektų klasifikavimas', 'Aplinkosaugos projektas'],
};

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [generalNotes, setGeneralNotes] = useState('');
  const [refinement, setRefinement] = useState('');

  const [evaluationType, setEvaluationType] = useState('Formuojamasis');
  const [customEvaluationType, setCustomEvaluationType] = useState('');
  const [evaluationDescription, setEvaluationDescription] = useState('');

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [isAllCopied, setIsAllCopied] = useState(false);

  const [selectedTerm, setSelectedTerm] = useState<{ term: string; definition: string; } | null>(null);
  const [showOnboarding, setShowOnboarding] = useState(false);
  const [onboardingStep, setOnboardingStep] = useState(0);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [privateComment, setPrivateComment] = useState('');
  const [isCommentSaving, setIsCommentSaving] = useState(false);

  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [planToDelete, setPlanToDelete] = useState<string | null>(null);
  const [isOverwriteModalOpen, setIsOverwriteModalOpen] = useState(false);
  const [isSaveModalOpen, setIsSaveModalOpen] = useState(false);

  const [analysisResult, setAnalysisResult] = useState<AnalysisResult | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisError, setAnalysisError] = useState<string | null>(null);

  const [searchQuery, setSearchQuery] = useState('');
  const [activeSuggestions, setActiveSuggestions] = useState<string[]>([]);

  const [diaryFormatOptions, setDiaryFormatOptions] = useState({
    classwork: { includeEmoji: false, includeIntro: false },
    homework: { includeEmoji: false, includeIntro: false },
    notes: { includeEmoji: false, includeIntro: false },
    thematicPlanning: { includeEmoji: false, includeIntro: false },
    individualWork: { includeEmoji: false, includeIntro: false },
  });

  type DiaryFieldKey = keyof typeof diaryFormatOptions;

  const DIARY_EMOJIS: Record<DiaryFieldKey, string> = {
    classwork: '📚',
    homework: '🏡',
    notes: '📝',
    thematicPlanning: '🗓️',
    individualWork: '🧑‍🏫',
  };

  const DIARY_INTRO_PHRASES: Record<DiaryFieldKey, string> = {
    classwork: 'Šiandien pamokoje: ',
    homework: 'Namų darbai: ',
    notes: 'Svarbi informacija: ',
    thematicPlanning: 'Tema pagal ilgalaikį planą: ',
    individualWork: 'Pastabos apie individualų darbą: ',
  };

  const chatRef = useRef<Chat | null>(null);
  const commentSaveTimeoutRef = useRef<number | null>(null);

  useEffect(() => {
    const onboardingComplete = localStorage.getItem('onboardingComplete');
    if (!onboardingComplete) {
        setShowOnboarding(true);
    }

    try {
        const storedPlans = localStorage.getItem('savedLessonPlans');
        if (storedPlans) {
            setSavedPlans(JSON.parse(storedPlans));
        }
    } catch (error) {
        console.error("Nepavyko įkelti planų iš vietinės saugyklos:", error);
    }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (error) {
      console.error("Nepavyko išsaugoti planų vietinėje saugyloje:", error);
    }
  }, [savedPlans]);

  // Topic-based suggestions
  useEffect(() => {
    const lowerTopic = topic.toLowerCase();
    const lowerSubject = subject.toLowerCase();
    let found = false;
    for (const key in topicSuggestions) {
      if (lowerTopic.includes(key) || lowerSubject.includes(key)) {
        setActiveSuggestions(topicSuggestions[key]);
        found = true;
        break;
      }
    }
    if (!found) setActiveSuggestions([]);
  }, [topic, subject]);

  useEffect(() => {
    if (!activePlanId) return;

    setIsCommentSaving(true);
    if (commentSaveTimeoutRef.current) {
        clearTimeout(commentSaveTimeoutRef.current);
    }

    commentSaveTimeoutRef.current = window.setTimeout(() => {
        setSavedPlans(prevPlans => {
            const planIndex = prevPlans.findIndex(p => p.id === activePlanId);
            if (planIndex === -1) return prevPlans;

            const currentPlan = prevPlans[planIndex];
            if (currentPlan.comments === privateComment) return prevPlans;

            const updatedPlan = { ...currentPlan, comments: privateComment };
            const newPlans = [...prevPlans];
            newPlans[planIndex] = updatedPlan;
            return newPlans;
        });
        setIsCommentSaving(false);
    }, 500);

    return () => {
        if (commentSaveTimeoutRef.current) {
            clearTimeout(commentSaveTimeoutRef.current);
        }
    };
  }, [privateComment, activePlanId]);

  const systemInstruction = `Tu esi ekspertas pedagogas ir pamokų planavimo asistentas, puikiai išmanantis Lietuvos bendrąsias ugdymo programas. Tavo tikslas - padėti mokytojams kurti išsamius, strukturuotus ir diferencijuotus pamokų planus.
SVARBU: Atsižvelk į nurodytą pamokos tipą (Įvadinė, Įtvirtinimo, Apibendrinamoji, Vertinamoji) ir atitinkamai pritaikyk veiklas.

Atsakas privalo būti JSON formatu:
{
  "generalNotes": "Bendros pastabos, komentarai ar priminimai mokytojui.",
  "lessonType": "Pamokos tipas",
  "lessonOverview": {
    "topic": "Pamokos tema",
    "goal": "Pamokos tikslas ir uždaviniai",
    "competencies": "Pagrindiniai gebėjimai",
    "evaluation": "Vertinimo aprašymas"
  },
  "lessonActivities": {
    "gifted": "Veiklos gabesniems.",
    "general": "Veiklos bendro lygio mokiniams.",
    "struggling": "Veiklos pagalbos reikalingiems.",
    "itTools": "Rekomendacijos IT įrankiams."
  },
  "homework": {
    "purpose": "Namų darbų tikslas.",
    "gifted": "Užduotis gabesniems.",
    "general": "Užduotis bendram lygiui su žingsnis po žingsnio instrukcijomis.",
    "struggling": "Užduotis pagalbos reikalingiems su atraminiais pavyzdžiais."
  },
  "eDiaryEntry": {
    "classwork": "Klasės darbai įrašui.",
    "homework": "Namų darbai įrašui.",
    "notes": "Pastabos įrašui.",
    "thematicPlanning": "Tema iš plano.",
    "individualWork": "Individualus darbas."
  },
  "motivation": "Motyvuojanti žinutė."
}
Atsakyk TIK JSON formatu lietuvių kalba.`;

  const handleGenerate = async (prompt: string, isInitial: boolean) => {
      setIsLoading(true);
      setError(null);
      setAnalysisResult(null);

      try {
          // Fixed: Properly initialized GoogleGenAI with named parameter apiKey
          const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
          if (isInitial || !chatRef.current) {
              chatRef.current = ai.chats.create({
                  model: 'gemini-3-flash-preview',
                  config: { systemInstruction, responseMimeType: "application/json" },
              });
          }

          if (!chatRef.current) throw new Error("Nepavyko sukurti pokalbio.");

          const result = await chatRef.current.sendMessage({ message: prompt });
          // Fixed: result.text is a property, not a method
          const text = result.text.trim();
          const jsonString = text.replace(/```json|```/g, '').trim();
          const parsedPlan: LessonPlan = JSON.parse(jsonString);

          if (isInitial && lessonType) parsedPlan.lessonType = lessonType;

          setLessonPlan(parsedPlan);
          if (isInitial) {
            setActivePlanId(null);
            setPrivateComment('');
          }
      } catch (e: any) {
          setError(`Klaida generuojant planą: ${e.message}`);
          setLessonPlan(null);
      } finally {
          setIsLoading(false);
      }
  };

  const handleInitialSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Būtina nurodyti klasę, dalyką ir temą.');
      return;
    }

    let evaluationPrompt = '';
    if (evaluationDescription) {
        const finalEvalType = evaluationType === 'Kitas' && customEvaluationType ? customEvaluationType : evaluationType;
        evaluationPrompt = `\n- Vertinimo tipas: ${finalEvalType}\n- Vertinimo aprašymas: ${evaluationDescription}`;
    }

    const prompt = `Sukurk pamokos planą.
- Klasė: ${grade}
- Dalykas: ${subject}
- Pamokos tema: ${topic}
- Pamokos tipas: ${lessonType || 'Nenurodyta'}
${goal ? `- Pamokos tikslas: ${goal}` : ''}
${activities ? `- Papildomos idėjos: ${activities}` : ''}
${generalNotes ? `- Bendros pastabos: ${generalNotes}` : ''}${evaluationPrompt}
Užtikrink aiškų diferencijavimą.`;

    handleGenerate(prompt, true);
  };

  const handleRefinementSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      if (!refinement) return;
      handleGenerate(refinement, false);
      setRefinement('');
  }

  const handleDiaryOptionChange = (field: DiaryFieldKey, option: 'includeEmoji' | 'includeIntro', value: boolean) => {
    setDiaryFormatOptions(prev => ({ ...prev, [field]: { ...prev[field], [option]: value } }));
  };

  const formatDiaryEntry = (field: DiaryFieldKey, text: string): string => {
    if (!text) return '';
    const options = diaryFormatOptions[field];
    let formattedText = text;
    if (options.includeIntro) formattedText = `${DIARY_INTRO_PHRASES[field]}${formattedText}`;
    if (options.includeEmoji) formattedText = `${DIARY_EMOJIS[field]} ${formattedText}`;
    return formattedText;
  };

  const handleCopy = (rawText: string, fieldName: string) => {
    const formattedText = formatDiaryEntry(fieldName as DiaryFieldKey, rawText);
    navigator.clipboard.writeText(formattedText).then(() => {
        setCopiedField(fieldName);
        setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const handleCopyAllDiaryEntries = () => {
    if (!lessonPlan || !lessonPlan.eDiaryEntry) return;
    const entries = [
      formatDiaryEntry('classwork', lessonPlan.eDiaryEntry.classwork),
      formatDiaryEntry('homework', lessonPlan.eDiaryEntry.homework),
      formatDiaryEntry('notes', lessonPlan.eDiaryEntry.notes),
      formatDiaryEntry('thematicPlanning', lessonPlan.eDiaryEntry.thematicPlanning),
      formatDiaryEntry('individualWork', lessonPlan.eDiaryEntry.individualWork),
    ];
    const allEntriesText = entries.filter(Boolean).join('\n\n');
    navigator.clipboard.writeText(allEntriesText).then(() => {
        setIsAllCopied(true);
        setTimeout(() => setIsAllCopied(false), 2000);
    });
  };

  const confirmSavePlan = () => {
    if (!lessonPlan) return;
    const planTopic = lessonPlan.lessonOverview.topic || 'Neįvardinta tema';
    const date = new Date().toLocaleDateString('lt-LT');
    const title = `${subject || ''} ${grade || ''}: ${planTopic} (${date})`;
    const newPlan: SavedPlan = {
      id: `plan-${Date.now()}`,
      title,
      plan: lessonPlan,
      createdAt: new Date().toISOString(),
      grade,
      subject,
      lessonType: lessonPlan.lessonType || lessonType,
      comments: privateComment
    };
    setSavedPlans(prevPlans => [newPlan, ...prevPlans]);
    setActivePlanId(newPlan.id);
    setIsSaveModalOpen(false);
  };

  const handleOverwritePlan = () => {
    if (!activePlanId || !lessonPlan) return;
    setSavedPlans(prevPlans => prevPlans.map(p => {
      if (p.id === activePlanId) {
         return {
           ...p,
           plan: lessonPlan,
           comments: privateComment,
           lessonType: lessonPlan.lessonType || lessonType
         };
      }
      return p;
    }));
    setIsOverwriteModalOpen(false);
  };

  const handleLoadPlan = (planId: string) => {
    const planToLoad = savedPlans.find(p => p.id === planId);
    if (planToLoad) {
      setLessonPlan(planToLoad.plan);
      setActivePlanId(planToLoad.id);
      setPrivateComment(planToLoad.comments || '');
      setGrade(planToLoad.grade || '');
      setSubject(planToLoad.subject || '');
      setTopic(planToLoad.plan.lessonOverview.topic || '');
      setLessonType(planToLoad.lessonType || '');
    }
  };

  // Fixed error: Added missing handleDeletePlan function
  const handleDeletePlan = (id: string) => {
    setPlanToDelete(id);
    setIsDeleteModalOpen(true);
  };

  // Fixed error: Added missing confirmDeletePlan function
  const confirmDeletePlan = () => {
    if (!planToDelete) return;
    setSavedPlans(prevPlans => prevPlans.filter(p => p.id !== planToDelete));
    if (activePlanId === planToDelete) {
      setActivePlanId(null);
      setLessonPlan(null);
      setPrivateComment('');
    }
    setIsDeleteModalOpen(false);
    setPlanToDelete(null);
  };

  const handleAnalyzePlan = async () => {
    if (!lessonPlan) return;
    setIsAnalyzing(true);
    setAnalysisError(null);
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const analysisPrompt = `Išanalizuok šį pamokos planą kaip ekspertas pedagogas. Pateik JSON:
{ "summary": "vertinimas", "strengths": [], "weaknesses": [], "suggestions": [] }
Planą: ${JSON.stringify(lessonPlan)}`;
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: analysisPrompt,
            config: { 
              responseMimeType: 'application/json',
              responseSchema: {
                type: Type.OBJECT,
                properties: {
                  summary: { type: Type.STRING },
                  strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
                  weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
                  suggestions: { type: Type.ARRAY, items: { type: Type.STRING } }
                },
                required: ["summary", "strengths", "weaknesses", "suggestions"]
              }
            }
        });
        // Fixed: response.text is a property
        setAnalysisResult(JSON.parse(response.text || '{}'));
    } catch (e) {
        setAnalysisError("Nepavyko atlikti analizės.");
    } finally {
        setIsAnalyzing(false);
    }
  };

  const renderTextWithGlossaryTerms = (text: string) => {
    if (!text) return text;
    const terms = Object.keys(glossaryData);
    const regex = new RegExp(`\\b(${terms.join('|')})\\b`, 'gi');
    const parts = text.split(regex);
    return parts.map((part, index) => {
      const lowerCasePart = part.toLowerCase();
      const originalTerm = terms.find(term => term.toLowerCase() === lowerCasePart);
      if (originalTerm) {
        return (
          <span
            key={index}
            className="glossary-term"
            onClick={(e) => {
              e.stopPropagation();
              setSelectedTerm({ term: originalTerm, definition: glossaryData[originalTerm] })
            }}
          >
            {part}
          </span>
        );
      }
      return part;
    });
  };

  const renderFormattedText = (text: string) => {
    if (!text) return null;
    return text.split('\n').map((line, index) => (
      <React.Fragment key={index}>
        {renderTextWithGlossaryTerms(line)}
        <br />
      </React.Fragment>
    ));
  };

  const closeOnboarding = () => {
    setShowOnboarding(false);
    localStorage.setItem('onboardingComplete', 'true');
  };

  const lessonTypeOptions: LessonCategory[] = ['Įvadinė', 'Įtvirtinimo', 'Apibendrinamoji', 'Vertinamoji'];

  const filteredPlans = savedPlans.filter(plan => {
    const query = searchQuery.toLowerCase();
    return plan.title.toLowerCase().includes(query) || (plan.subject && plan.subject.toLowerCase().includes(query));
  });

  const handleUpdateNotes = (newNotes: string) => {
    if (!lessonPlan) return;
    setLessonPlan({ ...lessonPlan, generalNotes: newNotes });
  };

  const injectSuggestion = (suggestion: string) => {
    setActivities(prev => prev ? `${prev}\n- ${suggestion}` : `- ${suggestion}`);
  };

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>Jūsų pagalbininkas kūrybiškoms ir efektyvioms pamokoms</p>
        <div className="header-buttons">
            <button onClick={() => { setOnboardingStep(0); setShowOnboarding(true); }} className="external-link-button">Kaip naudotis?</button>
            <a href="https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos" target="_blank" rel="noopener noreferrer" className="external-link-button">BP nuoroda</a>
        </div>
      </header>
      <main className="main-content">
            <div className="form-container">
            <h2>Pamokos informacija</h2>
            <form onSubmit={handleInitialSubmit}>
                <div className="form-group">
                  <label>Pamokos tipas</label>
                  <select value={lessonType} onChange={(e) => setLessonType(e.target.value as LessonCategory)} style={{width: '100%', padding: '0.75rem', borderRadius: '8px', border: '1px solid var(--border-color)'}}>
                    <option value="">-- Pasirinkite tipą --</option>
                    {lessonTypeOptions.map(t => <option key={t} value={t}>{t}</option>)}
                  </select>
                </div>
                <div className="form-group">
                <label>Klasė / Grupė *</label>
                <input type="text" value={grade} onChange={(e) => setGrade(e.target.value)} placeholder="pvz., 5b klasė" required />
                </div>
                <div className="form-group">
                <label>Dalykas *</label>
                <input type="text" value={subject} onChange={(e) => setSubject(e.target.value)} placeholder="pvz., Matematika" required/>
                </div>
                <div className="form-group">
                <label>Pamokos tema *</label>
                <input type="text" value={topic} onChange={(e) => setTopic(e.target.value)} placeholder="pvz., Trupmenų sudėtis" required/>
                {activeSuggestions.length > 0 && (
                  <div className="suggestions-box" style={{marginTop: '0.5rem', display: 'flex', flexWrap: 'wrap', gap: '5px'}}>
                    <span style={{fontSize: '0.8rem', color: '#888', width: '100%'}}>Pasiūlymai:</span>
                    {activeSuggestions.map(s => (
                      <button key={s} type="button" onClick={() => injectSuggestion(s)} className="suggestion-pill" style={{fontSize: '0.75rem', padding: '2px 8px', borderRadius: '12px', background: '#e1f5fe', border: 'none', cursor: 'pointer'}}>{s}</button>
                    ))}
                  </div>
                )}
                </div>
                <div className="form-group">
                <label>Tikslas (nebūtina)</label>
                <textarea value={goal} onChange={(e) => setGoal(e.target.value)} placeholder="Mokiniai gebės..."></textarea>
                </div>
                <div className="form-group">
                <label>Veiklos idėjos (nebūtina)</label>
                <textarea value={activities} onChange={(e) => setActivities(e.target.value)} placeholder="pvz., darbas grupėse"></textarea>
                </div>
                <div className="form-group">
                    <label>Vertinimas</label>
                    <select value={evaluationType} onChange={(e) => setEvaluationType(e.target.value)} style={{width: '100%', marginBottom: '10px', padding: '0.75rem', borderRadius: '8px', border: '1px solid var(--border-color)'}}>
                        {['Formuojamasis', 'Kaupiamasis', 'Diagnostinis', 'Kitas'].map(opt => <option key={opt} value={opt}>{opt}</option>)}
                    </select>
                    <textarea value={evaluationDescription} onChange={(e) => setEvaluationDescription(e.target.value)} placeholder="Vertinimo detalės..."></textarea>
                </div>
                <button type="submit" disabled={isLoading} className="generate-button">
                  {isLoading && !lessonPlan ? <div className="spinner"></div> : null} Pateikti aprašą
                </button>
            </form>
            <div className="saved-plans-container">
                <h3>Išsaugoti planai</h3>
                <input type="text" placeholder="Ieškoti..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} className="search-input" />
                <ul className="saved-plans-list">
                    {filteredPlans.map(plan => (
                    <li key={plan.id} className={plan.id === activePlanId ? 'active' : ''} onClick={() => handleLoadPlan(plan.id)}>
                        <span className="plan-title">
                        {plan.title}
                        {plan.lessonType && <span className="type-tag" style={{fontSize: '0.7rem', color: 'var(--primary-color)', fontWeight: 'bold'}}>[{plan.lessonType}]</span>}
                        </span>
                        <button onClick={(e) => { e.stopPropagation(); handleDeletePlan(plan.id); }} className="delete-button">✖</button>
                    </li>
                    ))}
                </ul>
            </div>
            </div>

        <div className="results-container">
            {isLoading && !lessonPlan && <div className="loading-overlay"><div className="spinner-large"></div><p>Generuojama...</p></div>}
            {lessonPlan && (
                <>
                  <div className="export-container">
                    <button onClick={handleAnalyzePlan} disabled={isAnalyzing} className="analysis-button">Analizuoti 🔍</button>
                    <button onClick={() => activePlanId ? setIsOverwriteModalOpen(true) : setIsSaveModalOpen(true)} className="save-button">Išsaugoti 💾</button>
                  </div>
                  {analysisResult && (
                    <div className="card analysis-card">
                        <h3>Analizė</h3>
                        <p>{analysisResult.summary}</p>
                        {analysisResult.strengths?.length > 0 && (
                          <div style={{marginTop: '10px'}}>
                            <strong>Stiprybės:</strong>
                            <ul>{analysisResult.strengths.map((s, i) => <li key={i}>{s}</li>)}</ul>
                          </div>
                        )}
                        {analysisResult.suggestions?.length > 0 && (
                          <div style={{marginTop: '10px'}}>
                            <strong>Pasiūlymai:</strong>
                            <ul>{analysisResult.suggestions.map((s, i) => <li key={i}>{s}</li>)}</ul>
                          </div>
                        )}
                    </div>
                  )}
                  <div className="lesson-plan">
                      <div className="card general-notes-card">
                          <h3>📌 Bendros pastabos (Redaguojama)</h3>
                          <textarea 
                            value={lessonPlan.generalNotes} 
                            onChange={(e) => handleUpdateNotes(e.target.value)} 
                            className="notes-edit-area"
                            style={{width: '100%', minHeight: '80px', background: 'transparent', border: '1px dashed #ccc', padding: '10px', fontFamily: 'inherit'}}
                          />
                      </div>
                      <div className="card lesson-overview-card">
                          <h3>📖 Apžvalga [{lessonPlan.lessonType || lessonType}]</h3>
                          <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                          <p><strong>Tikslas:</strong> {renderFormattedText(lessonPlan.lessonOverview.goal)}</p>
                          <p><strong>Gebėjimai:</strong> {renderFormattedText(lessonPlan.lessonOverview.competencies)}</p>
                          <p><strong>Vertinimas:</strong> {renderFormattedText(lessonPlan.lessonOverview.evaluation)}</p>
                      </div>
                      <div className="card lesson-activities-card">
                          <h3>🎨 Veiklos</h3>
                          <p><strong>Gabesniems:</strong> {renderFormattedText(lessonPlan.lessonActivities.gifted)}</p>
                          <p><strong>Bendra:</strong> {renderFormattedText(lessonPlan.lessonActivities.general)}</p>
                          <p><strong>Pagalba:</strong> {renderFormattedText(lessonPlan.lessonActivities.struggling)}</p>
                      </div>
                      <div className="card homework-card">
                          <h3>📚 Namų darbai</h3>
                          <p><strong>Tikslas:</strong> {renderFormattedText(lessonPlan.homework.purpose)}</p>
                          <p><strong>Bendra:</strong> {renderFormattedText(lessonPlan.homework.general)}</p>
                          <p><strong>Pagalba:</strong> {renderFormattedText(lessonPlan.homework.struggling)}</p>
                      </div>
                      <div className="card motivation-card"><h3>💖 Ačiū</h3><p>{lessonPlan.motivation}</p></div>
                      {activePlanId && (
                        <div className="card private-comments-card">
                          <h3>📝 Pastabos {isCommentSaving && <span>...</span>}</h3>
                          <textarea value={privateComment} onChange={(e) => setPrivateComment(e.target.value)} className="comment-textarea" />
                        </div>
                      )}
                  </div>
                </>
            )}
        </div>
      </main>
      {selectedTerm && (
        <div className="modal-overlay" onClick={() => setSelectedTerm(null)}>
          <div className="modal-content glossary-modal" onClick={(e) => e.stopPropagation()}>
            <button className="modal-close-button" onClick={() => setSelectedTerm(null)}>&times;</button>
            <h3>{selectedTerm.term}</h3>
            <p>{selectedTerm.definition}</p>
          </div>
        </div>
      )}
      {isDeleteModalOpen && (
        <div className="modal-overlay" onClick={() => setIsDeleteModalOpen(false)}>
            <div className="modal-content delete-modal" onClick={(e) => e.stopPropagation()}>
                <p>Ar tikrai norite ištrinti šį planą?</p>
                <div style={{display: 'flex', justifyContent: 'flex-end', gap: '10px', marginTop: '1rem'}}>
                    <button onClick={() => setIsDeleteModalOpen(false)} className="button-secondary">Atšaukti</button>
                    <button onClick={confirmDeletePlan} className="button-danger">Ištrinti</button>
                </div>
            </div>
        </div>
      )}
      {isOverwriteModalOpen && (
        <div className="modal-overlay" onClick={() => setIsOverwriteModalOpen(false)}>
            <div className="modal-content" onClick={(e) => e.stopPropagation()}>
                <p>Ar tikrai norite perrašyti išsaugotą planą?</p>
                <div style={{display: 'flex', justifyContent: 'flex-end', gap: '10px', marginTop: '1rem'}}>
                    <button onClick={() => setIsOverwriteModalOpen(false)} className="button-secondary">Atšaukti</button>
                    <button onClick={handleOverwritePlan} className="button-primary">Perrašyti</button>
                </div>
            </div>
        </div>
      )}
      {isSaveModalOpen && (
        <div className="modal-overlay" onClick={() => setIsSaveModalOpen(false)}>
            <div className="modal-content" onClick={(e) => e.stopPropagation()}>
                <p>Ar norite išsaugoti šį naują planą?</p>
                <div style={{display: 'flex', justifyContent: 'flex-end', gap: '10px', marginTop: '1rem'}}>
                    <button onClick={() => setIsSaveModalOpen(false)} className="button-secondary">Atšaukti</button>
                    <button onClick={confirmSavePlan} className="button-primary">Išsaugoti</button>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

const container = document.getElementById('root');
const root = createRoot(container!);
root.render(<App />);

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';

interface EDiaryEntry {
  classwork: string;
  homework: string;
  notes: string;
  thematicPlanning: string;
  individualWork: string;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: string;
  };
  lessonActivities: {
    gifted: string;
    general: string;
    struggling: string;
    itTools?: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
}

interface AnalysisResult {
  summary: string;
  strengths: string[];
  weaknesses: string[];
  suggestions: string[];
}

const glossaryData: { [key: string]: string } = {
  'Diferencijuotos': 'Tai mokymo strategija, kai mokytojas pritaiko ugdymo turinį, procesą, aplinką ir vertinimą, atsižvelgdamas į skirtingus mokinių mokymosi poreikius, gebėjimus ir interesus.',
  'Diferencijuoti': 'Tai mokymo strategija, kai mokytojas pritaiko ugdymo turinį, procesą, aplinką ir vertinimą, atsižvelgdamas į skirtingus mokinių mokymosi poreikius, gebėjimus ir interesus.',
  'Formuojamasis vertinimas': 'Nuolatinis vertinimas pamokoje, skirtas stebėti mokinio pažangą, suprasti jo mokymosi sunkumus ir laiku suteikti pagalbą. Jo tikslas – gerinti mokymąsi, o ne rašyti pažymį.',
