  'Gebėjimai': 'Mokinio įgytos žinios ir įgūdžiai, leidžiantys jam sėkmingai atlikti tam tikras užduotis ar veiklas. Gebėjimai yra kompetencijų sudedamoji dalis.',
  'Scaffolding': 'Mokymosi pastoliai – paramos teikimas mokiniui, padedant jam atlikti užduotį, kurios jis pats dar negali įveikti.',
  'Metakognicija': 'Mąstymas apie savo mąstymo procesus, padedantis kontroliuoti ir vertinti savo mokymąsi.'
};

const topicSuggestions: { [key: string]: string[] } = {
  'matematika': ['Interaktyvūs uždaviniai', 'Matematiniai žaidimai', 'Uždavinių sprendimas porose', 'Geometrinių figūrų konstravimas'],
  'lietuvių': ['Kūrybinis rašymas', 'Teksto analizė grupėse', 'Debatai', 'Vaidmenų žaidimai'],
  'istorija': ['Laiko juostos kūrimas', 'Istorinių šaltinių analizė', 'Virtuali kelionė laiku', 'Diskusija apie priežastis ir pasekmes'],
  'gamta': ['Eksperimentų atlikimas', 'Stebėjimų dienoraštis', 'Gamtos objektų klasifikavimas', 'Aplinkosaugos projektas'],
};

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [generalNotes, setGeneralNotes] = useState('');
  const [refinement, setRefinement] = useState('');

  const [evaluationType, setEvaluationType] = useState('Formuojamasis');
  const [customEvaluationType, setCustomEvaluationType] = useState('');
  const [evaluationDescription, setEvaluationDescription] = useState('');

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [isAllCopied, setIsAllCopied] = useState(false);

  const [selectedTerm, setSelectedTerm] = useState<{ term: string; definition: string; } | null>(null);
  const [showOnboarding, setShowOnboarding] = useState(false);
  const [onboardingStep, setOnboardingStep] = useState(0);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [privateComment, setPrivateComment] = useState('');
  const [isCommentSaving, setIsCommentSaving] = useState(false);

  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [planToDelete, setPlanToDelete] = useState<string | null>(null);
  const [isOverwriteModalOpen, setIsOverwriteModalOpen] = useState(false);
  const [isSaveModalOpen, setIsSaveModalOpen] = useState(false);

  const [analysisResult, setAnalysisResult] = useState<AnalysisResult | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisError, setAnalysisError] = useState<string | null>(null);

  const [searchQuery, setSearchQuery] = useState('');
  const [sortOrder, setSortOrder] = useState<'date-desc' | 'date-asc' | 'title-asc' | 'title-desc'>('date-desc');
  const [activeSuggestions, setActiveSuggestions] = useState<string[]>([]);

  const [diaryFormatOptions, setDiaryFormatOptions] = useState({
    classwork: { includeEmoji: false, includeIntro: false },
    homework: { includeEmoji: false, includeIntro: false },
    notes: { includeEmoji: false, includeIntro: false },
    thematicPlanning: { includeEmoji: false, includeIntro: false },
    individualWork: { includeEmoji: false, includeIntro: false },
  });

  type DiaryFieldKey = keyof typeof diaryFormatOptions;

  const DIARY_EMOJIS: Record<DiaryFieldKey, string> = {
    classwork: '📚',
    homework: '🏡',
    notes: '📝',
    thematicPlanning: '🗓️',
    individualWork: '🧑‍🏫',
  };

  const DIARY_INTRO_PHRASES: Record<DiaryFieldKey, string> = {
    classwork: 'Šiandien pamokoje: ',
    homework: 'Namų darbai: ',
    notes: 'Svarbi informacija: ',
    thematicPlanning: 'Tema pagal ilgalaikį planą: ',
    individualWork: 'Pastabos apie individualų darbą: ',
  };

  const chatRef = useRef<Chat | null>(null);
  const commentSaveTimeoutRef = useRef<number | null>(null);

  useEffect(() => {
    const onboardingComplete = localStorage.getItem('onboardingComplete');
    if (!onboardingComplete) {
        setShowOnboarding(true);
    }

    try {
        const storedPlans = localStorage.getItem('savedLessonPlans');
        if (storedPlans) {
            setSavedPlans(JSON.parse(storedPlans));
        }
    } catch (error) {
        console.error("Nepavyko įkelti planų iš vietinės saugyklos:", error);
    }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (error) {
      console.error("Nepavyko išsaugoti planų vietinėje saugyloje:", error);
    }
  }, [savedPlans]);

  // Topic-based suggestions
  useEffect(() => {
    const lowerTopic = topic.toLowerCase();
    const lowerSubject = subject.toLowerCase();
    let found = false;
    for (const key in topicSuggestions) {
      if (lowerTopic.includes(key) || lowerSubject.includes(key)) {
        setActiveSuggestions(topicSuggestions[key]);
        found = true;
        break;
      }
    }
    if (!found) setActiveSuggestions([]);
  }, [topic, subject]);

  useEffect(() => {
    if (!activePlanId) return;

    setIsCommentSaving(true);
    if (commentSaveTimeoutRef.current) {
        clearTimeout(commentSaveTimeoutRef.current);
    }

    commentSaveTimeoutRef.current = window.setTimeout(() => {
        setSavedPlans(prevPlans => {
            const planIndex = prevPlans.findIndex(p => p.id === activePlanId);
            if (planIndex === -1) return prevPlans;

            const currentPlan = prevPlans[planIndex];
            if (currentPlan.comments === privateComment) return prevPlans;

            const updatedPlan = { ...currentPlan, comments: privateComment };
            const newPlans = [...prevPlans];
            newPlans[planIndex] = updatedPlan;
            return newPlans;
        });
        setIsCommentSaving(false);
    }, 500);

    return () => {
        if (commentSaveTimeoutRef.current) {
            clearTimeout(commentSaveTimeoutRef.current);
        }
    };
  }, [privateComment, activePlanId]);

  const systemInstruction = `Tu esi ekspertas pedagogas ir pamokų planavimo asistentas, puikiai išmanantis Lietuvos bendrąsias ugdymo programas. Tavo tikslas - padėti mokytojams kurti išsamius, strukturuotus ir diferencijuotus pamokų planus.
SVARBU: Atsižvelk į nurodytą pamokos tipą (Įvadinė, Įtvirtinimo, Apibendrinamoji, Vertinamoji) ir atitinkamai pritaikyk veiklas.

Atsakas privalo būti JSON formatu:
{
  "generalNotes": "Bendros pastabos, komentarai ar priminimai mokytojui.",
  "lessonType": "Pamokos tipas",
  "lessonOverview": {
    "topic": "Pamokos tema",
    "goal": "Pamokos tikslas ir uždaviniai",
    "competencies": "Pagrindiniai gebėjimai",
    "evaluation": "Vertinimo aprašymas"
  },
  "lessonActivities": {
    "gifted": "Veiklos gabesniems.",
    "general": "Veiklos bendro lygio mokiniams.",
    "struggling": "Veiklos pagalbos reikalingiems.",
    "itTools": "Rekomendacijos IT įrankiams."
  },
  "homework": {
    "purpose": "Namų darbų tikslas.",
    "gifted": "Užduotis gabesniems.",
    "general": "Užduotis bendram lygiui su žingsnis po žingsnio instrukcijomis.",
    "struggling": "Užduotis pagalbos reikalingiems su atraminiais pavyzdžiais."
  },
  "eDiaryEntry": {
    "classwork": "Klasės darbai įrašui.",
    "homework": "Namų darbai įrašui.",
    "notes": "Pastabos įrašui.",
    "thematicPlanning": "Tema iš plano.",
    "individualWork": "Individualus darbas."
  },
  "motivation": "Motyvuojanti žinutė."
}
Atsakyk TIK JSON formatu lietuvių kalba.`;

  const handleGenerate = async (prompt: string, isInitial: boolean) => {
      setIsLoading(true);
      setError(null);
      setAnalysisResult(null);

      try {
          const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
          if (isInitial || !chatRef.current) {
              chatRef.current = ai.chats.create({
                  model: 'gemini-3-flash-preview',
                  config: { systemInstruction, responseMimeType: "application/json" },
              });
          }

          if (!chatRef.current) throw new Error("Nepavyko sukurti pokalbio.");

          const result = await chatRef.current.sendMessage({ message: prompt });
          const text = result.text.trim();
          const jsonString = text.replace(/```json|```/g, '').trim();
          const parsedPlan: LessonPlan = JSON.parse(jsonString);

          if (isInitial && lessonType) parsedPlan.lessonType = lessonType;

          setLessonPlan(parsedPlan);
          if (isInitial) {
            setActivePlanId(null);
            setPrivateComment('');
          }
      } catch (e: any) {
          setError(`Klaida generuojant planą: ${e.message}`);
          setLessonPlan(null);
      } finally {
          setIsLoading(false);
      }
  };

  const handleInitialSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Būtina nurodyti klasę, dalyką ir temą.');
      return;
    }

    let evaluationPrompt = '';
    if (evaluationDescription) {
        const finalEvalType = evaluationType === 'Kitas' && customEvaluationType ? customEvaluationType : evaluationType;
        evaluationPrompt = `\n- Vertinimo tipas: ${finalEvalType}\n- Vertinimo aprašymas: ${evaluationDescription}`;
    }

    const prompt = `Sukurk pamokos planą.
- Klasė: ${grade}
- Dalykas: ${subject}
- Pamokos tema: ${topic}
- Pamokos tipas: ${lessonType || 'Nenurodyta'}
${goal ? `- Pamokos tikslas: ${goal}` : ''}
${activities ? `- Papildomos idėjos: ${activities}` : ''}
${generalNotes ? `- Bendros pastabos: ${generalNotes}` : ''}${evaluationPrompt}
Užtikrink aiškų diferencijavimą.`;

    handleGenerate(prompt, true);
  };

  const handleRefinementSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      if (!refinement) return;
      handleGenerate(refinement, false);
      setRefinement('');
  }

  const handleDiaryOptionChange = (field: DiaryFieldKey, option: 'includeEmoji' | 'includeIntro', value: boolean) => {
    setDiaryFormatOptions(prev => ({ ...prev, [field]: { ...prev[field], [option]: value } }));
  };

  const formatDiaryEntry = (field: DiaryFieldKey, text: string): string => {
    if (!text) return '';
    const options = diaryFormatOptions[field];
    let formattedText = text;
    if (options.includeIntro) formattedText = `${DIARY_INTRO_PHRASES[field]}${formattedText}`;
    if (options.includeEmoji) formattedText = `${DIARY_EMOJIS[field]} ${formattedText}`;
    return formattedText;
  };

  const handleCopy = (rawText: string, fieldName: string) => {
    const formattedText = formatDiaryEntry(fieldName as DiaryFieldKey, rawText);
    navigator.clipboard.writeText(formattedText).then(() => {
        setCopiedField(fieldName);
        setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const handleCopyAllDiaryEntries = () => {
    if (!lessonPlan || !lessonPlan.eDiaryEntry) return;
    const entries = [
      formatDiaryEntry('classwork', lessonPlan.eDiaryEntry.classwork),
      formatDiaryEntry('homework', lessonPlan.eDiaryEntry.homework),
      formatDiaryEntry('notes', lessonPlan.eDiaryEntry.notes),
      formatDiaryEntry('thematicPlanning', lessonPlan.eDiaryEntry.thematicPlanning),
      formatDiaryEntry('individualWork', lessonPlan.eDiaryEntry.individualWork),
    ];
    const allEntriesText = entries.filter(Boolean).join('\n\n');
    navigator.clipboard.writeText(allEntriesText).then(() => {
        setIsAllCopied(true);
        setTimeout(() => setIsAllCopied(false), 2000);
    });
  };

  const confirmSavePlan = () => {
    if (!lessonPlan) return;
    const planTopic = lessonPlan.lessonOverview.topic || 'Neįvardinta tema';
    const date = new Date().toLocaleDateString('lt-LT');
    const title = `${subject || ''} ${grade || ''}: ${planTopic} (${date})`;
    const newPlan: SavedPlan = {
      id: `plan-${Date.now()}`,
      title,
      plan: lessonPlan,
      createdAt: new Date().toISOString(),
      grade,
      subject,
      lessonType: lessonPlan.lessonType || lessonType,
      comments: privateComment
    };
    setSavedPlans(prevPlans => [newPlan, ...prevPlans]);
    setActivePlanId(newPlan.id);
    setIsSaveModalOpen(false);
  };

  const handleOverwritePlan = () => {
    if (!activePlanId || !lessonPlan) return;
    setSavedPlans(prevPlans => prevPlans.map(p => {
      if (p.id === activePlanId) {
         return {
           ...p,
           plan: lessonPlan,
           comments: privateComment,
           lessonType: lessonPlan.lessonType || lessonType
         };
      }
      return p;
    }));
    setIsOverwriteModalOpen(false);
  };

  const handleLoadPlan = (planId: string) => {
    const planToLoad = savedPlans.find(p => p.id === planId);
    if (planToLoad) {
      setLessonPlan(planToLoad.plan);
      setActivePlanId(planToLoad.id);
      setPrivateComment(planToLoad.comments || '');
      setGrade(planToLoad.grade || '');
      setSubject(planToLoad.subject || '');
      setTopic(planToLoad.plan.lessonOverview.topic || '');
      setLessonType(planToLoad.lessonType || '');
    }
  };

  const handleDeletePlan = (id: string) => {
    setPlanToDelete(id);
    setIsDeleteModalOpen(true);
  };

  const confirmDeletePlan = () => {
    if (!planToDelete) return;
    setSavedPlans(prevPlans => prevPlans.filter(p => p.id !== planToDelete));
    if (activePlanId === planToDelete) {
      setActivePlanId(null);
      setLessonPlan(null);
      setPrivateComment('');
    }
    setIsDeleteModalOpen(false);
    setPlanToDelete(null);
  };

  const handleAnalyzePlan = async () => {
    if (!lessonPlan) return;
    setIsAnalyzing(true);
    setAnalysisError(null);
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const analysisPrompt = `Išanalizuok šį pamokos planą kaip ekspertas pedagogas. Pateik JSON:
{ "summary": "vertinimas", "strengths": [], "weaknesses": [], "suggestions": [] }
Planą: ${JSON.stringify(lessonPlan)}`;
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: analysisPrompt,
            config: { 
              responseMimeType: 'application/json',
              responseSchema: {
                type: Type.OBJECT,
                properties: {
                  summary: { type: Type.STRING },
                  strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
                  weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
                  suggestions: { type: Type.ARRAY, items: { type: Type.STRING } }
                },
                required: ["summary", "strengths", "weaknesses", "suggestions"]
              }
            }
        });
        setAnalysisResult(JSON.parse(response.text || '{}'));
    } catch (e) {
        setAnalysisError("Nepavyko atlikti analizės.");
    } finally {
        setIsAnalyzing(false);
    }
  };

  const renderTextWithGlossaryTerms = (text: string) => {
    if (!text) return text;
    const terms = Object.keys(glossaryData);
    const regex = new RegExp(`\\b(${terms.join('|')})\\b`, 'gi');
    const parts = text.split(regex);
    return parts.map((part, index) => {
      const lowerCasePart = part.toLowerCase();
      const originalTerm = terms.find(term => term.toLowerCase() === lowerCasePart);
      if (originalTerm) {
        return (
          <span
            key={index}
            className="glossary-term"
            onClick={(e) => {
              e.stopPropagation();
              setSelectedTerm({ term: originalTerm, definition: glossaryData[originalTerm] })
            }}
          >
            {part}
          </span>
        );
      }
      return part;
    });
  };

  const renderFormattedText = (text: string) => {
    if (!text) return null;
    return text.split('\n').map((line, index) => (
      <React.Fragment key={index}>
        {renderTextWithGlossaryTerms(line)}
        <br />
      </React.Fragment>
    ));
  };

  const closeOnboarding = () => {
    setShowOnboarding(false);
    localStorage.setItem('onboardingComplete', 'true');
  };

  const lessonTypeOptions: LessonCategory[] = ['Įvadinė', 'Įtvirtinimo', 'Apibendrinamoji', 'Vertinamoji'];

  const filteredAndSortedPlans = savedPlans
    .filter(plan => {
      const query = searchQuery.toLowerCase();
      return plan.title.toLowerCase().includes(query) || (plan.subject && plan.subject.toLowerCase().includes(query));
    })
    .sort((a, b) => {
      if (sortOrder === 'date-desc') return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
      if (sortOrder === 'date-asc') return new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime();
      if (sortOrder === 'title-asc') return a.title.localeCompare(b.title);
      if (sortOrder === 'title-desc') return b.title.localeCompare(a.title);
      return 0;
    });

  const handleUpdateNotes = (newNotes: string) => {
    if (!lessonPlan) return;
    setLessonPlan({ ...lessonPlan, generalNotes: newNotes });
  };

  const injectSuggestion = (suggestion: string) => {
    setActivities(prev => prev ? `${prev}\n- ${suggestion}` : `- ${suggestion}`);
  };

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>Jūsų pagalbininkas kūrybiškoms ir efektyvioms pamokoms</p>
        <div className="header-buttons">
            <button onClick={() => { setOnboardingStep(0); setShowOnboarding(true); }} className="external-link-button">Kaip naudotis?</button>
            <a href="https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos" target="_blank" rel="noopener noreferrer" className="external-link-button">BP nuoroda</a>
        </div>
      </header>
      <main className="main-content">
            <div className="form-container">
            <h2>Pamokos informacija</h2>
            <form onSubmit={handleInitialSubmit}>
                <div className="form-group">
                  <label>Pamokos tipas</label>
                  <select value={lessonType} onChange={(e) => setLessonType(e.target.value as LessonCategory)} style={{width: '100%', padding: '0.75rem', borderRadius: '8px', border: '1px solid var(--border-color)'}}>
                    <option value="">-- Pasirinkite tipą --</option>
                    {lessonTypeOptions.map(t => <option key={t} value={t}>{t}</option>)}
                  </select>
                </div>
                <div className="form-group">
                <label>Klasė / Grupė *</label>
                <input type="text" value={grade} onChange={(e) => setGrade(e.target.value)} placeholder="pvz., 5b klasė" required />
                </div>
                <div className="form-group">
                <label>Dalykas *</label>
                <input type="text" value={subject} onChange={(e) => setSubject(e.target.value)} placeholder="pvz., Matematika" required/>
                </div>
                <div className="form-group">
                <label>Pamokos tema *</label>
                <input type="text" value={topic} onChange={(e) => setTopic(e.target.value)} placeholder="pvz., Trupmenų sudėtis" required/>
                {activeSuggestions.length > 0 && (
                  <div className="suggestions-box" style={{marginTop: '0.5rem', display: 'flex', flexWrap: 'wrap', gap: '5px'}}>
                    <span style={{fontSize: '0.8rem', color: '#888', width: '100%'}}>Pasiūlymai:</span>
                    {activeSuggestions.map(s => (
                      <button key={s} type="button" onClick={() => injectSuggestion(s)} className="suggestion-pill" style={{fontSize: '0.75rem', padding: '2px 8px', borderRadius: '12px', background: '#e1f5fe', border: 'none', cursor: 'pointer'}}>{s}</button>
                    ))}
                  </div>
                )}
                </div>
                <div className="form-group">
                <label>Tikslas (nebūtina)</label>
                <textarea value={goal} onChange={(e) => setGoal(e.target.value)} placeholder="Mokiniai gebės..."></textarea>
                </div>
                <div className="form-group">
                <label>Veiklos idėjos (nebūtina)</label>
                <textarea value={activities} onChange={(e) => setActivities(e.target.value)} placeholder="pvz., darbas grupėse"></textarea>
                </div>
                <div className="form-group">
                    <label>Vertinimas</label>
                    <select value={evaluationType} onChange={(e) => setEvaluationType(e.target.value)} style={{width: '100%', marginBottom: '10px', padding: '0.75rem', borderRadius: '8px', border: '1px solid var(--border-color)'}}>
                        {['Formuojamasis', 'Kaupiamasis', 'Diagnostinis', 'Kitas'].map(opt => <option key={opt} value={opt}>{opt}</option>)}
                    </select>
                    <textarea value={evaluationDescription} onChange={(e) => setEvaluationDescription(e.target.value)} placeholder="Vertinimo detalės..."></textarea>
                </div>
                <button type="submit" disabled={isLoading} className="generate-button">
                  {isLoading && !lessonPlan ? <div className="spinner"></div> : null} Pateikti aprašą
                </button>
            </form>
            <div className="saved-plans-container">
                <h3>Išsaugoti planai</h3>
                <div className="search-and-sort" style={{display: 'flex', gap: '10px', marginBottom: '10px', flexDirection: 'column'}}>
                  <input type="text" placeholder="Ieškoti..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} className="search-input" />
                  <select 
                    value={sortOrder} 
                    onChange={(e) => setSortOrder(e.target.value as any)} 
                    className="search-input"
                    style={{padding: '8px'}}
                  >
                    <option value="date-desc">Naujausi viršuje</option>
                    <option value="date-asc">Seniausi viršuje</option>
                    <option value="title-asc">Pavadinimas A-Z</option>
                    <option value="title-desc">Pavadinimas Z-A</option>
                  </select>
                </div>
                <ul className="saved-plans-list">
                    {filteredAndSortedPlans.map(plan => (
                    <li key={plan.id} className={plan.id === activePlanId ? 'active' : ''} onClick={() => handleLoadPlan(plan.id)}>
                        <span className="plan-title">
                        {plan.title}
                        {plan.lessonType && <span className="type-tag" style={{fontSize: '0.7rem', color: 'var(--primary-color)', fontWeight: 'bold'}}>[{plan.lessonType}]</span>}
                        </span>
                        <button onClick={(e) => { e.stopPropagation(); handleDeletePlan(plan.id); }} className="delete-button">✖</button>
                    </li>
                    ))}
                </ul>
            </div>
            </div>

        <div className="results-container">
            {isLoading && !lessonPlan && <div className="loading-overlay"><div className="spinner-large"></div><p>Generuojama...</p></div>}
            {lessonPlan && (
                <>
                  <div className="export-container">
                    <button onClick={handleAnalyzePlan} disabled={isAnalyzing} className="analysis-button">Analizuoti 🔍</button>
                    <button onClick={() => activePlanId ? setIsOverwriteModalOpen(true) : setIsSaveModalOpen(true)} className="save-button">Išsaugoti 💾</button>
                  </div>
                  {analysisResult && (
                    <div className="card analysis-card">
                        <h3>Analizė</h3>
                        <p>{analysisResult.summary}</p>
                        {analysisResult.strengths?.length > 0 && (
                          <div style={{marginTop: '10px'}}>
                            <strong>Stiprybės:</strong>
                            <ul>{analysisResult.strengths.map((s, i) => <li key={i}>{s}</li>)}</ul>
                          </div>
                        )}
                        {analysisResult.suggestions?.length > 0 && (
                          <div style={{marginTop: '10px'}}>
                            <strong>Pasiūlymai:</strong>
                            <ul>{analysisResult.suggestions.map((s, i) => <li key={i}>{s}</li>)}</ul>
                          </div>
                        )}
                    </div>
                  )}
                  <div className="lesson-plan">
                      <div className="card general-notes-card">
                          <h3>📌 Bendros pastabos (Redaguojama)</h3>
                          <textarea 
                            value={lessonPlan.generalNotes} 
                            onChange={(e) => handleUpdateNotes(e.target.value)} 
                            className="notes-edit-area"
                            style={{width: '100%', minHeight: '80px', background: 'transparent', border: '1px dashed #ccc', padding: '10px', fontFamily: 'inherit'}}
                          />
                      </div>
                      <div className="card lesson-overview-card">
                          <h3>📖 Apžvalga [{lessonPlan.lessonType || lessonType}]</h3>
                          <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                          <p><strong>Tikslas:</strong> {renderFormattedText(lessonPlan.lessonOverview.goal)}</p>
                          <p><strong>Gebėjimai:</strong> {renderFormattedText(lessonPlan.lessonOverview.competencies)}</p>
                          <p><strong>Vertinimas:</strong> {renderFormattedText(lessonPlan.lessonOverview.evaluation)}</p>
                      </div>
                      <div className="card lesson-activities-card">
                          <h3>🎨 Veiklos</h3>
                          <p><strong>Gabesniems:</strong> {renderFormattedText(lessonPlan.lessonActivities.gifted)}</p>
                          <p><strong>Bendra:</strong> {renderFormattedText(lessonPlan.lessonActivities.general)}</p>
                          <p><strong>Pagalba:</strong> {renderFormattedText(lessonPlan.lessonActivities.struggling)}</p>
                      </div>
                      <div className="card homework-card">
                          <h3>📚 Namų darbai</h3>
                          <p><strong>Tikslas:</strong> {renderFormattedText(lessonPlan.homework.purpose)}</p>
                          <p><strong>Bendra:</strong> {renderFormattedText(lessonPlan.homework.general)}</p>
                          <p><strong>Pagalba:</strong> {renderFormattedText(lessonPlan.homework.struggling)}</p>
                      </div>
                      <div className="card motivation-card"><h3>💖 Ačiū</h3><p>{lessonPlan.motivation}</p></div>
                      {activePlanId && (
                        <div className="card private-comments-card">
                          <h3>📝 Pastabos {isCommentSaving && <span>...</span>}</h3>
                          <textarea value={privateComment} onChange={(e) => setPrivateComment(e.target.value)} className="comment-textarea" />
                        </div>
                      )}
                  </div>
                </>
            )}
        </div>
      </main>
      {selectedTerm && (
        <div className="modal-overlay" onClick={() => setSelectedTerm(null)}>
          <div className="modal-content glossary-modal" onClick={(e) => e.stopPropagation()}>
            <button className="modal-close-button" onClick={() => setSelectedTerm(null)}>&times;</button>
            <h3>{selectedTerm.term}</h3>
            <p>{selectedTerm.definition}</p>
          </div>
        </div>
      )}
      {isDeleteModalOpen && (
        <div className="modal-overlay" onClick={() => setIsDeleteModalOpen(false)}>
            <div className="modal-content delete-modal" onClick={(e) => e.stopPropagation()}>
                <p>Ar tikrai norite ištrinti šį planą?</p>
                <div style={{display: 'flex', justifyContent: 'flex-end', gap: '10px', marginTop: '1rem'}}>
                    <button onClick={() => setIsDeleteModalOpen(false)} className="button-secondary">Atšaukti</button>
                    <button onClick={confirmDeletePlan} className="button-danger">Ištrinti</button>
                </div>
            </div>
        </div>
      )}
      {isOverwriteModalOpen && (
        <div className="modal-overlay" onClick={() => setIsOverwriteModalOpen(false)}>
            <div className="modal-content" onClick={(e) => e.stopPropagation()}>
                <p>Ar tikrai norite perrašyti išsaugotą planą?</p>
                <div style={{display: 'flex', justifyContent: 'flex-end', gap: '10px', marginTop: '1rem'}}>
                    <button onClick={() => setIsOverwriteModalOpen(false)} className="button-secondary">Atšaukti</button>
                    <button onClick={handleOverwritePlan} className="button-primary">Perrašyti</button>
                </div>
            </div>
        </div>
      )}
      {isSaveModalOpen && (
        <div className="modal-overlay" onClick={() => setIsSaveModalOpen(false)}>
            <div className="modal-content" onClick={(e) => e.stopPropagation()}>
                <p>Ar norite išsaugoti šį naują planą?</p>
                <div style={{display: 'flex', justifyContent: 'flex-end', gap: '10px', marginTop: '1rem'}}>
                    <button onClick={() => setIsSaveModalOpen(false)} className="button-secondary">Atšaukti</button>
                    <button onClick={confirmSavePlan} className="button-primary">Išsaugoti</button>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

const container = document.getElementById('root');
const root = createRoot(container!);
root.render(<App />);

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: string;
  };
  lessonActivities: {
    gifted: string;
    general: string;
    struggling: string;
    itTools?: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
}

interface AnalysisResult {
  summary: string;
  strengths: string[];
  weaknesses: string[];
  suggestions: string[];
}

const glossaryData: { [key: string]: string } = {
  'Diferencijuotos': 'Tai mokymo strategija, kai mokytojas pritaiko ugdymo turinį, procesą, aplinką ir vertinimą, atsižvelgdamas į skirtingus mokinių mokymosi poreikius, gebėjimus ir interesus.',
  'Formuojamasis vertinimas': 'Nuolatinis vertinimas pamokoje, skirtas stebėti mokinio pažangą, suprasti jo mokymosi sunkumus.',
  'Kaupiamasis vertinimas': 'Vertinimo būdas, kai per tam tikrą laikotarpį surinkti įrodymai sumuojami į vieną bendrą įvertinimą.',
  'Diagnostinis vertinimas': 'Vertinimas, atliekamas temos pradžioje, siekiant nustatyti esamas mokinių žinias.',
  'Kompetencijos': 'Gebėjimas atlikti tam tikrą veiklą, remiantis žiniomis, įgūdžiais ir vertybėmis.',
  'Scaffolding': 'Mokymosi pastoliai – paramos teikimas mokiniui, padedant jam atlikti sudėtingą užduotį.'
};

const topicSuggestions: { [key: string]: string[] } = {
  'matematika': ['Interaktyvūs uždaviniai', 'Matematiniai žaidimai', 'Uždavinių sprendimas porose'],
  'lietuvių': ['Kūrybinis rašymas', 'Teksto analizė grupėse', 'Debatai'],
  'istorija': ['Laiko juostos kūrimas', 'Istorinių šaltinių analizė', 'Virtuali kelionė'],
  'gamta': ['Eksperimentų atlikimas', 'Stebėjimų dienoraštis', 'Projektas'],
};

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [generalNotes, setGeneralNotes] = useState('');
  const [refinement, setRefinement] = useState('');

  const [evaluationType, setEvaluationType] = useState(EVALUATION_TAGS[0]);
  const [evaluationDescription, setEvaluationDescription] = useState('');

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [isAllCopied, setIsAllCopied] = useState(false);

  const [selectedTerm, setSelectedTerm] = useState<{ term: string; definition: string; } | null>(null);
  const [showOnboarding, setShowOnboarding] = useState(false);
  const [onboardingStep, setOnboardingStep] = useState(0);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [privateComment, setPrivateComment] = useState('');
  const [isCommentSaving, setIsCommentSaving] = useState(false);

  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [planToDelete, setPlanToDelete] = useState<string | null>(null);
  const [isOverwriteModalOpen, setIsOverwriteModalOpen] = useState(false);
  const [isSaveModalOpen, setIsSaveModalOpen] = useState(false);

  const [analysisResult, setAnalysisResult] = useState<AnalysisResult | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisError, setAnalysisError] = useState<string | null>(null);

