      {isSaveModalOpen && (
        <div className="modal-overlay">
          <div className="modal-content">
            <p>Išsaugoti kaip naują planą?</p>
            <div className="modal-actions">
              <button onClick={() => setIsSaveModalOpen(false)} className="button-secondary">Atšaukti</button>
              <button onClick={confirmSavePlan} className="button-primary">Išsaugoti</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

