        contents: prompt,
        config: { responseMimeType: "application/json" }
      });
      setAnalysisResult(JSON.parse(res.text));
    } catch (e) { setAnalysisError("Analizė nepavyko."); }
    finally { setIsAnalyzing(false); }
  };

  const filteredAndSortedPlans = savedPlans
    .filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase()))
    .sort((a, b) => {
      if (sortOrder === 'date-desc') return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
      if (sortOrder === 'title-asc') return a.title.localeCompare(b.title);
      return 0;
    });

