              </div>

              {analysisResult && (
                <div className="card analysis-card">
                  <h3>🔍 Analizė</h3>
                  <p>{analysisResult.summary}</p>
                </div>
              )}

              <div className="lesson-plan">
                <div className="card general-notes-card">
                  <h3>📌 Bendros pastabos (Redaguojama)</h3>
                  <textarea value={lessonPlan.generalNotes} onChange={e => handleUpdateNotes(e.target.value)} className="notes-edit-area" style={{width: '100%', minHeight: '100px', padding: '10px'}} />
                </div>

                <div className="card lesson-overview-card">
                  <h3>📖 Apžvalga</h3>
                  <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                  <p><strong>Tikslas:</strong> {lessonPlan.lessonOverview.goal}</p>
                  <p><strong>Gebėjimai:</strong> {lessonPlan.lessonOverview.competencies}</p>
                  <p><strong>Vertinimas:</strong> {lessonPlan.lessonOverview.evaluation}</p>
