                        <label>{f.label}:</label>
                        <div className="diary-field">
                          <p>{f.val || '---'}</p>
                          <button onClick={() => handleCopy(f.val, f.id)} className={`copy-button ${copiedField === f.id ? 'copied' : ''}`}>
                            {copiedField === f.id ? "Nukopijuota" : "Kopijuoti"}
                          </button>
                        </div>
                      </div>
                    ))}
                  </div>
                )}

                <div className="card motivation-card">
                  <h3>💖 Motyvacija</h3>
                  <p>{lessonPlan.motivation}</p>
                </div>
              </div>
            </>
          )}
        </div>
      </main>

      {isDeleteModalOpen && (
        <div className="modal-overlay">
          <div className="modal-content delete-modal">
            <p>Ar tikrai norite ištrinti?</p>
            <div className="modal-actions">
              <button onClick={() => setIsDeleteModalOpen(false)} className="button-secondary">Atšaukti</button>
              <button onClick={confirmDeletePlan} className="button-danger">Ištrinti</button>
            </div>
          </div>
        </div>
      )}

      {isSaveModalOpen && (
        <div className="modal-overlay">
          <div className="modal-content">
            <p>Išsaugoti kaip naują planą?</p>
            <div className="modal-actions">
              <button onClick={() => setIsSaveModalOpen(false)} className="button-secondary">Atšaukti</button>
              <button onClick={confirmSavePlan} className="button-primary">Išsaugoti</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useRef, useEffect } from 'react';
