    let found = false;
    for (const key in topicSuggestions) {
      if (lowerTopic.includes(key) || lowerSubject.includes(key)) {
        setActiveSuggestions(topicSuggestions[key]);
        found = true;
        break;
      }
    }
    if (!found) setActiveSuggestions([]);
  }, [topic, subject]);

  const systemInstruction = `Tu esi ekspertas pedagogas. Sukurk išsamų pamokos planą JSON formatu. 
SVARBU: Atsižvelk į Lietuvos bendrąsias programas. Jei vartotojas nurodė specifinius pedagoginius iššūkius ar mokinių poreikius, pateik konkrečius, patirtimi grįstus patarimus 'consultationAdvice' lauke.

Struktūra:
{
