  "consultationAdvice": "Patarimai dėl nurodytų pedagoginių iššūkių ar specifinių poreikių (jei nurodyta)",
  "motivation": "Motyvacija"
}
Atsakyk tik JSON.`;

  const handleGenerate = async (prompt: string, isInitial: boolean) => {
