    }
    const prompt = `Pamoka: ${subject}, ${grade}. Tema: ${topic}. Tipas: ${lessonType}. Vertinimas: ${evaluationType}. Aprašymas: ${evaluationDescription}. Papildomai: ${activities}. Tikslas: ${goal}. Pastabos: ${generalNotes}. Pedagoginiai iššūkiai/poreikiai: ${consultationChallenges}.`;
