      const prompt = `Išanalizuok pamokos planą. Atsakyk JSON: { "summary": "", "strengths": [], "weaknesses": [], "suggestions": [] }. Planas: ${JSON.stringify(lessonPlan)}`;
      const res = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { responseMimeType: "application/json" }
      });
      setAnalysisResult(JSON.parse(res.text));
    } catch (e) { setAnalysisError("Analizė nepavyko."); }
    finally { setIsAnalyzing(false); }
