            <button type="submit" disabled={isLoading} className="generate-button">
              {isLoading ? <div className="spinner"></div> : "Generuoti planą"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" style={{marginBottom: '10px'}} />
            <ul className="saved-plans-list">
              {filteredAndSortedPlans.map(p => (
                <li key={p.id} onClick={() => handleLoadPlan(p.id)} className={activePlanId === p.id ? 'active' : ''}>
                  <span className="plan-title">{p.title}</span>
                  <button onClick={e => { e.stopPropagation(); handleDeletePlan(p.id); }} className="delete-button">✖</button>
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && !lessonPlan && <div className="loading-overlay"><div className="spinner-large"></div><p>Generuojama...</p></div>}
          {error && <div className="error-message">{error}</div>}

          {lessonPlan && (
            <>
              <div className="export-container">
                <button onClick={handleAnalyzePlan} disabled={isAnalyzing} className="analysis-button">Analizuoti 🔍</button>
                <button onClick={() => activePlanId ? setIsOverwriteModalOpen(true) : setIsSaveModalOpen(true)} className="save-button">Išsaugoti 💾</button>
              </div>

              {analysisResult && (
                <div className="card analysis-card">
                  <h3>🔍 Analizė</h3>
                  <p>{analysisResult.summary}</p>
                </div>
              )}

              <div className="lesson-plan">
                {lessonPlan.consultationAdvice && (
                  <div className="card consultation-card" style={{borderLeftColor: 'var(--info-color)', backgroundColor: 'var(--info-color-light)'}}>
                    <h3>💡 Pedagoginė konsultacija</h3>
                    <p>{lessonPlan.consultationAdvice}</p>
                  </div>
                )}

                <div className="card general-notes-card">
                  <h3>📌 Bendros pastabos (Redaguojama)</h3>
                  <textarea value={lessonPlan.generalNotes} onChange={e => handleUpdateNotes(e.target.value)} className="notes-edit-area" style={{width: '100%', minHeight: '100px', padding: '10px'}} />
                </div>

                <div className="card lesson-overview-card">
                  <h3>📖 Apžvalga</h3>
                  <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                  <p><strong>Tikslas:</strong> {lessonPlan.lessonOverview.goal}</p>
                  <p><strong>Gebėjimai:</strong> {lessonPlan.lessonOverview.competencies}</p>
                  <p><strong>Vertinimas:</strong> {lessonPlan.lessonOverview.evaluation}</p>
                </div>

                <div className="card lesson-activities-card">
                  <h3>🎨 Veiklos</h3>
                  <p><strong>🙂 Bendra:</strong> {lessonPlan.lessonActivities.general}</p>
                  <p><strong>🚀 Gabesniems:</strong> {lessonPlan.lessonActivities.gifted}</p>
                  <p><strong>🌱 Pagalba:</strong> {lessonPlan.lessonActivities.struggling}</p>
                </div>

                {lessonPlan.eDiaryEntry && (
                  <div className="card ediary-card" style={{borderLeftColor: 'var(--secondary-color)', backgroundColor: 'var(--primary-color-light)'}}>
                    <h3>✍️ El. dienyno įrašai</h3>
                    <div style={{display: 'flex', gap: '15px', marginBottom: '15px'}}>
                      <label style={{display: 'flex', alignItems: 'center', gap: '5px', fontSize: '0.9rem'}}>
                        <input type="checkbox" checked={lessonPlan.eDiaryEntry.isIntegrated} readOnly /> Integruota pamoka
                      </label>
                      <label style={{display: 'flex', alignItems: 'center', gap: '5px', fontSize: '0.9rem'}}>
                        <input type="checkbox" checked={lessonPlan.eDiaryEntry.isOutside} readOnly /> Pamoka už mokyklos ribų
                      </label>
                    </div>

                    {[
                      { label: "Tema, klasės darbai, pasiekimai", val: lessonPlan.eDiaryEntry.topicClassworkExpectations, id: 'diary-topic' },
                      { label: "Namų darbai", val: lessonPlan.eDiaryEntry.homework, id: 'diary-hw' },
                      { label: "Individualūs namų darbai", val: lessonPlan.eDiaryEntry.individualHomework, id: 'diary-ind-hw' },
                      { label: "Pastabos apie pamoką", val: lessonPlan.eDiaryEntry.notes, id: 'diary-notes' }
                    ].map(f => (
                      <div key={f.id} className="diary-entry">
                        <label>{f.label}:</label>
                        <div className="diary-field">
                          <p>{f.val || '---'}</p>
                          <button onClick={() => handleCopy(f.val, f.id)} className={`copy-button ${copiedField === f.id ? 'copied' : ''}`}>
                            {copiedField === f.id ? "Nukopijuota" : "Kopijuoti"}
                          </button>
                        </div>
                      </div>
                    ))}
                  </div>
                )}

                <div className="card motivation-card">
                  <h3>💖 Motyvacija</h3>
                  <p>{lessonPlan.motivation}</p>
                </div>
              </div>
            </>
          )}
        </div>
      </main>

      {isDeleteModalOpen && (
        <div className="modal-overlay">
          <div className="modal-content delete-modal">
            <p>Ar tikrai norite ištrinti?</p>
            <div className="modal-actions">
              <button onClick={() => setIsDeleteModalOpen(false)} className="button-secondary">Atšaukti</button>
              <button onClick={confirmDeletePlan} className="button-danger">Ištrinti</button>
            </div>
          </div>
        </div>
      )}

      {isSaveModalOpen && (
        <div className="modal-overlay">
          <div className="modal-content">
            <p>Išsaugoti kaip naują planą?</p>
            <div className="modal-actions">
              <button onClick={() => setIsSaveModalOpen(false)} className="button-secondary">Atšaukti</button>
              <button onClick={confirmSavePlan} className="button-primary">Išsaugoti</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: string;
  };
  lessonActivities: {
    gifted: string;
    general: string;
    struggling: string;
    itTools?: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  consultationAdvice?: string;
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
}

const topicSuggestions: { [key: string]: string[] } = {
  'matematika': ['Interaktyvūs uždaviniai', 'Matematiniai žaidimai', 'Uždavinių sprendimas porose'],
  'lietuvių': ['Kūrybinis rašymas', 'Teksto analizė grupėse', 'Debatai'],
  'istorija': ['Laiko juostos kūrimas', 'Istorinių šaltinių analizė', 'Virtuali kelionė'],
  'gamta': ['Eksperimentų atlikimas', 'Stebėjimų dienoraštis', 'Projektas'],
};

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [consultationChallenges, setConsultationChallenges] = useState('');
  const [isIntegratedInput, setIsIntegratedInput] = useState(false);
  const [isOutsideInput, setIsOutsideInput] = useState(false);
  const [generalNotes, setGeneralNotes] = useState('');

  const [evaluationType, setEvaluationType] = useState(EVALUATION_TAGS[0]);
  const [evaluationDescription, setEvaluationDescription] = useState('');

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [activeSuggestions, setActiveSuggestions] = useState<string[]>([]);

  const chatRef = useRef<Chat | null>(null);

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  useEffect(() => {
    const lowerTopic = topic.toLowerCase();
    const lowerSubject = subject.toLowerCase();
    let found = false;
    for (const key in topicSuggestions) {
      if (lowerTopic.includes(key) || lowerSubject.includes(key)) {
        setActiveSuggestions(topicSuggestions[key]);
        found = true;
        break;
      }
    }
    if (!found) setActiveSuggestions([]);
  }, [topic, subject]);

  const systemInstruction = `Tu esi ekspertas pedagogas. Sukurk išsamų pamokos planą JSON formatu. 
SVARBU: Atsižvelk į Lietuvos bendrąsias programas. 
Užtikrink, kad 'eDiaryEntry' laukai būtų paruošti įklijavimui į TAMO ar MANO DIENYNAS sistemas.

Struktūra:
{
  "generalNotes": "Bendros pastabos mokytojui apie pamokos eigą ir pasiruošimą",
  "lessonType": "Tipas",
  "lessonOverview": { "topic": "", "goal": "", "competencies": "", "evaluation": "" },
  "lessonActivities": { "gifted": "", "general": "", "struggling": "", "itTools": "" },
  "homework": { "purpose": "", "gifted": "", "general": "", "struggling": "" },
  "eDiaryEntry": {
    "topicClassworkExpectations": "Sugeneruotas tekstas skilčiai: Tema, klasės darbai, numatomi pasiekimai",
    "homework": "Namų darbai",
    "individualHomework": "Individualūs namų darbai",
    "notes": "Pastabos apie pamoką (pvz., kas pavyko, kas ne)",
    "isIntegrated": false,
    "isOutside": false
  },
  "consultationAdvice": "Patarimai dėl nurodytų pedagoginių iššūkių",
  "motivation": "Motyvuojanti žinutė mokytojui"
}
Atsakyk TIK JSON formatu.`;

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);

    const prompt = `
      Sukurk pamokos planą:
      - Dalykas: ${subject}, Klasė: ${grade}
      - Tema: ${topic}
      - Pamokos tipas: ${lessonType}
      - Tikslas: ${goal}
      - Veiklos idėjos: ${activities}
      - Vertinimo tipas dienyne: ${evaluationType}
      - Vertinimo aprašymas: ${evaluationDescription}
      - Pedagoginiai iššūkiai: ${consultationChallenges}
      - Ar integruota: ${isIntegratedInput ? 'Taip' : 'Ne'}
      - Ar už mokyklos ribų: ${isOutsideInput ? 'Taip' : 'Ne'}
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { systemInstruction, responseMimeType: "application/json" },
      });

      const parsedPlan: LessonPlan = JSON.parse(response.text || '{}');

      // Override from inputs if AI missed it
      parsedPlan.eDiaryEntry.isIntegrated = isIntegratedInput;
      parsedPlan.eDiaryEntry.isOutside = isOutsideInput;

      setLessonPlan(parsedPlan);
      setActivePlanId(null);
    } catch (e: any) {
      setError(`Klaida generuojant: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const confirmSavePlan = () => {
    if (!lessonPlan) return;
    const newPlan: SavedPlan = {
      id: `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${lessonPlan.lessonOverview.topic}`,
      plan: lessonPlan,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: lessonPlan.lessonType || lessonType,
    };
    setSavedPlans([newPlan, ...savedPlans]);
    setActivePlanId(newPlan.id);
  };

  const handleDeletePlan = (id: string) => {
    if (confirm("Ar tikrai norite ištrinti šį planą?")) {
      setSavedPlans(savedPlans.filter(p => p.id !== id));
      if (activePlanId === id) {
        setLessonPlan(null);
        setActivePlanId(null);
      }
    }
  };

  const handleLoadPlan = (id: string) => {
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setActivePlanId(p.id);
      setGrade(p.grade || '');
      setSubject(p.subject || '');
    }
  };

  const filteredPlans = savedPlans.filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase()));

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>Efektyvus planavimas Lietuvos mokytojams</p>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Pamokos informacija</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="pvz., Lietuvių kalba" required />
            </div>
            <div className="form-group">
              <label>Klasė / Grupė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodžio laikai" required />
              <div style={{marginTop: '5px', display: 'flex', flexWrap: 'wrap', gap: '5px'}}>
                {activeSuggestions.map(s => <button key={s} type="button" onClick={() => setActivities(v => v + ' ' + s)} className="suggestion-pill">{s}</button>)}
              </div>
            </div>
            <div className="form-group">
              <label>Pamokos tipas</label>
              <select value={lessonType} onChange={e => setLessonType(e.target.value as LessonCategory)}>
                <option value="">-- Pasirinkite --</option>
                <option value="Įvadinė">Įvadinė</option>
                <option value="Įtvirtinimo">Įtvirtinimo</option>
                <option value="Apibendrinamoji">Apibendrinamoji</option>
                <option value="Vertinamoji">Vertinamoji</option>
              </select>
            </div>
            <div className="form-group">
              <label>Tikslas (nebūtina)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} placeholder="Mokiniai gebės..." />
            </div>
            <div className="form-group">
              <label>Veiklos idėjos (nebūtina)</label>
              <textarea value={activities} onChange={e => setActivities(e.target.value)} placeholder="pvz., darbas grupėse, interaktyvi apklausa" />
            </div>
            <div className="form-group">
              <label>Pedagoginė konsultacija (iššūkiai)</label>
              <textarea value={consultationChallenges} onChange={e => setConsultationChallenges(e.target.value)} placeholder="pvz., mokinys su specialiaisiais poreikiais, triukšmas klasėje..." />
            </div>
            <div className="form-group">
              <label>Vertinimo tipas (žymimas dienyne)</label>
              <select value={evaluationType} onChange={e => setEvaluationType(e.target.value)}>
                {EVALUATION_TAGS.map(t => <option key={t} value={t}>{t}</option>)}
              </select>
            </div>
            <div className="form-group">
              <label>Vertinimo aprašymas</label>
              <textarea value={evaluationDescription} onChange={e => setEvaluationDescription(e.target.value)} placeholder="Kaip ir už ką mokiniai bus vertinami..." />
            </div>
            <div className="form-group checkbox-group" style={{display: 'flex', flexDirection: 'column', gap: '10px', marginTop: '10px'}}>
              <label style={{display: 'flex', alignItems: 'center', gap: '8px', fontWeight: 'normal', cursor: 'pointer'}}>
                <input type="checkbox" checked={isIntegratedInput} onChange={e => setIsIntegratedInput(e.target.checked)} /> El. dienyne žymėti: Integruota pamoka
              </label>
              <label style={{display: 'flex', alignItems: 'center', gap: '8px', fontWeight: 'normal', cursor: 'pointer'}}>
                <input type="checkbox" checked={isOutsideInput} onChange={e => setIsOutsideInput(e.target.checked)} /> El. dienyne žymėti: Pamoka už mokyklos ribų
              </label>
            </div>
            <button type="submit" disabled={isLoading} className="generate-button" style={{marginTop: '20px'}}>
              {isLoading ? <div className="spinner"></div> : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {filteredPlans.map(p => (
                <li key={p.id} onClick={() => handleLoadPlan(p.id)} className={activePlanId === p.id ? 'active' : ''}>
                  <span className="plan-title">{p.title}</span>
                  <button onClick={e => { e.stopPropagation(); handleDeletePlan(p.id); }} className="delete-button">✖</button>
                </li>
              ))}
              {filteredPlans.length === 0 && <li style={{cursor: 'default', opacity: 0.5}}>Sąrašas tuščias</li>}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && !lessonPlan && <div className="loading-overlay"><div className="spinner-large"></div><p>Ruošiamas pamokos planas...</p></div>}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !lessonPlan && !error && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Užpildykite kairėje esančią formą ir aš sugeneruosiu jums išsamų pamokos planą su el. dienyno įrašais.</p>
            </div>
          )}

          {lessonPlan && (
            <div className="lesson-plan-result">
              <div className="export-container">
                <button onClick={confirmSavePlan} className="save-button">Išsaugoti planą 💾</button>
              </div>

              <div className="card general-notes-card">
                <h3>📌 Bendros pastabos (redaguojama)</h3>
                <textarea 
                  value={lessonPlan.generalNotes} 
                  onChange={e => setLessonPlan({...lessonPlan, generalNotes: e.target.value})} 
                  className="notes-edit-area" 
                  style={{width: '100%', minHeight: '100px', padding: '10px', border: 'none', background: 'transparent', resize: 'vertical'}} 
                />
              </div>

              <div className="card lesson-overview-card">
                <h3>📖 Apžvalga ({lessonPlan.lessonType || 'Pamoka'})</h3>
                <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                <p><strong>Tikslas:</strong> {lessonPlan.lessonOverview.goal}</p>
                <p><strong>Gebėjimai:</strong> {lessonPlan.lessonOverview.competencies}</p>
                <p><strong>Vertinimas dienyne:</strong> {evaluationType}</p>
              </div>

              {lessonPlan.consultationAdvice && (
                <div className="card consultation-card" style={{borderLeftColor: 'var(--info-color)', backgroundColor: 'var(--info-color-light)'}}>
                  <h3>💡 Pedagoginė konsultacija</h3>
                  <p>{lessonPlan.consultationAdvice}</p>
                </div>
              )}

              <div className="card lesson-activities-card">
                <h3>🎨 Veiklos</h3>
                <p><strong>🙂 Bendra:</strong> {lessonPlan.lessonActivities.general}</p>
                <p><strong>🚀 Gabesniems:</strong> {lessonPlan.lessonActivities.gifted}</p>
                <p><strong>🌱 Pagalba:</strong> {lessonPlan.lessonActivities.struggling}</p>
                {lessonPlan.lessonActivities.itTools && <p><strong>💻 IT įrankiai:</strong> {lessonPlan.lessonActivities.itTools}</p>}
              </div>

              <div className="card ediary-card" style={{borderLeftColor: 'var(--secondary-color)', backgroundColor: 'var(--primary-color-light)'}}>
                <h3>✍️ El. dienyno įrašai</h3>
                <div style={{display: 'flex', gap: '15px', marginBottom: '15px'}}>
                  <label style={{display: 'flex', alignItems: 'center', gap: '5px', fontSize: '0.9rem', opacity: lessonPlan.eDiaryEntry.isIntegrated ? 1 : 0.4}}>
                    <input type="checkbox" checked={lessonPlan.eDiaryEntry.isIntegrated} readOnly /> Integruota pamoka
                  </label>
                  <label style={{display: 'flex', alignItems: 'center', gap: '5px', fontSize: '0.9rem', opacity: lessonPlan.eDiaryEntry.isOutside ? 1 : 0.4}}>
                    <input type="checkbox" checked={lessonPlan.eDiaryEntry.isOutside} readOnly /> Pamoka už mokyklos ribų
                  </label>
                </div>

                {[
                  { label: "Tema, klasės darbai, pasiekimai", val: lessonPlan.eDiaryEntry.topicClassworkExpectations, id: 'diary-topic' },
                  { label: "Namų darbai", val: lessonPlan.eDiaryEntry.homework, id: 'diary-hw' },
                  { label: "Individualūs namų darbai", val: lessonPlan.eDiaryEntry.individualHomework, id: 'diary-ind-hw' },
                  { label: "Pastabos apie pamoką", val: lessonPlan.eDiaryEntry.notes, id: 'diary-notes' }
                ].map(f => (
                  <div key={f.id} className="diary-entry" style={{marginBottom: '15px'}}>
                    <label style={{display: 'block', fontWeight: 'bold', fontSize: '0.85rem', marginBottom: '4px'}}>{f.label}:</label>
                    <div className="diary-field" style={{display: 'flex', alignItems: 'center', justifyContent: 'space-between', background: '#fff', padding: '8px 12px', borderRadius: '4px', border: '1px solid #ddd'}}>
                      <span style={{fontSize: '0.95rem'}}>{f.val || '---'}</span>
                      <button onClick={() => handleCopy(f.val, f.id)} className={`copy-button ${copiedField === f.id ? 'copied' : ''}`} style={{padding: '4px 8px', fontSize: '0.8rem'}}>
                        {copiedField === f.id ? "Nukopijuota" : "Kopijuoti"}
                      </button>
                    </div>
                  </div>
                ))}
              </div>

              <div className="card motivation-card">
                <h3>💖 Motyvacija</h3>
                <p>{lessonPlan.motivation}</p>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

