  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas. Sukurk išsamų pamokos planą JSON formatu lietuvių kalba.
Užtikrink, kad 'eDiaryEntry' laukai būtų paruošti įklijavimui į elektroninį dienyną.
SVARBU:
1. Jei pamoka yra INTEGRUOTA, 'specialAdvice' lauke pateik patarimus kaip efektyviai integruoti nurodytą dalyką/temą. Primink mokytojui tai pažymėti el. dienyne.
2. Jei pamoka yra UŽ MOKYKLOS RIBŲ, 'specialAdvice' lauke pateik konkrečias užduotis mokiniams išvykoje pagal nurodytą vietą. Primink mokytojui tai pažymėti el. dienyne.
3. 'generalNotes' turi būti aiškiai užpildytas su pasirengimo instrukcijomis.

Struktūra:
{
  "generalNotes": "Išsamios pastabos mokytojui",
  "lessonType": "Tipas",
  "lessonOverview": { "topic": "", "goal": "", "competencies": "", "evaluation": "" },
  "lessonActivities": { "gifted": "", "general": "", "struggling": "", "itTools": "" },
  "homework": { "purpose": "", "gifted": "", "general": "", "struggling": "" },
  "eDiaryEntry": {
    "topicClassworkExpectations": "Tema, klasės darbai, pasiekimai",
    "homework": "Namų darbai",
    "individualHomework": "Individualūs namų darbai",
    "notes": "Pastabos",
    "isIntegrated": false,
    "isOutside": false
  },
  "specialAdvice": "Patarimai integracijai/išvykai ir primygtinis priminimas pažymėti el. dienyne",
  "consultationAdvice": "Patarimai dėl iššūkių",
  "motivation": "Motyvacinė žinutė"
}
Atsakyk TIK JSON formatu.`;

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);

    const prompt = `
      Sukurk pamokos planą:
      - Dalykas: ${subject}, Klasė: ${grade}
      - Tema: ${topic}
      - Pamokos tipas: ${lessonType}
      - Tikslas (Mokiniai gebės...): ${goal}
      - Veiklos idėjos: ${activities}
      - Vertinimo tipas: ${evaluationType}
      - Vertinimo aprašymas: ${evaluationDescription}
      - Pedagoginiai iššūkiai: ${consultationChallenges}
      - AR INTEGRUOTA: ${isIntegratedInput ? `Taip (${integrationDetails})` : 'Ne'}
      - AR UŽ MOKYKLOS RIBŲ: ${isOutsideInput ? `Taip (${locationDetails})` : 'Ne'}
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { systemInstruction, responseMimeType: "application/json" },
      });

      const parsedPlan: LessonPlan = JSON.parse(response.text || '{}');
      parsedPlan.eDiaryEntry.isIntegrated = isIntegratedInput;
      parsedPlan.eDiaryEntry.isOutside = isOutsideInput;

      setLessonPlan(parsedPlan);
      setActivePlanId(null);
    } catch (e: any) {
      setError(`Klaida generuojant: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const confirmSavePlan = () => {
    if (!lessonPlan) return;
    const newPlan: SavedPlan = {
      id: `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${lessonPlan.lessonOverview.topic}`,
      plan: lessonPlan,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: lessonPlan.lessonType || lessonType,
    };
    setSavedPlans([newPlan, ...savedPlans]);
    setActivePlanId(newPlan.id);
  };

  const handleDeletePlan = (id: string) => {
    if (confirm("Ar tikrai norite ištrinti šį planą?")) {
      setSavedPlans(savedPlans.filter(p => p.id !== id));
      if (activePlanId === id) {
        setLessonPlan(null);
        setActivePlanId(null);
      }
    }
  };

  const handleLoadPlan = (id: string) => {
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setActivePlanId(p.id);
      setGrade(p.grade || '');
      setSubject(p.subject || '');
    }
  };

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>Jūsų pagalbininkas kūrybiškoms ir efektyvioms pamokoms</p>
        <div className="header-buttons">
          <button onClick={() => setShowOnboarding(true)} className="external-link-button">Kaip naudotis?</button>
          <a href="https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos" target="_blank" rel="noopener noreferrer" className="external-link-button">BP nuoroda</a>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Pamokos informacija</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="pvz., Lietuvių kalba" required />
            </div>
            <div className="form-group">
              <label>Klasė / Grupė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodžio laikai" required />
            </div>
            <div className="form-group">
              <label>Pamokos tipas</label>
              <select value={lessonType} onChange={e => setLessonType(e.target.value as LessonCategory)}>
                <option value="">-- Pasirinkite --</option>
                <option value="Įvadinė">Įvadinė</option>
                <option value="Įtvirtinimo">Įtvirtinimo</option>
                <option value="Apibendrinamoji">Apibendrinamoji</option>
                <option value="Vertinamoji">Vertinamoji</option>
              </select>
            </div>
            <div className="form-group">
              <label>Tikslas (Mokiniai gebės...)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} placeholder="pvz., atpažinti veiksmažodžio laikus..." />
            </div>
            <div className="form-group">
              <label>Veiklos idėjos (pvz., darbas grupėse)</label>
              <textarea value={activities} onChange={e => setActivities(e.target.value)} placeholder="pvz., Kahoot žaidimas, diskusija..." />
            </div>

            <div className="form-group">
              <label>Vertinimas</label>
              <select value={evaluationType} onChange={e => setEvaluationType(e.target.value)}>
                {EVALUATION_TAGS.map(t => <option key={t} value={t}>{t}</option>)}
              </select>
              <textarea 
                value={evaluationDescription} 
                onChange={e => setEvaluationDescription(e.target.value)} 
                placeholder="Papildomas vertinimo aprašymas..." 
                style={{marginTop: '8px', minHeight: '60px'}}
              />
            </div>

            <div className="form-group checkbox-group" style={{display: 'flex', flexDirection: 'column', gap: '15px', borderTop: '1px solid #eee', paddingTop: '15px'}}>
              <div>
                <label style={{display: 'flex', alignItems: 'center', gap: '8px', fontWeight: 'bold', cursor: 'pointer'}}>
                  <input type="checkbox" checked={isIntegratedInput} onChange={e => setIsIntegratedInput(e.target.checked)} /> El. dienyne žymėti: Integruota pamoka
                </label>
                {isIntegratedInput && (
                  <input 
                    type="text" 
                    value={integrationDetails} 
                    onChange={e => setIntegrationDetails(e.target.value)} 
                    placeholder="Su kokiu dalyku, tema?" 
                    style={{marginTop: '8px', fontSize: '0.9rem'}}
                  />
                )}
              </div>

              <div>
                <label style={{display: 'flex', alignItems: 'center', gap: '8px', fontWeight: 'bold', cursor: 'pointer'}}>
                  <input type="checkbox" checked={isOutsideInput} onChange={e => setIsOutsideInput(e.target.checked)} /> El. dienyne žymėti: Pamoka už mokyklos ribų
                </label>
                {isOutsideInput && (
                  <input 
                    type="text" 
                    value={locationDetails} 
                    onChange={e => setLocationDetails(e.target.value)} 
                    placeholder="Kur vyks pamoka?" 
                    style={{marginTop: '8px', fontSize: '0.9rem'}}
                  />
                )}
              </div>
            </div>

            <div className="form-group" style={{marginTop: '15px'}}>
              <div className="label-wrapper">
                <label>Pedagoginė konsultacija (iššūkiai)</label>
              </div>
              <textarea value={consultationChallenges} onChange={e => setConsultationChallenges(e.target.value)} placeholder="pvz., mokinys su ADHD, motyvacijos trūkumas..." />
            </div>

            <button type="submit" disabled={isLoading} className="generate-button" style={{marginTop: '20px'}}>
              {isLoading ? <div className="spinner"></div> : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {savedPlans.filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase())).map(p => (
                <li key={p.id} onClick={() => handleLoadPlan(p.id)} className={activePlanId === p.id ? 'active' : ''}>
                  <span className="plan-title">{p.title}</span>
                  <button onClick={e => { e.stopPropagation(); handleDeletePlan(p.id); }} className="delete-button">✖</button>
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && <div className="loading-overlay"><div className="spinner-large"></div><p>Ruošiamas pamokos planas...</p></div>}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !lessonPlan && !error && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Užpildykite formą kairėje ir aš padėsiu jums paruošti kūrybišką pamokos planą.</p>
            </div>
          )}

          {lessonPlan && (
            <div className="lesson-plan-result">
              <div className="export-container">
                <button onClick={confirmSavePlan} className="save-button">Išsaugoti planą 💾</button>
              </div>

              <div className="card general-notes-card">
                <h3>📌 Bendros pastabos (redaguojama)</h3>
                <textarea 
                  value={lessonPlan.generalNotes} 
                  onChange={e => setLessonPlan({...lessonPlan, generalNotes: e.target.value})} 
                  className="notes-edit-area" 
                  style={{width: '100%', minHeight: '120px', padding: '15px', border: '1px dashed #666', background: 'transparent', color: '#333', fontSize: '1rem'}} 
                />
              </div>

              <div className="card lesson-overview-card">
                <h3>📖 Apžvalga ({lessonPlan.lessonType || 'Pamoka'})</h3>
                <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                <p><strong>Tikslas:</strong> {lessonPlan.lessonOverview.goal}</p>
                <p><strong>Gebėjimai:</strong> {lessonPlan.lessonOverview.competencies}</p>
                <p><strong>Vertinimas dienyne:</strong> {evaluationType}</p>
              </div>

              {lessonPlan.specialAdvice && (
                <div className="card consultation-card" style={{borderLeftColor: 'var(--secondary-color)', backgroundColor: 'var(--success-color-light)'}}>
                  <h3>🌟 Integracijos ir išvykos patarimai</h3>
                  <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.specialAdvice}</p>
                </div>
              )}

              {lessonPlan.consultationAdvice && (
                <div className="card consultation-card" style={{borderLeftColor: 'var(--info-color)', backgroundColor: 'var(--info-color-light)'}}>
                  <h3>💡 Pedagoginė konsultacija</h3>
                  <p>{lessonPlan.consultationAdvice}</p>
                </div>
              )}

              <div className="card lesson-activities-card">
                <h3>🎨 Veiklos</h3>
                <p><strong>🙂 Bendra:</strong> {lessonPlan.lessonActivities.general}</p>
                <p><strong>🚀 Gabesniems:</strong> {lessonPlan.lessonActivities.gifted}</p>
                <p><strong>🌱 Pagalba:</strong> {lessonPlan.lessonActivities.struggling}</p>
              </div>

              <div className="card ediary-card" style={{borderLeftColor: 'var(--secondary-color)', backgroundColor: 'var(--primary-color-light)'}}>
                <h3>✍️ El. dienyno įrašai</h3>
                <div style={{display: 'flex', gap: '15px', marginBottom: '15px'}}>
                  <label style={{display: 'flex', alignItems: 'center', gap: '5px', fontSize: '0.9rem', color: lessonPlan.eDiaryEntry.isIntegrated ? '#2e7d32' : '#777', fontWeight: lessonPlan.eDiaryEntry.isIntegrated ? 'bold' : 'normal'}}>
                    <input type="checkbox" checked={lessonPlan.eDiaryEntry.isIntegrated} readOnly /> El. dienyne žymėti: Integruota pamoka
                  </label>
                  <label style={{display: 'flex', alignItems: 'center', gap: '5px', fontSize: '0.9rem', color: lessonPlan.eDiaryEntry.isOutside ? '#2e7d32' : '#777', fontWeight: lessonPlan.eDiaryEntry.isOutside ? 'bold' : 'normal'}}>
                    <input type="checkbox" checked={lessonPlan.eDiaryEntry.isOutside} readOnly /> El. dienyne žymėti: Pamoka už mokyklos ribų
                  </label>
                </div>

                {[
                  { label: "Tema, klasės darbai, numatomi pasiekimai", val: lessonPlan.eDiaryEntry.topicClassworkExpectations, id: 'diary-topic' },
                  { label: "Namų darbai", val: lessonPlan.eDiaryEntry.homework, id: 'diary-hw' },
                  { label: "Individualūs namų darbai", val: lessonPlan.eDiaryEntry.individualHomework, id: 'diary-ind-hw' },
                  { label: "Pastabos apie pamoką", val: lessonPlan.eDiaryEntry.notes, id: 'diary-notes' }
                ].map(f => (
                  <div key={f.id} className="diary-entry" style={{marginBottom: '15px'}}>
                    <label style={{display: 'block', fontWeight: 'bold', fontSize: '0.85rem', marginBottom: '4px'}}>{f.label}:</label>
                    <div className="diary-field" style={{display: 'flex', alignItems: 'center', justifyContent: 'space-between', background: '#fff', padding: '10px', borderRadius: '4px', border: '1px solid #ddd'}}>
                      <span style={{fontSize: '0.95rem'}}>{f.val || '---'}</span>
                      <button onClick={() => handleCopy(f.val, f.id)} className={`copy-button ${copiedField === f.id ? 'copied' : ''}`}>
                        {copiedField === f.id ? "Nukopijuota" : "Kopijuoti"}
                      </button>
                    </div>
                  </div>
                ))}
              </div>

              <div className="card motivation-card">
                <h3>💖 Motyvacija</h3>
                <p>{lessonPlan.motivation}</p>
              </div>
            </div>
          )}
        </div>
      </main>

      {showOnboarding && (
        <div className="modal-overlay" onClick={() => setShowOnboarding(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <button className="modal-close-button" onClick={() => setShowOnboarding(false)}>&times;</button>
            <h2>Kaip naudotis programėle?</h2>
            <div className="onboarding-step-content" style={{textAlign: 'left'}}>
              <p>1. Užpildykite kairėje pusėje esančią formą.</p>
              <p>2. Jei pamoka integruota ar vyks išvykoje – būtinai tai pažymėkite!</p>
              <p>3. AI pateiks specifinius patarimus ir užduotis būtent jūsų atvejui.</p>
              <p>4. Rezultatuose rasite tekstus, kuriuos galėsite nukopijuoti į el. dienyną.</p>
              <p>5. Nepamirškite pažymėti specialių varnelių savo el. dienyne (Integruota / Už mokyklos ribų).</p>
            </div>
            <div className="modal-actions">
              <button onClick={() => setShowOnboarding(false)} className="button-primary">Supratau</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

:root {
  /* Colors */
  --primary-color: #4a90e2;
  --primary-color-dark: #3a7ac8;
  --primary-color-light: #e9f3fe;
  --primary-color-focus: rgba(74, 144, 226, 0.2);
  --secondary-color: #50e3c2;
  --secondary-color-dark: #45c9ac;
  --background-color: #f4f7f6;
  --surface-color: #ffffff;
  --text-color: #333;
  --text-color-light: #555;
  --heading-color: #1a253c;
  --border-color: #dce4e1;
  --shadow-color: rgba(0, 0, 0, 0.08);
  --error-color: #e57373;
  --error-color-dark: #c62828;
  --error-color-light: #ffcdd2;
  --success-color: #81c784;
  --success-color-dark: #2e7d32;
  --success-color-light: #e8f5e9;
  --warning-color: #fdd835;
  --warning-color-light: #fffde7;
  --info-color: #8e44ad;
  --info-color-dark: #7b3a96;
  --info-color-light: #f3e5f5;
  --analysis-color: #6c5ce7;
  --analysis-color-light: #e0d8ff;
  --disabled-color: #bdc3c7;
  --white: #ffffff;
  --black: #000000;

  /* Typography */
  --font-family: 'Inter', sans-serif;
  --font-size-base: 1rem;
  --font-size-sm: 0.85rem;
  --font-size-lg: 1.1rem;
  --font-weight-normal: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;
  --line-height-base: 1.6;

  /* Sizing & Spacing */
  --spacing-xs: 0.25rem;
  --spacing-sm: 0.5rem;
  --spacing-md: 0.75rem;
  --spacing-lg: 1rem;
  --spacing-xl: 1.5rem;
  --spacing-xxl: 2rem;

  /* Borders & Shadows */
  --border-radius-sm: 6px;
  --border-radius-md: 8px;
  --border-radius-lg: 12px;
  --box-shadow-md: 0 4px 12px var(--shadow-color);
  --box-shadow-lg: 0 6px 15px rgba(74, 144, 226, 0.3);

  /* Transitions */
  --transition-speed: 0.3s;
  --transition-timing: ease;

  /* Z-Index */
  --z-index-tooltip: 10;
  --z-index-modal: 1000;
}


* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--background-color);
  color: var(--text-color);
  line-height: var(--line-height-base);
}

.container {
  max-width: 1400px;
  margin: 0 auto;
  padding: var(--spacing-lg);
}

.header {
  text-align: center;
  margin-bottom: var(--spacing-xxl);
  padding: var(--spacing-xl);
  background-color: var(--surface-color);
  border-radius: var(--border-radius-lg);
  box-shadow: var(--box-shadow-md);
}

.header h1 {
  color: var(--heading-color);
  font-size: 2.5rem;
  font-weight: var(--font-weight-bold);
}

.header p {
  font-size: var(--font-size-lg);
  color: var(--text-color);
  opacity: 0.8;
}

.header-buttons {
  display: flex;
  justify-content: center;
  gap: var(--spacing-lg);
  margin-top: var(--spacing-lg);
  flex-wrap: wrap;
}

.external-link-button {
  display: inline-block;
  padding: 0.6rem 1.2rem;
  border: 2px solid var(--primary-color);
  border-radius: var(--border-radius-md);
  color: var(--primary-color);
  text-decoration: none;
  font-weight: var(--font-weight-semibold);
  transition: all var(--transition-speed) var(--transition-timing);
  background-color: transparent;
  font-family: var(--font-family);
  font-size: var(--font-size-base);
  cursor: pointer;
}

.external-link-button:hover {
  background-color: var(--primary-color);
  color: var(--white);
}

.main-content {
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: var(--spacing-xxl);
}


/* --- Form Container --- */
.form-container {
  background-color: var(--surface-color);
  padding: var(--spacing-xxl);
  border-radius: var(--border-radius-lg);
  box-shadow: var(--box-shadow-md);
  height: fit-content;
}

.form-container h2 {
  color: var(--heading-color);
  margin-bottom: var(--spacing-xl);
  text-align: center;
}

.form-group {
  margin-bottom: 1.25rem;
}

.form-group label {
  display: block;
  font-weight: var(--font-weight-semibold);
  color: var(--heading-color);
  margin-bottom: 5px;
}

.form-group input,
.form-group textarea,
.form-group select {
  width: 100%;
  padding: var(--spacing-md);
  border: 1px solid var(--border-color);
  border-radius: var(--border-radius-md);
  font-family: var(--font-family);
  font-size: var(--font-size-base);
  transition: border-color var(--transition-speed), box-shadow var(--transition-speed);
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
  outline: none;
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px var(--primary-color-focus);
}

.form-group textarea {
  min-height: 80px;
  resize: vertical;
}

.generate-button {
  width: 100%;
  padding: 0.8rem 1rem;
  background: linear-gradient(45deg, var(--primary-color), var(--secondary-color));
  color: var(--white);
  border: none;
  border-radius: var(--border-radius-md);
  font-size: var(--font-size-lg);
  font-weight: var(--font-weight-semibold);
  cursor: pointer;
  transition: transform var(--transition-speed), box-shadow var(--transition-speed);
  display: flex;
  justify-content: center;
  align-items: center;
}

.generate-button:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: var(--box-shadow-lg);
}

.generate-button:disabled {
  background: var(--disabled-color);
  cursor: not-allowed;
}

/* --- Results Container --- */
.results-container {
  background-color: var(--surface-color);
  padding: var(--spacing-xxl);
  border-radius: var(--border-radius-lg);
  box-shadow: var(--box-shadow-md);
  min-height: 70vh;
}

.welcome-message {
  text-align: center;
  padding: 4rem 2rem;
  color: var(--text-color-light);
  opacity: 0.7;
}

.card {
  border-left: 5px solid var(--primary-color);
  padding: var(--spacing-xl);
  margin-bottom: var(--spacing-xl);
  border-radius: 0 var(--border-radius-md) var(--border-radius-md) 0;
}

.card h3 {
  color: var(--heading-color);
  margin-bottom: var(--spacing-lg);
  display: flex;
  align-items: center;
  gap: 8px;
}

.card p {
  margin-bottom: var(--spacing-sm);
}

.general-notes-card {
  border-left-color: var(--warning-color);
  background-color: var(--warning-color-light);
}

.general-notes-card textarea {
  background: white;
  color: #333;
  width: 100%;
  border: 1px dashed #999;
  border-radius: 4px;
  padding: 10px;
  font-family: inherit;
  font-size: 1rem;
}

.motivation-card {
  border-left-color: var(--success-color);
  background-color: var(--success-color-light);
  font-style: italic;
}

.diary-field {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background-color: var(--white);
  padding: 10px;
  border-radius: var(--border-radius-sm);
  border: 1px solid var(--border-color);
  margin-bottom: var(--spacing-sm);
}

.copy-button {
  background-color: var(--primary-color);
  color: var(--white);
  border: none;
  border-radius: 5px;
  padding: 0.4rem 0.8rem;
  font-size: var(--font-size-sm);
  cursor: pointer;
  transition: all var(--transition-speed);
  min-width: 90px;
}

.copy-button:hover:not(.copied) {
  background-color: var(--primary-color-dark);
}

.copy-button.copied {
  background-color: var(--success-color);
}

/* --- Saved Plans --- */
.saved-plans-container {
  margin-top: var(--spacing-xxl);
  padding-top: var(--spacing-xl);
  border-top: 1px solid var(--border-color);
}

.saved-plans-list {
  list-style: none;
  max-height: 30vh;
  overflow-y: auto;
}

.saved-plans-list li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px;
  border-radius: var(--border-radius-md);
  margin-bottom: 5px;
  background-color: var(--background-color);
  border: 1px solid var(--border-color);
  cursor: pointer;
  font-size: 0.9rem;
}

.saved-plans-list li:hover {
  background-color: var(--primary-color-light);
}

.saved-plans-list li.active {
  background-color: #ddebf8;
  border-left: 4px solid var(--primary-color);
}

.delete-button {
  background: none;
  border: none;
  color: #999;
  cursor: pointer;
  padding: 0 5px;
}

.delete-button:hover {
  color: var(--error-color);
}

/* --- Export Actions --- */
.export-container {
    display: flex;
    justify-content: flex-end;
    margin-bottom: var(--spacing-xl);
}

.save-button {
    padding: 0.6rem 1.2rem;
    background-color: var(--secondary-color);
    color: var(--heading-color);
    border: none;
    border-radius: var(--border-radius-md);
    font-weight: var(--font-weight-semibold);
    cursor: pointer;
}

/* --- Loading Spinner --- */
.loading-overlay {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    height: 100%;
}

.spinner-large {
  width: 50px;
  height: 50px;
  border: 5px solid var(--border-color);
  border-top-color: var(--primary-color);
  border-radius: 50%;
  animation: spin 1s linear infinite;
  margin-bottom: 15px;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

/* --- Modals --- */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(0, 0, 0, 0.6);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: var(--z-index-modal);
  padding: 20px;
}

.modal-content {
  background-color: var(--surface-color);
  padding: 30px;
  border-radius: var(--border-radius-lg);
  max-width: 500px;
  width: 100%;
  position: relative;
}

.modal-close-button {
  position: absolute;
  top: 10px;
  right: 15px;
  background: none;
  border: none;
  font-size: 2rem;
  cursor: pointer;
  color: #aaa;
}

/* Responsive */
@media (max-width: 992px) {
  .main-content { grid-template-columns: 1fr; }
}

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: string;
  };
  lessonActivities: {
    gifted: string;
    general: string;
    struggling: string;
    itTools?: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  consultationAdvice?: string;
  specialAdvice?: string; 
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
}

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [consultationChallenges, setConsultationChallenges] = useState('');

  const [isIntegratedInput, setIsIntegratedInput] = useState(false);
  const [integrationDetails, setIntegrationDetails] = useState('');
  const [isOutsideInput, setIsOutsideInput] = useState(false);
  const [locationDetails, setLocationDetails] = useState('');

  const [evaluationType, setEvaluationType] = useState(EVALUATION_TAGS[0]);
  const [evaluationDescription, setEvaluationDescription] = useState('');

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [showOnboarding, setShowOnboarding] = useState(false);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas. Sukurk išsamų pamokos planą JSON formatu lietuvių kalba.

SVARBIOS TAISYKLĖS FORMAVIMUI:
Lauke 'topicClassworkExpectations' informaciją PRIVALAI pateikti tiksliai tokia struktūra (naudok naujas eilutes \\n):
Temą: [tekstas]
Klasės darbą: [tekstas]
Numatomus pasiekimus: [tekstas]

SVARBU DĖL INTEGRACIJOS IR IŠVYKŲ:
1. Jei pamoka yra INTEGRUOTA, 'specialAdvice' lauke pateik išsamius patarimus integracijai (metodus, užduotis). Primygtinai nurodyk mokytojui tai pažymėti el. dienyne.
2. Jei pamoka yra UŽ MOKYKLOS RIBŲ, 'specialAdvice' lauke pateik ugdymo temas ir užduotis būtent išvykai/vietai. Primygtinai nurodyk mokytojui tai pažymėti el. dienyne.
3. 'generalNotes' turi būti UŽPILDYTAS (ne tuščias), pateikiant svarbiausius akcentus mokytojui.

Struktūra:
{
  "generalNotes": "Ryškios ir aiškios pastabos mokytojui",
  "lessonType": "Tipas",
  "lessonOverview": { "topic": "", "goal": "", "competencies": "", "evaluation": "" },
  "lessonActivities": { "gifted": "", "general": "", "struggling": "", "itTools": "" },
  "homework": { "purpose": "", "gifted": "", "general": "", "struggling": "" },
  "eDiaryEntry": {
    "topicClassworkExpectations": "Temą: ...\\nKlasės darbą: ...\\nNumatomus pasiekimus: ...",
    "homework": "Namų darbai",
    "individualHomework": "Individualūs namų darbai",
    "notes": "Pastabos",
    "isIntegrated": false,
    "isOutside": false
  },
  "specialAdvice": "Patarimai integracijai/išvykai ir PRIMYGTINIS nurodymas pažymėti statusą el. dienyne",
  "consultationAdvice": "Patarimai dėl iššūkių",
  "motivation": "Padėkos ir motyvacijos žodžiai"
}
Atsakyk TIK JSON formatu.`;

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);

    const prompt = `
      Sukurk pamokos planą:
      - Dalykas: ${subject}, Klasė: ${grade}
      - Tema: ${topic}
      - Pamokos tipas: ${lessonType}
      - Tikslas (Mokiniai gebės...): ${goal}
      - Veiklos idėjos: ${activities}
      - Vertinimo tipas: ${evaluationType}
      - Vertinimo aprašymas: ${evaluationDescription}
      - Pedagoginiai iššūkiai: ${consultationChallenges}
      - INTEGRUOTA PAMOKA: ${isIntegratedInput ? `Taip. Dalykas/tema: ${integrationDetails}` : 'Ne'}
      - PAMOKA UŽ MOKYKLOS RIBŲ: ${isOutsideInput ? `Taip. Vieta: ${locationDetails}` : 'Ne'}
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { systemInstruction, responseMimeType: "application/json" },
      });

      const parsedPlan: LessonPlan = JSON.parse(response.text || '{}');
      parsedPlan.eDiaryEntry.isIntegrated = isIntegratedInput;
      parsedPlan.eDiaryEntry.isOutside = isOutsideInput;

      setLessonPlan(parsedPlan);
      setActivePlanId(null);
    } catch (e: any) {
      setError(`Klaida generuojant: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const confirmSavePlan = () => {
    if (!lessonPlan) return;
    const newPlan: SavedPlan = {
      id: `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${lessonPlan.lessonOverview.topic}`,
      plan: lessonPlan,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: lessonPlan.lessonType || lessonType,
    };
    setSavedPlans([newPlan, ...savedPlans]);
    setActivePlanId(newPlan.id);
  };

  const handleDeletePlan = (id: string) => {
    if (confirm("Ar tikrai norite ištrinti šį planą?")) {
      setSavedPlans(savedPlans.filter(p => p.id !== id));
      if (activePlanId === id) {
        setLessonPlan(null);
        setActivePlanId(null);
      }
    }
  };

  const handleLoadPlan = (id: string) => {
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setActivePlanId(p.id);
      setGrade(p.grade || '');
      setSubject(p.subject || '');
    }
  };

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>Jūsų pagalbininkas kūrybiškoms ir efektyvioms pamokoms</p>
        <div className="header-buttons">
          <button onClick={() => setShowOnboarding(true)} className="external-link-button">Kaip naudotis?</button>
          <a href="https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos" target="_blank" rel="noopener noreferrer" className="external-link-button">BP nuoroda</a>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Pamokos informacija</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="pvz., Lietuvių kalba" required />
            </div>
            <div className="form-group">
              <label>Klasė / Grupė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodžio laikai" required />
            </div>
            <div className="form-group">
              <label>Pamokos tipas</label>
              <select value={lessonType} onChange={e => setLessonType(e.target.value as LessonCategory)}>
                <option value="">-- Pasirinkite --</option>
                <option value="Įvadinė">Įvadinė</option>
                <option value="Įtvirtinimo">Įtvirtinimo</option>
                <option value="Apibendrinamoji">Apibendrinamoji</option>
                <option value="Vertinamoji">Vertinamoji</option>
              </select>
            </div>
            <div className="form-group">
              <label>Tikslas (Mokiniai gebės...)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} placeholder="pvz., atpažinti veiksmažodžio laikus..." />
            </div>
            <div className="form-group">
              <label>Veiklos idėjos (pvz., darbas grupėse)</label>
              <textarea value={activities} onChange={e => setActivities(e.target.value)} placeholder="pvz., Kahoot žaidimas, diskusija..." />
            </div>

            <div className="form-group">
              <label>Vertinimas</label>
              <select value={evaluationType} onChange={setEvaluationType as any}>
                {EVALUATION_TAGS.map(t => <option key={t} value={t}>{t}</option>)}
              </select>
              <textarea 
                value={evaluationDescription} 
                onChange={e => setEvaluationDescription(e.target.value)} 
                placeholder="Papildomas vertinimo aprašymas..." 
                style={{marginTop: '8px', minHeight: '60px'}}
              />
            </div>

            <div className="form-group checkbox-group" style={{display: 'flex', flexDirection: 'column', gap: '15px', borderTop: '1px solid #eee', paddingTop: '15px'}}>
              <div>
                <label style={{display: 'flex', alignItems: 'center', gap: '8px', fontWeight: 'bold', cursor: 'pointer'}}>
                  <input type="checkbox" checked={isIntegratedInput} onChange={e => setIsIntegratedInput(e.target.checked)} /> Integruota pamoka
                </label>
                {isIntegratedInput && (
                  <input 
                    type="text" 
                    value={integrationDetails} 
                    onChange={e => setIntegrationDetails(e.target.value)} 
                    placeholder="Su kokiu dalyku, tema?" 
                    style={{marginTop: '8px', fontSize: '0.9rem'}}
                  />
                )}
              </div>

              <div>
                <label style={{display: 'flex', alignItems: 'center', gap: '8px', fontWeight: 'bold', cursor: 'pointer'}}>
                  <input type="checkbox" checked={isOutsideInput} onChange={e => setIsOutsideInput(e.target.checked)} /> Pamoka už mokyklos ribų
                </label>
                {isOutsideInput && (
                  <input 
                    type="text" 
                    value={locationDetails} 
                    onChange={e => setLocationDetails(e.target.value)} 
                    placeholder="Kur vyks pamoka?" 
                    style={{marginTop: '8px', fontSize: '0.9rem'}}
                  />
                )}
              </div>
            </div>

            <div className="form-group" style={{marginTop: '15px'}}>
              <label>Pedagoginė konsultacija (iššūkiai)</label>
              <textarea value={consultationChallenges} onChange={e => setConsultationChallenges(e.target.value)} placeholder="pvz., mokinys su ADHD, motyvacijos trūkumas..." />
            </div>

            <button type="submit" disabled={isLoading} className="generate-button" style={{marginTop: '20px'}}>
              {isLoading ? <div className="spinner"></div> : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {savedPlans.filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase())).map(p => (
                <li key={p.id} onClick={() => handleLoadPlan(p.id)} className={activePlanId === p.id ? 'active' : ''}>
                  <span className="plan-title">{p.title}</span>
                  <button onClick={e => { e.stopPropagation(); handleDeletePlan(p.id); }} className="delete-button">✖</button>
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && <div className="loading-overlay"><div className="spinner-large"></div><p>Ruošiamas pamokos planas...</p></div>}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !lessonPlan && !error && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Užpildykite formą kairėje ir aš padėsiu jums paruošti kūrybišką pamokos planą.</p>
            </div>
          )}

          {lessonPlan && (
            <div className="lesson-plan-result">
              <div className="export-container">
                <button onClick={confirmSavePlan} className="save-button">Išsaugoti planą 💾</button>
              </div>

              <div className="card general-notes-card">
                <h3>📌 Bendros pastabos (redaguojama)</h3>
                <textarea 
                  value={lessonPlan.generalNotes} 
                  onChange={e => setLessonPlan({...lessonPlan, generalNotes: e.target.value})} 
                  className="notes-edit-area" 
                  style={{
                    width: '100%', 
                    minHeight: '120px', 
                    padding: '15px', 
                    border: '1px solid #999', 
                    background: '#fff', 
                    color: '#000', 
                    fontSize: '1rem',
                    fontWeight: '500'
                  }} 
                />
              </div>

              <div className="card lesson-overview-card">
                <h3>📖 Apžvalga ({lessonPlan.lessonType || 'Pamoka'})</h3>
                <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                <p><strong>Tikslas:</strong> {lessonPlan.lessonOverview.goal}</p>
                <p><strong>Gebėjimai:</strong> {lessonPlan.lessonOverview.competencies}</p>
                <p><strong>Vertinimas dienyne:</strong> {evaluationType}</p>
              </div>

              {lessonPlan.specialAdvice && (
                <div className="card consultation-card" style={{borderLeftColor: '#f39c12', backgroundColor: '#fef5e7'}}>
                  <h3>🌟 Integracijos ir išvykos patarimai</h3>
                  <p style={{whiteSpace: 'pre-wrap', fontWeight: '500', color: '#c0392b'}}>{lessonPlan.specialAdvice}</p>
                </div>
              )}

              {lessonPlan.consultationAdvice && (
                <div className="card consultation-card" style={{borderLeftColor: 'var(--info-color)', backgroundColor: 'var(--info-color-light)'}}>
                  <h3>💡 Pedagoginė konsultacija</h3>
                  <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.consultationAdvice}</p>
                </div>
              )}

              <div className="card lesson-activities-card">
                <h3>🎨 Veiklos</h3>
                <p><strong>🙂 Bendra:</strong> {lessonPlan.lessonActivities.general}</p>
                <p><strong>🚀 Gabesniems:</strong> {lessonPlan.lessonActivities.gifted}</p>
                <p><strong>🌱 Pagalba:</strong> {lessonPlan.lessonActivities.struggling}</p>
              </div>

              <div className="card ediary-card" style={{borderLeftColor: 'var(--secondary-color)', backgroundColor: 'var(--primary-color-light)'}}>
                <h3>✍️ El. dienyno įrašai</h3>
                <div style={{display: 'flex', gap: '15px', marginBottom: '15px'}}>
                  <label style={{display: 'flex', alignItems: 'center', gap: '5px', fontSize: '0.9rem', color: lessonPlan.eDiaryEntry.isIntegrated ? '#2e7d32' : '#777', fontWeight: lessonPlan.eDiaryEntry.isIntegrated ? 'bold' : 'normal'}}>
                    <input type="checkbox" checked={lessonPlan.eDiaryEntry.isIntegrated} readOnly /> Integruota pamoka
                  </label>
                  <label style={{display: 'flex', alignItems: 'center', gap: '5px', fontSize: '0.9rem', color: lessonPlan.eDiaryEntry.isOutside ? '#2e7d32' : '#777', fontWeight: lessonPlan.eDiaryEntry.isOutside ? 'bold' : 'normal'}}>
                    <input type="checkbox" checked={lessonPlan.eDiaryEntry.isOutside} readOnly /> Pamoka už mokyklos ribų
                  </label>
                </div>

                <div className="diary-entry" style={{marginBottom: '15px'}}>
                  <label style={{display: 'block', fontWeight: 'bold', fontSize: '0.85rem', marginBottom: '4px'}}>Tema, klasės darbai, numatomi pasiekimai:</label>
                  <div className="diary-field" style={{display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', background: '#fff', padding: '10px', borderRadius: '4px', border: '1px solid #ddd'}}>
                    <span style={{fontSize: '0.95rem', whiteSpace: 'pre-wrap'}}>{lessonPlan.eDiaryEntry.topicClassworkExpectations || '---'}</span>
                    <button onClick={() => handleCopy(lessonPlan.eDiaryEntry.topicClassworkExpectations, 'diary-topic')} className={`copy-button ${copiedField === 'diary-topic' ? 'copied' : ''}`}>
                      {copiedField === 'diary-topic' ? "Nukopijuota" : "Kopijuoti"}
                    </button>
                  </div>
                </div>

                {[
                  { label: "Namų darbai", val: lessonPlan.eDiaryEntry.homework, id: 'diary-hw' },
                  { label: "Individualūs namų darbai", val: lessonPlan.eDiaryEntry.individualHomework, id: 'diary-ind-hw' },
                  { label: "Pastabos apie pamoką", val: lessonPlan.eDiaryEntry.notes, id: 'diary-notes' }
                ].map(f => (
                  <div key={f.id} className="diary-entry" style={{marginBottom: '15px'}}>
                    <label style={{display: 'block', fontWeight: 'bold', fontSize: '0.85rem', marginBottom: '4px'}}>{f.label}:</label>
                    <div className="diary-field" style={{display: 'flex', alignItems: 'center', justifyContent: 'space-between', background: '#fff', padding: '10px', borderRadius: '4px', border: '1px solid #ddd'}}>
                      <span style={{fontSize: '0.95rem', whiteSpace: 'pre-wrap'}}>{f.val || '---'}</span>
                      <button onClick={() => handleCopy(f.val, f.id)} className={`copy-button ${copiedField === f.id ? 'copied' : ''}`}>
                        {copiedField === f.id ? "Nukopijuota" : "Kopijuoti"}
                      </button>
                    </div>
                  </div>
                ))}
              </div>

              <div className="card motivation-card">
                <h3>💝 Ačiū TAU, Mokytojau!</h3>
                <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.motivation}</p>
              </div>
            </div>
          )}
        </div>
      </main>

      {showOnboarding && (
        <div className="modal-overlay" onClick={() => setShowOnboarding(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <button className="modal-close-button" onClick={() => setShowOnboarding(false)}>&times;</button>
            <h2>Kaip naudotis programėle?</h2>
            <div className="onboarding-step-content" style={{textAlign: 'left'}}>
              <p>1. Užpildykite kairėje pusėje esančią formą.</p>
              <p>2. Jei pamoka integruota ar vyks išvykoje – būtinai tai pažymėkite!</p>
              <p>3. AI pateiks specifinius patarimus, kaip suformuoti el. dienyno įrašą ir ką veikti su mokiniais.</p>
              <p>4. Rezultatuose rasite tekstus su Temą:, Klasės darbą: ir Pasiekimus:, suformuotus naujose eilutėse.</p>
              <p>5. Nepamirškite pažymėti specialių varnelių savo el. dienyne!</p>
            </div>
            <div className="modal-actions">
              <button onClick={() => setShowOnboarding(false)} className="button-primary">Supratau</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: string;
  };
  lessonActivities: {
    gifted: string;
    general: string;
    struggling: string;
    itTools?: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  consultationAdvice?: string;
  specialAdvice?: string; 
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
}

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [consultationChallenges, setConsultationChallenges] = useState('');

  const [isIntegratedInput, setIsIntegratedInput] = useState(false);
  const [integrationDetails, setIntegrationDetails] = useState('');
  const [isOutsideInput, setIsOutsideInput] = useState(false);
  const [locationDetails, setLocationDetails] = useState('');

  const [evaluationType, setEvaluationType] = useState(EVALUATION_TAGS[0]);
  const [evaluationDescription, setEvaluationDescription] = useState('');

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [showOnboarding, setShowOnboarding] = useState(false);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas. Sukurk išsamų pamokos planą JSON formatu lietuvių kalba.

SVARBIOS TAISYKLĖS FORMAVIMUI:
Lauke 'topicClassworkExpectations' informaciją PRIVALAI pateikti tiksliai tokia struktūra (naudok naujas eilutes \\n):
Temą: [tekstas]
Klasės darbą: [tekstas]
Numatomus pasiekimus: [tekstas]

SVARBU DĖL INTEGRACIJOS IR IŠVYKŲ:
1. Jei pažymėta, kad pamoka INTEGRUOTA, 'specialAdvice' lauke pateik patarimus kaip efektyviai integruoti nurodytą dalyką/temą. PRIMYGTINAI nurodyk mokytojui, kad tai BŪTINA pažymėti el. dienyne.
2. Jei pažymėta, kad pamoka UŽ MOKYKLOS RIBŲ, 'specialAdvice' lauke pateik konkrečias ugdymo temas ir užduotis mokiniams išvykoje pagal nurodytą vietą. PRIMYGTINAI nurodyk mokytojui, kad tai BŪTINA pažymėti el. dienyne.

Struktūra:
{
  "generalNotes": "Ryškios pasirengimo instrukcijos",
  "lessonType": "Tipas",
  "lessonOverview": { "topic": "", "goal": "", "competencies": "", "evaluation": "" },
  "lessonActivities": { "gifted": "", "general": "", "struggling": "", "itTools": "" },
  "homework": { "purpose": "", "gifted": "", "general": "", "struggling": "" },
  "eDiaryEntry": {
    "topicClassworkExpectations": "Temą: ...\\nKlasės darbą: ...\\nNumatomus pasiekimus: ...",
    "homework": "Namų darbai",
    "individualHomework": "Individualūs namų darbai",
    "notes": "Pastabos",
    "isIntegrated": false,
    "isOutside": false
  },
  "specialAdvice": "Patarimai integracijai/išvykai ir PRIMYGTINIS priminimas mokytojui pažymėti el. dienyne!",
  "consultationAdvice": "Patarimai dėl iššūkių",
  "motivation": "Padėkos žinutė mokytojui"
}
Atsakyk TIK JSON formatu.`;

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);

    const prompt = `
      Sukurk pamokos planą:
      - Dalykas: ${subject}, Klasė: ${grade}
      - Tema: ${topic}
      - Pamokos tipas: ${lessonType}
      - Tikslas (Mokiniai gebės...): ${goal}
      - Veiklos idėjos: ${activities}
      - Vertinimo tipas: ${evaluationType}
      - Vertinimo aprašymas: ${evaluationDescription}
      - Pedagoginiai iššūkiai: ${consultationChallenges}
      - AR TAI INTEGRUOTA PAMOKA? ${isIntegratedInput ? `Taip. Su kokiu dalyku, tema? ${integrationDetails}` : 'Ne'}
      - AR TAI PAMOKA UŽ MOKYKLOS RIBŲ? ${isOutsideInput ? `Taip. Kur vyks? ${locationDetails}` : 'Ne'}
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { systemInstruction, responseMimeType: "application/json" },
      });

      const parsedPlan: LessonPlan = JSON.parse(response.text || '{}');
      parsedPlan.eDiaryEntry.isIntegrated = isIntegratedInput;
      parsedPlan.eDiaryEntry.isOutside = isOutsideInput;

      setLessonPlan(parsedPlan);
      setActivePlanId(null);
    } catch (e: any) {
      setError(`Klaida generuojant: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const confirmSavePlan = () => {
    if (!lessonPlan) return;
    const newPlan: SavedPlan = {
      id: `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${lessonPlan.lessonOverview.topic}`,
      plan: lessonPlan,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: lessonPlan.lessonType || lessonType,
    };
    setSavedPlans([newPlan, ...savedPlans]);
    setActivePlanId(newPlan.id);
  };

  const handleDeletePlan = (id: string) => {
    if (confirm("Ar tikrai norite ištrinti šį planą?")) {
      setSavedPlans(savedPlans.filter(p => p.id !== id));
      if (activePlanId === id) {
        setLessonPlan(null);
        setActivePlanId(null);
      }
    }
  };

  const handleLoadPlan = (id: string) => {
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setActivePlanId(p.id);
      setGrade(p.grade || '');
      setSubject(p.subject || '');
    }
  };

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>Jūsų pagalbininkas kūrybiškoms ir efektyvioms pamokoms</p>
        <div className="header-buttons">
          <button onClick={() => setShowOnboarding(true)} className="external-link-button">Kaip naudotis?</button>
          <a href="https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos" target="_blank" rel="noopener noreferrer" className="external-link-button">BP nuoroda</a>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Pamokos informacija</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="pvz., Lietuvių kalba ir literatūra" required />
            </div>
            <div className="form-group">
              <label>Klasė / Grupė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodžio laikai" required />
            </div>
            <div className="form-group">
              <label>Pamokos tipas</label>
              <select value={lessonType} onChange={e => setLessonType(e.target.value as LessonCategory)}>
                <option value="">-- Pasirinkite --</option>
                <option value="Įvadinė">Įvadinė</option>
                <option value="Įtvirtinimo">Įtvirtinimo</option>
                <option value="Apibendrinamoji">Apibendrinamoji</option>
                <option value="Vertinamoji">Vertinamoji</option>
              </select>
            </div>
            <div className="form-group">
              <label>Tikslas (Mokiniai gebės...)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} placeholder="pvz., atpažinti veiksmažodžio laikus..." />
            </div>
            <div className="form-group">
              <label>Veiklos idėjos (pvz., darbas grupėse)</label>
              <textarea value={activities} onChange={e => setActivities(e.target.value)} placeholder="pvz., darbas grupėse, interaktyvus žaidimas..." />
            </div>

            <div className="form-group">
              <label>Vertinimas</label>
              <select value={evaluationType} onChange={e => setEvaluationType(e.target.value)}>
                {EVALUATION_TAGS.map(t => <option key={t} value={t}>{t}</option>)}
              </select>
              <textarea 
                value={evaluationDescription} 
                onChange={e => setEvaluationDescription(e.target.value)} 
                placeholder="Papildomas vertinimo aprašymas..." 
                style={{marginTop: '8px', minHeight: '60px'}}
              />
            </div>

            <div className="form-group checkbox-group" style={{display: 'flex', flexDirection: 'column', gap: '20px', borderTop: '1px solid #eee', paddingTop: '20px', marginBottom: '20px'}}>
              <div className="checkbox-item">
                <label className="checkbox-label">
                  <input type="checkbox" checked={isIntegratedInput} onChange={e => setIsIntegratedInput(e.target.checked)} />
                  Ar tai integruota pamoka?
                </label>
                {isIntegratedInput && (
                  <div className="nested-input">
                    <label>Su kokiu dalyku, tema?</label>
                    <input 
                      type="text" 
                      value={integrationDetails} 
                      onChange={e => setIntegrationDetails(e.target.value)} 
                      placeholder="Įrašykite detales..." 
                    />
                  </div>
                )}
              </div>

              <div className="checkbox-item">
                <label className="checkbox-label">
                  <input type="checkbox" checked={isOutsideInput} onChange={e => setIsOutsideInput(e.target.checked)} />
                  Ar tai pamoka už mokyklos ribų?
                </label>
                {isOutsideInput && (
                  <div className="nested-input">
                    <label>Kur vyks pamoka?</label>
                    <input 
                      type="text" 
                      value={locationDetails} 
                      onChange={e => setLocationDetails(e.target.value)} 
                      placeholder="Vieta, muziejus, gamta..." 
                    />
                  </div>
                )}
              </div>
            </div>

            <div className="form-group">
              <label>Pedagoginė konsultacija (iššūkiai)</label>
              <textarea value={consultationChallenges} onChange={e => setConsultationChallenges(e.target.value)} placeholder="pvz., mokinys su ADHD, triukšminga klasė..." />
            </div>

            <button type="submit" disabled={isLoading} className="generate-button" style={{marginTop: '20px'}}>
              {isLoading ? <div className="spinner"></div> : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {savedPlans.filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase())).map(p => (
                <li key={p.id} onClick={() => handleLoadPlan(p.id)} className={activePlanId === p.id ? 'active' : ''}>
                  <span className="plan-title">{p.title}</span>
                  <button onClick={e => { e.stopPropagation(); handleDeletePlan(p.id); }} className="delete-button">✖</button>
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && <div className="loading-overlay"><div className="spinner-large"></div><p>Ruošiamas pamokos planas...</p></div>}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !lessonPlan && !error && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Užpildykite formą kairėje ir aš padėsiu jums paruošti kūrybišką pamokos planą.</p>
            </div>
          )}

          {lessonPlan && (
            <div className="lesson-plan-result">
              <div className="export-container">
                <button onClick={confirmSavePlan} className="save-button">Išsaugoti planą 💾</button>
              </div>

              <div className="card general-notes-card">
                <h3>📌 Bendros pastabos (redaguojama)</h3>
                <textarea 
                  value={lessonPlan.generalNotes} 
                  onChange={e => setLessonPlan({...lessonPlan, generalNotes: e.target.value})} 
                  className="notes-edit-area" 
                  style={{
                    width: '100%', 
                    minHeight: '120px', 
                    padding: '15px', 
                    border: '1px solid #000', 
                    background: '#fff', 
                    color: '#000', 
                    fontSize: '1rem',
                    fontWeight: '500'
                  }} 
                />
              </div>

              <div className="card lesson-overview-card">
                <h3>📖 Apžvalga ({lessonPlan.lessonType || 'Pamoka'})</h3>
                <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                <p><strong>Tikslas:</strong> {lessonPlan.lessonOverview.goal}</p>
                <p><strong>Gebėjimai:</strong> {lessonPlan.lessonOverview.competencies}</p>
                <p><strong>Vertinimas dienyne:</strong> {evaluationType}</p>
              </div>

              {lessonPlan.specialAdvice && (
                <div className="card consultation-card" style={{borderLeftColor: '#f39c12', backgroundColor: '#fef5e7'}}>
                  <h3>🌟 Integracijos ir išvykos patarimai</h3>
                  <p style={{whiteSpace: 'pre-wrap', fontWeight: 'bold', color: '#c0392b'}}>{lessonPlan.specialAdvice}</p>
                </div>
              )}

              {lessonPlan.consultationAdvice && (
                <div className="card consultation-card" style={{borderLeftColor: 'var(--info-color)', backgroundColor: 'var(--info-color-light)'}}>
                  <h3>💡 Pedagoginė konsultacija</h3>
                  <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.consultationAdvice}</p>
                </div>
              )}

              <div className="card lesson-activities-card">
                <h3>🎨 Veiklos</h3>
                <p><strong>🙂 Bendra:</strong> {lessonPlan.lessonActivities.general}</p>
                <p><strong>🚀 Gabesniems:</strong> {lessonPlan.lessonActivities.gifted}</p>
                <p><strong>🌱 Pagalba:</strong> {lessonPlan.lessonActivities.struggling}</p>
              </div>

              <div className="card ediary-card" style={{borderLeftColor: 'var(--secondary-color)', backgroundColor: 'var(--primary-color-light)'}}>
                <h3>✍️ El. dienyno įrašai</h3>
                <div style={{display: 'flex', gap: '15px', marginBottom: '15px'}}>
                  <label style={{display: 'flex', alignItems: 'center', gap: '5px', fontSize: '0.9rem', color: lessonPlan.eDiaryEntry.isIntegrated ? '#2e7d32' : '#777', fontWeight: 'bold'}}>
                    <input type="checkbox" checked={lessonPlan.eDiaryEntry.isIntegrated} readOnly /> Integruota pamoka
                  </label>
                  <label style={{display: 'flex', alignItems: 'center', gap: '5px', fontSize: '0.9rem', color: lessonPlan.eDiaryEntry.isOutside ? '#2e7d32' : '#777', fontWeight: 'bold'}}>
                    <input type="checkbox" checked={lessonPlan.eDiaryEntry.isOutside} readOnly /> Pamoka už mokyklos ribų
                  </label>
                </div>

                <div className="diary-entry" style={{marginBottom: '15px'}}>
                  <label style={{display: 'block', fontWeight: 'bold', fontSize: '0.85rem', marginBottom: '4px'}}>Tema, klasės darbai, numatomi pasiekimai:</label>
                  <div className="diary-field" style={{display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', background: '#fff', padding: '10px', borderRadius: '4px', border: '1px solid #ddd'}}>
                    <span style={{fontSize: '0.95rem', whiteSpace: 'pre-wrap', color: '#000', lineHeight: '1.5'}}>{lessonPlan.eDiaryEntry.topicClassworkExpectations || '---'}</span>
                    <button onClick={() => handleCopy(lessonPlan.eDiaryEntry.topicClassworkExpectations, 'diary-topic')} className={`copy-button ${copiedField === 'diary-topic' ? 'copied' : ''}`}>
                      {copiedField === 'diary-topic' ? "Nukopijuota" : "Kopijuoti"}
                    </button>
                  </div>
                </div>

                {[
                  { label: "Namų darbai", val: lessonPlan.eDiaryEntry.homework, id: 'diary-hw' },
                  { label: "Individualūs namų darbai", val: lessonPlan.eDiaryEntry.individualHomework, id: 'diary-ind-hw' },
                  { label: "Pastabos apie pamoką", val: lessonPlan.eDiaryEntry.notes, id: 'diary-notes' }
                ].map(f => (
                  <div key={f.id} className="diary-entry" style={{marginBottom: '15px'}}>
                    <label style={{display: 'block', fontWeight: 'bold', fontSize: '0.85rem', marginBottom: '4px'}}>{f.label}:</label>
                    <div className="diary-field" style={{display: 'flex', alignItems: 'center', justifyContent: 'space-between', background: '#fff', padding: '10px', borderRadius: '4px', border: '1px solid #ddd'}}>
                      <span style={{fontSize: '0.95rem', color: '#000'}}>{f.val || '---'}</span>
                      <button onClick={() => handleCopy(f.val, f.id)} className={`copy-button ${copiedField === f.id ? 'copied' : ''}`}>
                        {copiedField === f.id ? "Nukopijuota" : "Kopijuoti"}
                      </button>
                    </div>
                  </div>
                ))}
              </div>

              <div className="card motivation-card">
                <h3>💖 Ačiū TAU, Mokytojau!</h3>
                <p style={{whiteSpace: 'pre-wrap', fontWeight: '500'}}>{lessonPlan.motivation}</p>
              </div>
            </div>
          )}
        </div>
      </main>

      {showOnboarding && (
        <div className="modal-overlay" onClick={() => setShowOnboarding(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <button className="modal-close-button" onClick={() => setShowOnboarding(false)}>&times;</button>
            <h2>Kaip naudotis programėle?</h2>
            <div className="onboarding-step-content" style={{textAlign: 'left'}}>
              <p>1. Užpildykite kairėje pusėje esančią formą.</p>
              <p>2. Jei pamoka integruota ar vyks išvykoje – būtinai tai pažymėkite!</p>
              <p>3. AI pateiks specifinius patarimus, kaip suformuoti el. dienyno įrašą ir ką veikti su mokiniais.</p>
              <p>4. Rezultatuose rasite tekstus su Temą:, Klasės darbą: ir Pasiekimus:, suformuotus naujose eilutėse.</p>
              <p>5. Nepamirškite pažymėti specialių varnelių savo el. dienyne!</p>
            </div>
            <div className="modal-actions">
              <button onClick={() => setShowOnboarding(false)} className="button-primary">Supratau</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

:root {
  /* Colors */
  --primary-color: #4a90e2;
  --primary-color-dark: #3a7ac8;
  --primary-color-light: #e9f3fe;
  --primary-color-focus: rgba(74, 144, 226, 0.2);
  --secondary-color: #50e3c2;
  --secondary-color-dark: #45c9ac;
  --background-color: #f4f7f6;
  --surface-color: #ffffff;
  --text-color: #333;
  --text-color-light: #555;
  --heading-color: #1a253c;
  --border-color: #dce4e1;
  --shadow-color: rgba(0, 0, 0, 0.08);
  --error-color: #e57373;
  --error-color-dark: #c62828;
  --error-color-light: #ffcdd2;
  --success-color: #81c784;
  --success-color-dark: #2e7d32;
  --success-color-light: #e8f5e9;
  --warning-color: #fdd835;
  --warning-color-light: #fffde7;
  --info-color: #8e44ad;
  --info-color-dark: #7b3a96;
  --info-color-light: #f3e5f5;
  --analysis-color: #6c5ce7;
  --analysis-color-light: #e0d8ff;
  --disabled-color: #bdc3c7;
  --white: #ffffff;
  --black: #000000;

  /* Typography */
  --font-family: 'Inter', sans-serif;
  --font-size-base: 1rem;
  --font-size-sm: 0.85rem;
  --font-size-lg: 1.1rem;
  --font-weight-normal: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;
  --line-height-base: 1.6;

  /* Sizing & Spacing */
  --spacing-xs: 0.25rem;
  --spacing-sm: 0.5rem;
  --spacing-md: 0.75rem;
  --spacing-lg: 1rem;
  --spacing-xl: 1.5rem;
  --spacing-xxl: 2rem;

  /* Borders & Shadows */
  --border-radius-sm: 6px;
  --border-radius-md: 8px;
  --border-radius-lg: 12px;
  --box-shadow-md: 0 4px 12px var(--shadow-color);
  --box-shadow-lg: 0 6px 15px rgba(74, 144, 226, 0.3);

  /* Transitions */
  --transition-speed: 0.3s;
  --transition-timing: ease;

  /* Z-Index */
  --z-index-tooltip: 10;
  --z-index-modal: 1000;
}


* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--background-color);
  color: var(--text-color);
  line-height: var(--line-height-base);
}

.container {
  max-width: 1400px;
  margin: 0 auto;
  padding: var(--spacing-lg);
}

.header {
  text-align: center;
  margin-bottom: var(--spacing-xxl);
  padding: var(--spacing-xl);
  background-color: var(--surface-color);
  border-radius: var(--border-radius-lg);
  box-shadow: var(--box-shadow-md);
}

.header h1 {
  color: var(--heading-color);
  font-size: 2.5rem;
  font-weight: var(--font-weight-bold);
}

.header p {
  font-size: var(--font-size-lg);
  color: var(--text-color);
  opacity: 0.8;
}

.header-buttons {
  display: flex;
  justify-content: center;
  gap: var(--spacing-lg);
  margin-top: var(--spacing-lg);
  flex-wrap: wrap;
}

.external-link-button {
  display: inline-block;
  padding: 0.6rem 1.2rem;
  border: 2px solid var(--primary-color);
  border-radius: var(--border-radius-md);
  color: var(--primary-color);
  text-decoration: none;
  font-weight: var(--font-weight-semibold);
  transition: all var(--transition-speed) var(--transition-timing);
  background-color: transparent;
  font-family: var(--font-family);
  font-size: var(--font-size-base);
  cursor: pointer;
}

.external-link-button:hover {
  background-color: var(--primary-color);
  color: var(--white);
}

.main-content {
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: var(--spacing-xxl);
}


/* --- Form Container --- */
.form-container {
  background-color: var(--surface-color);
  padding: var(--spacing-xxl);
  border-radius: var(--border-radius-lg);
  box-shadow: var(--box-shadow-md);
  height: fit-content;
}

.form-container h2 {
  color: var(--heading-color);
  margin-bottom: var(--spacing-xl);
  text-align: center;
}

.form-group {
  margin-bottom: 1.25rem;
}

.form-group label {
  display: block;
  font-weight: var(--font-weight-semibold);
  color: var(--heading-color);
  margin-bottom: 5px;
}

.form-group input,
.form-group textarea,
.form-group select {
  width: 100%;
  padding: var(--spacing-md);
  border: 1px solid var(--border-color);
  border-radius: var(--border-radius-md);
  font-family: var(--font-family);
  font-size: var(--font-size-base);
  transition: border-color var(--transition-speed), box-shadow var(--transition-speed);
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
  outline: none;
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px var(--primary-color-focus);
}

.form-group textarea {
  min-height: 80px;
  resize: vertical;
}

/* --- Checkbox Styling --- */
.checkbox-item {
  display: flex;
  flex-direction: column;
}

.checkbox-label {
  display: flex !important;
  align-items: center;
  gap: 12px;
  cursor: pointer;
  font-weight: var(--font-weight-bold) !important;
  color: var(--heading-color);
  user-select: none;
}

.checkbox-label input[type="checkbox"] {
  width: 20px;
  height: 20px;
  cursor: pointer;
}

.nested-input {
  margin-left: 32px;
  margin-top: 10px;
  padding: 12px;
  background-color: #f9f9f9;
  border-radius: 6px;
  border: 1px solid #eee;
}

.nested-input label {
  font-size: 0.85rem;
  margin-bottom: 6px;
  color: #555;
}

.nested-input input {
  padding: 8px;
  font-size: 0.9rem;
}

/* --- Results --- */
.generate-button {
  width: 100%;
  padding: 0.8rem 1rem;
  background: linear-gradient(45deg, var(--primary-color), var(--secondary-color));
  color: var(--white);
  border: none;
  border-radius: var(--border-radius-md);
  font-size: var(--font-size-lg);
  font-weight: var(--font-weight-semibold);
  cursor: pointer;
  transition: transform var(--transition-speed), box-shadow var(--transition-speed);
  display: flex;
  justify-content: center;
  align-items: center;
}

.generate-button:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: var(--box-shadow-lg);
}

.generate-button:disabled {
  background: var(--disabled-color);
  cursor: not-allowed;
}

.results-container {
  background-color: var(--surface-color);
  padding: var(--spacing-xxl);
  border-radius: var(--border-radius-lg);
  box-shadow: var(--box-shadow-md);
  min-height: 70vh;
}

.card {
  border-left: 5px solid var(--primary-color);
  padding: var(--spacing-xl);
  margin-bottom: var(--spacing-xl);
  border-radius: 0 var(--border-radius-md) var(--border-radius-md) 0;
}

.general-notes-card {
  border-left-color: #000;
  background-color: #fdfdfd;
}

.motivation-card {
  border-left-color: var(--success-color);
  background-color: var(--success-color-light);
}

.diary-field {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background-color: var(--white);
  padding: 10px;
  border-radius: var(--border-radius-sm);
  border: 1px solid var(--border-color);
  margin-bottom: var(--spacing-sm);
}

.copy-button {
  background-color: var(--primary-color);
  color: var(--white);
  border: none;
  border-radius: 5px;
  padding: 0.4rem 0.8rem;
  font-size: var(--font-size-sm);
  cursor: pointer;
  transition: all var(--transition-speed);
  min-width: 90px;
}

.copy-button:hover:not(.copied) {
  background-color: var(--primary-color-dark);
}

.copy-button.copied {
  background-color: var(--success-color);
}

/* --- Loading Spinner --- */
.loading-overlay {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    height: 100%;
}

.spinner-large {
  width: 50px;
  height: 50px;
  border: 5px solid var(--border-color);
  border-top-color: var(--primary-color);
  border-radius: 50%;
  animation: spin 1s linear infinite;
  margin-bottom: 15px;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

@media (max-width: 992px) {
  .main-content { grid-template-columns: 1fr; }
}

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: string;
  };
  lessonActivities: {
    gifted: string;
    general: string;
    struggling: string;
    itTools?: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  consultationAdvice?: string;
  specialAdvice?: string; 
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
}

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [consultationChallenges, setConsultationChallenges] = useState('');

  const [isIntegratedInput, setIsIntegratedInput] = useState(false);
  const [integrationDetails, setIntegrationDetails] = useState('');
  const [isOutsideInput, setIsOutsideInput] = useState(false);
  const [locationDetails, setLocationDetails] = useState('');

  const [evaluationType, setEvaluationType] = useState(EVALUATION_TAGS[0]);
  const [evaluationDescription, setEvaluationDescription] = useState('');

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [showOnboarding, setShowOnboarding] = useState(false);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas. Sukurk išsamų pamokos planą JSON formatu lietuvių kalba.

SVARBIOS TAISYKLĖS FORMAVIMUI:
Lauke 'topicClassworkExpectations' informaciją PRIVALAI pateikti tiksliai tokia struktūra (naudok naujas eilutes \\n):
Temą: [tekstas susijęs su BP temomis]
Klasės darbą: [tekstas su siūlomu darbu]
Numatomus pasiekimus: [tekstas su galimu vertinimu]

SVARBU DĖL INTEGRACIJOS IR IŠVYKŲ:
1. Jei pažymėta, kad pamoka INTEGRUOTA, 'specialAdvice' lauke pateik patarimus kaip efektyviai integruoti nurodytą dalyką/temą. PRIMYGTINAI nurodyk mokytojui, kad tai BŪTINA pažymėti el. dienyne.
2. Jei pažymėta, kad pamoka UŽ MOKYKLOS RIBŲ, 'specialAdvice' lauke pateik konkrečias ugdymo temas ir užduotis mokiniams išvykoje pagal nurodytą vietą. PRIMYGTINAI nurodyk mokytojui, kad tai BŪTINA pažymėti el. dienyne.

Struktūra:
{
  "generalNotes": "Ryškios pasirengimo instrukcijos",
  "lessonType": "Tipas",
  "lessonOverview": { "topic": "", "goal": "", "competencies": "", "evaluation": "" },
  "lessonActivities": { "gifted": "", "general": "", "struggling": "", "itTools": "" },
  "homework": { "purpose": "", "gifted": "", "general": "", "struggling": "" },
  "eDiaryEntry": {
    "topicClassworkExpectations": "Temą: ...\\nKlasės darbą: ...\\nNumatomus pasiekimus: ...",
    "homework": "Namų darbai",
    "individualHomework": "Individualūs namų darbai",
    "notes": "Pastabos",
    "isIntegrated": false,
    "isOutside": false
  },
  "specialAdvice": "Patarimai integracijai/išvykai ir PRIMYGTINIS priminimas mokytojui pažymėti el. dienyne!",
  "consultationAdvice": "Patarimai dėl iššūkių",
  "motivation": "Padėkos žinutė mokytojui"
}
Atsakyk TIK JSON formatu.`;

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);

    const prompt = `
      Sukurk pamokos planą:
      - Dalykas: ${subject}, Klasė: ${grade}
      - Tema: ${topic}
      - Pamokos tipas: ${lessonType}
      - Tikslas (Mokiniai gebės...): ${goal}
      - Veiklos idėjos: ${activities}
      - Vertinimo tipas: ${evaluationType}
      - Vertinimo aprašymas: ${evaluationDescription}
      - Pedagoginiai iššūkiai: ${consultationChallenges}
      - AR TAI INTEGRUOTA PAMOKA? ${isIntegratedInput ? `Taip. Su kokiu dalyku, tema? ${integrationDetails}` : 'Ne'}
      - AR TAI PAMOKA UŽ MOKYKLOS RIBŲ? ${isOutsideInput ? `Taip. Kur vyks? ${locationDetails}` : 'Ne'}
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { systemInstruction, responseMimeType: "application/json" },
      });

      const parsedPlan: LessonPlan = JSON.parse(response.text || '{}');
      parsedPlan.eDiaryEntry.isIntegrated = isIntegratedInput;
      parsedPlan.eDiaryEntry.isOutside = isOutsideInput;

      setLessonPlan(parsedPlan);
      setActivePlanId(null);
    } catch (e: any) {
      setError(`Klaida generuojant: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const confirmSavePlan = () => {
    if (!lessonPlan) return;
    const newPlan: SavedPlan = {
      id: `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${lessonPlan.lessonOverview.topic}`,
      plan: lessonPlan,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: lessonPlan.lessonType || lessonType,
    };
    setSavedPlans([newPlan, ...savedPlans]);
    setActivePlanId(newPlan.id);
  };

  const handleDeletePlan = (id: string) => {
    if (confirm("Ar tikrai norite ištrinti šį planą?")) {
      setSavedPlans(savedPlans.filter(p => p.id !== id));
      if (activePlanId === id) {
        setLessonPlan(null);
        setActivePlanId(null);
      }
    }
  };

  const handleLoadPlan = (id: string) => {
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setActivePlanId(p.id);
      setGrade(p.grade || '');
      setSubject(p.subject || '');
    }
  };

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>Jūsų pagalbininkas kūrybiškoms ir efektyvioms pamokoms</p>
        <div className="header-buttons">
          <button onClick={() => setShowOnboarding(true)} className="external-link-button">Kaip naudotis?</button>
          <a href="https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos" target="_blank" rel="noopener noreferrer" className="external-link-button">BP nuoroda</a>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Pamokos informacija</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="pvz., Lietuvių kalba ir literatūra" required />
            </div>
            <div className="form-group">
              <label>Klasė / Grupė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodžio laikai" required />
            </div>
            <div className="form-group">
              <label>Pamokos tipas</label>
              <select value={lessonType} onChange={e => setLessonType(e.target.value as LessonCategory)}>
                <option value="">-- Pasirinkite --</option>
                <option value="Įvadinė">Įvadinė</option>
                <option value="Įtvirtinimo">Įtvirtinimo</option>
                <option value="Apibendrinamoji">Apibendrinamoji</option>
                <option value="Vertinamoji">Vertinamoji</option>
              </select>
            </div>
            <div className="form-group">
              <label>Tikslas (Mokiniai gebės...)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} placeholder="pvz., atpažinti veiksmažodžio laikus..." />
            </div>
            <div className="form-group">
              <label>Veiklos idėjos (pvz., darbas grupėse)</label>
              <textarea value={activities} onChange={e => setActivities(e.target.value)} placeholder="pvz., darbas grupėse, interaktyvus žaidimas..." />
            </div>

            <div className="form-group">
              <label>Vertinimas</label>
              <select value={evaluationType} onChange={e => setEvaluationType(e.target.value)}>
                {EVALUATION_TAGS.map(t => <option key={t} value={t}>{t}</option>)}
              </select>
              <textarea 
                value={evaluationDescription} 
                onChange={e => setEvaluationDescription(e.target.value)} 
                placeholder="Papildomas vertinimo aprašymas..." 
                style={{marginTop: '8px', minHeight: '60px'}}
              />
            </div>

            <div className="form-group checkbox-group" style={{display: 'flex', flexDirection: 'column', gap: '20px', borderTop: '1px solid #eee', paddingTop: '20px', marginBottom: '20px'}}>
              <div className="checkbox-item">
                <label className="checkbox-label">
                  <input type="checkbox" checked={isIntegratedInput} onChange={e => setIsIntegratedInput(e.target.checked)} />
                  Ar tai integruota pamoka?
                </label>
                {isIntegratedInput && (
                  <div className="nested-input">
                    <label>Su kokiu dalyku, tema?</label>
                    <input 
                      type="text" 
                      value={integrationDetails} 
                      onChange={e => setIntegrationDetails(e.target.value)} 
                      placeholder="Įrašykite detales..." 
                    />
                  </div>
                )}
              </div>

              <div className="checkbox-item">
                <label className="checkbox-label">
                  <input type="checkbox" checked={isOutsideInput} onChange={e => setIsOutsideInput(e.target.checked)} />
                  Ar tai pamoka už mokyklos ribų?
                </label>
                {isOutsideInput && (
                  <div className="nested-input">
                    <label>Kur vyks pamoka?</label>
                    <input 
                      type="text" 
                      value={locationDetails} 
                      onChange={e => setLocationDetails(e.target.value)} 
                      placeholder="Vieta, muziejus, gamta..." 
                    />
                  </div>
                )}
              </div>
            </div>

            <div className="form-group">
              <label>Pedagoginė konsultacija (iššūkiai)</label>
              <textarea value={consultationChallenges} onChange={e => setConsultationChallenges(e.target.value)} placeholder="pvz., mokinys su ADHD, triukšminga klasė..." />
            </div>

            <button type="submit" disabled={isLoading} className="generate-button" style={{marginTop: '20px'}}>
              {isLoading ? <div className="spinner"></div> : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {savedPlans.filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase())).map(p => (
                <li key={p.id} onClick={() => handleLoadPlan(p.id)} className={activePlanId === p.id ? 'active' : ''}>
                  <span className="plan-title">{p.title}</span>
                  <button onClick={e => { e.stopPropagation(); handleDeletePlan(p.id); }} className="delete-button">✖</button>
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && <div className="loading-overlay"><div className="spinner-large"></div><p>Ruošiamas pamokos planas...</p></div>}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !lessonPlan && !error && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Užpildykite formą kairėje ir aš padėsiu jums paruošti kūrybišką pamokos planą.</p>
            </div>
          )}

          {lessonPlan && (
            <div className="lesson-plan-result">
              <div className="export-container">
                <button onClick={confirmSavePlan} className="save-button">Išsaugoti planą 💾</button>
              </div>

              <div className="card general-notes-card">
                <h3>📌 Bendros pastabos (redaguojama)</h3>
                <textarea 
                  value={lessonPlan.generalNotes} 
                  onChange={e => setLessonPlan({...lessonPlan, generalNotes: e.target.value})} 
                  className="notes-edit-area" 
                  style={{
                    width: '100%', 
                    minHeight: '120px', 
                    padding: '15px', 
                    border: '1px solid #000', 
                    background: '#fff', 
                    color: '#000', 
                    fontSize: '1rem',
                    fontWeight: '500'
                  }} 
                />
              </div>

              <div className="card lesson-overview-card">
                <h3>📖 Apžvalga ({lessonPlan.lessonType || 'Pamoka'})</h3>
                <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                <p><strong>Tikslas:</strong> {lessonPlan.lessonOverview.goal}</p>
                <p><strong>Gebėjimai:</strong> {lessonPlan.lessonOverview.competencies}</p>
                <p><strong>Vertinimas dienyne:</strong> {evaluationType}</p>
              </div>

              {lessonPlan.specialAdvice && (
                <div className="card consultation-card" style={{borderLeftColor: '#f39c12', backgroundColor: '#fef5e7'}}>
                  <h3>🌟 Integracijos ir išvykos patarimai</h3>
                  <p style={{whiteSpace: 'pre-wrap', fontWeight: 'bold', color: '#c0392b'}}>{lessonPlan.specialAdvice}</p>
                </div>
              )}

              {lessonPlan.consultationAdvice && (
                <div className="card consultation-card" style={{borderLeftColor: 'var(--info-color)', backgroundColor: 'var(--info-color-light)'}}>
                  <h3>💡 Pedagoginė konsultacija</h3>
                  <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.consultationAdvice}</p>
                </div>
              )}

              <div className="card lesson-activities-card">
                <h3>🎨 Veiklos</h3>
                <p><strong>🙂 Bendra:</strong> {lessonPlan.lessonActivities.general}</p>
                <p><strong>🚀 Gabesniems:</strong> {lessonPlan.lessonActivities.gifted}</p>
                <p><strong>🌱 Pagalba:</strong> {lessonPlan.lessonActivities.struggling}</p>
              </div>

              <div className="card ediary-card" style={{borderLeftColor: 'var(--secondary-color)', backgroundColor: 'var(--primary-color-light)'}}>
                <h3>✍️ El. dienyno įrašai</h3>
                <div style={{display: 'flex', gap: '15px', marginBottom: '15px'}}>
                  <label style={{display: 'flex', alignItems: 'center', gap: '5px', fontSize: '0.9rem', color: lessonPlan.eDiaryEntry.isIntegrated ? '#2e7d32' : '#777', fontWeight: 'bold'}}>
                    <input type="checkbox" checked={lessonPlan.eDiaryEntry.isIntegrated} readOnly /> Integruota pamoka
                  </label>
                  <label style={{display: 'flex', alignItems: 'center', gap: '5px', fontSize: '0.9rem', color: lessonPlan.eDiaryEntry.isOutside ? '#2e7d32' : '#777', fontWeight: 'bold'}}>
                    <input type="checkbox" checked={lessonPlan.eDiaryEntry.isOutside} readOnly /> Pamoka už mokyklos ribų
                  </label>
                </div>

                <div className="diary-entry" style={{marginBottom: '15px'}}>
                  <label style={{display: 'block', fontWeight: 'bold', fontSize: '0.85rem', marginBottom: '4px'}}>Tema, klasės darbai, numatomi pasiekimai:</label>
                  <div className="diary-field" style={{display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', background: '#fff', padding: '10px', borderRadius: '4px', border: '1px solid #ddd'}}>
                    <span style={{fontSize: '0.95rem', whiteSpace: 'pre-wrap', color: '#000', lineHeight: '1.5'}}>{lessonPlan.eDiaryEntry.topicClassworkExpectations || '---'}</span>
                    <button onClick={() => handleCopy(lessonPlan.eDiaryEntry.topicClassworkExpectations, 'diary-topic')} className={`copy-button ${copiedField === 'diary-topic' ? 'copied' : ''}`}>
                      {copiedField === 'diary-topic' ? "Nukopijuota" : "Kopijuoti"}
                    </button>
                  </div>
                </div>

                {[
                  { label: "Namų darbai", val: lessonPlan.eDiaryEntry.homework, id: 'diary-hw' },
                  { label: "Individualūs namų darbai", val: lessonPlan.eDiaryEntry.individualHomework, id: 'diary-ind-hw' },
                  { label: "Pastabos apie pamoką", val: lessonPlan.eDiaryEntry.notes, id: 'diary-notes' }
                ].map(f => (
                  <div key={f.id} className="diary-entry" style={{marginBottom: '15px'}}>
                    <label style={{display: 'block', fontWeight: 'bold', fontSize: '0.85rem', marginBottom: '4px'}}>{f.label}:</label>
                    <div className="diary-field" style={{display: 'flex', alignItems: 'center', justifyContent: 'space-between', background: '#fff', padding: '10px', borderRadius: '4px', border: '1px solid #ddd'}}>
                      <span style={{fontSize: '0.95rem', color: '#000'}}>{f.val || '---'}</span>
                      <button onClick={() => handleCopy(f.val, f.id)} className={`copy-button ${copiedField === f.id ? 'copied' : ''}`}>
                        {copiedField === f.id ? "Nukopijuota" : "Kopijuoti"}
                      </button>
                    </div>
                  </div>
                ))}
              </div>

              <div className="card motivation-card">
                <h3>💖 Ačiū TAU, Mokytojau!</h3>
                <p style={{whiteSpace: 'pre-wrap', fontWeight: '500'}}>{lessonPlan.motivation}</p>
              </div>
            </div>
          )}
        </div>
      </main>

      {showOnboarding && (
        <div className="modal-overlay" onClick={() => setShowOnboarding(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <button className="modal-close-button" onClick={() => setShowOnboarding(false)}>&times;</button>
            <h2>Kaip naudotis programėle?</h2>
            <div className="onboarding-step-content" style={{textAlign: 'left'}}>
              <p>1. Užpildykite kairėje pusėje esančią formą.</p>
              <p>2. Jei pamoka integruota ar vyks išvykoje – būtinai tai pažymėkite!</p>
              <p>3. DI pateiks specifinius patarimus, kaip suformuoti el. dienyno įrašą ir pamokos plano įgyvendinimą.</p>
              <p>4. Rezultatuose rasite tekstus susijusius su Bendrųjų ugdymo programų temomis; siūlomu klasės darbu, galimą pasiekimų vertinimą suformuotus naujose eilutėse.</p>
              <p>5. Planą galite išsaugoti ir koreguoti.</p>
            </div>
            <div className="modal-actions">
              <button onClick={() => setShowOnboarding(false)} className="button-primary">Supratau</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
  eDiaryLessonType: string;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: string;
  };
  lessonActivities: {
    gifted: string;
    general: string;
    struggling: string;
    itTools?: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  consultationAdvice?: string;
  specialAdvice?: string; 
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
}

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [consultationChallenges, setConsultationChallenges] = useState('');

  const [isIntegratedInput, setIsIntegratedInput] = useState(false);
  const [integrationDetails, setIntegrationDetails] = useState('');
  const [isOutsideInput, setIsOutsideInput] = useState(false);
  const [locationDetails, setLocationDetails] = useState('');

  const [evaluationType, setEvaluationType] = useState(EVALUATION_TAGS[0]);
  const [evaluationDescription, setEvaluationDescription] = useState('');

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [showOnboarding, setShowOnboarding] = useState(false);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas. Sukurk išsamų pamokos planą JSON formatu lietuvių kalba.

SVARBIOS TAISYKLĖS FORMAVIMUI:
Lauke 'topicClassworkExpectations' informaciją PRIVALAI pateikti tiksliai tokia struktūra (naudok naujas eilutes \\n):
Temą: [tekstas susijęs su BP temomis]
Klasės darbą: [tekstas su siūlomu darbu]
Numatomus pasiekimus: [tekstas su galimu vertinimu]

SVARBU DĖL INTEGRACIJOS IR IŠVYKŲ:
1. Jei pažymėta, kad pamoka INTEGRUOTA, 'specialAdvice' lauke pateik patarimus kaip efektyviai integruoti nurodytą dalyką/temą. PRIMYGTINAI nurodyk mokytojui, kad tai BŪTINA pažymėti el. dienyne.
2. Jei pažymėta, kad pamoka UŽ MOKYKLOS RIBŲ, 'specialAdvice' lauke pateik konkrečias ugdymo temas ir užduotis mokiniams išvykoje pagal nurodytą vietą. PRIMYGTINAI nurodyk mokytojui, kad tai BŪTINA pažymėti el. dienyne.

Struktūra:
{
  "generalNotes": "Ryškios pasirengimo instrukcijos",
  "lessonType": "Tipas",
  "lessonOverview": { "topic": "", "goal": "", "competencies": "", "evaluation": "" },
  "lessonActivities": { "gifted": "", "general": "", "struggling": "", "itTools": "" },
  "homework": { "purpose": "", "gifted": "", "general": "", "struggling": "" },
  "eDiaryEntry": {
    "topicClassworkExpectations": "Temą: ...\\nKlasės darbą: ...\\nNumatomus pasiekimus: ...",
    "homework": "Namų darbai",
    "individualHomework": "Individualūs namų darbai",
    "notes": "Pastabos",
    "isIntegrated": false,
    "isOutside": false,
    "eDiaryLessonType": "Pamokos tipas el. dienyne"
  },
  "specialAdvice": "Patarimai integracijai/išvykai ir PRIMYGTINIS priminimas mokytojui pažymėti el. dienyne!",
  "consultationAdvice": "Patarimai dėl iššūkių",
  "motivation": "Padėkos žinutė mokytojui"
}
Atsakyk TIK JSON formatu.`;

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);

    const prompt = `
      Sukurk pamokos planą:
      - Dalykas: ${subject}, Klasė: ${grade}
      - Tema: ${topic}
      - Pamokos tipas: ${lessonType}
      - Tikslas (Mokiniai gebės...): ${goal}
      - Veiklos idėjos: ${activities}
      - Vertinimo tipas: ${evaluationType}
      - Vertinimo aprašymas: ${evaluationDescription}
      - Pedagoginiai iššūkiai: ${consultationChallenges}
      - AR TAI INTEGRUOTA PAMOKA? ${isIntegratedInput ? `Taip. Su kokiu dalyku, tema? ${integrationDetails}` : 'Ne'}
      - AR TAI PAMOKA UŽ MOKYKLOS RIBŲ? ${isOutsideInput ? `Taip. Kur vyks? ${locationDetails}` : 'Ne'}
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { systemInstruction, responseMimeType: "application/json" },
      });

      const parsedPlan: LessonPlan = JSON.parse(response.text || '{}');
      parsedPlan.eDiaryEntry.isIntegrated = isIntegratedInput;
      parsedPlan.eDiaryEntry.isOutside = isOutsideInput;
      // Numatytasis el. dienyno pamokos tipas
      parsedPlan.eDiaryEntry.eDiaryLessonType = parsedPlan.eDiaryEntry.eDiaryLessonType || parsedPlan.lessonType || lessonType || '';

      setLessonPlan(parsedPlan);
      setActivePlanId(null);
    } catch (e: any) {
      setError(`Klaida generuojant: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const confirmSavePlan = () => {
    if (!lessonPlan) return;
    const newPlan: SavedPlan = {
      id: `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${lessonPlan.lessonOverview.topic}`,
      plan: lessonPlan,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: lessonPlan.lessonType || lessonType,
    };
    setSavedPlans([newPlan, ...savedPlans]);
    setActivePlanId(newPlan.id);
  };

  const handleDeletePlan = (id: string) => {
    if (confirm("Ar tikrai norite ištrinti šį planą?")) {
      setSavedPlans(savedPlans.filter(p => p.id !== id));
      if (activePlanId === id) {
        setLessonPlan(null);
        setActivePlanId(null);
      }
    }
  };

  const handleLoadPlan = (id: string) => {
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setActivePlanId(p.id);
      setGrade(p.grade || '');
      setSubject(p.subject || '');
    }
  };

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>Jūsų pagalbininkas kūrybiškoms ir efektyvioms pamokoms</p>
        <div className="header-buttons">
          <button onClick={() => setShowOnboarding(true)} className="external-link-button">Kaip naudotis?</button>
          <a href="https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos" target="_blank" rel="noopener noreferrer" className="external-link-button">BP nuoroda</a>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Pamokos informacija</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="pvz., Lietuvių kalba ir literatūra" required />
            </div>
            <div className="form-group">
              <label>Klasė / Grupė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodžio laikai" required />
            </div>
            <div className="form-group">
              <label>Pamokos tipas</label>
              <select value={lessonType} onChange={e => setLessonType(e.target.value as LessonCategory)}>
                <option value="">-- Pasirinkite --</option>
                <option value="Įvadinė">Įvadinė</option>
                <option value="Įtvirtinimo">Įtvirtinimo</option>
                <option value="Apibendrinamoji">Apibendrinamoji</option>
                <option value="Vertinamoji">Vertinamoji</option>
              </select>
            </div>
            <div className="form-group">
              <label>Tikslas (Mokiniai gebės...)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} placeholder="pvz., atpažinti veiksmažodžio laikus..." />
            </div>
            <div className="form-group">
              <label>Veiklos idėjos (pvz., darbas grupėse)</label>
              <textarea value={activities} onChange={e => setActivities(e.target.value)} placeholder="pvz., darbas grupėse, interaktyvus žaidimas..." />
            </div>

            <div className="form-group">
              <label>Vertinimas</label>
              <select value={evaluationType} onChange={e => setEvaluationType(e.target.value)}>
                {EVALUATION_TAGS.map(t => <option key={t} value={t}>{t}</option>)}
              </select>
              <textarea 
                value={evaluationDescription} 
                onChange={e => setEvaluationDescription(e.target.value)} 
                placeholder="Papildomas vertinimo aprašymas..." 
                style={{marginTop: '8px', minHeight: '60px'}}
              />
            </div>

            <div className="form-group checkbox-group" style={{display: 'flex', flexDirection: 'column', gap: '20px', borderTop: '1px solid #eee', paddingTop: '20px', marginBottom: '20px'}}>
              <div className="checkbox-item">
                <label className="checkbox-label">
                  <input type="checkbox" checked={isIntegratedInput} onChange={e => setIsIntegratedInput(e.target.checked)} />
                  Ar tai integruota pamoka?
                </label>
                {isIntegratedInput && (
                  <div className="nested-input">
                    <label>Su kokiu dalyku, tema?</label>
                    <input 
                      type="text" 
                      value={integrationDetails} 
                      onChange={e => setIntegrationDetails(e.target.value)} 
                      placeholder="Įrašykite detales..." 
                    />
                  </div>
                )}
              </div>

              <div className="checkbox-item">
                <label className="checkbox-label">
                  <input type="checkbox" checked={isOutsideInput} onChange={e => setIsOutsideInput(e.target.checked)} />
                  Ar tai pamoka už mokyklos ribų?
                </label>
                {isOutsideInput && (
                  <div className="nested-input">
                    <label>Kur vyks pamoka?</label>
                    <input 
                      type="text" 
                      value={locationDetails} 
                      onChange={e => setLocationDetails(e.target.value)} 
                      placeholder="Vieta, muziejus, gamta..." 
                    />
                  </div>
                )}
              </div>
            </div>

            <div className="form-group">
              <label>Pedagoginė konsultacija (iššūkiai)</label>
              <textarea value={consultationChallenges} onChange={e => setConsultationChallenges(e.target.value)} placeholder="pvz., mokinys su ADHD, triukšminga klasė..." />
            </div>

            <button type="submit" disabled={isLoading} className="generate-button" style={{marginTop: '20px'}}>
              {isLoading ? <div className="spinner"></div> : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {savedPlans.filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase())).map(p => (
                <li key={p.id} onClick={() => handleLoadPlan(p.id)} className={activePlanId === p.id ? 'active' : ''}>
                  <span className="plan-title">{p.title}</span>
                  <button onClick={e => { e.stopPropagation(); handleDeletePlan(p.id); }} className="delete-button">✖</button>
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && <div className="loading-overlay"><div className="spinner-large"></div><p>Ruošiamas pamokos planas...</p></div>}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !lessonPlan && !error && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Užpildykite formą kairėje ir aš padėsiu jums paruošti kūrybišką pamokos planą.</p>
            </div>
          )}

          {lessonPlan && (
            <div className="lesson-plan-result">
              <div className="export-container">
                <button onClick={confirmSavePlan} className="save-button">Išsaugoti planą 💾</button>
              </div>

              <div className="card general-notes-card">
                <h3>📌 Bendros pastabos (redaguojama)</h3>
                <textarea 
                  value={lessonPlan.generalNotes} 
                  onChange={e => setLessonPlan({...lessonPlan, generalNotes: e.target.value})} 
                  className="notes-edit-area" 
                  style={{
                    width: '100%', 
                    minHeight: '120px', 
                    padding: '15px', 
                    border: '1px solid #000', 
                    background: '#fff', 
                    color: '#000', 
                    fontSize: '1rem',
                    fontWeight: '500'
                  }} 
                />
              </div>

              <div className="card lesson-overview-card">
                <h3>📖 Apžvalga ({lessonPlan.lessonType || 'Pamoka'})</h3>
                <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                <p><strong>Tikslas:</strong> {lessonPlan.lessonOverview.goal}</p>
                <p><strong>Gebėjimai:</strong> {lessonPlan.lessonOverview.competencies}</p>
                <p><strong>Vertinimas dienyne:</strong> {evaluationType}</p>
              </div>

              {lessonPlan.specialAdvice && (
                <div className="card consultation-card" style={{borderLeftColor: '#f39c12', backgroundColor: '#fef5e7'}}>
                  <h3>🌟 Integracijos ir išvykos patarimai</h3>
                  <p style={{whiteSpace: 'pre-wrap', fontWeight: 'bold', color: '#c0392b'}}>{lessonPlan.specialAdvice}</p>
                </div>
              )}

              {lessonPlan.consultationAdvice && (
                <div className="card consultation-card" style={{borderLeftColor: 'var(--info-color)', backgroundColor: 'var(--info-color-light)'}}>
                  <h3>💡 Pedagoginė konsultacija</h3>
                  <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.consultationAdvice}</p>
                </div>
              )}

              <div className="card lesson-activities-card">
                <h3>🎨 Veiklos</h3>
                <p><strong>🙂 Bendra:</strong> {lessonPlan.lessonActivities.general}</p>
                <p><strong>🚀 Gabesniems:</strong> {lessonPlan.lessonActivities.gifted}</p>
                <p><strong>🌱 Pagalba:</strong> {lessonPlan.lessonActivities.struggling}</p>
              </div>

              <div className="card ediary-card" style={{borderLeftColor: 'var(--secondary-color)', backgroundColor: 'var(--primary-color-light)'}}>
                <h3>✍️ El. dienyno įrašai</h3>
                <div style={{display: 'flex', gap: '15px', marginBottom: '15px'}}>
                  <label style={{display: 'flex', alignItems: 'center', gap: '5px', fontSize: '0.9rem', color: lessonPlan.eDiaryEntry.isIntegrated ? '#2e7d32' : '#777', fontWeight: 'bold'}}>
                    <input type="checkbox" checked={lessonPlan.eDiaryEntry.isIntegrated} readOnly /> Integruota pamoka
                  </label>
                  <label style={{display: 'flex', alignItems: 'center', gap: '5px', fontSize: '0.9rem', color: lessonPlan.eDiaryEntry.isOutside ? '#2e7d32' : '#777', fontWeight: 'bold'}}>
                    <input type="checkbox" checked={lessonPlan.eDiaryEntry.isOutside} readOnly /> Pamoka už mokyklos ribų
                  </label>
                </div>

                {[
                  { label: "Pamokos tipas", val: lessonPlan.eDiaryEntry.eDiaryLessonType, id: 'diary-type' },
                  { label: "Tema, klasės darbai, numatomi pasiekimai", val: lessonPlan.eDiaryEntry.topicClassworkExpectations, id: 'diary-topic' },
                  { label: "Namų darbai", val: lessonPlan.eDiaryEntry.homework, id: 'diary-hw' },
                  { label: "Individualūs namų darbai", val: lessonPlan.eDiaryEntry.individualHomework, id: 'diary-ind-hw' },
                  { label: "Pastabos apie pamoką", val: lessonPlan.eDiaryEntry.notes, id: 'diary-notes' }
                ].map(f => (
                  <div key={f.id} className="diary-entry" style={{marginBottom: '15px'}}>
                    <label style={{display: 'block', fontWeight: 'bold', fontSize: '0.85rem', marginBottom: '4px'}}>{f.label}:</label>
                    <div className="diary-field" style={{display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', background: '#fff', padding: '10px', borderRadius: '4px', border: '1px solid #ddd'}}>
                      <span style={{fontSize: '0.95rem', whiteSpace: 'pre-wrap', color: '#000', lineHeight: '1.5'}}>{f.val || '---'}</span>
                      <button onClick={() => handleCopy(f.val, f.id)} className={`copy-button ${copiedField === f.id ? 'copied' : ''}`}>
                        {copiedField === f.id ? "Nukopijuota" : "Kopijuoti"}
                      </button>
                    </div>
                  </div>
                ))}
              </div>

              <div className="card motivation-card">
                <h3>💖 Ačiū TAU, Mokytojau!</h3>
                <p style={{whiteSpace: 'pre-wrap', fontWeight: '500'}}>{lessonPlan.motivation}</p>
              </div>
            </div>
          )}
        </div>
      </main>

      {showOnboarding && (
        <div className="modal-overlay" onClick={() => setShowOnboarding(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <button className="modal-close-button" onClick={() => setShowOnboarding(false)}>&times;</button>
            <h2>Kaip naudotis programėle?</h2>
            <div className="onboarding-step-content" style={{textAlign: 'left'}}>
              <p>1. Užpildykite kairėje pusėje esančią formą.</p>
              <p>2. Jei pamoka integruota ar vyks išvykoje – būtinai tai pažymėkite!</p>
              <p>3. DI pateiks specifinius patarimus, kaip suformuoti el. dienyno įrašą ir pamokos plano įgyvendinimą.</p>
              <p>4. Rezultatuose rasite tekstus susijusius su Bendrųjų ugdymo programų temomis; siūlomu klasės darbu, galimą pasiekimų vertinimą suformuotus naujose eilutėse.</p>
              <p>5. Planą galite išsaugoti ir koreguoti.</p>
            </div>
            <div className="modal-actions">
              <button onClick={() => setShowOnboarding(false)} className="button-primary">Supratau</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
  eDiaryLessonType: string;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: string;
  };
  lessonActivities: {
    gifted: string;
    general: string;
    struggling: string;
    itTools?: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  consultationAdvice?: string;
  specialAdvice?: string; 
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
}

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [consultationChallenges, setConsultationChallenges] = useState('');

  const [isIntegratedInput, setIsIntegratedInput] = useState(false);
  const [integrationDetails, setIntegrationDetails] = useState('');
  const [isOutsideInput, setIsOutsideInput] = useState(false);
  const [locationDetails, setLocationDetails] = useState('');

  const [evaluationType, setEvaluationType] = useState(EVALUATION_TAGS[0]);
  const [evaluationDescription, setEvaluationDescription] = useState('');

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [showOnboarding, setShowOnboarding] = useState(false);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas. Sukurk išsamų pamokos planą JSON formatu lietuvių kalba.

SVARBIOS TAISYKLĖS FORMAVIMUI:
Lauke 'topicClassworkExpectations' informaciją PRIVALAI pateikti tiksliai tokia struktūra (naudok naujas eilutes \\n):
Temą: [tekstas susijęs su BP temomis]
Klasės darbą: [tekstas su siūlomu darbu]
Numatomus pasiekimus: [tekstas su galimu vertinimu]

SVARBU DĖL INTEGRACIJOS IR IŠVYKŲ:
1. Jei pažymėta, kad pamoka INTEGRUOTA, 'specialAdvice' lauke pateik patarimus kaip efektyviai integruoti nurodytą dalyką/temą. PRIMYGTINAI nurodyk mokytojui, kad tai BŪTINA pažymėti el. dienyne.
2. Jei pažymėta, kad pamoka UŽ MOKYKLOS RIBŲ, 'specialAdvice' lauke pateik konkrečias ugdymo temas ir užduotis mokiniams išvykoje pagal nurodytą vietą. PRIMYGTINAI nurodyk mokytojui, kad tai BŪTINA pažymėti el. dienyne.

Struktūra:
{
  "generalNotes": "Ryškios pasirengimo instrukcijos",
  "lessonType": "Tipas",
  "lessonOverview": { "topic": "", "goal": "", "competencies": "", "evaluation": "" },
  "lessonActivities": { "gifted": "", "general": "", "struggling": "", "itTools": "" },
  "homework": { "purpose": "", "gifted": "", "general": "", "struggling": "" },
  "eDiaryEntry": {
    "topicClassworkExpectations": "Temą: ...\\nKlasės darbą: ...\\nNumatomus pasiekimus: ...",
    "homework": "Namų darbai",
    "individualHomework": "Individualūs namų darbai",
    "notes": "Pastabos",
    "isIntegrated": false,
    "isOutside": false,
    "eDiaryLessonType": "Pamokos tipas el. dienyne"
  },
  "specialAdvice": "Patarimai integracijai/išvykai ir PRIMYGTINIS priminimas mokytojui pažymėti el. dienyne!",
  "consultationAdvice": "Patarimai dėl iššūkių",
  "motivation": "Padėkos žinutė mokytojui"
}
Atsakyk TIK JSON formatu.`;

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);

    const prompt = `
      Sukurk pamokos planą:
      - Dalykas: ${subject}, Klasė: ${grade}
      - Tema: ${topic}
      - Pamokos tipas: ${lessonType}
      - Tikslas (Mokiniai gebės...): ${goal}
      - Veiklos idėjos: ${activities}
      - Vertinimo tipas: ${evaluationType}
      - Vertinimo aprašymas: ${evaluationDescription}
      - Pedagoginiai iššūkiai: ${consultationChallenges}
      - AR TAI INTEGRUOTA PAMOKA? ${isIntegratedInput ? `Taip. Su kokiu dalyku, tema? ${integrationDetails}` : 'Ne'}
      - AR TAI PAMOKA UŽ MOKYKLOS RIBŲ? ${isOutsideInput ? `Taip. Kur vyks? ${locationDetails}` : 'Ne'}
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { systemInstruction, responseMimeType: "application/json" },
      });

      const parsedPlan: LessonPlan = JSON.parse(response.text || '{}');
      parsedPlan.eDiaryEntry.isIntegrated = isIntegratedInput;
      parsedPlan.eDiaryEntry.isOutside = isOutsideInput;
      // Numatytasis el. dienyno pamokos tipas
      parsedPlan.eDiaryEntry.eDiaryLessonType = parsedPlan.eDiaryEntry.eDiaryLessonType || parsedPlan.lessonType || lessonType || '';

      setLessonPlan(parsedPlan);
      setActivePlanId(null);
    } catch (e: any) {
      setError(`Klaida generuojant: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const confirmSavePlan = () => {
    if (!lessonPlan) return;
    const newPlan: SavedPlan = {
      id: `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${lessonPlan.lessonOverview.topic}`,
      plan: lessonPlan,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: lessonPlan.lessonType || lessonType,
    };
    setSavedPlans([newPlan, ...savedPlans]);
    setActivePlanId(newPlan.id);
  };

  const handleDeletePlan = (id: string) => {
    if (confirm("Ar tikrai norite ištrinti šį planą?")) {
      setSavedPlans(savedPlans.filter(p => p.id !== id));
      if (activePlanId === id) {
        setLessonPlan(null);
        setActivePlanId(null);
      }
    }
  };

  const handleLoadPlan = (id: string) => {
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setActivePlanId(p.id);
      setGrade(p.grade || '');
      setSubject(p.subject || '');
    }
  };

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>Jūsų pagalbininkas kūrybiškoms ir efektyvioms pamokoms</p>
        <div className="header-buttons">
          <button onClick={() => setShowOnboarding(true)} className="external-link-button">Kaip naudotis?</button>
          <a href="https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos" target="_blank" rel="noopener noreferrer" className="external-link-button">BP nuoroda</a>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Pamokos informacija</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="pvz., Lietuvių kalba ir literatūra" required />
            </div>
            <div className="form-group">
              <label>Klasė / Grupė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodžio laikai" required />
            </div>
            <div className="form-group">
              <label>Pamokos tipas</label>
              <select value={lessonType} onChange={e => setLessonType(e.target.value as LessonCategory)}>
                <option value="">-- Pasirinkite --</option>
                <option value="Įvadinė">Įvadinė</option>
                <option value="Įtvirtinimo">Įtvirtinimo</option>
                <option value="Apibendrinamoji">Apibendrinamoji</option>
                <option value="Vertinamoji">Vertinamoji</option>
              </select>
            </div>
            <div className="form-group">
              <label>Tikslas (Mokiniai gebės...)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} placeholder="pvz., atpažinti veiksmažodžio laikus..." />
            </div>
            <div className="form-group">
              <label>Veiklos idėjos (pvz., darbas grupėse)</label>
              <textarea value={activities} onChange={e => setActivities(e.target.value)} placeholder="pvz., darbas grupėse, interaktyvus žaidimas..." />
            </div>

            <div className="form-group">
              <label>Vertinimas</label>
              <select value={evaluationType} onChange={e => setEvaluationType(e.target.value)}>
                {EVALUATION_TAGS.map(t => <option key={t} value={t}>{t}</option>)}
              </select>
              <textarea 
                value={evaluationDescription} 
                onChange={e => setEvaluationDescription(e.target.value)} 
                placeholder="Papildomas vertinimo aprašymas..." 
                style={{marginTop: '8px', minHeight: '60px'}}
              />
            </div>

            <div className="form-group checkbox-group" style={{display: 'flex', flexDirection: 'column', gap: '20px', borderTop: '1px solid #eee', paddingTop: '20px', marginBottom: '20px'}}>
              <div className="checkbox-item">
                <label className="checkbox-label">
                  <input type="checkbox" checked={isIntegratedInput} onChange={e => setIsIntegratedInput(e.target.checked)} />
                  Ar tai integruota pamoka?
                </label>
                {isIntegratedInput && (
                  <div className="nested-input">
                    <label>Su kokiu dalyku, tema?</label>
                    <input 
                      type="text" 
                      value={integrationDetails} 
                      onChange={setIntegrationDetails as any} 
                      placeholder="Įrašykite detales..." 
                    />
                  </div>
                )}
              </div>

              <div className="checkbox-item">
                <label className="checkbox-label">
                  <input type="checkbox" checked={isOutsideInput} onChange={e => setIsOutsideInput(e.target.checked)} />
                  Ar tai pamoka už mokyklos ribų?
                </label>
                {isOutsideInput && (
                  <div className="nested-input">
                    <label>Kur vyks pamoka?</label>
                    <input 
                      type="text" 
                      value={locationDetails} 
                      onChange={setLocationDetails as any} 
                      placeholder="Vieta, muziejus, gamta..." 
                    />
                  </div>
                )}
              </div>
            </div>

            <div className="form-group">
              <label>Pedagoginė konsultacija (iššūkiai)</label>
              <textarea value={consultationChallenges} onChange={e => setConsultationChallenges(e.target.value)} placeholder="pvz., mokinys su ADHD, triukšminga klasė..." />
            </div>

            <button type="submit" disabled={isLoading} className="generate-button" style={{marginTop: '20px'}}>
              {isLoading ? <div className="spinner"></div> : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {savedPlans.filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase())).map(p => (
                <li key={p.id} onClick={() => handleLoadPlan(p.id)} className={activePlanId === p.id ? 'active' : ''}>
                  <span className="plan-title">{p.title}</span>
                  <button onClick={e => { e.stopPropagation(); handleDeletePlan(p.id); }} className="delete-button">✖</button>
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && <div className="loading-overlay"><div className="spinner-large"></div><p>Ruošiamas pamokos planas...</p></div>}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !lessonPlan && !error && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Užpildykite formą kairėje ir aš padėsiu jums paruošti kūrybišką pamokos planą.</p>
            </div>
          )}

          {lessonPlan && (
            <div className="lesson-plan-result">
              <div className="export-container">
                <button onClick={confirmSavePlan} className="save-button">Išsaugoti planą 💾</button>
              </div>

              <div className="card general-notes-card">
                <h3>📌 Bendros pastabos (redaguojama)</h3>
                <textarea 
                  value={lessonPlan.generalNotes} 
                  onChange={e => setLessonPlan({...lessonPlan, generalNotes: e.target.value})} 
                  className="notes-edit-area" 
                  style={{
                    width: '100%', 
                    minHeight: '120px', 
                    padding: '15px', 
                    border: '1px solid #000', 
                    background: '#fff', 
                    color: '#000', 
                    fontSize: '1rem',
                    fontWeight: '500'
                  }} 
                />
              </div>

              <div className="card lesson-overview-card">
                <h3>📖 Apžvalga ({lessonPlan.lessonType || 'Pamoka'})</h3>
                <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                <p><strong>Tikslas:</strong> {lessonPlan.lessonOverview.goal}</p>
                <p><strong>Gebėjimai:</strong> {lessonPlan.lessonOverview.competencies}</p>
                <p><strong>Vertinimas dienyne:</strong> {evaluationType}</p>
              </div>

              {lessonPlan.specialAdvice && (
                <div className="card consultation-card" style={{borderLeftColor: '#f39c12', backgroundColor: '#fef5e7'}}>
                  <h3>🌟 Integracijos ir išvykos patarimai</h3>
                  <p style={{whiteSpace: 'pre-wrap', fontWeight: 'bold', color: '#c0392b'}}>{lessonPlan.specialAdvice}</p>
                </div>
              )}

              {lessonPlan.consultationAdvice && (
                <div className="card consultation-card" style={{borderLeftColor: 'var(--info-color)', backgroundColor: 'var(--info-color-light)'}}>
                  <h3>💡 Pedagoginė konsultacija</h3>
                  <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.consultationAdvice}</p>
                </div>
              )}

              <div className="card lesson-activities-card">
                <h3>🎨 Veiklos</h3>
                <p><strong>🙂 Bendra:</strong> {lessonPlan.lessonActivities.general}</p>
                <p><strong>🚀 Gabesniems:</strong> {lessonPlan.lessonActivities.gifted}</p>
                <p><strong>🌱 Pagalba:</strong> {lessonPlan.lessonActivities.struggling}</p>
              </div>

              <div className="card ediary-card" style={{borderLeftColor: 'var(--secondary-color)', backgroundColor: 'var(--primary-color-light)'}}>
                <h3>✍️ El. dienyno įrašai</h3>
                <div style={{display: 'flex', gap: '15px', marginBottom: '15px'}}>
                  <label style={{display: 'flex', alignItems: 'center', gap: '5px', fontSize: '0.9rem', color: lessonPlan.eDiaryEntry.isIntegrated ? '#2e7d32' : '#777', fontWeight: 'bold'}}>
                    <input type="checkbox" checked={lessonPlan.eDiaryEntry.isIntegrated} readOnly /> Integruota pamoka
                  </label>
                  <label style={{display: 'flex', alignItems: 'center', gap: '5px', fontSize: '0.9rem', color: lessonPlan.eDiaryEntry.isOutside ? '#2e7d32' : '#777', fontWeight: 'bold'}}>
                    <input type="checkbox" checked={lessonPlan.eDiaryEntry.isOutside} readOnly /> Pamoka už mokyklos ribų
                  </label>
                </div>

                {[
                  { label: "Pamokos tipas", val: lessonPlan.eDiaryEntry.eDiaryLessonType, id: 'diary-type' },
                  { label: "Tema, klasės darbai, numatomi pasiekimai", val: lessonPlan.eDiaryEntry.topicClassworkExpectations, id: 'diary-topic' },
                  { label: "Namų darbai", val: lessonPlan.eDiaryEntry.homework, id: 'diary-hw' },
                  { label: "Individualūs namų darbai", val: lessonPlan.eDiaryEntry.individualHomework, id: 'diary-ind-hw' },
                  { label: "Pastabos apie pamoką", val: lessonPlan.eDiaryEntry.notes, id: 'diary-notes' }
                ].map(f => (
                  <div key={f.id} className="diary-entry" style={{marginBottom: '15px'}}>
                    <label style={{display: 'block', fontWeight: 'bold', fontSize: '0.85rem', marginBottom: '4px'}}>{f.label}:</label>
                    <div className="diary-field" style={{display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', background: '#fff', padding: '10px', borderRadius: '4px', border: '1px solid #ddd'}}>
                      <span style={{fontSize: '0.95rem', whiteSpace: 'pre-wrap', color: '#000', lineHeight: '1.5'}}>{f.val || '---'}</span>
                      <button onClick={() => handleCopy(f.val, f.id)} className={`copy-button ${copiedField === f.id ? 'copied' : ''}`}>
                        {copiedField === f.id ? "Nukopijuota" : "Kopijuoti"}
                      </button>
                    </div>
                  </div>
                ))}
              </div>

              <div className="card motivation-card">
                <h3>💖 Ačiū TAU, Mokytojau!</h3>
                <p style={{whiteSpace: 'pre-wrap', fontWeight: '500'}}>{lessonPlan.motivation}</p>
              </div>
            </div>
          )}
        </div>
      </main>

      {showOnboarding && (
        <div className="modal-overlay" onClick={() => setShowOnboarding(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <button className="modal-close-button" onClick={() => setShowOnboarding(false)}>&times;</button>
            <h2>Kaip naudotis programėle?</h2>
            <div className="onboarding-step-content" style={{textAlign: 'left'}}>
              <p>1. Užpildykite kairėje pusėje esančią formą.</p>
              <p>2. Jei pamoka integruota ar vyks išvykoje – būtinai tai pažymėkite!</p>
              <p>3. DI pateiks specifinius patarimus, kaip suformuoti el. dienyno įrašą ir pamokos plano įgyvendinimą.</p>
              <p>4. Rezultatuose rasite tekstus susijusius su Bendrųjų ugdymo programų temomis; siūlomu klasės darbu, galimą pasiekimų vertinimą suformuotus naujose eilutėse.</p>
              <p>5. Planą galite išsaugoti ir koreguoti.</p>
            </div>
            <div className="modal-actions">
              <button onClick={() => setShowOnboarding(false)} className="button-primary">Supratau</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
  eDiaryLessonType: string;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: string;
  };
  lessonActivities: {
    gifted: string;
    general: string;
    struggling: string;
    itTools?: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  consultationAdvice?: string;
  specialAdvice?: string; 
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
}

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [consultationChallenges, setConsultationChallenges] = useState('');

  const [isIntegratedInput, setIsIntegratedInput] = useState(false);
  const [integrationDetails, setIntegrationDetails] = useState('');
  const [isOutsideInput, setIsOutsideInput] = useState(false);
  const [locationDetails, setLocationDetails] = useState('');

  const [evaluationType, setEvaluationType] = useState(EVALUATION_TAGS[0]);
  const [evaluationDescription, setEvaluationDescription] = useState('');

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [showOnboarding, setShowOnboarding] = useState(false);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  // Editing state for saved plans
  const [editingPlanId, setEditingPlanId] = useState<string | null>(null);
  const [editTitle, setEditTitle] = useState('');
  const [editSubject, setEditSubject] = useState('');
  const [editGrade, setEditGrade] = useState('');

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas. Sukurk išsamų pamokos planą JSON formatu lietuvių kalba.

SVARBIOS TAISYKLĖS FORMAVIMUI:
Lauke 'topicClassworkExpectations' informaciją PRIVALAI pateikti tiksliai tokia struktūra (naudok naujas eilutes \\n):
Temą: [tekstas susijęs su BP temomis]
Klasės darbą: [tekstas su siūlomu darbu]
Numatomus pasiekimus: [tekstas su galimu vertinimu]

SVARBU DĖL INTEGRACIJOS IR IŠVYKŲ:
1. Jei pažymėta, kad pamoka INTEGRUOTA, 'specialAdvice' lauke pateik patarimus kaip efektyviai integruoti nurodytą dalyką/temą. PRIMYGTINAI nurodyk mokytojui, kad tai BŪTINA pažymėti el. dienyne.
2. Jei pažymėta, kad pamoka UŽ MOKYKLOS RIBŲ, 'specialAdvice' lauke pateik konkrečias ugdymo temas ir užduotis mokiniams išvykoje pagal nurodytą vietą. PRIMYGTINAI nurodyk mokytojui, kad tai BŪTINA pažymėti el. dienyne.

Struktūra:
{
  "generalNotes": "Ryškios pasirengimo instrukcijos",
  "lessonType": "Tipas",
  "lessonOverview": { "topic": "", "goal": "", "competencies": "", "evaluation": "" },
  "lessonActivities": { "gifted": "", "general": "", "struggling": "", "itTools": "" },
  "homework": { "purpose": "", "gifted": "", "general": "", "struggling": "" },
  "eDiaryEntry": {
    "topicClassworkExpectations": "Temą: ...\\nKlasės darbą: ...\\nNumatomus pasiekimus: ...",
    "homework": "Namų darbai",
    "individualHomework": "Individualūs namų darbai",
    "notes": "Pastabos",
    "isIntegrated": false,
    "isOutside": false,
    "eDiaryLessonType": "Pamokos tipas el. dienyne"
  },
  "specialAdvice": "Patarimai integracijai/išvykai ir PRIMYGTINIS priminimas mokytojui pažymėti el. dienyne!",
  "consultationAdvice": "Patarimai dėl iššūkių",
  "motivation": "Padėkos žinutė mokytojui"
}
Atsakyk TIK JSON formatu.`;

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);

    const prompt = `
      Sukurk pamokos planą:
      - Dalykas: ${subject}, Klasė: ${grade}
      - Tema: ${topic}
      - Pamokos tipas: ${lessonType}
      - Tikslas (Mokiniai gebės...): ${goal}
      - Veiklos idėjos: ${activities}
      - Vertinimo tipas: ${evaluationType}
      - Vertinimo aprašymas: ${evaluationDescription}
      - Pedagoginiai iššūkiai: ${consultationChallenges}
      - AR TAI INTEGRUOTA PAMOKA? ${isIntegratedInput ? `Taip. Su kokiu dalyku, tema? ${integrationDetails}` : 'Ne'}
      - AR TAI PAMOKA UŽ MOKYKLOS RIBŲ? ${isOutsideInput ? `Taip. Kur vyks? ${locationDetails}` : 'Ne'}
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { systemInstruction, responseMimeType: "application/json" },
      });

      const parsedPlan: LessonPlan = JSON.parse(response.text || '{}');
      parsedPlan.eDiaryEntry.isIntegrated = isIntegratedInput;
      parsedPlan.eDiaryEntry.isOutside = isOutsideInput;
      // Numatytasis el. dienyno pamokos tipas
      parsedPlan.eDiaryEntry.eDiaryLessonType = parsedPlan.eDiaryEntry.eDiaryLessonType || parsedPlan.lessonType || lessonType || '';

      setLessonPlan(parsedPlan);
      setActivePlanId(null);
    } catch (e: any) {
      setError(`Klaida generuojant: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const confirmSavePlan = () => {
    if (!lessonPlan) return;
    const newPlan: SavedPlan = {
      id: `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${lessonPlan.lessonOverview.topic}`,
      plan: lessonPlan,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: lessonPlan.lessonType || lessonType,
    };
    setSavedPlans([newPlan, ...savedPlans]);
    setActivePlanId(newPlan.id);
  };

  const handleDeletePlan = (id: string) => {
    if (confirm("Ar tikrai norite ištrinti šį planą?")) {
      setSavedPlans(savedPlans.filter(p => p.id !== id));
      if (activePlanId === id) {
        setLessonPlan(null);
        setActivePlanId(null);
      }
    }
  };

  const handleLoadPlan = (id: string) => {
    if (editingPlanId) return; // Prevent loading while editing
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setActivePlanId(p.id);
      setGrade(p.grade || '');
      setSubject(p.subject || '');
    }
  };

  const startEditing = (e: React.MouseEvent, plan: SavedPlan) => {
    e.stopPropagation();
    setEditingPlanId(plan.id);
    setEditTitle(plan.title);
    setEditSubject(plan.subject || '');
    setEditGrade(plan.grade || '');
  };

  const cancelEditing = (e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingPlanId(null);
  };

  const savePlanEdits = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!editingPlanId) return;

    setSavedPlans(prev => prev.map(p => {
      if (p.id === editingPlanId) {
        return {
          ...p,
          title: editTitle,
          subject: editSubject,
          grade: editGrade
        };
      }
      return p;
    }));
    setEditingPlanId(null);
  };

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>Jūsų pagalbininkas kūrybiškoms ir efektyvioms pamokoms</p>
        <div className="header-buttons">
          <button onClick={() => setShowOnboarding(true)} className="external-link-button">Kaip naudotis?</button>
          <a href="https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos" target="_blank" rel="noopener noreferrer" className="external-link-button">BP nuoroda</a>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Pamokos informacija</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="pvz., Lietuvių kalba ir literatūra" required />
            </div>
            <div className="form-group">
              <label>Klasė / Grupė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodžio laikai" required />
            </div>
            <div className="form-group">
              <label>Pamokos tipas</label>
              <select value={lessonType} onChange={e => setLessonType(e.target.value as LessonCategory)}>
                <option value="">-- Pasirinkite --</option>
                <option value="Įvadinė">Įvadinė</option>
                <option value="Įtvirtinimo">Įtvirtinimo</option>
                <option value="Apibendrinamoji">Apibendrinamoji</option>
                <option value="Vertinamoji">Vertinamoji</option>
              </select>
            </div>
            <div className="form-group">
              <label>Tikslas (Mokiniai gebės...)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} placeholder="pvz., atpažinti veiksmažodžio laikus..." />
            </div>
            <div className="form-group">
              <label>Veiklos idėjos (pvz., darbas grupėse)</label>
              <textarea value={activities} onChange={e => setActivities(e.target.value)} placeholder="pvz., darbas grupėse, interaktyvus žaidimas..." />
            </div>

            <div className="form-group">
              <label>Vertinimas</label>
              <select value={evaluationType} onChange={e => setEvaluationType(e.target.value)}>
                {EVALUATION_TAGS.map(t => <option key={t} value={t}>{t}</option>)}
              </select>
              <textarea 
                value={evaluationDescription} 
                onChange={e => setEvaluationDescription(e.target.value)} 
                placeholder="Papildomas vertinimo aprašymas..." 
                style={{marginTop: '8px', minHeight: '60px'}}
              />
            </div>

            <div className="form-group checkbox-group" style={{display: 'flex', flexDirection: 'column', gap: '20px', borderTop: '1px solid #eee', paddingTop: '20px', marginBottom: '20px'}}>
              <div className="checkbox-item">
                <label className="checkbox-label">
                  <input type="checkbox" checked={isIntegratedInput} onChange={e => setIsIntegratedInput(e.target.checked)} />
                  Ar tai integruota pamoka?
                </label>
                {isIntegratedInput && (
                  <div className="nested-input">
                    <label>Su kokiu dalyku, tema?</label>
                    <input 
                      type="text" 
                      value={integrationDetails} 
                      onChange={e => setIntegrationDetails(e.target.value)} 
                      placeholder="Įrašykite detales..." 
                    />
                  </div>
                )}
              </div>

              <div className="checkbox-item">
                <label className="checkbox-label">
                  <input type="checkbox" checked={isOutsideInput} onChange={e => setIsOutsideInput(e.target.checked)} />
                  Ar tai pamoka už mokyklos ribų?
                </label>
                {isOutsideInput && (
                  <div className="nested-input">
                    <label>Kur vyks pamoka?</label>
                    <input 
                      type="text" 
                      value={locationDetails} 
                      onChange={e => setLocationDetails(e.target.value)} 
                      placeholder="Vieta, muziejus, gamta..." 
                    />
                  </div>
                )}
              </div>
            </div>

            <div className="form-group">
              <label>Pedagoginė konsultacija (iššūkiai)</label>
              <textarea value={consultationChallenges} onChange={e => setConsultationChallenges(e.target.value)} placeholder="pvz., mokinys su ADHD, triukšminga klasė..." />
            </div>

            <button type="submit" disabled={isLoading} className="generate-button" style={{marginTop: '20px'}}>
              {isLoading ? <div className="spinner"></div> : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {savedPlans.filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase())).map(p => (
                <li 
                  key={p.id} 
                  onClick={() => handleLoadPlan(p.id)} 
                  className={`${activePlanId === p.id ? 'active' : ''} ${editingPlanId === p.id ? 'editing' : ''}`}
                >
                  {editingPlanId === p.id ? (
                    <div className="edit-plan-form" onClick={e => e.stopPropagation()}>
                      <input type="text" value={editTitle} onChange={e => setEditTitle(e.target.value)} placeholder="Pavadinimas" className="edit-input" />
                      <div className="edit-row">
                        <input type="text" value={editSubject} onChange={e => setEditSubject(e.target.value)} placeholder="Dalykas" className="edit-input-small" />
                        <input type="text" value={editGrade} onChange={e => setEditGrade(e.target.value)} placeholder="Klasė" className="edit-input-small" />
                      </div>
                      <div className="edit-actions">
                        <button onClick={savePlanEdits} className="save-edit-button">Išsaugoti</button>
                        <button onClick={cancelEditing} className="cancel-edit-button">Atšaukti</button>
                      </div>
                    </div>
                  ) : (
                    <>
                      <div className="plan-info">
                        <span className="plan-title">{p.title}</span>
                        <div className="plan-meta">
                          {p.subject && <span className="meta-tag">{p.subject}</span>}
                          {p.grade && <span className="meta-tag">{p.grade}</span>}
                        </div>
                      </div>
                      <div className="plan-actions">
                        <button onClick={e => startEditing(e, p)} className="edit-button-icon" title="Redaguoti">✏️</button>
                        <button onClick={e => { e.stopPropagation(); handleDeletePlan(p.id); }} className="delete-button" title="Ištrinti">✖</button>
                      </div>
                    </>
                  )}
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && <div className="loading-overlay"><div className="spinner-large"></div><p>Ruošiamas pamokos planas...</p></div>}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !lessonPlan && !error && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Užpildykite formą kairėje ir aš padėsiu jums paruošti kūrybišką pamokos planą.</p>
            </div>
          )}

          {lessonPlan && (
            <div className="lesson-plan-result">
              <div className="export-container">
                <button onClick={confirmSavePlan} className="save-button">Išsaugoti planą 💾</button>
              </div>

              <div className="card general-notes-card">
                <h3>📌 Bendros pastabos (redaguojama)</h3>
                <textarea 
                  value={lessonPlan.generalNotes} 
                  onChange={e => setLessonPlan({...lessonPlan, generalNotes: e.target.value})} 
                  className="notes-edit-area" 
                  style={{
                    width: '100%', 
                    minHeight: '120px', 
                    padding: '15px', 
                    border: '1px solid #000', 
                    background: '#fff', 
                    color: '#000', 
                    fontSize: '1rem',
                    fontWeight: '500'
                  }} 
                />
              </div>

              <div className="card lesson-overview-card">
                <h3>📖 Apžvalga ({lessonPlan.lessonType || 'Pamoka'})</h3>
                <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                <p><strong>Tikslas:</strong> {lessonPlan.lessonOverview.goal}</p>
                <p><strong>Gebėjimai:</strong> {lessonPlan.lessonOverview.competencies}</p>
                <p><strong>Vertinimas dienyne:</strong> {evaluationType}</p>
              </div>

              {lessonPlan.specialAdvice && (
                <div className="card consultation-card" style={{borderLeftColor: '#f39c12', backgroundColor: '#fef5e7'}}>
                  <h3>🌟 Integracijos ir išvykos patarimai</h3>
                  <p style={{whiteSpace: 'pre-wrap', fontWeight: 'bold', color: '#c0392b'}}>{lessonPlan.specialAdvice}</p>
                </div>
              )}

              {lessonPlan.consultationAdvice && (
                <div className="card consultation-card" style={{borderLeftColor: 'var(--info-color)', backgroundColor: 'var(--info-color-light)'}}>
                  <h3>💡 Pedagoginė konsultacija</h3>
                  <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.consultationAdvice}</p>
                </div>
              )}

              <div className="card lesson-activities-card">
                <h3>🎨 Veiklos</h3>
                <p><strong>🙂 Bendra:</strong> {lessonPlan.lessonActivities.general}</p>
                <p><strong>🚀 Gabesniems:</strong> {lessonPlan.lessonActivities.gifted}</p>
                <p><strong>🌱 Pagalba:</strong> {lessonPlan.lessonActivities.struggling}</p>
              </div>

              <div className="card ediary-card" style={{borderLeftColor: 'var(--secondary-color)', backgroundColor: 'var(--primary-color-light)'}}>
                <h3>✍️ El. dienyno įrašai</h3>
                <div style={{display: 'flex', gap: '15px', marginBottom: '15px'}}>
                  <label style={{display: 'flex', alignItems: 'center', gap: '5px', fontSize: '0.9rem', color: lessonPlan.eDiaryEntry.isIntegrated ? '#2e7d32' : '#777', fontWeight: 'bold'}}>
                    <input type="checkbox" checked={lessonPlan.eDiaryEntry.isIntegrated} readOnly /> Integruota pamoka
                  </label>
                  <label style={{display: 'flex', alignItems: 'center', gap: '5px', fontSize: '0.9rem', color: lessonPlan.eDiaryEntry.isOutside ? '#2e7d32' : '#777', fontWeight: 'bold'}}>
                    <input type="checkbox" checked={lessonPlan.eDiaryEntry.isOutside} readOnly /> Pamoka už mokyklos ribų
                  </label>
                </div>

                {[
                  { label: "Pamokos tipas", val: lessonPlan.eDiaryEntry.eDiaryLessonType, id: 'diary-type' },
                  { label: "Tema, klasės darbai, numatomi pasiekimai", val: lessonPlan.eDiaryEntry.topicClassworkExpectations, id: 'diary-topic' },
                  { label: "Namų darbai", val: lessonPlan.eDiaryEntry.homework, id: 'diary-hw' },
                  { label: "Individualūs namų darbai", val: lessonPlan.eDiaryEntry.individualHomework, id: 'diary-ind-hw' },
                  { label: "Pastabos apie pamoką", val: lessonPlan.eDiaryEntry.notes, id: 'diary-notes' }
                ].map(f => (
                  <div key={f.id} className="diary-entry" style={{marginBottom: '15px'}}>
                    <label style={{display: 'block', fontWeight: 'bold', fontSize: '0.85rem', marginBottom: '4px'}}>{f.label}:</label>
                    <div className="diary-field" style={{display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', background: '#fff', padding: '10px', borderRadius: '4px', border: '1px solid #ddd'}}>
                      <span style={{fontSize: '0.95rem', whiteSpace: 'pre-wrap', color: '#000', lineHeight: '1.5'}}>{f.val || '---'}</span>
                      <button onClick={() => handleCopy(f.val, f.id)} className={`copy-button ${copiedField === f.id ? 'copied' : ''}`}>
                        {copiedField === f.id ? "Nukopijuota" : "Kopijuoti"}
                      </button>
                    </div>
                  </div>
                ))}
              </div>

              <div className="card motivation-card">
                <h3>💖 Ačiū TAU, Mokytojau!</h3>
                <p style={{whiteSpace: 'pre-wrap', fontWeight: '500'}}>{lessonPlan.motivation}</p>
              </div>
            </div>
          )}
        </div>
      </main>

      {showOnboarding && (
        <div className="modal-overlay" onClick={() => setShowOnboarding(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <button className="modal-close-button" onClick={() => setShowOnboarding(false)}>&times;</button>
            <h2>Kaip naudotis programėle?</h2>
            <div className="onboarding-step-content" style={{textAlign: 'left'}}>
              <p>1. Užpildykite kairėje pusėje esančią formą.</p>
