              <p>5. Planą galite išsaugoti ir koreguoti.</p>
            </div>
            <div className="modal-actions">
              <button onClick={() => setShowOnboarding(false)} className="button-primary">Supratau</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

