  border: 1px solid var(--border-color);
  border-radius: 4px;
  font-size: 0.9rem;
  background-color: #0f172a;
  color: var(--heading-color);
}

.edit-input-small {
  flex: 1;
  padding: 6px 10px;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  font-size: 0.85rem;
  background-color: #0f172a;
  color: var(--heading-color);
}

.edit-actions {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
}

.save-edit-button {
  background-color: var(--success-color-dark);
  color: white;
  border: none;
  padding: 4px 12px;
  border-radius: 4px;
  font-size: 0.85rem;
  cursor: pointer;
}

.cancel-edit-button {
  background-color: #475569;
  color: white;
  border: none;
  padding: 4px 12px;
  border-radius: 4px;
  font-size: 0.85rem;
  cursor: pointer;
}

/* --- Results --- */
.generate-button {
  width: 100%;
  padding: 0.8rem 1rem;
  background: linear-gradient(45deg, var(--primary-color), var(--secondary-color));
  color: var(--white);
  border: none;
  border-radius: var(--border-radius-md);
  font-size: var(--font-size-lg);
  font-weight: var(--font-weight-semibold);
  cursor: pointer;
  transition: transform var(--transition-speed), box-shadow var(--transition-speed);
  display: flex;
  justify-content: center;
  align-items: center;
}

.generate-button:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: var(--box-shadow-lg);
}

.generate-button:disabled {
  background: var(--disabled-color);
  cursor: not-allowed;
}

.results-container {
  background-color: var(--surface-color);
  padding: var(--spacing-xxl);
  border-radius: var(--border-radius-lg);
  box-shadow: var(--box-shadow-md);
  min-height: 70vh;
  border: 1px solid var(--border-color);
}

.welcome-message h2 {
  color: var(--heading-color);
  margin-bottom: 1rem;
}

.card {
  border-left: 5px solid var(--primary-color);
  padding: var(--spacing-xl);
  margin-bottom: var(--spacing-xl);
  border-radius: 0 var(--border-radius-md) var(--border-radius-md) 0;
  background-color: #1e293b;
  border: 1px solid var(--border-color);
  border-left-width: 5px;
}

.card h3 {
  color: var(--heading-color);
  margin-bottom: 1rem;
}

.card p {
  margin-bottom: 0.5rem;
  color: var(--text-color-light);
}

.card strong {
  color: var(--heading-color);
}

.general-notes-card {
  border-left-color: var(--white);
  background-color: #0f172a;
}

.motivation-card {
  border-left-color: var(--success-color);
  background-color: var(--success-color-light);
}

.consultation-card {
  border-left-color: var(--info-color);
  background-color: var(--info-color-light);
}

.ediary-card {
  border-left-color: var(--secondary-color);
  background-color: var(--primary-color-light);
}

.diary-field {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  background-color: #0f172a;
  padding: 12px;
  border-radius: var(--border-radius-sm);
  border: 1px solid var(--border-color);
  margin-bottom: var(--spacing-sm);
}

.diary-field span {
  color: var(--heading-color);
}

.copy-button {
  background-color: var(--primary-color);
  color: var(--white);
  border: none;
  border-radius: 5px;
  padding: 0.4rem 0.8rem;
  font-size: var(--font-size-sm);
  cursor: pointer;
  transition: all var(--transition-speed);
  min-width: 90px;
}

.copy-button:hover:not(.copied) {
  background-color: var(--primary-color-dark);
}

.copy-button.copied {
  background-color: var(--success-color-dark);
}

/* --- Modal Overlay --- */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(0, 0, 0, 0.75);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: var(--z-index-modal);
  backdrop-filter: blur(4px);
}

.modal-content {
  background-color: var(--surface-color);
  padding: var(--spacing-xxl);
  border-radius: var(--border-radius-lg);
  max-width: 600px;
  width: 90%;
  position: relative;
  border: 1px solid var(--border-color);
}

.modal-content h2 {
  color: var(--heading-color);
  margin-bottom: 1.5rem;
}

.modal-close-button {
  position: absolute;
  top: 1rem;
  right: 1rem;
  background: none;
  border: none;
  color: var(--text-color);
  font-size: 1.5rem;
  cursor: pointer;
}

.onboarding-step-content p {
  margin-bottom: 1rem;
  color: var(--text-color-light);
}

.button-primary {
  background-color: var(--primary-color);
  color: white;
  border: none;
  padding: 0.6rem 1.5rem;
  border-radius: var(--border-radius-md);
  font-weight: var(--font-weight-semibold);
  cursor: pointer;
}

/* --- Loading Spinner --- */
.loading-overlay {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    height: 100%;
}

.spinner-large {
  width: 50px;
  height: 50px;
  border: 5px solid var(--border-color);
  border-top-color: var(--primary-color);
  border-radius: 50%;
  animation: spin 1s linear infinite;
  margin-bottom: 15px;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

@media (max-width: 992px) {
  .main-content { grid-template-columns: 1fr; }
}

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
  eDiaryLessonType: string;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: string;
  };
  lessonActivities: {
    gifted: string;
    general: string;
    struggling: string;
    itTools?: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  consultationAdvice?: string;
  specialAdvice?: string; 
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
}

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [consultationChallenges, setConsultationChallenges] = useState('');

  const [isIntegratedInput, setIsIntegratedInput] = useState(false);
  const [integrationDetails, setIntegrationDetails] = useState('');
  const [isOutsideInput, setIsOutsideInput] = useState(false);
  const [locationDetails, setLocationDetails] = useState('');

  const [evaluationType, setEvaluationType] = useState(EVALUATION_TAGS[0]);
  const [evaluationDescription, setEvaluationDescription] = useState('');

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [showOnboarding, setShowOnboarding] = useState(false);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  // Editing state for saved plans
  const [editingPlanId, setEditingPlanId] = useState<string | null>(null);
  const [editTitle, setEditTitle] = useState('');
  const [editSubject, setEditSubject] = useState('');
  const [editGrade, setEditGrade] = useState('');

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas. Sukurk išsamų pamokos planą JSON formatu lietuvių kalba.

SVARBIOS TAISYKLĖS FORMAVIMUI:
Lauke 'topicClassworkExpectations' informaciją PRIVALAI pateikti tiksliai tokia struktūra (naudok naujas eilutes \\n):
Temą: [tekstas susijęs su BP temomis]
Klasės darbą: [tekstas su siūlomu darbu]
Numatomus pasiekimus: [tekstas su galimu vertinimu]

SVARBU DĖL INTEGRACIJOS IR IŠVYKŲ:
1. Jei pažymėta, kad pamoka INTEGRUOTA, 'specialAdvice' lauke pateik patarimus kaip efektyviai integruoti nurodytą dalyką/temą. PRIMYGTINAI nurodyk mokytojui, kad tai BŪTINA pažymėti el. dienyne.
2. Jei pažymėta, kad pamoka UŽ MOKYKLOS RIBŲ, 'specialAdvice' lauke pateik konkrečias ugdymo temas ir užduotis mokiniams išvykoje pagal nurodytą vietą. PRIMYGTINAI nurodyk mokytojui, kad tai BŪTINA pažymėti el. dienyne.

Struktūra:
{
  "generalNotes": "Ryškios pasirengimo instrukcijos",
  "lessonType": "Tipas",
  "lessonOverview": { "topic": "", "goal": "", "competencies": "", "evaluation": "" },
  "lessonActivities": { "gifted": "", "general": "", "struggling": "", "itTools": "" },
  "homework": { "purpose": "", "gifted": "", "general": "", "struggling": "" },
  "eDiaryEntry": {
    "topicClassworkExpectations": "Temą: ...\\nKlasės darbą: ...\\nNumatomus pasiekimus: ...",
    "homework": "Namų darbai",
    "individualHomework": "Individualūs namų darbai",
    "notes": "Pastabos",
    "isIntegrated": false,
    "isOutside": false,
    "eDiaryLessonType": "Pamokos tipas el. dienyne"
  },
  "specialAdvice": "Patarimai integracijai/išvykai ir PRIMYGTINIS priminimas mokytojui pažymėti el. dienyne!",
  "consultationAdvice": "Patarimai dėl iššūkių",
  "motivation": "Padėkos žinutė mokytojui"
}
Atsakyk TIK JSON formatu.`;

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);

    const prompt = `
      Sukurk pamokos planą:
      - Dalykas: ${subject}, Klasė: ${grade}
      - Tema: ${topic}
      - Pamokos tipas: ${lessonType}
      - Tikslas (Mokiniai gebės...): ${goal}
      - Veiklos idėjos: ${activities}
      - Vertinimo tipas: ${evaluationType}
      - Vertinimo aprašymas: ${evaluationDescription}
      - Pedagoginiai iššūkiai: ${consultationChallenges}
      - AR TAI INTEGRUOTA PAMOKA? ${isIntegratedInput ? `Taip. Su kokiu dalyku, tema? ${integrationDetails}` : 'Ne'}
      - AR TAI PAMOKA UŽ MOKYKLOS RIBŲ? ${isOutsideInput ? `Taip. Kur vyks? ${locationDetails}` : 'Ne'}
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { systemInstruction, responseMimeType: "application/json" },
      });

      const parsedPlan: LessonPlan = JSON.parse(response.text || '{}');
      parsedPlan.eDiaryEntry.isIntegrated = isIntegratedInput;
      parsedPlan.eDiaryEntry.isOutside = isOutsideInput;
      // Numatytasis el. dienyno pamokos tipas
      parsedPlan.eDiaryEntry.eDiaryLessonType = parsedPlan.eDiaryEntry.eDiaryLessonType || parsedPlan.lessonType || lessonType || '';

      setLessonPlan(parsedPlan);
      setActivePlanId(null);
    } catch (e: any) {
      setError(`Klaida generuojant: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const confirmSavePlan = () => {
    if (!lessonPlan) return;
    const newPlan: SavedPlan = {
      id: `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${lessonPlan.lessonOverview.topic}`,
      plan: lessonPlan,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: lessonPlan.lessonType || lessonType,
    };
    setSavedPlans([newPlan, ...savedPlans]);
    setActivePlanId(newPlan.id);
  };

  const handleDeletePlan = (id: string) => {
    if (confirm("Ar tikrai norite ištrinti šį planą?")) {
      setSavedPlans(savedPlans.filter(p => p.id !== id));
      if (activePlanId === id) {
        setLessonPlan(null);
        setActivePlanId(null);
      }
    }
  };

  const handleLoadPlan = (id: string) => {
    if (editingPlanId) return; // Prevent loading while editing
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setActivePlanId(p.id);
      setGrade(p.grade || '');
      setSubject(p.subject || '');
    }
  };

  const startEditing = (e: React.MouseEvent, plan: SavedPlan) => {
    e.stopPropagation();
    setEditingPlanId(plan.id);
    setEditTitle(plan.title);
    setEditSubject(plan.subject || '');
    setEditGrade(plan.grade || '');
  };

  const cancelEditing = (e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingPlanId(null);
  };

  const savePlanEdits = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!editingPlanId) return;

    setSavedPlans(prev => prev.map(p => {
      if (p.id === editingPlanId) {
        return {
          ...p,
          title: editTitle,
          subject: editSubject,
          grade: editGrade
        };
      }
      return p;
    }));
    setEditingPlanId(null);
  };

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>Jūsų pagalbininkas kūrybiškoms ir efektyvioms pamokoms</p>
        <div className="header-buttons">
          <button onClick={() => setShowOnboarding(true)} className="external-link-button">Kaip naudotis?</button>
          <a href="https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos" target="_blank" rel="noopener noreferrer" className="external-link-button">BP nuoroda</a>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Pamokos informacija</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="pvz., Lietuvių kalba ir literatūra" required />
            </div>
            <div className="form-group">
              <label>Klasė / Grupė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodžio laikai" required />
            </div>
            <div className="form-group">
              <label>Pamokos tipas</label>
              <select value={lessonType} onChange={e => setLessonType(e.target.value as LessonCategory)}>
                <option value="">-- Pasirinkite --</option>
                <option value="Įvadinė">Įvadinė</option>
                <option value="Įtvirtinimo">Įtvirtinimo</option>
                <option value="Apibendrinamoji">Apibendrinamoji</option>
                <option value="Vertinamoji">Vertinamoji</option>
              </select>
            </div>
            <div className="form-group">
              <label>Tikslas (Mokiniai gebės...)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} placeholder="pvz., atpažinti veiksmažodžio laikus..." />
            </div>
            <div className="form-group">
              <label>Veiklos idėjos (pvz., darbas grupėse)</label>
              <textarea value={activities} onChange={e => setActivities(e.target.value)} placeholder="pvz., darbas grupėse, interaktyvus žaidimas..." />
            </div>

            <div className="form-group">
              <label>Vertinimas</label>
              <select value={evaluationType} onChange={e => setEvaluationType(e.target.value)}>
                {EVALUATION_TAGS.map(t => <option key={t} value={t}>{t}</option>)}
              </select>
              <textarea 
                value={evaluationDescription} 
                onChange={e => setEvaluationDescription(e.target.value)} 
                placeholder="Papildomas vertinimo aprašymas..." 
                style={{marginTop: '8px', minHeight: '60px'}}
              />
            </div>

            <div className="form-group checkbox-group" style={{display: 'flex', flexDirection: 'column', gap: '20px', borderTop: '1px solid var(--border-color)', paddingTop: '20px', marginBottom: '20px'}}>
              <div className="checkbox-item">
                <label className="checkbox-label">
                  <input type="checkbox" checked={isIntegratedInput} onChange={e => setIsIntegratedInput(e.target.checked)} />
                  Ar tai integruota pamoka?
                </label>
                {isIntegratedInput && (
                  <div className="nested-input">
                    <label>Su kokiu dalyku, tema?</label>
                    <input 
                      type="text" 
                      value={integrationDetails} 
                      onChange={e => setIntegrationDetails(e.target.value)} 
                      placeholder="Įrašykite detales..." 
                    />
                  </div>
                )}
              </div>

              <div className="checkbox-item">
                <label className="checkbox-label">
                  <input type="checkbox" checked={isOutsideInput} onChange={e => setIsOutsideInput(e.target.checked)} />
                  Ar tai pamoka už mokyklos ribų?
                </label>
                {isOutsideInput && (
                  <div className="nested-input">
                    <label>Kur vyks pamoka?</label>
                    <input 
                      type="text" 
                      value={locationDetails} 
                      onChange={e => setLocationDetails(e.target.value)} 
                      placeholder="Vieta, muziejus, gamta..." 
                    />
                  </div>
                )}
              </div>
            </div>

            <div className="form-group">
              <label>Pedagoginė konsultacija (iššūkiai)</label>
              <textarea value={consultationChallenges} onChange={e => setConsultationChallenges(e.target.value)} placeholder="pvz., mokinys su ADHD, triukšminga klasė..." />
            </div>

            <button type="submit" disabled={isLoading} className="generate-button" style={{marginTop: '20px'}}>
              {isLoading ? <div className="spinner"></div> : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {savedPlans.filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase())).map(p => (
                <li 
                  key={p.id} 
                  onClick={() => handleLoadPlan(p.id)} 
                  className={`${activePlanId === p.id ? 'active' : ''} ${editingPlanId === p.id ? 'editing' : ''}`}
                >
                  {editingPlanId === p.id ? (
                    <div className="edit-plan-form" onClick={e => e.stopPropagation()}>
                      <input type="text" value={editTitle} onChange={e => setEditTitle(e.target.value)} placeholder="Pavadinimas" className="edit-input" />
                      <div className="edit-row">
                        <input type="text" value={editSubject} onChange={e => setEditSubject(e.target.value)} placeholder="Dalykas" className="edit-input-small" />
                        <input type="text" value={editGrade} onChange={e => setEditGrade(e.target.value)} placeholder="Klasė" className="edit-input-small" />
                      </div>
                      <div className="edit-actions">
                        <button onClick={savePlanEdits} className="save-edit-button">Išsaugoti</button>
                        <button onClick={cancelEditing} className="cancel-edit-button">Atšaukti</button>
                      </div>
                    </div>
                  ) : (
                    <>
                      <div className="plan-info">
                        <span className="plan-title">{p.title}</span>
                        <div className="plan-meta">
                          {p.subject && <span className="meta-tag">{p.subject}</span>}
                          {p.grade && <span className="meta-tag">{p.grade}</span>}
                        </div>
                      </div>
                      <div className="plan-actions">
                        <button onClick={e => startEditing(e, p)} className="edit-button-icon" title="Redaguoti">✏️</button>
                        <button onClick={e => { e.stopPropagation(); handleDeletePlan(p.id); }} className="delete-button" title="Ištrinti">✖</button>
                      </div>
                    </>
                  )}
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && <div className="loading-overlay"><div className="spinner-large"></div><p>Ruošiamas pamokos planas...</p></div>}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !lessonPlan && !error && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Užpildykite formą kairėje ir aš padėsiu jums paruošti kūrybišką pamokos planą.</p>
            </div>
          )}

          {lessonPlan && (
            <div className="lesson-plan-result">
              <div className="export-container">
                <button onClick={confirmSavePlan} className="save-button">Išsaugoti planą 💾</button>
              </div>

              <div className="card general-notes-card">
                <h3>📌 Bendros pastabos (redaguojama)</h3>
                <textarea 
                  value={lessonPlan.generalNotes} 
                  onChange={e => setLessonPlan({...lessonPlan, generalNotes: e.target.value})} 
                  className="notes-edit-area" 
                  style={{
                    width: '100%', 
                    minHeight: '120px', 
                    padding: '15px', 
                    border: '1px solid var(--border-color)', 
                    background: 'var(--background-color)', 
                    color: 'var(--heading-color)', 
                    fontSize: '1rem',
                    fontWeight: '500'
                  }} 
                />
              </div>

              <div className="card lesson-overview-card">
                <h3>📖 Apžvalga ({lessonPlan.lessonType || 'Pamoka'})</h3>
                <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                <p><strong>Tikslas:</strong> {lessonPlan.lessonOverview.goal}</p>
                <p><strong>Gebėjimai:</strong> {lessonPlan.lessonOverview.competencies}</p>
                <p><strong>Vertinimas dienyne:</strong> {evaluationType}</p>
              </div>

              {lessonPlan.specialAdvice && (
                <div className="card consultation-card">
                  <h3>🌟 Integracijos ir išvykos patarimai</h3>
                  <p style={{whiteSpace: 'pre-wrap', fontWeight: 'bold', color: 'var(--warning-color)'}}>{lessonPlan.specialAdvice}</p>
                </div>
              )}

              {lessonPlan.consultationAdvice && (
                <div className="card consultation-card">
                  <h3>💡 Pedagoginė konsultacija</h3>
                  <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.consultationAdvice}</p>
                </div>
              )}

              <div className="card lesson-activities-card">
                <h3>🎨 Veiklos</h3>
                <p><strong>🙂 Bendra:</strong> {lessonPlan.lessonActivities.general}</p>
                <p><strong>🚀 Gabesniems:</strong> {lessonPlan.lessonActivities.gifted}</p>
                <p><strong>🌱 Pagalba:</strong> {lessonPlan.lessonActivities.struggling}</p>
              </div>

              <div className="card ediary-card">
                <h3>✍️ El. dienyno įrašai</h3>
                <div style={{display: 'flex', gap: '15px', marginBottom: '15px'}}>
                  <label style={{display: 'flex', alignItems: 'center', gap: '5px', fontSize: '0.9rem', color: lessonPlan.eDiaryEntry.isIntegrated ? 'var(--success-color)' : 'var(--text-color)', fontWeight: 'bold'}}>
                    <input type="checkbox" checked={lessonPlan.eDiaryEntry.isIntegrated} readOnly /> Integruota pamoka
                  </label>
                  <label style={{display: 'flex', alignItems: 'center', gap: '5px', fontSize: '0.9rem', color: lessonPlan.eDiaryEntry.isOutside ? 'var(--success-color)' : 'var(--text-color)', fontWeight: 'bold'}}>
                    <input type="checkbox" checked={lessonPlan.eDiaryEntry.isOutside} readOnly /> Pamoka už mokyklos ribų
                  </label>
                </div>

                {[
                  { label: "Pamokos tipas", val: lessonPlan.eDiaryEntry.eDiaryLessonType, id: 'diary-type' },
                  { label: "Tema, klasės darbai, numatomi pasiekimai", val: lessonPlan.eDiaryEntry.topicClassworkExpectations, id: 'diary-topic' },
                  { label: "Namų darbai", val: lessonPlan.eDiaryEntry.homework, id: 'diary-hw' },
                  { label: "Individualūs namų darbai", val: lessonPlan.eDiaryEntry.individualHomework, id: 'diary-ind-hw' },
                  { label: "Pastabos apie pamoką", val: lessonPlan.eDiaryEntry.notes, id: 'diary-notes' }
                ].map(f => (
                  <div key={f.id} className="diary-entry" style={{marginBottom: '15px'}}>
                    <label style={{display: 'block', fontWeight: 'bold', fontSize: '0.85rem', marginBottom: '4px'}}>{f.label}:</label>
                    <div className="diary-field">
                      <span style={{fontSize: '0.95rem', whiteSpace: 'pre-wrap', lineHeight: '1.5'}}>{f.val || '---'}</span>
                      <button onClick={() => handleCopy(f.val, f.id)} className={`copy-button ${copiedField === f.id ? 'copied' : ''}`}>
                        {copiedField === f.id ? "Nukopijuota" : "Kopijuoti"}
                      </button>
                    </div>
                  </div>
                ))}
              </div>

              <div className="card motivation-card">
                <h3>💖 Ačiū TAU, Mokytojau!</h3>
                <p style={{whiteSpace: 'pre-wrap', fontWeight: '500'}}>{lessonPlan.motivation}</p>
              </div>
            </div>
          )}
        </div>
      </main>

      {showOnboarding && (
        <div className="modal-overlay" onClick={() => setShowOnboarding(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <button className="modal-close-button" onClick={() => setShowOnboarding(false)}>&times;</button>
            <h2>Kaip naudotis programėle?</h2>
            <div className="onboarding-step-content" style={{textAlign: 'left'}}>
              <p>1. Užpildykite kairėje pusėje esančią formą.</p>
              <p>2. Jei pamoka integruota ar vyks išvykoje – būtinai tai pažymėkite!</p>
              <p>3. DI pateiks specifinius patarimus, kaip suformuoti el. dienyno įrašą ir pamokos plano įgyvendinimą.</p>
              <p>4. Rezultatuose rasite tekstus susijusius su Bendrųjų ugdymo programų temomis; siūlomu klasės darbu, galimą pasiekimų vertinimą suformuotus naujose eilutėse.</p>
              <p>5. Planą galite išsaugoti ir koreguoti.</p>
            </div>
            <div className="modal-actions">
              <button onClick={() => setShowOnboarding(false)} className="button-primary">Supratau</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
  eDiaryLessonType: string;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: string;
  };
  lessonActivities: {
    gifted: string;
    general: string;
    struggling: string;
    itTools?: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  consultationAdvice?: string;
  specialAdvice?: string; 
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
}

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [consultationChallenges, setConsultationChallenges] = useState('');

  const [isIntegratedInput, setIsIntegratedInput] = useState(false);
  const [integrationDetails, setIntegrationDetails] = useState('');
  const [isOutsideInput, setIsOutsideInput] = useState(false);
  const [locationDetails, setLocationDetails] = useState('');

  const [evaluationType, setEvaluationType] = useState(EVALUATION_TAGS[0]);
  const [evaluationDescription, setEvaluationDescription] = useState('');

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [showOnboarding, setShowOnboarding] = useState(false);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  // Editing state for saved plans
  const [editingPlanId, setEditingPlanId] = useState<string | null>(null);
  const [editTitle, setEditTitle] = useState('');
  const [editSubject, setEditSubject] = useState('');
  const [editGrade, setEditGrade] = useState('');

  // Deletion state
  const [deletingPlanId, setDeletingPlanId] = useState<string | null>(null);

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas. Sukurk išsamų pamokos planą JSON formatu lietuvių kalba.

SVARBIOS TAISYKLĖS FORMAVIMUI:
Lauke 'topicClassworkExpectations' informaciją PRIVALAI pateikti tiksliai tokia struktūra (naudok naujas eilutes \\n):
Temą: [tekstas susijęs su BP temomis]
Klasės darbą: [tekstas su siūlomu darbu]
Numatomus pasiekimus: [tekstas su galimu vertinimu]

SVARBU DĖL INTEGRACIJOS IR IŠVYKŲ:
1. Jei pažymėta, kad pamoka INTEGRUOTA, 'specialAdvice' lauke pateik patarimus kaip efektyviai integruoti nurodytą dalyką/temą. PRIMYGTINAI nurodyk mokytojui, kad tai BŪTINA pažymėti el. dienyne.
2. Jei pažymėta, kad pamoka UŽ MOKYKLOS RIBŲ, 'specialAdvice' lauke pateik konkrečias ugdymo temas ir užduotis mokiniams išvykoje pagal nurodytą vietą. PRIMYGTINAI nurodyk mokytojui, kad tai BŪTINA pažymėti el. dienyne.

Struktūra:
{
  "generalNotes": "Ryškios pasirengimo instrukcijos",
  "lessonType": "Tipas",
  "lessonOverview": { "topic": "", "goal": "", "competencies": "", "evaluation": "" },
  "lessonActivities": { "gifted": "", "general": "", "struggling": "", "itTools": "" },
  "homework": { "purpose": "", "gifted": "", "general": "", "struggling": "" },
  "eDiaryEntry": {
    "topicClassworkExpectations": "Temą: ...\\nKlasės darbą: ...\\nNumatomus pasiekimus: ...",
    "homework": "Namų darbai",
    "individualHomework": "Individualūs namų darbai",
    "notes": "Pastabos",
    "isIntegrated": false,
    "isOutside": false,
    "eDiaryLessonType": "Pamokos tipas el. dienyne"
  },
  "specialAdvice": "Patarimai integracijai/išvykai ir PRIMYGTINIS priminimas mokytojui pažymėti el. dienyne!",
  "consultationAdvice": "Patarimai dėl iššūkių",
  "motivation": "Padėkos žinutė mokytojui"
}
Atsakyk TIK JSON formatu.`;

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);

    const prompt = `
      Sukurk pamokos planą:
      - Dalykas: ${subject}, Klasė: ${grade}
      - Tema: ${topic}
      - Pamokos tipas: ${lessonType}
      - Tikslas (Mokiniai gebės...): ${goal}
      - Veiklos idėjos: ${activities}
      - Vertinimo tipas: ${evaluationType}
      - Vertinimo aprašymas: ${evaluationDescription}
      - Pedagoginiai iššūkiai: ${consultationChallenges}
      - AR TAI INTEGRUOTA PAMOKA? ${isIntegratedInput ? `Taip. Su kokiu dalyku, tema? ${integrationDetails}` : 'Ne'}
      - AR TAI PAMOKA UŽ MOKYKLOS RIBŲ? ${isOutsideInput ? `Taip. Kur vyks? ${locationDetails}` : 'Ne'}
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { systemInstruction, responseMimeType: "application/json" },
      });

      const parsedPlan: LessonPlan = JSON.parse(response.text || '{}');
      parsedPlan.eDiaryEntry.isIntegrated = isIntegratedInput;
      parsedPlan.eDiaryEntry.isOutside = isOutsideInput;
      // Numatytasis el. dienyno pamokos tipas
      parsedPlan.eDiaryEntry.eDiaryLessonType = parsedPlan.eDiaryEntry.eDiaryLessonType || parsedPlan.lessonType || lessonType || '';

      setLessonPlan(parsedPlan);
      setActivePlanId(null);
    } catch (e: any) {
      setError(`Klaida generuojant: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const confirmSavePlan = () => {
    if (!lessonPlan) return;
    const newPlan: SavedPlan = {
      id: `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${lessonPlan.lessonOverview.topic}`,
      plan: lessonPlan,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: lessonPlan.lessonType || lessonType,
    };
    setSavedPlans([newPlan, ...savedPlans]);
    setActivePlanId(newPlan.id);
  };

  const triggerDelete = (id: string) => {
    setDeletingPlanId(id);
  };

  const handleConfirmDelete = () => {
    if (!deletingPlanId) return;
    setSavedPlans(savedPlans.filter(p => p.id !== deletingPlanId));
    if (activePlanId === deletingPlanId) {
      setLessonPlan(null);
      setActivePlanId(null);
    }
    setDeletingPlanId(null);
  };

  const handleLoadPlan = (id: string) => {
    if (editingPlanId) return; // Prevent loading while editing
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setActivePlanId(p.id);
      setGrade(p.grade || '');
      setSubject(p.subject || '');
    }
  };

  const startEditing = (e: React.MouseEvent, plan: SavedPlan) => {
    e.stopPropagation();
    setEditingPlanId(plan.id);
    setEditTitle(plan.title);
    setEditSubject(plan.subject || '');
    setEditGrade(plan.grade || '');
  };

  const cancelEditing = (e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingPlanId(null);
  };

  const savePlanEdits = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!editingPlanId) return;

    setSavedPlans(prev => prev.map(p => {
      if (p.id === editingPlanId) {
        return {
          ...p,
          title: editTitle,
          subject: editSubject,
          grade: editGrade
        };
      }
      return p;
    }));
    setEditingPlanId(null);
  };

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>Jūsų pagalbininkas kūrybiškoms ir efektyvioms pamokoms</p>
        <div className="header-buttons">
          <button onClick={() => setShowOnboarding(true)} className="external-link-button">Kaip naudotis?</button>
          <a href="https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos" target="_blank" rel="noopener noreferrer" className="external-link-button">BP nuoroda</a>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Pamokos informacija</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="pvz., Lietuvių kalba ir literatūra" required />
            </div>
            <div className="form-group">
              <label>Klasė / Grupė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodžio laikai" required />
            </div>
            <div className="form-group">
              <label>Pamokos tipas</label>
              <select value={lessonType} onChange={e => setLessonType(e.target.value as LessonCategory)}>
                <option value="">-- Pasirinkite --</option>
                <option value="Įvadinė">Įvadinė</option>
                <option value="Įtvirtinimo">Įtvirtinimo</option>
                <option value="Apibendrinamoji">Apibendrinamoji</option>
                <option value="Vertinamoji">Vertinamoji</option>
              </select>
            </div>
            <div className="form-group">
              <label>Tikslas (Mokiniai gebės...)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} placeholder="pvz., atpažinti veiksmažodžio laikus..." />
            </div>
            <div className="form-group">
              <label>Veiklos idėjos (pvz., darbas grupėse)</label>
              <textarea value={activities} onChange={e => setActivities(e.target.value)} placeholder="pvz., darbas grupėse, interaktyvus žaidimas..." />
            </div>

            <div className="form-group">
              <label>Vertinimas</label>
              <select value={evaluationType} onChange={e => setEvaluationType(e.target.value)}>
                {EVALUATION_TAGS.map(t => <option key={t} value={t}>{t}</option>)}
              </select>
              <textarea 
                value={evaluationDescription} 
                onChange={e => setEvaluationDescription(e.target.value)} 
                placeholder="Papildomas vertinimo aprašymas..." 
                style={{marginTop: '8px', minHeight: '60px'}}
              />
            </div>

            <div className="form-group checkbox-group" style={{display: 'flex', flexDirection: 'column', gap: '20px', borderTop: '1px solid var(--border-color)', paddingTop: '20px', marginBottom: '20px'}}>
              <div className="checkbox-item">
                <label className="checkbox-label">
                  <input type="checkbox" checked={isIntegratedInput} onChange={e => setIsIntegratedInput(e.target.checked)} />
                  Ar tai integruota pamoka?
                </label>
                {isIntegratedInput && (
                  <div className="nested-input">
                    <label>Su kokiu dalyku, tema?</label>
                    <input 
                      type="text" 
                      value={integrationDetails} 
                      onChange={e => setIntegrationDetails(e.target.value)} 
                      placeholder="Įrašykite detales..." 
                    />
                  </div>
                )}
              </div>

              <div className="checkbox-item">
                <label className="checkbox-label">
                  <input type="checkbox" checked={isOutsideInput} onChange={e => setIsOutsideInput(e.target.checked)} />
                  Ar tai pamoka už mokyklos ribų?
                </label>
                {isOutsideInput && (
                  <div className="nested-input">
                    <label>Kur vyks pamoka?</label>
                    <input 
                      type="text" 
                      value={locationDetails} 
                      onChange={e => setLocationDetails(e.target.value)} 
                      placeholder="Vieta, muziejus, gamta..." 
                    />
                  </div>
                )}
              </div>
            </div>

            <div className="form-group">
              <label>Pedagoginė konsultacija (iššūkiai)</label>
              <textarea value={consultationChallenges} onChange={e => setConsultationChallenges(e.target.value)} placeholder="pvz., mokinys su ADHD, triukšminga klasė..." />
            </div>

            <button type="submit" disabled={isLoading} className="generate-button" style={{marginTop: '20px'}}>
              {isLoading ? <div className="spinner"></div> : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {savedPlans.filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase())).map(p => (
                <li 
                  key={p.id} 
                  onClick={() => handleLoadPlan(p.id)} 
                  className={`${activePlanId === p.id ? 'active' : ''} ${editingPlanId === p.id ? 'editing' : ''}`}
                >
                  {editingPlanId === p.id ? (
                    <div className="edit-plan-form" onClick={e => e.stopPropagation()}>
                      <input type="text" value={editTitle} onChange={e => setEditTitle(e.target.value)} placeholder="Pavadinimas" className="edit-input" />
                      <div className="edit-row">
                        <input type="text" value={editSubject} onChange={e => setEditSubject(e.target.value)} placeholder="Dalykas" className="edit-input-small" />
                        <input type="text" value={editGrade} onChange={e => setEditGrade(e.target.value)} placeholder="Klasė" className="edit-input-small" />
                      </div>
                      <div className="edit-actions">
                        <button onClick={savePlanEdits} className="save-edit-button">Išsaugoti</button>
                        <button onClick={cancelEditing} className="cancel-edit-button">Atšaukti</button>
                      </div>
                    </div>
                  ) : (
                    <>
                      <div className="plan-info">
                        <span className="plan-title">{p.title}</span>
                        <div className="plan-meta">
                          {p.subject && <span className="meta-tag">{p.subject}</span>}
                          {p.grade && <span className="meta-tag">{p.grade}</span>}
                        </div>
                      </div>
                      <div className="plan-actions">
                        <button onClick={e => startEditing(e, p)} className="edit-button-icon" title="Redaguoti">✏️</button>
                        <button onClick={e => { e.stopPropagation(); triggerDelete(p.id); }} className="delete-button" title="Ištrinti">✖</button>
                      </div>
                    </>
                  )}
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && <div className="loading-overlay"><div className="spinner-large"></div><p>Ruošiamas pamokos planas...</p></div>}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !lessonPlan && !error && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Užpildykite formą kairėje ir aš padėsiu jums paruošti kūrybišką pamokos planą.</p>
            </div>
          )}

          {lessonPlan && (
            <div className="lesson-plan-result">
              <div className="export-container">
                <button onClick={confirmSavePlan} className="save-button">Išsaugoti planą 💾</button>
              </div>

              <div className="card general-notes-card">
                <h3>📌 Bendros pastabos (redaguojama)</h3>
                <textarea 
                  value={lessonPlan.generalNotes} 
                  onChange={e => setLessonPlan({...lessonPlan, generalNotes: e.target.value})} 
                  className="notes-edit-area" 
                  style={{
                    width: '100%', 
                    minHeight: '120px', 
                    padding: '15px', 
                    border: '1px solid var(--border-color)', 
                    background: 'var(--background-color)', 
                    color: 'var(--heading-color)', 
                    fontSize: '1rem',
                    fontWeight: '500'
                  }} 
                />
              </div>

              <div className="card lesson-overview-card">
                <h3>📖 Apžvalga ({lessonPlan.lessonType || 'Pamoka'})</h3>
                <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                <p><strong>Tikslas:</strong> {lessonPlan.lessonOverview.goal}</p>
                <p><strong>Gebėjimai:</strong> {lessonPlan.lessonOverview.competencies}</p>
                <p><strong>Vertinimas dienyne:</strong> {evaluationType}</p>
              </div>

              {lessonPlan.specialAdvice && (
                <div className="card consultation-card">
                  <h3>🌟 Integracijos ir išvykos patarimai</h3>
                  <p style={{whiteSpace: 'pre-wrap', fontWeight: 'bold', color: 'var(--warning-color)'}}>{lessonPlan.specialAdvice}</p>
                </div>
              )}

              {lessonPlan.consultationAdvice && (
                <div className="card consultation-card">
                  <h3>💡 Pedagoginė konsultacija</h3>
                  <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.consultationAdvice}</p>
                </div>
              )}

              <div className="card lesson-activities-card">
                <h3>🎨 Veiklos</h3>
                <p><strong>🙂 Bendra:</strong> {lessonPlan.lessonActivities.general}</p>
                <p><strong>🚀 Gabesniems:</strong> {lessonPlan.lessonActivities.gifted}</p>
                <p><strong>🌱 Pagalba:</strong> {lessonPlan.lessonActivities.struggling}</p>
              </div>

              <div className="card ediary-card">
                <h3>✍️ El. dienyno įrašai</h3>
                <div style={{display: 'flex', gap: '15px', marginBottom: '15px'}}>
                  <label style={{display: 'flex', alignItems: 'center', gap: '5px', fontSize: '0.9rem', color: lessonPlan.eDiaryEntry.isIntegrated ? 'var(--success-color)' : 'var(--text-color)', fontWeight: 'bold'}}>
                    <input type="checkbox" checked={lessonPlan.eDiaryEntry.isIntegrated} readOnly /> Integruota pamoka
                  </label>
                  <label style={{display: 'flex', alignItems: 'center', gap: '5px', fontSize: '0.9rem', color: lessonPlan.eDiaryEntry.isOutside ? 'var(--success-color)' : 'var(--text-color)', fontWeight: 'bold'}}>
                    <input type="checkbox" checked={lessonPlan.eDiaryEntry.isOutside} readOnly /> Pamoka už mokyklos ribų
                  </label>
                </div>

                {[
                  { label: "Pamokos tipas", val: lessonPlan.eDiaryEntry.eDiaryLessonType, id: 'diary-type' },
                  { label: "Tema, klasės darbai, numatomi pasiekimai", val: lessonPlan.eDiaryEntry.topicClassworkExpectations, id: 'diary-topic' },
                  { label: "Namų darbai", val: lessonPlan.eDiaryEntry.homework, id: 'diary-hw' },
                  { label: "Individualūs namų darbai", val: lessonPlan.eDiaryEntry.individualHomework, id: 'diary-ind-hw' },
                  { label: "Pastabos apie pamoką", val: lessonPlan.eDiaryEntry.notes, id: 'diary-notes' }
                ].map(f => (
                  <div key={f.id} className="diary-entry" style={{marginBottom: '15px'}}>
                    <label style={{display: 'block', fontWeight: 'bold', fontSize: '0.85rem', marginBottom: '4px'}}>{f.label}:</label>
                    <div className="diary-field">
                      <span style={{fontSize: '0.95rem', whiteSpace: 'pre-wrap', lineHeight: '1.5'}}>{f.val || '---'}</span>
                      <button onClick={() => handleCopy(f.val, f.id)} className={`copy-button ${copiedField === f.id ? 'copied' : ''}`}>
                        {copiedField === f.id ? "Nukopijuota" : "Kopijuoti"}
                      </button>
                    </div>
                  </div>
                ))}
              </div>

              <div className="card motivation-card">
                <h3>💖 Ačiū TAU, Mokytojau!</h3>
                <p style={{whiteSpace: 'pre-wrap', fontWeight: '500'}}>{lessonPlan.motivation}</p>
              </div>
            </div>
          )}
        </div>
      </main>

      {showOnboarding && (
        <div className="modal-overlay" onClick={() => setShowOnboarding(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <button className="modal-close-button" onClick={() => setShowOnboarding(false)}>&times;</button>
            <h2>Kaip naudotis programėle?</h2>
            <div className="onboarding-step-content" style={{textAlign: 'left'}}>
              <p>1. Užpildykite kairėje pusėje esančią formą.</p>
              <p>2. Jei pamoka integruota ar vyks išvykoje – būtinai tai pažymėkite!</p>
              <p>3. DI pateiks specifinius patarimus, kaip suformuoti el. dienyno įrašą ir pamokos plano įgyvendinimą.</p>
              <p>4. Rezultatuose rasite tekstus susijusius su Bendrųjų ugdymo programų temomis; siūlomu klasės darbu, galimą pasiekimų vertinimą suformuotus naujose eilutėse.</p>
              <p>5. Planą galite išsaugoti ir koreguoti.</p>
            </div>
            <div className="modal-actions">
              <button onClick={() => setShowOnboarding(false)} className="button-primary">Supratau</button>
            </div>
          </div>
        </div>
      )}

      {deletingPlanId && (
        <div className="modal-overlay" onClick={() => setDeletingPlanId(null)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2>Patvirtinti trinimą</h2>
            <p style={{marginBottom: '1.5rem', color: 'var(--text-color-light)'}}>
              Ar tikrai norite ištrinti šį pamokos planą? Šio veiksmo atšaukti nepavyks.
            </p>
            <div className="modal-actions" style={{display: 'flex', gap: '1rem', justifyContent: 'flex-end'}}>
              <button onClick={() => setDeletingPlanId(null)} className="cancel-edit-button" style={{padding: '0.6rem 1.2rem'}}>Atšaukti</button>
              <button onClick={handleConfirmDelete} className="save-edit-button" style={{padding: '0.6rem 1.2rem', backgroundColor: 'var(--error-color)'}}>Ištrinti</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
  eDiaryLessonType: string;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: string;
  };
  lessonActivities: {
    gifted: string;
    general: string;
    struggling: string;
    itTools?: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  consultationAdvice?: string;
  specialAdvice?: string; 
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
}

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [consultationChallenges, setConsultationChallenges] = useState('');

  const [isIntegratedInput, setIsIntegratedInput] = useState(false);
  const [integrationDetails, setIntegrationDetails] = useState('');
  const [isOutsideInput, setIsOutsideInput] = useState(false);
  const [locationDetails, setLocationDetails] = useState('');

  const [evaluationType, setEvaluationType] = useState(EVALUATION_TAGS[0]);
  const [evaluationDescription, setEvaluationDescription] = useState('');

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [showOnboarding, setShowOnboarding] = useState(false);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const [editingPlanId, setEditingPlanId] = useState<string | null>(null);
  const [editTitle, setEditTitle] = useState('');
  const [editSubject, setEditSubject] = useState('');
  const [editGrade, setEditGrade] = useState('');

  const [deletingPlanId, setDeletingPlanId] = useState<string | null>(null);

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas. Sukurk išsamų pamokos planą JSON formatu lietuvių kalba.

SVARBIOS TAISYKLĖS FORMAVIMUI:
Lauke 'topicClassworkExpectations' informaciją PRIVALAI pateikti tiksliai tokia struktūra (naudok naujas eilutes \\n):
Temą: [tekstas susijęs su BP temomis]
Klasės darbą: [tekstas su siūlomu darbu]
Numatomus pasiekimus: [tekstas su galimu vertinimu]

SVARBU DĖL INTEGRACIJOS IR IŠVYKŲ:
1. Jei pažymėta, kad pamoka INTEGRUOTA, 'specialAdvice' lauke pateik patarimus kaip efektyviai integruoti nurodytą dalyką/temą. PRIMYGTINAI nurodyk mokytojui, kad tai BŪTINA pažymėti el. dienyne.
2. Jei pažymėta, kad pamoka UŽ MOKYKLOS RIBŲ, 'specialAdvice' lauke pateik konkrečias ugdymo temas ir užduotis mokiniams išvykoje pagal nurodytą vietą. PRIMYGTINAI nurodyk mokytojui, kad tai BŪTINA pažymėti el. dienyne.

Struktūra:
{
  "generalNotes": "Ryškios pasirengimo instrukcijos",
  "lessonType": "Tipas",
  "lessonOverview": { "topic": "", "goal": "", "competencies": "", "evaluation": "" },
  "lessonActivities": { "gifted": "", "general": "", "struggling": "", "itTools": "" },
  "homework": { "purpose": "", "gifted": "", "general": "", "struggling": "" },
  "eDiaryEntry": {
    "topicClassworkExpectations": "Temą: ...\\nKlasės darbą: ...\\nNumatomus pasiekimus: ...",
    "homework": "Namų darbai",
    "individualHomework": "Individualūs namų darbai",
    "notes": "Pastabos",
    "isIntegrated": false,
    "isOutside": false,
    "eDiaryLessonType": "Pamokos tipas el. dienyne"
  },
  "specialAdvice": "Patarimai integracijai/išvykai ir PRIMYGTINIS priminimas mokytojui pažymėti el. dienyne!",
  "consultationAdvice": "Patarimai dėl iššūkių",
  "motivation": "Padėkos žinutė mokytojui"
}
Atsakyk TIK JSON formatu.`;

  const tryParseJSON = (text: string): LessonPlan | null => {
    try {
      return JSON.parse(text);
    } catch (e) {
      console.warn("Tiesioginis JSON parsinimas nepavyko, bandoma ištraukti bloką...");
      const jsonMatch = text.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        try {
          return JSON.parse(jsonMatch[0]);
        } catch (e2) {
          console.error("Nepavyko ištraukti JSON bloko:", e2);
        }
      }
      return null;
    }
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);

    const prompt = `
      Sukurk pamokos planą:
      - Dalykas: ${subject}, Klasė: ${grade}
      - Tema: ${topic}
      - Pamokos tipas: ${lessonType}
      - Tikslas (Mokiniai gebės...): ${goal}
      - Veiklos idėjos: ${activities}
      - Vertinimo tipas: ${evaluationType}
      - Vertinimo aprašymas: ${evaluationDescription}
      - Pedagoginiai iššūkiai: ${consultationChallenges}
      - AR TAI INTEGRUOTA PAMOKA? ${isIntegratedInput ? `Taip. Su kokiu dalyku, tema? ${integrationDetails}` : 'Ne'}
      - AR TAI PAMOKA UŽ MOKYKLOS RIBŲ? ${isOutsideInput ? `Taip. Kur vyks? ${locationDetails}` : 'Ne'}
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { systemInstruction, responseMimeType: "application/json" },
      });

      const parsedPlan = tryParseJSON(response.text || '');

      if (!parsedPlan) {
        throw new Error("AI sugeneravo netinkamą duomenų formatą. Prašome pabandyti dar kartą.");
      }

      // Užtikriname, kad visi būtini laukai egzistuoja (minimalus fallback)
      const sanitizedPlan: LessonPlan = {
        ...parsedPlan,
        eDiaryEntry: {
          topicClassworkExpectations: parsedPlan.eDiaryEntry?.topicClassworkExpectations || '',
          homework: parsedPlan.eDiaryEntry?.homework || '',
          individualHomework: parsedPlan.eDiaryEntry?.individualHomework || '',
          notes: parsedPlan.eDiaryEntry?.notes || '',
          isIntegrated: isIntegratedInput,
          isOutside: isOutsideInput,
          eDiaryLessonType: parsedPlan.eDiaryEntry?.eDiaryLessonType || parsedPlan.lessonType || lessonType || ''
        }
      };

      setLessonPlan(sanitizedPlan);
      setActivePlanId(null);
    } catch (e: any) {
      setError(`Klaida generuojant: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const confirmSavePlan = () => {
    if (!lessonPlan) return;
    const newPlan: SavedPlan = {
      id: `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${lessonPlan.lessonOverview.topic}`,
      plan: lessonPlan,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: lessonPlan.lessonType || lessonType,
    };
    setSavedPlans([newPlan, ...savedPlans]);
    setActivePlanId(newPlan.id);
  };

  const triggerDelete = (id: string) => {
    setDeletingPlanId(id);
  };

  const handleConfirmDelete = () => {
    if (!deletingPlanId) return;
    setSavedPlans(savedPlans.filter(p => p.id !== deletingPlanId));
    if (activePlanId === deletingPlanId) {
      setLessonPlan(null);
      setActivePlanId(null);
    }
    setDeletingPlanId(null);
  };

  const handleLoadPlan = (id: string) => {
    if (editingPlanId) return;
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setActivePlanId(p.id);
      setGrade(p.grade || '');
      setSubject(p.subject || '');
    }
  };

  const startEditing = (e: React.MouseEvent, plan: SavedPlan) => {
    e.stopPropagation();
    setEditingPlanId(plan.id);
    setEditTitle(plan.title);
    setEditSubject(plan.subject || '');
    setEditGrade(plan.grade || '');
  };

  const cancelEditing = (e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingPlanId(null);
  };

  const savePlanEdits = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!editingPlanId) return;

    setSavedPlans(prev => prev.map(p => {
      if (p.id === editingPlanId) {
        return {
          ...p,
          title: editTitle,
          subject: editSubject,
          grade: editGrade
        };
      }
      return p;
    }));
    setEditingPlanId(null);
  };

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>Jūsų pagalbininkas kūrybiškoms ir efektyvioms pamokoms</p>
        <div className="header-buttons">
          <button onClick={() => setShowOnboarding(true)} className="external-link-button">Kaip naudotis?</button>
          <a href="https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos" target="_blank" rel="noopener noreferrer" className="external-link-button">BP nuoroda</a>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Pamokos informacija</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="pvz., Lietuvių kalba ir literatūra" required />
            </div>
            <div className="form-group">
              <label>Klasė / Grupė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodžio laikai" required />
            </div>
            <div className="form-group">
              <label>Pamokos tipas</label>
              <select value={lessonType} onChange={e => setLessonType(e.target.value as LessonCategory)}>
                <option value="">-- Pasirinkite --</option>
                <option value="Įvadinė">Įvadinė</option>
                <option value="Įtvirtinimo">Įtvirtinimo</option>
                <option value="Apibendrinamoji">Apibendrinamoji</option>
                <option value="Vertinamoji">Vertinamoji</option>
              </select>
            </div>
            <div className="form-group">
              <label>Tikslas (Mokiniai gebės...)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} placeholder="pvz., atpažinti veiksmažodžio laikus..." />
            </div>
            <div className="form-group">
              <label>Veiklos idėjos (pvz., darbas grupėse)</label>
              <textarea value={activities} onChange={e => setActivities(e.target.value)} placeholder="pvz., darbas grupėse, interaktyvus žaidimas..." />
            </div>

            <div className="form-group">
              <label>Vertinimas</label>
              <select value={evaluationType} onChange={e => setEvaluationType(e.target.value)}>
                {EVALUATION_TAGS.map(t => <option key={t} value={t}>{t}</option>)}
              </select>
              <textarea 
                value={evaluationDescription} 
                onChange={e => setEvaluationDescription(e.target.value)} 
                placeholder="Papildomas vertinimo aprašymas..." 
                style={{marginTop: '8px', minHeight: '60px'}}
              />
            </div>

            <div className="form-group checkbox-group" style={{display: 'flex', flexDirection: 'column', gap: '20px', borderTop: '1px solid var(--border-color)', paddingTop: '20px', marginBottom: '20px'}}>
              <div className="checkbox-item">
                <label className="checkbox-label">
                  <input type="checkbox" checked={isIntegratedInput} onChange={e => setIsIntegratedInput(e.target.checked)} />
                  Ar tai integruota pamoka?
                </label>
                {isIntegratedInput && (
                  <div className="nested-input">
                    <label>Su kokiu dalyku, tema?</label>
                    <input 
                      type="text" 
                      value={integrationDetails} 
                      onChange={e => setIntegrationDetails(e.target.value)} 
                      placeholder="Įrašykite detales..." 
                    />
                  </div>
                )}
              </div>

              <div className="checkbox-item">
                <label className="checkbox-label">
                  <input type="checkbox" checked={isOutsideInput} onChange={e => setIsOutsideInput(e.target.checked)} />
                  Ar tai pamoka už mokyklos ribų?
                </label>
                {isOutsideInput && (
                  <div className="nested-input">
                    <label>Kur vyks pamoka?</label>
                    <input 
                      type="text" 
                      value={locationDetails} 
                      onChange={e => setLocationDetails(e.target.value)} 
                      placeholder="Vieta, muziejus, gamta..." 
                    />
                  </div>
                )}
              </div>
            </div>

            <div className="form-group">
              <label>Pedagoginė konsultacija (iššūkiai)</label>
              <textarea value={consultationChallenges} onChange={e => setConsultationChallenges(e.target.value)} placeholder="pvz., mokinys su ADHD, triukšminga klasė..." />
            </div>

            <button type="submit" disabled={isLoading} className="generate-button" style={{marginTop: '20px'}}>
              {isLoading ? <div className="spinner"></div> : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {savedPlans.filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase())).map(p => (
                <li 
                  key={p.id} 
                  onClick={() => handleLoadPlan(p.id)} 
                  className={`${activePlanId === p.id ? 'active' : ''} ${editingPlanId === p.id ? 'editing' : ''}`}
                >
                  {editingPlanId === p.id ? (
                    <div className="edit-plan-form" onClick={e => e.stopPropagation()}>
                      <input type="text" value={editTitle} onChange={e => setEditTitle(e.target.value)} placeholder="Pavadinimas" className="edit-input" />
                      <div className="edit-row">
                        <input type="text" value={editSubject} onChange={e => setEditSubject(e.target.value)} placeholder="Dalykas" className="edit-input-small" />
                        <input type="text" value={editGrade} onChange={e => setEditGrade(e.target.value)} placeholder="Klasė" className="edit-input-small" />
                      </div>
                      <div className="edit-actions">
                        <button onClick={savePlanEdits} className="save-edit-button">Išsaugoti</button>
                        <button onClick={cancelEditing} className="cancel-edit-button">Atšaukti</button>
                      </div>
                    </div>
                  ) : (
                    <>
                      <div className="plan-info">
                        <span className="plan-title">{p.title}</span>
                        <div className="plan-meta">
                          {p.subject && <span className="meta-tag">{p.subject}</span>}
                          {p.grade && <span className="meta-tag">{p.grade}</span>}
                        </div>
                      </div>
                      <div className="plan-actions">
                        <button onClick={e => startEditing(e, p)} className="edit-button-icon" title="Redaguoti">✏️</button>
                        <button onClick={e => { e.stopPropagation(); triggerDelete(p.id); }} className="delete-button" title="Ištrinti">✖</button>
                      </div>
                    </>
                  )}
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && <div className="loading-overlay"><div className="spinner-large"></div><p>Ruošiamas pamokos planas...</p></div>}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !lessonPlan && !error && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Užpildykite formą kairėje ir aš padėsiu jums paruošti kūrybišką pamokos planą.</p>
            </div>
          )}

          {lessonPlan && (
            <div className="lesson-plan-result">
              <div className="export-container">
                <button onClick={confirmSavePlan} className="save-button">Išsaugoti planą 💾</button>
              </div>

              <div className="card general-notes-card">
                <h3>📌 Bendros pastabos (redaguojama)</h3>
                <textarea 
                  value={lessonPlan.generalNotes} 
                  onChange={e => setLessonPlan({...lessonPlan, generalNotes: e.target.value})} 
                  className="notes-edit-area" 
                  style={{
                    width: '100%', 
                    minHeight: '120px', 
                    padding: '15px', 
                    border: '1px solid var(--border-color)', 
                    background: 'var(--background-color)', 
                    color: 'var(--heading-color)', 
                    fontSize: '1rem',
                    fontWeight: '500'
                  }} 
                />
              </div>

              <div className="card lesson-overview-card">
                <h3>📖 Apžvalga ({lessonPlan.lessonType || 'Pamoka'})</h3>
                <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                <p><strong>Tikslas:</strong> {lessonPlan.lessonOverview.goal}</p>
                <p><strong>Gebėjimai:</strong> {lessonPlan.lessonOverview.competencies}</p>
                <p><strong>Vertinimas dienyne:</strong> {evaluationType}</p>
              </div>

              {lessonPlan.specialAdvice && (
                <div className="card consultation-card">
                  <h3>🌟 Integracijos ir išvykos patarimai</h3>
                  <p style={{whiteSpace: 'pre-wrap', fontWeight: 'bold', color: 'var(--warning-color)'}}>{lessonPlan.specialAdvice}</p>
                </div>
              )}

              {lessonPlan.consultationAdvice && (
                <div className="card consultation-card">
                  <h3>💡 Pedagoginė konsultacija</h3>
                  <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.consultationAdvice}</p>
                </div>
              )}

              <div className="card lesson-activities-card">
                <h3>🎨 Veiklos</h3>
                <p><strong>🙂 Bendra:</strong> {lessonPlan.lessonActivities.general}</p>
                <p><strong>🚀 Gabesniems:</strong> {lessonPlan.lessonActivities.gifted}</p>
                <p><strong>🌱 Pagalba:</strong> {lessonPlan.lessonActivities.struggling}</p>
              </div>

              <div className="card ediary-card">
                <h3>✍️ El. dienyno įrašai</h3>
                <div style={{display: 'flex', gap: '15px', marginBottom: '15px'}}>
                  <label style={{display: 'flex', alignItems: 'center', gap: '5px', fontSize: '0.9rem', color: lessonPlan.eDiaryEntry.isIntegrated ? 'var(--success-color)' : 'var(--text-color)', fontWeight: 'bold'}}>
                    <input type="checkbox" checked={lessonPlan.eDiaryEntry.isIntegrated} readOnly /> Integruota pamoka
                  </label>
                  <label style={{display: 'flex', alignItems: 'center', gap: '5px', fontSize: '0.9rem', color: lessonPlan.eDiaryEntry.isOutside ? 'var(--success-color)' : 'var(--text-color)', fontWeight: 'bold'}}>
                    <input type="checkbox" checked={lessonPlan.eDiaryEntry.isOutside} readOnly /> Pamoka už mokyklos ribų
                  </label>
                </div>

                {[
                  { label: "Pamokos tipas", val: lessonPlan.eDiaryEntry.eDiaryLessonType, id: 'diary-type' },
                  { label: "Tema, klasės darbai, numatomi pasiekimai", val: lessonPlan.eDiaryEntry.topicClassworkExpectations, id: 'diary-topic' },
                  { label: "Namų darbai", val: lessonPlan.eDiaryEntry.homework, id: 'diary-hw' },
                  { label: "Individualūs namų darbai", val: lessonPlan.eDiaryEntry.individualHomework, id: 'diary-ind-hw' },
                  { label: "Pastabos apie pamoką", val: lessonPlan.eDiaryEntry.notes, id: 'diary-notes' }
                ].map(f => (
                  <div key={f.id} className="diary-entry" style={{marginBottom: '15px'}}>
                    <label style={{display: 'block', fontWeight: 'bold', fontSize: '0.85rem', marginBottom: '4px'}}>{f.label}:</label>
                    <div className="diary-field">
                      <span style={{fontSize: '0.95rem', whiteSpace: 'pre-wrap', lineHeight: '1.5'}}>{f.val || '---'}</span>
                      <button onClick={() => handleCopy(f.val, f.id)} className={`copy-button ${copiedField === f.id ? 'copied' : ''}`}>
                        {copiedField === f.id ? "Nukopijuota" : "Kopijuoti"}
                      </button>
                    </div>
                  </div>
                ))}
              </div>

              <div className="card motivation-card">
                <h3>💖 Ačiū TAU, Mokytojau!</h3>
                <p style={{whiteSpace: 'pre-wrap', fontWeight: '500'}}>{lessonPlan.motivation}</p>
              </div>
            </div>
          )}
        </div>
      </main>

      {showOnboarding && (
        <div className="modal-overlay" onClick={() => setShowOnboarding(false)}>
          <div className="modal-content onboarding-modal" onClick={e => e.stopPropagation()}>
            <button className="modal-close-button" onClick={() => setShowOnboarding(false)}>&times;</button>
            <div className="onboarding-header">
              <h2>Kaip naudotis programėle? 🚀</h2>
              <p>Štai 5 žingsniai iki jūsų tobulo pamokos plano:</p>
            </div>
            <div className="onboarding-steps">
              <div className="onboarding-step">
                <div className="step-number">1</div>
                <div className="step-text"><strong>Užpildykite formą:</strong> Įveskite dalyką, klasę, temą ir kitą svarbią informaciją kairėje pusėje.</div>
              </div>
              <div className="onboarding-step">
                <div className="step-number">2</div>
                <div className="step-text"><strong>Pažymėkite ypatybes:</strong> Jei pamoka integruota ar vyks išvykoje – būtinai tai nurodykite!</div>
              </div>
              <div className="onboarding-step">
                <div className="step-number">3</div>
                <div className="step-text"><strong>Gaukite patarimus:</strong> DI pateiks specifinius patarimus el. dienyno įrašui ir pamokos eigai.</div>
              </div>
              <div className="onboarding-step">
                <div className="step-number">4</div>
                <div className="step-text"><strong>Analizuokite rezultatus:</strong> Matysite BP temas, siūlomus darbus ir pasiekimų vertinimą aiškia struktūra.</div>
              </div>
              <div className="onboarding-step">
                <div className="step-number">5</div>
                <div className="step-text"><strong>Išsaugokite:</strong> Galite išsaugoti planą ateičiai, jį redaguoti ar kopijuoti tekstus į dienyną.</div>
              </div>
            </div>
            <div className="modal-actions">
              <button onClick={() => setShowOnboarding(false)} className="button-primary">Pradėti darbą!</button>
            </div>
          </div>
        </div>
      )}

      {deletingPlanId && (
        <div className="modal-overlay" onClick={() => setDeletingPlanId(null)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2>Patvirtinti trinimą</h2>
            <p style={{marginBottom: '1.5rem', color: 'var(--text-color-light)'}}>
              Ar tikrai norite ištrinti šį pamokos planą? Šio veiksmo atšaukti nepavyks.
            </p>
            <div className="modal-actions" style={{display: 'flex', gap: '1rem', justifyContent: 'flex-end'}}>
              <button onClick={() => setDeletingPlanId(null)} className="cancel-edit-button" style={{padding: '0.6rem 1.2rem'}}>Atšaukti</button>
              <button onClick={handleConfirmDelete} className="save-edit-button" style={{padding: '0.6rem 1.2rem', backgroundColor: 'var(--error-color)'}}>Ištrinti</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

:root {
  /* Dark Theme Colors */
  --primary-color: #3b82f6;
  --primary-color-dark: #2563eb;
  --primary-color-light: #1e293b;
  --primary-color-focus: rgba(59, 130, 246, 0.3);
  --secondary-color: #10b981;
  --secondary-color-dark: #059669;
  --background-color: #0f172a;
  --surface-color: #1e293b;
  --text-color: #94a3b8;
  --text-color-light: #cbd5e1;
  --heading-color: #f8fafc;
  --border-color: #334155;
  --shadow-color: rgba(0, 0, 0, 0.4);
  --error-color: #ef4444;
  --error-color-dark: #b91c1c;
  --error-color-light: #450a0a;
  --success-color: #10b981;
  --success-color-dark: #047857;
  --success-color-light: #064e3b;
  --warning-color: #f59e0b;
  --warning-color-light: #451a03;
  --info-color: #8b5cf6;
  --info-color-dark: #6d28d9;
  --info-color-light: #2e1065;
  --disabled-color: #475569;
  --white: #ffffff;
  --black: #000000;

  /* Typography */
  --font-family: 'Inter', sans-serif;
  --font-size-base: 1rem;
  --font-size-sm: 0.85rem;
  --font-size-lg: 1.1rem;
  --font-weight-normal: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;
  --line-height-base: 1.6;

  /* Sizing & Spacing */
  --spacing-xs: 0.25rem;
  --spacing-sm: 0.5rem;
  --spacing-md: 0.75rem;
  --spacing-lg: 1rem;
  --spacing-xl: 1.5rem;
  --spacing-xxl: 2rem;

  /* Borders & Shadows */
  --border-radius-sm: 6px;
  --border-radius-md: 8px;
  --border-radius-lg: 12px;
  --box-shadow-md: 0 4px 12px var(--shadow-color);
  --box-shadow-lg: 0 6px 15px rgba(59, 130, 246, 0.2);

  /* Transitions */
  --transition-speed: 0.3s;
  --transition-timing: ease;

  /* Z-Index */
  --z-index-tooltip: 10;
  --z-index-modal: 1000;
}


* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--background-color);
  color: var(--text-color);
  line-height: var(--line-height-base);
}

.container {
  max-width: 1400px;
  margin: 0 auto;
  padding: var(--spacing-lg);
}

.header {
  text-align: center;
  margin-bottom: var(--spacing-xxl);
  padding: var(--spacing-xl);
  background-color: var(--surface-color);
  border-radius: var(--border-radius-lg);
  box-shadow: var(--box-shadow-md);
  border: 1px solid var(--border-color);
}

.header h1 {
  color: var(--heading-color);
  font-size: 2.5rem;
  font-weight: var(--font-weight-bold);
}

.header p {
  font-size: var(--font-size-lg);
  color: var(--text-color);
}

.header-buttons {
  display: flex;
  justify-content: center;
  gap: var(--spacing-lg);
  margin-top: var(--spacing-lg);
  flex-wrap: wrap;
}

.external-link-button {
  display: inline-block;
  padding: 0.6rem 1.2rem;
  border: 2px solid var(--primary-color);
  border-radius: var(--border-radius-md);
  color: var(--primary-color);
  text-decoration: none;
  font-weight: var(--font-weight-semibold);
  transition: all var(--transition-speed) var(--transition-timing);
  background-color: transparent;
  font-family: var(--font-family);
  font-size: var(--font-size-base);
  cursor: pointer;
}

.external-link-button:hover {
  background-color: var(--primary-color);
  color: var(--white);
}

.main-content {
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: var(--spacing-xxl);
}


/* --- Form Container --- */
.form-container {
  background-color: var(--surface-color);
  padding: var(--spacing-xxl);
  border-radius: var(--border-radius-lg);
  box-shadow: var(--box-shadow-md);
  height: fit-content;
  border: 1px solid var(--border-color);
}

.form-container h2 {
  color: var(--heading-color);
  margin-bottom: var(--spacing-xl);
  text-align: center;
}

.form-group {
  margin-bottom: 1.25rem;
}

.form-group label {
  display: block;
  font-weight: var(--font-weight-semibold);
  color: var(--heading-color);
  margin-bottom: 5px;
}

.form-group input,
.form-group textarea,
.form-group select {
  width: 100%;
  padding: var(--spacing-md);
  border: 1px solid var(--border-color);
  border-radius: var(--border-radius-md);
  font-family: var(--font-family);
  font-size: var(--font-size-base);
  transition: border-color var(--transition-speed), box-shadow var(--transition-speed);
  background-color: #0f172a;
  color: var(--heading-color);
}

.form-group input::placeholder,
.form-group textarea::placeholder {
  color: #475569;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
  outline: none;
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px var(--primary-color-focus);
}

.form-group textarea {
  min-height: 80px;
  resize: vertical;
}

/* --- Checkbox Styling --- */
.checkbox-item {
  display: flex;
  flex-direction: column;
}

.checkbox-label {
  display: flex !important;
  align-items: center;
  gap: 12px;
  cursor: pointer;
  font-weight: var(--font-weight-bold) !important;
  color: var(--heading-color);
  user-select: none;
}

.checkbox-label input[type="checkbox"] {
  width: 20px;
  height: 20px;
  cursor: pointer;
}

.nested-input {
  margin-left: 32px;
  margin-top: 10px;
  padding: 12px;
  background-color: #1a2333;
  border-radius: 6px;
  border: 1px solid var(--border-color);
}

.nested-input label {
  font-size: 0.85rem;
  margin-bottom: 6px;
  color: var(--text-color);
}

.nested-input input {
  padding: 8px;
  font-size: 0.9rem;
  background-color: #0f172a;
}

/* --- Saved Plans List --- */
.saved-plans-container {
  margin-top: 2rem;
  border-top: 2px solid var(--border-color);
  padding-top: 1.5rem;
}

.saved-plans-container h3 {
  margin-bottom: 1rem;
  color: var(--heading-color);
}

.search-input {
  width: 100%;
  padding: 0.6rem;
  border-radius: var(--border-radius-md);
  border: 1px solid var(--border-color);
  margin-bottom: 1rem;
  background-color: #0f172a;
  color: var(--heading-color);
}

.saved-plans-list {
  list-style: none;
  max-height: 400px;
  overflow-y: auto;
}

.saved-plans-list li {
  padding: 0.8rem;
  border-bottom: 1px solid var(--border-color);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: background-color 0.2s;
  border-radius: var(--border-radius-sm);
  margin-bottom: 4px;
}

.saved-plans-list li:hover {
  background-color: #334155;
}

.saved-plans-list li.active {
  background-color: var(--primary-color-light);
  border-left: 3px solid var(--primary-color);
}

.saved-plans-list li.editing {
  background-color: var(--surface-color);
  cursor: default;
  box-shadow: 0 0 0 2px var(--primary-color);
}

.plan-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
  flex: 1;
}

.plan-title {
  font-weight: var(--font-weight-medium);
  color: var(--heading-color);
}

.plan-meta {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.meta-tag {
  font-size: 0.75rem;
  background-color: #334155;
  padding: 2px 6px;
  border-radius: 4px;
  color: var(--text-color-light);
}

.plan-actions {
  display: flex;
  gap: 8px;
  align-items: center;
}

.edit-button-icon {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 1.1rem;
  padding: 4px;
  border-radius: 4px;
  transition: background-color 0.2s;
}

.edit-button-icon:hover {
  background-color: #334155;
}

.delete-button {
  color: var(--error-color);
  background: none;
  border: none;
  cursor: pointer;
  font-size: 1.2rem;
  padding: 4px;
  border-radius: 4px;
  transition: background-color 0.2s;
}

.delete-button:hover {
  background-color: var(--error-color-light);
}

/* --- Editing Form in List --- */
.edit-plan-form {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.edit-row {
  display: flex;
  gap: 8px;
}

.edit-input {
  padding: 6px 10px;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  font-size: 0.9rem;
  background-color: #0f172a;
  color: var(--heading-color);
}

.edit-input-small {
  flex: 1;
  padding: 6px 10px;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  font-size: 0.85rem;
  background-color: #0f172a;
  color: var(--heading-color);
}

.edit-actions {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
}

.save-edit-button {
  background-color: var(--success-color-dark);
  color: white;
  border: none;
  padding: 4px 12px;
  border-radius: 4px;
  font-size: 0.85rem;
  cursor: pointer;
}

.cancel-edit-button {
  background-color: #475569;
  color: white;
  border: none;
  padding: 4px 12px;
  border-radius: 4px;
  font-size: 0.85rem;
  cursor: pointer;
}

/* --- Results --- */
.generate-button {
  width: 100%;
  padding: 0.8rem 1rem;
  background: linear-gradient(45deg, var(--primary-color), var(--secondary-color));
  color: var(--white);
  border: none;
  border-radius: var(--border-radius-md);
  font-size: var(--font-size-lg);
  font-weight: var(--font-weight-semibold);
  cursor: pointer;
  transition: transform var(--transition-speed), box-shadow var(--transition-speed);
  display: flex;
  justify-content: center;
  align-items: center;
}

.generate-button:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: var(--box-shadow-lg);
}

.generate-button:disabled {
  background: var(--disabled-color);
  cursor: not-allowed;
}

.results-container {
  background-color: var(--surface-color);
  padding: var(--spacing-xxl);
  border-radius: var(--border-radius-lg);
  box-shadow: var(--box-shadow-md);
  min-height: 70vh;
  border: 1px solid var(--border-color);
}

.welcome-message h2 {
  color: var(--heading-color);
  margin-bottom: 1rem;
}

.card {
  border-left: 5px solid var(--primary-color);
  padding: var(--spacing-xl);
  margin-bottom: var(--spacing-xl);
  border-radius: 0 var(--border-radius-md) var(--border-radius-md) 0;
  background-color: #1e293b;
  border: 1px solid var(--border-color);
  border-left-width: 5px;
}

.card h3 {
  color: var(--heading-color);
  margin-bottom: 1rem;
}

.card p {
  margin-bottom: 0.5rem;
  color: var(--text-color-light);
}

.card strong {
  color: var(--heading-color);
}

.general-notes-card {
  border-left-color: var(--white);
  background-color: #0f172a;
}

.motivation-card {
  border-left-color: var(--success-color);
  background-color: var(--success-color-light);
}

.consultation-card {
  border-left-color: var(--info-color);
  background-color: var(--info-color-light);
}

.ediary-card {
  border-left-color: var(--secondary-color);
  background-color: var(--primary-color-light);
}

.diary-field {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  background-color: #0f172a;
  padding: 12px;
  border-radius: var(--border-radius-sm);
  border: 1px solid var(--border-color);
  margin-bottom: var(--spacing-sm);
}

.diary-field span {
  color: var(--heading-color);
}

.copy-button {
  background-color: var(--primary-color);
  color: var(--white);
  border: none;
  border-radius: 5px;
  padding: 0.4rem 0.8rem;
  font-size: var(--font-size-sm);
  cursor: pointer;
  transition: all var(--transition-speed);
  min-width: 90px;
}

.copy-button:hover:not(.copied) {
  background-color: var(--primary-color-dark);
}

.copy-button.copied {
  background-color: var(--success-color-dark);
}

/* --- Modal Overlay & Onboarding --- */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(0, 0, 0, 0.75);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: var(--z-index-modal);
  backdrop-filter: blur(4px);
}

.modal-content {
  background-color: var(--surface-color);
  padding: var(--spacing-xxl);
  border-radius: var(--border-radius-lg);
  max-width: 600px;
  width: 90%;
  position: relative;
  border: 1px solid var(--border-color);
}

.onboarding-modal {
  max-width: 700px;
}

.onboarding-header {
  text-align: center;
  margin-bottom: 2rem;
}

.onboarding-header h2 {
  font-size: 1.8rem;
  color: var(--heading-color);
  margin-bottom: 0.5rem;
}

.onboarding-steps {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  margin-bottom: 2rem;
}

.onboarding-step {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
}

.step-number {
  background-color: var(--primary-color);
  color: white;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: bold;
  flex-shrink: 0;
}

.step-text {
  color: var(--text-color-light);
  line-height: 1.4;
}

.step-text strong {
  color: var(--heading-color);
  display: block;
  margin-bottom: 2px;
}

.modal-close-button {
  position: absolute;
  top: 1rem;
  right: 1rem;
  background: none;
  border: none;
  color: var(--text-color);
  font-size: 1.5rem;
  cursor: pointer;
}

.button-primary {
  background-color: var(--primary-color);
  color: white;
  border: none;
  padding: 0.8rem 2rem;
  border-radius: var(--border-radius-md);
  font-weight: var(--font-weight-semibold);
  cursor: pointer;
  display: block;
  width: 100%;
  transition: background-color 0.2s;
}

.button-primary:hover {
  background-color: var(--primary-color-dark);
}

/* --- Error Messages --- */
.error-message {
  background-color: var(--error-color-light);
  color: #ff8080;
  padding: 1rem;
  border-radius: var(--border-radius-md);
  border: 1px solid var(--error-color);
  margin-bottom: 1rem;
  font-weight: 500;
}

/* --- Loading Spinner --- */
.loading-overlay {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    height: 100%;
}

.spinner-large {
  width: 50px;
  height: 50px;
  border: 5px solid var(--border-color);
  border-top-color: var(--primary-color);
  border-radius: 50%;
  animation: spin 1s linear infinite;
  margin-bottom: 15px;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

@media (max-width: 992px) {
  .main-content { grid-template-columns: 1fr; }
}

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
  eDiaryLessonType: string;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  bpConnections: string; // Naujas laukas BP sąsajoms
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: string;
  };
  lessonActivities: {
    gifted: string;
    general: string;
    struggling: string;
    itTools?: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  consultationAdvice?: string;
  specialAdvice?: string; 
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
  groundingUrls?: {title: string, uri: string}[];
}

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [consultationChallenges, setConsultationChallenges] = useState('');

  const [isIntegratedInput, setIsIntegratedInput] = useState(false);
  const [integrationDetails, setIntegrationDetails] = useState('');
  const [isOutsideInput, setIsOutsideInput] = useState(false);
  const [locationDetails, setLocationDetails] = useState('');

  const [evaluationType, setEvaluationType] = useState(EVALUATION_TAGS[0]);
  const [evaluationDescription, setEvaluationDescription] = useState('');

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [groundingUrls, setGroundingUrls] = useState<{title: string, uri: string}[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [showOnboarding, setShowOnboarding] = useState(false);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const [editingPlanId, setEditingPlanId] = useState<string | null>(null);
  const [editTitle, setEditTitle] = useState('');
  const [editSubject, setEditSubject] = useState('');
  const [editGrade, setEditGrade] = useState('');

  const [deletingPlanId, setDeletingPlanId] = useState<string | null>(null);

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas, puikiai išmanantis Lietuvos Bendrąsias ugdymo programas (BP). 
Tavo užduotis - sukurti išsamų pamokos planą JSON formatu lietuvių kalba.

SVARBU: Naudok Google Search tool, kad surastum aktualius BP reikalavimus nurodytam dalykui, klasei ir temai.
Lauke 'bpConnections' pateik trumpą santrauką apie tai, kaip ši pamoka siejasi su BP pasiekimų sritimis ar mokymosi turiniu.

SVARBIOS TAISYKLĖS FORMAVIMUI:
Lauke 'topicClassworkExpectations' informaciją PRIVALAI pateikti tiksliai tokia struktūra (naudok naujas eilutes \\n):
Temą: [tekstas susijęs su BP temomis]
Klasės darbą: [tekstas su siūlomu darbu]
Numatomus pasiekimus: [tekstas su galimu vertinimu]

Struktūra:
{
  "generalNotes": "Ryškios pasirengimo instrukcijos",
  "lessonType": "Tipas",
  "bpConnections": "Sąsajos su Bendrosiomis ugdymo programomis (naudojantis paieškos informacija)",
  "lessonOverview": { "topic": "", "goal": "", "competencies": "", "evaluation": "" },
  "lessonActivities": { "gifted": "", "general": "", "struggling": "", "itTools": "" },
  "homework": { "purpose": "", "gifted": "", "general": "", "struggling": "" },
  "eDiaryEntry": {
    "topicClassworkExpectations": "...",
    "homework": "...",
    "individualHomework": "...",
    "notes": "...",
    "isIntegrated": false,
    "isOutside": false,
    "eDiaryLessonType": "..."
  },
  "specialAdvice": "Patarimai integracijai/išvykai",
  "consultationAdvice": "Patarimai dėl iššūkių",
  "motivation": "Padėkos žinutė mokytojui"
}
Atsakyk TIK JSON formatu.`;

  const tryParseJSON = (text: string): LessonPlan | null => {
    try {
      return JSON.parse(text);
    } catch (e) {
      const jsonMatch = text.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        try {
          return JSON.parse(jsonMatch[0]);
        } catch (e2) {}
      }
      return null;
    }
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);
    setGroundingUrls([]);

    const prompt = `
      Sukurk pamokos planą remdamasis Lietuvos BP:
      - Dalykas: ${subject}, Klasė: ${grade}
      - Tema: ${topic}
      - Pamokos tipas: ${lessonType}
      - Tikslas: ${goal}
      - Veiklos idėjos: ${activities}
      - Vertinimo tipas: ${evaluationType}
      - Iššūkiai: ${consultationChallenges}
      - Integracija: ${isIntegratedInput ? integrationDetails : 'Ne'}
      - Išvyka: ${isOutsideInput ? locationDetails : 'Ne'}

      Rask BP sąsajas per Google Search (ieškok emokykla.lt, ŠMSM puslapiuose).
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { 
          systemInstruction, 
          responseMimeType: "application/json",
          tools: [{ googleSearch: {} }] 
        },
      });

      const parsedPlan = tryParseJSON(response.text || '');

      if (!parsedPlan) {
        throw new Error("AI sugeneravo netinkamą formatą. Bandykite dar kartą.");
      }

      // Ištraukiame grounding nuorodas
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const urls: {title: string, uri: string}[] = [];
      chunks.forEach((chunk: any) => {
        if (chunk.web) {
          urls.push({ title: chunk.web.title, uri: chunk.web.uri });
        }
      });
      setGroundingUrls(urls);

      const sanitizedPlan: LessonPlan = {
        ...parsedPlan,
        bpConnections: parsedPlan.bpConnections || 'Informacija apie BP sąsajas nerasta.',
        eDiaryEntry: {
          ...parsedPlan.eDiaryEntry,
          isIntegrated: isIntegratedInput,
          isOutside: isOutsideInput,
          eDiaryLessonType: parsedPlan.eDiaryEntry?.eDiaryLessonType || parsedPlan.lessonType || lessonType || ''
        }
      };

      setLessonPlan(sanitizedPlan);
      setActivePlanId(null);
    } catch (e: any) {
      setError(`Klaida generuojant: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const confirmSavePlan = () => {
    if (!lessonPlan) return;
    const newPlan: SavedPlan = {
      id: `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${lessonPlan.lessonOverview.topic}`,
      plan: lessonPlan,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: lessonPlan.lessonType || lessonType,
      groundingUrls
    };
    setSavedPlans([newPlan, ...savedPlans]);
    setActivePlanId(newPlan.id);
  };

  const triggerDelete = (id: string) => {
    setDeletingPlanId(id);
  };

  const handleConfirmDelete = () => {
    if (!deletingPlanId) return;
    setSavedPlans(savedPlans.filter(p => p.id !== deletingPlanId));
    if (activePlanId === deletingPlanId) {
      setLessonPlan(null);
      setActivePlanId(null);
      setGroundingUrls([]);
    }
    setDeletingPlanId(null);
  };

  const handleLoadPlan = (id: string) => {
    if (editingPlanId) return;
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setGroundingUrls(p.groundingUrls || []);
      setActivePlanId(p.id);
      setGrade(p.grade || '');
      setSubject(p.subject || '');
    }
  };

  const startEditing = (e: React.MouseEvent, plan: SavedPlan) => {
    e.stopPropagation();
    setEditingPlanId(plan.id);
    setEditTitle(plan.title);
    setEditSubject(plan.subject || '');
    setEditGrade(plan.grade || '');
  };

  const cancelEditing = (e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingPlanId(null);
  };

  const savePlanEdits = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!editingPlanId) return;
    setSavedPlans(prev => prev.map(p => {
      if (p.id === editingPlanId) {
        return { ...p, title: editTitle, subject: editSubject, grade: editGrade };
      }
      return p;
    }));
    setEditingPlanId(null);
  };

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>Jūsų pagalbininkas kūrybiškoms ir efektyvioms pamokoms</p>
        <div className="header-buttons">
          <button onClick={() => setShowOnboarding(true)} className="external-link-button">Kaip naudotis?</button>
          <a href="https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos" target="_blank" rel="noopener noreferrer" className="external-link-button">BP nuoroda</a>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Pamokos informacija</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="pvz., Lietuvių kalba ir literatūra" required />
            </div>
            <div className="form-group">
              <label>Klasė / Grupė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodžio laikai" required />
            </div>
            <div className="form-group">
              <label>Pamokos tipas</label>
              <select value={lessonType} onChange={e => setLessonType(e.target.value as LessonCategory)}>
                <option value="">-- Pasirinkite --</option>
                <option value="Įvadinė">Įvadinė</option>
                <option value="Įtvirtinimo">Įtvirtinimo</option>
                <option value="Apibendrinamoji">Apibendrinamoji</option>
                <option value="Vertinamoji">Vertinamoji</option>
              </select>
            </div>
            <div className="form-group">
              <label>Tikslas (Mokiniai gebės...)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} placeholder="pvz., atpažinti veiksmažodžio laikus..." />
            </div>
            <div className="form-group">
              <label>Veiklos idėjos</label>
              <textarea value={activities} onChange={e => setActivities(e.target.value)} placeholder="pvz., darbas grupėse, interaktyvus žaidimas..." />
            </div>

            <div className="form-group">
              <label>Vertinimas</label>
              <select value={evaluationType} onChange={e => setEvaluationType(e.target.value)}>
                {EVALUATION_TAGS.map(t => <option key={t} value={t}>{t}</option>)}
              </select>
            </div>

            <div className="form-group checkbox-group" style={{display: 'flex', flexDirection: 'column', gap: '20px', borderTop: '1px solid var(--border-color)', paddingTop: '20px', marginBottom: '20px'}}>
              <div className="checkbox-item">
                <label className="checkbox-label">
                  <input type="checkbox" checked={isIntegratedInput} onChange={e => setIsIntegratedInput(e.target.checked)} />
                  Ar tai integruota pamoka?
                </label>
                {isIntegratedInput && (
                  <div className="nested-input">
                    <input type="text" value={integrationDetails} onChange={e => setIntegrationDetails(e.target.value)} placeholder="Su kokiu dalyku, tema?" />
                  </div>
                )}
              </div>

              <div className="checkbox-item">
                <label className="checkbox-label">
                  <input type="checkbox" checked={isOutsideInput} onChange={e => setIsOutsideInput(e.target.checked)} />
                  Ar tai pamoka už mokyklos ribų?
                </label>
                {isOutsideInput && (
                  <div className="nested-input">
                    <input type="text" value={locationDetails} onChange={e => setLocationDetails(e.target.value)} placeholder="Kur vyks pamoka?" />
                  </div>
                )}
              </div>
            </div>

            <button type="submit" disabled={isLoading} className="generate-button">
              {isLoading ? <div className="spinner"></div> : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {savedPlans.filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase())).map(p => (
                <li key={p.id} onClick={() => handleLoadPlan(p.id)} className={`${activePlanId === p.id ? 'active' : ''} ${editingPlanId === p.id ? 'editing' : ''}`}>
                  {editingPlanId === p.id ? (
                    <div className="edit-plan-form" onClick={e => e.stopPropagation()}>
                      <input type="text" value={editTitle} onChange={e => setEditTitle(e.target.value)} className="edit-input" />
                      <div className="edit-actions">
                        <button onClick={savePlanEdits} className="save-edit-button">Išsaugoti</button>
                        <button onClick={cancelEditing} className="cancel-edit-button">Atšaukti</button>
                      </div>
                    </div>
                  ) : (
                    <>
                      <div className="plan-info">
                        <span className="plan-title">{p.title}</span>
                      </div>
                      <div className="plan-actions">
                        <button onClick={e => startEditing(e, p)} className="edit-button-icon">✏️</button>
                        <button onClick={e => { e.stopPropagation(); triggerDelete(p.id); }} className="delete-button">✖</button>
                      </div>
                    </>
                  )}
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && <div className="loading-overlay"><div className="spinner-large"></div><p>Ruošiamas pamokos planas su BP integracija...</p></div>}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !lessonPlan && !error && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Užpildykite formą kairėje. Mes surasime BP reikalavimus ir paruošime išsamų planą.</p>
            </div>
          )}

          {lessonPlan && (
            <div className="lesson-plan-result">
              <div className="export-container">
                <button onClick={confirmSavePlan} className="save-button">Išsaugoti planą 💾</button>
              </div>

              <div className="card grounding-card" style={{borderLeftColor: 'var(--info-color)', backgroundColor: 'var(--info-color-light)'}}>
                <h3>📚 Bendrosios programos sąsajos</h3>
                <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.bpConnections}</p>
                {groundingUrls.length > 0 && (
                  <div className="sources-list" style={{marginTop: '15px', borderTop: '1px solid var(--border-color)', paddingTop: '10px'}}>
                    <p style={{fontSize: '0.85rem', fontWeight: 'bold', marginBottom: '5px'}}>Šaltiniai:</p>
                    {groundingUrls.map((u, i) => (
                      <a key={i} href={u.uri} target="_blank" rel="noopener noreferrer" style={{display: 'block', fontSize: '0.8rem', color: 'var(--primary-color)', marginBottom: '3px'}}>
                        🔗 {u.title || u.uri}
                      </a>
                    ))}
                  </div>
                )}
              </div>

              <div className="card lesson-overview-card">
                <h3>📖 Apžvalga ({lessonPlan.lessonType || 'Pamoka'})</h3>
                <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                <p><strong>Tikslas:</strong> {lessonPlan.lessonOverview.goal}</p>
                <p><strong>Gebėjimai:</strong> {lessonPlan.lessonOverview.competencies}</p>
              </div>

              <div className="card lesson-activities-card">
                <h3>🎨 Veiklos</h3>
                <p><strong>🙂 Bendra:</strong> {lessonPlan.lessonActivities.general}</p>
                <p><strong>🚀 Gabesniems:</strong> {lessonPlan.lessonActivities.gifted}</p>
                <p><strong>🌱 Pagalba:</strong> {lessonPlan.lessonActivities.struggling}</p>
              </div>

              <div className="card ediary-card">
                <h3>✍️ El. dienyno įrašai</h3>
                {[
                  { label: "Tema, darbas, pasiekimai", val: lessonPlan.eDiaryEntry.topicClassworkExpectations, id: 'diary-topic' },
                  { label: "Namų darbai", val: lessonPlan.eDiaryEntry.homework, id: 'diary-hw' },
                ].map(f => (
                  <div key={f.id} className="diary-entry" style={{marginBottom: '15px'}}>
                    <label style={{display: 'block', fontWeight: 'bold', fontSize: '0.85rem', marginBottom: '4px'}}>{f.label}:</label>
                    <div className="diary-field">
                      <span style={{fontSize: '0.95rem', whiteSpace: 'pre-wrap', lineHeight: '1.5'}}>{f.val || '---'}</span>
                      <button onClick={() => handleCopy(f.val, f.id)} className={`copy-button ${copiedField === f.id ? 'copied' : ''}`}>
                        {copiedField === f.id ? "Nukopijuota" : "Kopijuoti"}
                      </button>
                    </div>
                  </div>
                ))}
              </div>

              <div className="card motivation-card">
                <h3>💖 Ačiū TAU, Mokytojau!</h3>
                <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.motivation}</p>
              </div>
            </div>
          )}
        </div>
      </main>

      {showOnboarding && (
        <div className="modal-overlay" onClick={() => setShowOnboarding(false)}>
          <div className="modal-content onboarding-modal" onClick={e => e.stopPropagation()}>
            <button className="modal-close-button" onClick={() => setShowOnboarding(false)}>&times;</button>
            <div className="onboarding-header">
              <h2>Kaip naudotis programėle? 🚀</h2>
            </div>
            <div className="onboarding-steps">
              <div className="onboarding-step"><div className="step-number">1</div><div className="step-text"><strong>Užpildykite formą:</strong> Įveskite dalyką, klasę ir temą.</div></div>
              <div className="onboarding-step"><div className="step-number">2</div><div className="step-text"><strong>AI paieška:</strong> DI automatiškai suras BP sąsajas internete.</div></div>
              <div className="onboarding-step"><div className="step-number">3</div><div className="step-text"><strong>Gaukite planą:</strong> Peržiūrėkite sugeneruotas veiklas ir įrašus.</div></div>
              <div className="onboarding-step"><div className="step-number">4</div><div className="step-text"><strong>Nuorodos:</strong> Matysite tiesiogines nuorodas į BP šaltinius.</div></div>
            </div>
            <div className="modal-actions"><button onClick={() => setShowOnboarding(false)} className="button-primary">Supratau</button></div>
          </div>
        </div>
      )}

      {deletingPlanId && (
        <div className="modal-overlay" onClick={() => setDeletingPlanId(null)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2>Patvirtinti trinimą</h2>
            <p>Ar tikrai norite ištrinti šį planą?</p>
            <div className="modal-actions" style={{display: 'flex', gap: '1rem', justifyContent: 'flex-end', marginTop: '1rem'}}>
              <button onClick={() => setDeletingPlanId(null)} className="cancel-edit-button">Atšaukti</button>
              <button onClick={handleConfirmDelete} className="save-edit-button" style={{backgroundColor: 'var(--error-color)'}}>Ištrinti</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
  eDiaryLessonType: string;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  bpConnections: string; // Naujas laukas BP sąsajoms
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: string;
  };
  lessonActivities: {
    gifted: string;
    general: string;
    struggling: string;
    itTools?: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  consultationAdvice?: string;
  specialAdvice?: string; 
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
  groundingUrls?: {title: string, uri: string}[];
}

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [consultationChallenges, setConsultationChallenges] = useState('');

  const [isIntegratedInput, setIsIntegratedInput] = useState(false);
  const [integrationDetails, setIntegrationDetails] = useState('');
  const [isOutsideInput, setIsOutsideInput] = useState(false);
  const [locationDetails, setLocationDetails] = useState('');

  const [evaluationType, setEvaluationType] = useState(EVALUATION_TAGS[0]);
  const [evaluationDescription, setEvaluationDescription] = useState('');

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [groundingUrls, setGroundingUrls] = useState<{title: string, uri: string}[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [showOnboarding, setShowOnboarding] = useState(false);
  const [showSaveConfirm, setShowSaveConfirm] = useState(false);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const [editingPlanId, setEditingPlanId] = useState<string | null>(null);
  const [editTitle, setEditTitle] = useState('');
  const [editSubject, setEditSubject] = useState('');
  const [editGrade, setEditGrade] = useState('');

  const [deletingPlanId, setDeletingPlanId] = useState<string | null>(null);

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas, puikiai išmanantis Lietuvos Bendrąsias ugdymo programas (BP). 
Tavo užduotis - sukurti išsamų pamokos planą JSON formatu lietuvių kalba.

SVARBU: Naudok Google Search tool, kad surastum aktualius BP reikalavimus nurodytam dalykui, klasei ir temai.
Lauke 'bpConnections' pateik trumpą santrauką apie tai, kaip ši pamoka siejasi su BP pasiekimų sritimis ar mokymosi turiniu.

SVARBIOS TAISYKLĖS FORMAVIMUI:
Lauke 'topicClassworkExpectations' informaciją PRIVALAI pateikti tiksliai tokia struktūra (naudok naujas eilutes \\n):
Temą: [tekstas susijęs su BP temomis]
Klasės darbą: [tekstas su siūlomu darbu]
Numatomus pasiekimus: [tekstas su galimu vertinimu]

Struktūra:
{
  "generalNotes": "Ryškios pasirengimo instrukcijos",
  "lessonType": "Tipas",
  "bpConnections": "Sąsajos su Bendrosiomis ugdymo programomis (naudojantis paieškos informacija)",
  "lessonOverview": { "topic": "", "goal": "", "competencies": "", "evaluation": "" },
  "lessonActivities": { "gifted": "", "general": "", "struggling": "", "itTools": "" },
  "homework": { "purpose": "", "gifted": "", "general": "", "struggling": "" },
  "eDiaryEntry": {
    "topicClassworkExpectations": "...",
    "homework": "...",
    "individualHomework": "...",
    "notes": "...",
    "isIntegrated": false,
    "isOutside": false,
    "eDiaryLessonType": "..."
  },
  "specialAdvice": "Patarimai integracijai/išvykai",
  "consultationAdvice": "Patarimai dėl iššūkių",
  "motivation": "Padėkos žinutė mokytojui"
}
Atsakyk TIK JSON formatu.`;

  const tryParseJSON = (text: string): LessonPlan | null => {
    try {
      return JSON.parse(text);
    } catch (e) {
      const jsonMatch = text.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        try {
          return JSON.parse(jsonMatch[0]);
        } catch (e2) {}
      }
      return null;
    }
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);
    setGroundingUrls([]);

    const prompt = `
      Sukurk pamokos planą remdamasis Lietuvos BP:
      - Dalykas: ${subject}, Klasė: ${grade}
      - Tema: ${topic}
      - Pamokos tipas: ${lessonType}
      - Tikslas: ${goal}
      - Veiklos idėjos: ${activities}
      - Vertinimo tipas: ${evaluationType}
      - Iššūkiai: ${consultationChallenges}
      - Integracija: ${isIntegratedInput ? integrationDetails : 'Ne'}
      - Išvyka: ${isOutsideInput ? locationDetails : 'Ne'}

      Rask BP sąsajas per Google Search (ieškok emokykla.lt, ŠMSM puslapiuose).
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { 
          systemInstruction, 
          responseMimeType: "application/json",
          tools: [{ googleSearch: {} }] 
        },
      });

      const parsedPlan = tryParseJSON(response.text || '');

      if (!parsedPlan) {
        throw new Error("AI sugeneravo netinkamą formatą. Bandykite dar kartą.");
      }

      // Ištraukiame grounding nuorodas
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const urls: {title: string, uri: string}[] = [];
      chunks.forEach((chunk: any) => {
        if (chunk.web) {
          urls.push({ title: chunk.web.title, uri: chunk.web.uri });
        }
      });
      setGroundingUrls(urls);

      const sanitizedPlan: LessonPlan = {
        ...parsedPlan,
        bpConnections: parsedPlan.bpConnections || 'Informacija apie BP sąsajas nerasta.',
        eDiaryEntry: {
          ...parsedPlan.eDiaryEntry,
          isIntegrated: isIntegratedInput,
          isOutside: isOutsideInput,
          eDiaryLessonType: parsedPlan.eDiaryEntry?.eDiaryLessonType || parsedPlan.lessonType || lessonType || ''
        }
      };

      setLessonPlan(sanitizedPlan);
      setActivePlanId(null);
    } catch (e: any) {
      setError(`Klaida generuojant: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const executeSavePlan = () => {
    if (!lessonPlan) return;
    const newPlan: SavedPlan = {
      id: `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${lessonPlan.lessonOverview.topic}`,
      plan: lessonPlan,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: lessonPlan.lessonType || lessonType,
      groundingUrls
    };
    setSavedPlans([newPlan, ...savedPlans]);
    setActivePlanId(newPlan.id);
    setShowSaveConfirm(false);
  };

  const triggerDelete = (id: string) => {
    setDeletingPlanId(id);
  };

  const handleConfirmDelete = () => {
    if (!deletingPlanId) return;
    setSavedPlans(savedPlans.filter(p => p.id !== deletingPlanId));
    if (activePlanId === deletingPlanId) {
      setLessonPlan(null);
      setActivePlanId(null);
      setGroundingUrls([]);
    }
    setDeletingPlanId(null);
  };

  const handleLoadPlan = (id: string) => {
    if (editingPlanId) return;
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setGroundingUrls(p.groundingUrls || []);
      setActivePlanId(p.id);
      setGrade(p.grade || '');
      setSubject(p.subject || '');
    }
  };

  const startEditing = (e: React.MouseEvent, plan: SavedPlan) => {
    e.stopPropagation();
    setEditingPlanId(plan.id);
    setEditTitle(plan.title);
    setEditSubject(plan.subject || '');
    setEditGrade(plan.grade || '');
  };

  const cancelEditing = (e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingPlanId(null);
  };

  const savePlanEdits = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!editingPlanId) return;
    setSavedPlans(prev => prev.map(p => {
      if (p.id === editingPlanId) {
        return { ...p, title: editTitle, subject: editSubject, grade: editGrade };
      }
      return p;
    }));
    setEditingPlanId(null);
  };

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>Jūsų pagalbininkas kūrybiškoms ir efektyvioms pamokoms</p>
        <div className="header-buttons">
          <button onClick={() => setShowOnboarding(true)} className="external-link-button">Kaip naudotis?</button>
          <a href="https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos" target="_blank" rel="noopener noreferrer" className="external-link-button">BP nuoroda</a>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Pamokos informacija</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="pvz., Lietuvių kalba ir literatūra" required />
            </div>
            <div className="form-group">
              <label>Klasė / Grupė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodžio laikai" required />
            </div>
            <div className="form-group">
              <label>Pamokos tipas</label>
              <select value={lessonType} onChange={e => setLessonType(e.target.value as LessonCategory)}>
                <option value="">-- Pasirinkite --</option>
                <option value="Įvadinė">Įvadinė</option>
                <option value="Įtvirtinimo">Įtvirtinimo</option>
                <option value="Apibendrinamoji">Apibendrinamoji</option>
                <option value="Vertinamoji">Vertinamoji</option>
              </select>
            </div>
            <div className="form-group">
              <label>Tikslas (Mokiniai gebės...)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} placeholder="pvz., atpažinti veiksmažodžio laikus..." />
            </div>
            <div className="form-group">
              <label>Veiklos idėjos</label>
              <textarea value={activities} onChange={e => setActivities(e.target.value)} placeholder="pvz., darbas grupėse, interaktyvus žaidimas..." />
            </div>

            <div className="form-group">
              <label>Vertinimas</label>
              <select value={evaluationType} onChange={e => setEvaluationType(e.target.value)}>
                {EVALUATION_TAGS.map(t => <option key={t} value={t}>{t}</option>)}
              </select>
            </div>

            <div className="form-group checkbox-group" style={{display: 'flex', flexDirection: 'column', gap: '20px', borderTop: '1px solid var(--border-color)', paddingTop: '20px', marginBottom: '20px'}}>
              <div className="checkbox-item">
                <label className="checkbox-label">
                  <input type="checkbox" checked={isIntegratedInput} onChange={e => setIsIntegratedInput(e.target.checked)} />
                  Ar tai integruota pamoka?
                </label>
                {isIntegratedInput && (
                  <div className="nested-input">
                    <input type="text" value={integrationDetails} onChange={e => setIntegrationDetails(e.target.value)} placeholder="Su kokiu dalyku, tema?" />
                  </div>
                )}
              </div>

              <div className="checkbox-item">
                <label className="checkbox-label">
                  <input type="checkbox" checked={isOutsideInput} onChange={e => setIsOutsideInput(e.target.checked)} />
                  Ar tai pamoka už mokyklos ribų?
                </label>
                {isOutsideInput && (
                  <div className="nested-input">
                    <input type="text" value={locationDetails} onChange={e => setLocationDetails(e.target.value)} placeholder="Kur vyks pamoka?" />
                  </div>
                )}
              </div>
            </div>

            <button type="submit" disabled={isLoading} className="generate-button">
              {isLoading ? <div className="spinner"></div> : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {savedPlans.filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase())).map(p => (
                <li key={p.id} onClick={() => handleLoadPlan(p.id)} className={`${activePlanId === p.id ? 'active' : ''} ${editingPlanId === p.id ? 'editing' : ''}`}>
                  {editingPlanId === p.id ? (
                    <div className="edit-plan-form" onClick={e => e.stopPropagation()}>
                      <input type="text" value={editTitle} onChange={e => setEditTitle(e.target.value)} className="edit-input" />
                      <div className="edit-actions">
                        <button onClick={savePlanEdits} className="save-edit-button">Išsaugoti</button>
                        <button onClick={cancelEditing} className="cancel-edit-button">Atšaukti</button>
                      </div>
                    </div>
                  ) : (
                    <>
                      <div className="plan-info">
                        <span className="plan-title">{p.title}</span>
                      </div>
                      <div className="plan-actions">
                        <button onClick={e => startEditing(e, p)} className="edit-button-icon">✏️</button>
                        <button onClick={e => { e.stopPropagation(); triggerDelete(p.id); }} className="delete-button">✖</button>
                      </div>
                    </>
                  )}
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && <div className="loading-overlay"><div className="spinner-large"></div><p>Ruošiamas pamokos planas su BP integracija...</p></div>}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !lessonPlan && !error && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Užpildykite formą kairėje. Mes surasime BP reikalavimus ir paruošime išsamų planą.</p>
            </div>
          )}

          {lessonPlan && (
            <div className="lesson-plan-result">
              <div className="export-container">
                <button onClick={() => setShowSaveConfirm(true)} className="save-button">Išsaugoti planą 💾</button>
              </div>

              <div className="card grounding-card" style={{borderLeftColor: 'var(--info-color)', backgroundColor: 'var(--info-color-light)'}}>
                <h3>📚 Bendrosios programos sąsajos</h3>
                <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.bpConnections}</p>
                {groundingUrls.length > 0 && (
                  <div className="sources-list" style={{marginTop: '15px', borderTop: '1px solid var(--border-color)', paddingTop: '10px'}}>
                    <p style={{fontSize: '0.85rem', fontWeight: 'bold', marginBottom: '5px'}}>Šaltiniai:</p>
                    {groundingUrls.map((u, i) => (
                      <a key={i} href={u.uri} target="_blank" rel="noopener noreferrer" style={{display: 'block', fontSize: '0.8rem', color: 'var(--primary-color)', marginBottom: '3px'}}>
                        🔗 {u.title || u.uri}
                      </a>
                    ))}
                  </div>
                )}
              </div>

              <div className="card lesson-overview-card">
                <h3>📖 Apžvalga ({lessonPlan.lessonType || 'Pamoka'})</h3>
                <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                <p><strong>Tikslas:</strong> {lessonPlan.lessonOverview.goal}</p>
                <p><strong>Gebėjimai:</strong> {lessonPlan.lessonOverview.competencies}</p>
              </div>

              <div className="card lesson-activities-card">
                <h3>🎨 Veiklos</h3>
                <p><strong>🙂 Bendra:</strong> {lessonPlan.lessonActivities.general}</p>
                <p><strong>🚀 Gabesniems:</strong> {lessonPlan.lessonActivities.gifted}</p>
                <p><strong>🌱 Pagalba:</strong> {lessonPlan.lessonActivities.struggling}</p>
              </div>

              <div className="card ediary-card">
                <h3>✍️ El. dienyno įrašai</h3>
                {[
                  { label: "Tema, darbas, pasiekimai", val: lessonPlan.eDiaryEntry.topicClassworkExpectations, id: 'diary-topic' },
                  { label: "Namų darbai", val: lessonPlan.eDiaryEntry.homework, id: 'diary-hw' },
                ].map(f => (
                  <div key={f.id} className="diary-entry" style={{marginBottom: '15px'}}>
                    <label style={{display: 'block', fontWeight: 'bold', fontSize: '0.85rem', marginBottom: '4px'}}>{f.label}:</label>
                    <div className="diary-field">
                      <span style={{fontSize: '0.95rem', whiteSpace: 'pre-wrap', lineHeight: '1.5'}}>{f.val || '---'}</span>
                      <button onClick={() => handleCopy(f.val, f.id)} className={`copy-button ${copiedField === f.id ? 'copied' : ''}`}>
                        {copiedField === f.id ? "Nukopijuota" : "Kopijuoti"}
                      </button>
                    </div>
                  </div>
                ))}
              </div>

              <div className="card motivation-card">
                <h3>💖 Ačiū TAU, Mokytojau!</h3>
                <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.motivation}</p>
              </div>
            </div>
          )}
        </div>
      </main>

      {showOnboarding && (
        <div className="modal-overlay" onClick={() => setShowOnboarding(false)}>
          <div className="modal-content onboarding-modal" onClick={e => e.stopPropagation()}>
            <button className="modal-close-button" onClick={() => setShowOnboarding(false)}>&times;</button>
            <div className="onboarding-header">
              <h2>Kaip naudotis programėle? 🚀</h2>
            </div>
            <div className="onboarding-steps">
              <div className="onboarding-step"><div className="step-number">1</div><div className="step-text"><strong>Užpildykite formą:</strong> Įveskite dalyką, klasę ir temą.</div></div>
              <div className="onboarding-step"><div className="step-number">2</div><div className="step-text"><strong>AI paieška:</strong> DI automatiškai suras BP sąsajas internete.</div></div>
              <div className="onboarding-step"><div className="step-number">3</div><div className="step-text"><strong>Gaukite planą:</strong> Peržiūrėkite sugeneruotas veiklas ir įrašus.</div></div>
              <div className="onboarding-step"><div className="step-number">4</div><div className="step-text"><strong>Nuorodos:</strong> Matysite tiesiogines nuorodas į BP šaltinius.</div></div>
            </div>
            <div className="modal-actions"><button onClick={() => setShowOnboarding(false)} className="button-primary">Supratau</button></div>
          </div>
        </div>
      )}

      {showSaveConfirm && (
        <div className="modal-overlay" onClick={() => setShowSaveConfirm(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2>Patvirtinti išsaugojimą</h2>
            <p style={{marginBottom: '1.5rem', color: 'var(--text-color-light)'}}>
              Ar tikrai norite išsaugoti šį pamokos planą savo sąraše?
            </p>
            <div className="modal-actions" style={{display: 'flex', gap: '1rem', justifyContent: 'flex-end'}}>
              <button onClick={() => setShowSaveConfirm(false)} className="cancel-edit-button" style={{padding: '0.6rem 1.2rem'}}>Atšaukti</button>
              <button onClick={executeSavePlan} className="save-edit-button" style={{padding: '0.6rem 1.2rem', backgroundColor: 'var(--success-color)'}}>Išsaugoti</button>
            </div>
          </div>
        </div>
      )}

      {deletingPlanId && (
        <div className="modal-overlay" onClick={() => setDeletingPlanId(null)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2>Patvirtinti trinimą</h2>
            <p>Ar tikrai norite ištrinti šį planą?</p>
            <div className="modal-actions" style={{display: 'flex', gap: '1rem', justifyContent: 'flex-end', marginTop: '1rem'}}>
              <button onClick={() => setDeletingPlanId(null)} className="cancel-edit-button">Atšaukti</button>
              <button onClick={handleConfirmDelete} className="save-edit-button" style={{backgroundColor: 'var(--error-color)'}}>Ištrinti</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
  eDiaryLessonType: string;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  bpConnections: string; // Naujas laukas BP sąsajoms
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: string;
  };
  lessonActivities: {
    gifted: string;
    general: string;
    struggling: string;
    itTools?: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  consultationAdvice?: string;
  specialAdvice?: string; 
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
  groundingUrls?: {title: string, uri: string}[];
}

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [consultationChallenges, setConsultationChallenges] = useState('');

  const [isIntegratedInput, setIsIntegratedInput] = useState(false);
  const [integrationDetails, setIntegrationDetails] = useState('');
  const [isOutsideInput, setIsOutsideInput] = useState(false);
  const [locationDetails, setLocationDetails] = useState('');

  const [evaluationType, setEvaluationType] = useState(EVALUATION_TAGS[0]);
  const [evaluationDescription, setEvaluationDescription] = useState('');

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [groundingUrls, setGroundingUrls] = useState<{title: string, uri: string}[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [showOnboarding, setShowOnboarding] = useState(false);
  const [showSaveConfirm, setShowSaveConfirm] = useState(false);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const [editingPlanId, setEditingPlanId] = useState<string | null>(null);
  const [editTitle, setEditTitle] = useState('');
  const [editSubject, setEditSubject] = useState('');
  const [editGrade, setEditGrade] = useState('');

  const [deletingPlanId, setDeletingPlanId] = useState<string | null>(null);

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas, puikiai išmanantis Lietuvos Bendrąsias ugdymo programas (BP). 
Tavo užduotis - sukurti išsamų pamokos planą JSON formatu lietuvių kalba.

SVARBU: Naudok Google Search tool, kad surastum aktualius BP reikalavimus nurodytam dalykui, klasei ir temai.
Lauke 'bpConnections' pateik trumpą santrauką apie tai, kaip ši pamoka siejasi su BP pasiekimų sritimis ar mokymosi turiniu.

SVARBIOS TAISYKLĖS FORMAVIMUI:
Lauke 'topicClassworkExpectations' informaciją PRIVALAI pateikti tiksliai tokia struktūra (naudok naujas eilutes \\n):
Temą: [tekstas susijęs su BP temomis]
Klasės darbą: [tekstas su siūlomu darbu]
Numatomus pasiekimus: [tekstas su galimu vertinimu]

Struktūra:
{
  "generalNotes": "Ryškios pasirengimo instrukcijos",
  "lessonType": "Tipas",
  "bpConnections": "Sąsajos su Bendrosiomis ugdymo programomis (naudojantis paieškos informacija)",
  "lessonOverview": { "topic": "", "goal": "", "competencies": "", "evaluation": "" },
  "lessonActivities": { "gifted": "", "general": "", "struggling": "", "itTools": "" },
  "homework": { "purpose": "", "gifted": "", "general": "", "struggling": "" },
  "eDiaryEntry": {
    "topicClassworkExpectations": "Temą: ...\\nKlasės darbą: ...\\nNumatomus pasiekimus: ...",
    "homework": "...",
    "individualHomework": "...",
    "notes": "...",
    "isIntegrated": false,
    "isOutside": false,
    "eDiaryLessonType": "..."
  },
  "specialAdvice": "Patarimai integracijai/išvykai",
  "consultationAdvice": "Patarimai dėl iššūkių",
  "motivation": "Padėkos žinutė mokytojui"
}
Atsakyk TIK JSON formatu.`;

  const tryParseJSON = (text: string): LessonPlan | null => {
    try {
      return JSON.parse(text);
    } catch (e) {
      const jsonMatch = text.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        try {
          return JSON.parse(jsonMatch[0]);
        } catch (e2) {}
      }
      return null;
    }
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);
    setGroundingUrls([]);

    const prompt = `
      Sukurk pamokos planą remdamasis Lietuvos BP:
      - Dalykas: ${subject}, Klasė: ${grade}
      - Tema: ${topic}
      - Pamokos tipas: ${lessonType}
      - Tikslas: ${goal}
      - Veiklos idėjos: ${activities}
      - Vertinimo tipas: ${evaluationType}
      - Iššūkiai: ${consultationChallenges}
      - Integracija: ${isIntegratedInput ? integrationDetails : 'Ne'}
      - Išvyka: ${isOutsideInput ? locationDetails : 'Ne'}

      Rask BP sąsajas per Google Search (ieškok emokykla.lt, ŠMSM puslapiuose).
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { 
          systemInstruction, 
          responseMimeType: "application/json",
          tools: [{ googleSearch: {} }] 
        },
      });

      const parsedPlan = tryParseJSON(response.text || '');

      if (!parsedPlan) {
        throw new Error("AI sugeneravo netinkamą formatą. Bandykite dar kartą.");
      }

      // Ištraukiame grounding nuorodas
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const urls: {title: string, uri: string}[] = [];
      chunks.forEach((chunk: any) => {
        if (chunk.web) {
          urls.push({ title: chunk.web.title, uri: chunk.web.uri });
        }
      });
      setGroundingUrls(urls);

      const sanitizedPlan: LessonPlan = {
        ...parsedPlan,
        bpConnections: parsedPlan.bpConnections || 'Informacija apie BP sąsajas nerasta.',
        eDiaryEntry: {
          ...parsedPlan.eDiaryEntry,
          isIntegrated: isIntegratedInput,
          isOutside: isOutsideInput,
          eDiaryLessonType: parsedPlan.eDiaryEntry?.eDiaryLessonType || parsedPlan.lessonType || lessonType || ''
        }
      };

      setLessonPlan(sanitizedPlan);
      setActivePlanId(null);
    } catch (e: any) {
      setError(`Klaida generuojant: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    let textToCopy = text;
    // Jei kopijuojame pagrindinį dienyno lauką, pašaliname „etiketes“
    if (field === 'diary-topic') {
      textToCopy = textToCopy
        .replace(/^Temą:\s*/gm, '')
        .replace(/^Klasės darbą:\s*/gm, '')
        .replace(/^Numatomus pasiekimus:\s*/gm, '');
    }

    navigator.clipboard.writeText(textToCopy).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const executeSavePlan = () => {
    if (!lessonPlan) return;
    const newPlan: SavedPlan = {
      id: `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${lessonPlan.lessonOverview.topic}`,
      plan: lessonPlan,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: lessonPlan.lessonType || lessonType,
      groundingUrls
    };
    setSavedPlans([newPlan, ...savedPlans]);
    setActivePlanId(newPlan.id);
    setShowSaveConfirm(false);
  };

  const triggerDelete = (id: string) => {
    setDeletingPlanId(id);
  };

  const handleConfirmDelete = () => {
    if (!deletingPlanId) return;
    setSavedPlans(savedPlans.filter(p => p.id !== deletingPlanId));
    if (activePlanId === deletingPlanId) {
      setLessonPlan(null);
      setActivePlanId(null);
      setGroundingUrls([]);
    }
    setDeletingPlanId(null);
  };

  const handleLoadPlan = (id: string) => {
    if (editingPlanId) return;
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setGroundingUrls(p.groundingUrls || []);
      setActivePlanId(p.id);
      setGrade(p.grade || '');
      setSubject(p.subject || '');
    }
  };

  const startEditing = (e: React.MouseEvent, plan: SavedPlan) => {
    e.stopPropagation();
    setEditingPlanId(plan.id);
    setEditTitle(plan.title);
    setEditSubject(plan.subject || '');
    setEditGrade(plan.grade || '');
  };

  const cancelEditing = (e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingPlanId(null);
  };

  const savePlanEdits = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!editingPlanId) return;
    setSavedPlans(prev => prev.map(p => {
      if (p.id === editingPlanId) {
        return { ...p, title: editTitle, subject: editSubject, grade: editGrade };
      }
      return p;
    }));
    setEditingPlanId(null);
  };

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>Jūsų pagalbininkas kūrybiškoms ir efektyvioms pamokoms</p>
        <div className="header-buttons">
          <button onClick={() => setShowOnboarding(true)} className="external-link-button">Kaip naudotis?</button>
          <a href="https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos" target="_blank" rel="noopener noreferrer" className="external-link-button">BP nuoroda</a>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Pamokos informacija</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="pvz., Lietuvių kalba ir literatūra" required />
            </div>
            <div className="form-group">
              <label>Klasė / Grupė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodžio laikai" required />
            </div>
            <div className="form-group">
              <label>Pamokos tipas</label>
              <select value={lessonType} onChange={e => setLessonType(e.target.value as LessonCategory)}>
                <option value="">-- Pasirinkite --</option>
                <option value="Įvadinė">Įvadinė</option>
                <option value="Įtvirtinimo">Įtvirtinimo</option>
                <option value="Apibendrinamoji">Apibendrinamoji</option>
                <option value="Vertinamoji">Vertinamoji</option>
              </select>
            </div>
            <div className="form-group">
              <label>Tikslas (Mokiniai gebės...)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} placeholder="pvz., atpažinti veiksmažodžio laikus..." />
            </div>
            <div className="form-group">
              <label>Veiklos idėjos</label>
              <textarea value={activities} onChange={e => setActivities(e.target.value)} placeholder="pvz., darbas grupėse, interaktyvus žaidimas..." />
            </div>

            <div className="form-group">
              <label>Vertinimas</label>
              <select value={evaluationType} onChange={e => setEvaluationType(e.target.value)}>
                {EVALUATION_TAGS.map(t => <option key={t} value={t}>{t}</option>)}
              </select>
            </div>

            <div className="form-group checkbox-group" style={{display: 'flex', flexDirection: 'column', gap: '20px', borderTop: '1px solid var(--border-color)', paddingTop: '20px', marginBottom: '20px'}}>
              <div className="checkbox-item">
                <label className="checkbox-label">
                  <input type="checkbox" checked={isIntegratedInput} onChange={e => setIsIntegratedInput(e.target.checked)} />
                  Ar tai integruota pamoka?
                </label>
                {isIntegratedInput && (
                  <div className="nested-input">
                    <input type="text" value={integrationDetails} onChange={e => setIntegrationDetails(e.target.value)} placeholder="Su kokiu dalyku, tema?" />
                  </div>
                )}
              </div>

              <div className="checkbox-item">
                <label className="checkbox-label">
                  <input type="checkbox" checked={isOutsideInput} onChange={e => setIsOutsideInput(e.target.checked)} />
                  Ar tai pamoka už mokyklos ribų?
                </label>
                {isOutsideInput && (
                  <div className="nested-input">
                    <input type="text" value={locationDetails} onChange={e => setLocationDetails(e.target.value)} placeholder="Kur vyks pamoka?" />
                  </div>
                )}
              </div>
            </div>

            <button type="submit" disabled={isLoading} className="generate-button">
              {isLoading ? <div className="spinner"></div> : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {savedPlans.filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase())).map(p => (
                <li key={p.id} onClick={() => handleLoadPlan(p.id)} className={`${activePlanId === p.id ? 'active' : ''} ${editingPlanId === p.id ? 'editing' : ''}`}>
                  {editingPlanId === p.id ? (
                    <div className="edit-plan-form" onClick={e => e.stopPropagation()}>
                      <input type="text" value={editTitle} onChange={e => setEditTitle(e.target.value)} className="edit-input" />
                      <div className="edit-actions">
                        <button onClick={savePlanEdits} className="save-edit-button">Išsaugoti</button>
                        <button onClick={cancelEditing} className="cancel-edit-button">Atšaukti</button>
                      </div>
                    </div>
                  ) : (
                    <>
                      <div className="plan-info">
                        <span className="plan-title">{p.title}</span>
                      </div>
                      <div className="plan-actions">
                        <button onClick={e => startEditing(e, p)} className="edit-button-icon">✏️</button>
                        <button onClick={e => { e.stopPropagation(); triggerDelete(p.id); }} className="delete-button">✖</button>
                      </div>
                    </>
                  )}
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && <div className="loading-overlay"><div className="spinner-large"></div><p>Ruošiamas pamokos planas su BP integracija...</p></div>}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !lessonPlan && !error && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Užpildykite formą kairėje. Mes surasime BP reikalavimus ir paruošime išsamų planą.</p>
            </div>
          )}

          {lessonPlan && (
            <div className="lesson-plan-result">
              <div className="export-container">
                <button onClick={() => setShowSaveConfirm(true)} className="save-button">Išsaugoti planą 💾</button>
              </div>

              <div className="card grounding-card" style={{borderLeftColor: 'var(--info-color)', backgroundColor: 'var(--info-color-light)'}}>
                <h3>📚 Bendrosios programos sąsajos</h3>
                <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.bpConnections}</p>
                {groundingUrls.length > 0 && (
                  <div className="sources-list" style={{marginTop: '15px', borderTop: '1px solid var(--border-color)', paddingTop: '10px'}}>
                    <p style={{fontSize: '0.85rem', fontWeight: 'bold', marginBottom: '5px'}}>Šaltiniai:</p>
                    {groundingUrls.map((u, i) => (
                      <a key={i} href={u.uri} target="_blank" rel="noopener noreferrer" style={{display: 'block', fontSize: '0.8rem', color: 'var(--primary-color)', marginBottom: '3px'}}>
                        🔗 {u.title || u.uri}
                      </a>
                    ))}
                  </div>
                )}
              </div>

              <div className="card lesson-overview-card">
                <h3>📖 Apžvalga ({lessonPlan.lessonType || 'Pamoka'})</h3>
                <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                <p><strong>Tikslas:</strong> {lessonPlan.lessonOverview.goal}</p>
                <p><strong>Gebėjimai:</strong> {lessonPlan.lessonOverview.competencies}</p>
              </div>

              <div className="card lesson-activities-card">
                <h3>🎨 Veiklos</h3>
                <p><strong>🙂 Bendra:</strong> {lessonPlan.lessonActivities.general}</p>
                <p><strong>🚀 Gabesniems:</strong> {lessonPlan.lessonActivities.gifted}</p>
                <p><strong>🌱 Pagalba:</strong> {lessonPlan.lessonActivities.struggling}</p>
              </div>

              <div className="card ediary-card">
                {[
                  { label: "Tema, darbas, pasiekimai", val: lessonPlan.eDiaryEntry.topicClassworkExpectations, id: 'diary-topic' },
                  { label: "Namų darbai", val: lessonPlan.eDiaryEntry.homework, id: 'diary-hw' },
                ].map(f => (
                  <div key={f.id} className="diary-entry" style={{marginBottom: '15px'}}>
                    <label style={{display: 'block', fontWeight: 'bold', fontSize: '0.85rem', marginBottom: '4px'}}>{f.label}:</label>
                    <div className="diary-field">
                      <span style={{fontSize: '0.95rem', whiteSpace: 'pre-wrap', lineHeight: '1.5'}}>{f.val || '---'}</span>
                      <button onClick={() => handleCopy(f.val, f.id)} className={`copy-button ${copiedField === f.id ? 'copied' : ''}`}>
                        {copiedField === f.id ? "Nukopijuota" : "Kopijuoti"}
                      </button>
                    </div>
                  </div>
                ))}
              </div>

              <div className="card motivation-card">
                <h3>💖 Ačiū TAU, Mokytojau!</h3>
                <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.motivation}</p>
              </div>
            </div>
          )}
        </div>
      </main>

      {showOnboarding && (
        <div className="modal-overlay" onClick={() => setShowOnboarding(false)}>
          <div className="modal-content onboarding-modal" onClick={e => e.stopPropagation()}>
            <button className="modal-close-button" onClick={() => setShowOnboarding(false)}>&times;</button>
            <div className="onboarding-header">
              <h2>Kaip naudotis programėle? 🚀</h2>
            </div>
            <div className="onboarding-steps">
              <div className="onboarding-step"><div className="step-number">1</div><div className="step-text"><strong>Užpildykite formą:</strong> Įveskite dalyką, klasę ir temą.</div></div>
              <div className="onboarding-step"><div className="step-number">2</div><div className="step-text"><strong>AI paieška:</strong> DI automatiškai suras BP sąsajas internete.</div></div>
              <div className="onboarding-step"><div className="step-number">3</div><div className="step-text"><strong>Gaukite planą:</strong> Peržiūrėkite sugeneruotas veiklas ir įrašus.</div></div>
              <div className="onboarding-step"><div className="step-number">4</div><div className="step-text"><strong>Nuorodos:</strong> Matysite tiesiogines nuorodas į BP šaltinius.</div></div>
            </div>
            <div className="modal-actions"><button onClick={() => setShowOnboarding(false)} className="button-primary">Supratau</button></div>
          </div>
        </div>
      )}

      {showSaveConfirm && (
        <div className="modal-overlay" onClick={() => setShowSaveConfirm(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2>Patvirtinti išsaugojimą</h2>
            <p style={{marginBottom: '1.5rem', color: 'var(--text-color-light)'}}>
              Ar tikrai norite išsaugoti šį pamokos planą savo sąraše?
            </p>
            <div className="modal-actions" style={{display: 'flex', gap: '1rem', justifyContent: 'flex-end'}}>
              <button onClick={() => setShowSaveConfirm(false)} className="cancel-edit-button" style={{padding: '0.6rem 1.2rem'}}>Atšaukti</button>
              <button onClick={executeSavePlan} className="save-edit-button" style={{padding: '0.6rem 1.2rem', backgroundColor: 'var(--success-color)'}}>Išsaugoti</button>
            </div>
          </div>
        </div>
      )}

      {deletingPlanId && (
        <div className="modal-overlay" onClick={() => setDeletingPlanId(null)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2>Patvirtinti trinimą</h2>
            <p>Ar tikrai norite ištrinti šį planą?</p>
            <div className="modal-actions" style={{display: 'flex', gap: '1rem', justifyContent: 'flex-end', marginTop: '1rem'}}>
              <button onClick={() => setDeletingPlanId(null)} className="cancel-edit-button">Atšaukti</button>
              <button onClick={handleConfirmDelete} className="save-edit-button" style={{backgroundColor: 'var(--error-color)'}}>Ištrinti</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
  eDiaryLessonType: string;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  bpConnections: string;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: string;
  };
  lessonStages: {
    introduction: string;       // Įvadas
    theory: string;             // Teorinis paaiškinimas
    practice: string;           // Praktika
    consolidation: string;      // Įtvirtinimas
    summary: string;            // Apibendrinimas
  };
  differentiation: {
    gifted: string;             // Gabesniems
    general: string;            // Bendra
    struggling: string;         // Pagalba
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  consultationAdvice?: string;
  specialAdvice?: string; 
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
  groundingUrls?: {title: string, uri: string}[];
}

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [consultationChallenges, setConsultationChallenges] = useState('');

  const [isIntegratedInput, setIsIntegratedInput] = useState(false);
  const [integrationDetails, setIntegrationDetails] = useState('');
  const [isOutsideInput, setIsOutsideInput] = useState(false);
  const [locationDetails, setLocationDetails] = useState('');

  const [evaluationType, setEvaluationType] = useState(EVALUATION_TAGS[0]);
  const [evaluationDescription, setEvaluationDescription] = useState('');

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [groundingUrls, setGroundingUrls] = useState<{title: string, uri: string}[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [showOnboarding, setShowOnboarding] = useState(false);
  const [showSaveConfirm, setShowSaveConfirm] = useState(false);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const [editingPlanId, setEditingPlanId] = useState<string | null>(null);
  const [editTitle, setEditTitle] = useState('');
  const [editSubject, setEditSubject] = useState('');
  const [editGrade, setEditGrade] = useState('');

  const [deletingPlanId, setDeletingPlanId] = useState<string | null>(null);

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas, puikiai išmanantis Lietuvos Bendrąsias ugdymo programas (BP). 
Tavo užduotis - sukurti labai išsamų, struktūruotą pamokos planą JSON formatu lietuvių kalba.

SVARBU: Naudok Google Search tool, kad surastum aktualius BP reikalavimus nurodytam dalykui, klasei ir temai.

PAMOKOS EIGOS STRUKTŪRA:
Privalai užpildyti 'lessonStages' objektą:
- 'introduction': Įvadas, sudominimas, tikslų paskelbimas.
- 'theory': Naujos medžiagos aiškinimas, teorinė dalis.
- 'practice': Praktinis darbas, užduočių atlikimas.
- 'consolidation': Žinių įtvirtinimas, grįžtamasis ryšys.
- 'summary': Apibendrinimas, refleksija.

DIFERENCIJAVIMAS:
Užpildyk 'differentiation' objektą su konkrečiomis strategijomis skirtingų gebėjimų mokiniams.

SVARBIOS TAISYKLĖS EL. DIENYNUI:
Lauke 'topicClassworkExpectations' informaciją PRIVALAI pateikti tiksliai tokia struktūra (naudok naujas eilutes \\n):
Temą: [tekstas susijęs su BP temomis]
Klasės darbą: [tekstas su siūlomu darbu]
Numatomus pasiekimus: [tekstas su galimu vertinimu]

Struktūra:
{
  "generalNotes": "Ryškios pasirengimo instrukcijos",
  "lessonType": "Tipas",
  "bpConnections": "Sąsajos su Bendrosiomis ugdymo programomis",
  "lessonOverview": { "topic": "", "goal": "", "competencies": "", "evaluation": "" },
  "lessonStages": {
    "introduction": "...",
    "theory": "...",
    "practice": "...",
    "consolidation": "...",
    "summary": "..."
  },
  "differentiation": {
    "gifted": "...",
    "general": "...",
    "struggling": "..."
  },
  "homework": { "purpose": "...", "gifted": "...", "general": "...", "struggling": "..." },
  "eDiaryEntry": {
    "topicClassworkExpectations": "Temą: ...\\nKlasės darbą: ...\\nNumatomus pasiekimus: ...",
    "homework": "...",
    "individualHomework": "...",
    "notes": "...",
    "isIntegrated": false,
    "isOutside": false,
    "eDiaryLessonType": "..."
  },
  "specialAdvice": "Patarimai integracijai/išvykai",
  "consultationAdvice": "Patarimai dėl iššūkių",
  "motivation": "Padėkos žinutė mokytojui"
}
Atsakyk TIK JSON formatu.`;

  const tryParseJSON = (text: string): LessonPlan | null => {
    try {
      return JSON.parse(text);
    } catch (e) {
      const jsonMatch = text.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        try {
          return JSON.parse(jsonMatch[0]);
        } catch (e2) {}
      }
      return null;
    }
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);
    setGroundingUrls([]);

    const prompt = `
      Sukurk IŠSAMŲ pamokos planą (su įvadu, teorija, praktika, įtvirtinimu, apibendrinimu ir diferenciacija) remdamasis Lietuvos BP:
      - Dalykas: ${subject}, Klasė: ${grade}
      - Tema: ${topic}
      - Pamokos tipas: ${lessonType}
      - Tikslas: ${goal}
      - Veiklos idėjos: ${activities}
      - Vertinimo tipas: ${evaluationType}
      - Iššūkiai: ${consultationChallenges}
      - Integracija: ${isIntegratedInput ? integrationDetails : 'Ne'}
      - Išvyka: ${isOutsideInput ? locationDetails : 'Ne'}

      Rask BP sąsajas per Google Search. Užtikrink loginę pamokos eigą.
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { 
          systemInstruction, 
          responseMimeType: "application/json",
          tools: [{ googleSearch: {} }] 
        },
      });

      const parsedPlan = tryParseJSON(response.text || '');

      if (!parsedPlan) {
        throw new Error("AI sugeneravo netinkamą formatą. Bandykite dar kartą.");
      }

      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const urls: {title: string, uri: string}[] = [];
      chunks.forEach((chunk: any) => {
        if (chunk.web) {
          urls.push({ title: chunk.web.title, uri: chunk.web.uri });
        }
      });
      setGroundingUrls(urls);

      const sanitizedPlan: LessonPlan = {
        ...parsedPlan,
        bpConnections: parsedPlan.bpConnections || 'Informacija apie BP sąsajas nerasta.',
        eDiaryEntry: {
          ...parsedPlan.eDiaryEntry,
          isIntegrated: isIntegratedInput,
          isOutside: isOutsideInput,
          eDiaryLessonType: parsedPlan.eDiaryEntry?.eDiaryLessonType || parsedPlan.lessonType || lessonType || ''
        }
      };

      setLessonPlan(sanitizedPlan);
      setActivePlanId(null);
    } catch (e: any) {
      setError(`Klaida generuojant: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    let textToCopy = text;
    if (field === 'diary-topic') {
      textToCopy = textToCopy
        .replace(/^Temą:\s*/gm, '')
        .replace(/^Klasės darbą:\s*/gm, '')
        .replace(/^Numatomus pasiekimus:\s*/gm, '');
    }

    navigator.clipboard.writeText(textToCopy).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const executeSavePlan = () => {
    if (!lessonPlan) return;
    const newPlan: SavedPlan = {
      id: `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${lessonPlan.lessonOverview.topic}`,
      plan: lessonPlan,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: lessonPlan.lessonType || lessonType,
      groundingUrls
    };
    setSavedPlans([newPlan, ...savedPlans]);
    setActivePlanId(newPlan.id);
    setShowSaveConfirm(false);
  };

  const triggerDelete = (id: string) => {
    setDeletingPlanId(id);
  };

  const handleConfirmDelete = () => {
    if (!deletingPlanId) return;
    setSavedPlans(savedPlans.filter(p => p.id !== deletingPlanId));
    if (activePlanId === deletingPlanId) {
      setLessonPlan(null);
      setActivePlanId(null);
      setGroundingUrls([]);
    }
    setDeletingPlanId(null);
  };

  const handleLoadPlan = (id: string) => {
    if (editingPlanId) return;
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setGroundingUrls(p.groundingUrls || []);
      setActivePlanId(p.id);
      setGrade(p.grade || '');
      setSubject(p.subject || '');
    }
  };

  const startEditing = (e: React.MouseEvent, plan: SavedPlan) => {
    e.stopPropagation();
    setEditingPlanId(plan.id);
    setEditTitle(plan.title);
    setEditSubject(plan.subject || '');
    setEditGrade(plan.grade || '');
  };

  const cancelEditing = (e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingPlanId(null);
  };

  const savePlanEdits = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!editingPlanId) return;
    setSavedPlans(prev => prev.map(p => {
      if (p.id === editingPlanId) {
        return { ...p, title: editTitle, subject: editSubject, grade: editGrade };
      }
      return p;
    }));
    setEditingPlanId(null);
  };

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>Jūsų pagalbininkas kūrybiškoms ir efektyvioms pamokoms</p>
        <div className="header-buttons">
          <button onClick={() => setShowOnboarding(true)} className="external-link-button">Kaip naudotis?</button>
          <a href="https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos" target="_blank" rel="noopener noreferrer" className="external-link-button">BP nuoroda</a>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Pamokos informacija</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="pvz., Lietuvių kalba ir literatūra" required />
            </div>
            <div className="form-group">
              <label>Klasė / Grupė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodžio laikai" required />
            </div>
            <div className="form-group">
              <label>Pamokos tipas</label>
              <select value={lessonType} onChange={e => setLessonType(e.target.value as LessonCategory)}>
                <option value="">-- Pasirinkite --</option>
                <option value="Įvadinė">Įvadinė</option>
                <option value="Įtvirtinimo">Įtvirtinimo</option>
                <option value="Apibendrinamoji">Apibendrinamoji</option>
                <option value="Vertinamoji">Vertinamoji</option>
              </select>
            </div>
            <div className="form-group">
              <label>Tikslas (Mokiniai gebės...)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} placeholder="pvz., atpažinti veiksmažodžio laikus..." />
            </div>
            <div className="form-group">
              <label>Papildomos idėjos</label>
              <textarea value={activities} onChange={e => setActivities(e.target.value)} placeholder="pvz., darbas grupėse, interaktyvus žaidimas..." />
            </div>

            <div className="form-group">
              <label>Vertinimas</label>
              <select value={evaluationType} onChange={e => setEvaluationType(e.target.value)}>
                {EVALUATION_TAGS.map(t => <option key={t} value={t}>{t}</option>)}
              </select>
            </div>

            <div className="form-group checkbox-group" style={{display: 'flex', flexDirection: 'column', gap: '20px', borderTop: '1px solid var(--border-color)', paddingTop: '20px', marginBottom: '20px'}}>
              <div className="checkbox-item">
                <label className="checkbox-label">
                  <input type="checkbox" checked={isIntegratedInput} onChange={e => setIsIntegratedInput(e.target.checked)} />
                  Ar tai integruota pamoka?
                </label>
                {isIntegratedInput && (
                  <div className="nested-input">
                    <input type="text" value={integrationDetails} onChange={e => setIntegrationDetails(e.target.value)} placeholder="Su kokiu dalyku, tema?" />
                  </div>
                )}
              </div>

              <div className="checkbox-item">
                <label className="checkbox-label">
                  <input type="checkbox" checked={isOutsideInput} onChange={e => setIsOutsideInput(e.target.checked)} />
                  Ar tai pamoka už mokyklos ribų?
                </label>
                {isOutsideInput && (
                  <div className="nested-input">
                    <input type="text" value={locationDetails} onChange={e => setLocationDetails(e.target.value)} placeholder="Kur vyks pamoka?" />
                  </div>
                )}
              </div>
            </div>

            <button type="submit" disabled={isLoading} className="generate-button">
              {isLoading ? <div className="spinner"></div> : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {savedPlans.filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase())).map(p => (
                <li key={p.id} onClick={() => handleLoadPlan(p.id)} className={`${activePlanId === p.id ? 'active' : ''} ${editingPlanId === p.id ? 'editing' : ''}`}>
                  {editingPlanId === p.id ? (
                    <div className="edit-plan-form" onClick={e => e.stopPropagation()}>
                      <input type="text" value={editTitle} onChange={e => setEditTitle(e.target.value)} className="edit-input" />
                      <div className="edit-actions">
                        <button onClick={savePlanEdits} className="save-edit-button">Išsaugoti</button>
                        <button onClick={cancelEditing} className="cancel-edit-button">Atšaukti</button>
                      </div>
                    </div>
                  ) : (
                    <>
                      <div className="plan-info">
                        <span className="plan-title">{p.title}</span>
                      </div>
                      <div className="plan-actions">
                        <button onClick={e => startEditing(e, p)} className="edit-button-icon">✏️</button>
                        <button onClick={e => { e.stopPropagation(); triggerDelete(p.id); }} className="delete-button">✖</button>
                      </div>
                    </>
                  )}
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && <div className="loading-overlay"><div className="spinner-large"></div><p>Ruošiamas pamokos planas su etapais ir diferenciacija...</p></div>}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !lessonPlan && !error && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Užpildykite formą kairėje. Sukursime loginę pamokos eigą nuo įvado iki apibendrinimo.</p>
            </div>
          )}

          {lessonPlan && (
            <div className="lesson-plan-result">
              <div className="export-container">
                <button onClick={() => setShowSaveConfirm(true)} className="save-button">Išsaugoti planą 💾</button>
              </div>

              <div className="card grounding-card" style={{borderLeftColor: 'var(--info-color)', backgroundColor: 'var(--info-color-light)'}}>
                <h3>📚 Bendrosios programos sąsajos</h3>
                <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.bpConnections}</p>
                {groundingUrls.length > 0 && (
                  <div className="sources-list" style={{marginTop: '15px', borderTop: '1px solid var(--border-color)', paddingTop: '10px'}}>
                    <p style={{fontSize: '0.85rem', fontWeight: 'bold', marginBottom: '5px'}}>Šaltiniai:</p>
                    {groundingUrls.map((u, i) => (
                      <a key={i} href={u.uri} target="_blank" rel="noopener noreferrer" style={{display: 'block', fontSize: '0.8rem', color: 'var(--primary-color)', marginBottom: '3px'}}>
                        🔗 {u.title || u.uri}
                      </a>
                    ))}
                  </div>
                )}
              </div>

              <div className="card lesson-overview-card">
                <h3>📖 Apžvalga ({lessonPlan.lessonType || 'Pamoka'})</h3>
                <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                <p><strong>Tikslas:</strong> {lessonPlan.lessonOverview.goal}</p>
                <p><strong>Gebėjimai:</strong> {lessonPlan.lessonOverview.competencies}</p>
              </div>

              <div className="card lesson-stages-card" style={{borderLeftColor: 'var(--primary-color)'}}>
                <h3>🛤️ Pamokos eiga</h3>
                <div className="stage-item"><strong>🏁 Įvadas:</strong> <p>{lessonPlan.lessonStages.introduction}</p></div>
                <div className="stage-item"><strong>🎓 Teorinė dalis:</strong> <p>{lessonPlan.lessonStages.theory}</p></div>
                <div className="stage-item"><strong>✍️ Praktika:</strong> <p>{lessonPlan.lessonStages.practice}</p></div>
                <div className="stage-item"><strong>🧩 Įtvirtinimas:</strong> <p>{lessonPlan.lessonStages.consolidation}</p></div>
                <div className="stage-item"><strong>🏁 Apibendrinimas:</strong> <p>{lessonPlan.lessonStages.summary}</p></div>
              </div>

              <div className="card lesson-activities-card" style={{borderLeftColor: 'var(--warning-color)'}}>
                <h3>🎨 Diferencijavimas</h3>
                <p><strong>🙂 Bendra:</strong> {lessonPlan.differentiation.general}</p>
                <p><strong>🚀 Gabesniems:</strong> {lessonPlan.differentiation.gifted}</p>
                <p><strong>🌱 Pagalba:</strong> {lessonPlan.differentiation.struggling}</p>
              </div>

              <div className="card ediary-card">
                {[
                  { label: "Tema, darbas, pasiekimai", val: lessonPlan.eDiaryEntry.topicClassworkExpectations, id: 'diary-topic' },
                  { label: "Namų darbai", val: lessonPlan.eDiaryEntry.homework, id: 'diary-hw' },
                ].map(f => (
                  <div key={f.id} className="diary-entry" style={{marginBottom: '15px'}}>
                    <label style={{display: 'block', fontWeight: 'bold', fontSize: '0.85rem', marginBottom: '4px'}}>{f.label}:</label>
                    <div className="diary-field">
                      <span style={{fontSize: '0.95rem', whiteSpace: 'pre-wrap', lineHeight: '1.5'}}>{f.val || '---'}</span>
                      <button onClick={() => handleCopy(f.val, f.id)} className={`copy-button ${copiedField === f.id ? 'copied' : ''}`}>
                        {copiedField === f.id ? "Nukopijuota" : "Kopijuoti"}
                      </button>
                    </div>
                  </div>
                ))}
              </div>

              <div className="card motivation-card">
                <h3>💖 Ačiū TAU, Mokytojau!</h3>
                <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.motivation}</p>
              </div>
            </div>
          )}
        </div>
      </main>

      {showOnboarding && (
        <div className="modal-overlay" onClick={() => setShowOnboarding(false)}>
          <div className="modal-content onboarding-modal" onClick={e => e.stopPropagation()}>
            <button className="modal-close-button" onClick={() => setShowOnboarding(false)}>&times;</button>
            <div className="onboarding-header">
              <h2>Kaip naudotis programėle? 🚀</h2>
            </div>
            <div className="onboarding-steps">
              <div className="onboarding-step"><div className="step-number">1</div><div className="step-text"><strong>Užpildykite formą:</strong> Įveskite duomenis.</div></div>
              <div className="onboarding-step"><div className="step-number">2</div><div className="step-text"><strong>Struktūruotas planas:</strong> DI suformuos etapus nuo įvado iki apibendrinimo.</div></div>
              <div className="onboarding-step"><div className="step-number">3</div><div className="step-text"><strong>Diferenciacija:</strong> Gausite patarimus skirtingų gebėjimų mokiniams.</div></div>
            </div>
            <div className="modal-actions"><button onClick={() => setShowOnboarding(false)} className="button-primary">Supratau</button></div>
          </div>
        </div>
      )}

      {showSaveConfirm && (
        <div className="modal-overlay" onClick={() => setShowSaveConfirm(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2>Patvirtinti išsaugojimą</h2>
            <p style={{marginBottom: '1.5rem', color: 'var(--text-color-light)'}}>
              Ar tikrai norite išsaugoti šį pamokos planą?
            </p>
            <div className="modal-actions" style={{display: 'flex', gap: '1rem', justifyContent: 'flex-end'}}>
              <button onClick={() => setShowSaveConfirm(false)} className="cancel-edit-button" style={{padding: '0.6rem 1.2rem'}}>Atšaukti</button>
              <button onClick={executeSavePlan} className="save-edit-button" style={{padding: '0.6rem 1.2rem', backgroundColor: 'var(--success-color)'}}>Išsaugoti</button>
            </div>
          </div>
        </div>
      )}

      {deletingPlanId && (
        <div className="modal-overlay" onClick={() => setDeletingPlanId(null)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2>Patvirtinti trinimą</h2>
            <p>Ar tikrai norite ištrinti šį planą?</p>
            <div className="modal-actions" style={{display: 'flex', gap: '1rem', justifyContent: 'flex-end', marginTop: '1rem'}}>
              <button onClick={() => setDeletingPlanId(null)} className="cancel-edit-button">Atšaukti</button>
              <button onClick={handleConfirmDelete} className="save-edit-button" style={{backgroundColor: 'var(--error-color)'}}>Ištrinti</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

:root {
  /* Dark Theme Colors */
  --primary-color: #3b82f6;
  --primary-color-dark: #2563eb;
  --primary-color-light: #1e293b;
  --primary-color-focus: rgba(59, 130, 246, 0.3);
  --secondary-color: #10b981;
  --secondary-color-dark: #059669;
  --background-color: #0f172a;
  --surface-color: #1e293b;
  --text-color: #94a3b8;
  --text-color-light: #cbd5e1;
  --heading-color: #f8fafc;
  --border-color: #334155;
  --shadow-color: rgba(0, 0, 0, 0.4);
  --error-color: #ef4444;
  --error-color-dark: #b91c1c;
  --error-color-light: #450a0a;
  --success-color: #10b981;
  --success-color-dark: #047857;
  --success-color-light: #064e3b;
  --warning-color: #f59e0b;
  --warning-color-light: #451a03;
  --info-color: #8b5cf6;
  --info-color-dark: #6d28d9;
  --info-color-light: #2e1065;
  --disabled-color: #475569;
  --white: #ffffff;
  --black: #000000;

  /* Typography */
  --font-family: 'Inter', sans-serif;
  --font-size-base: 1rem;
  --font-size-sm: 0.85rem;
  --font-size-lg: 1.1rem;
  --font-weight-normal: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;
  --line-height-base: 1.6;

  /* Sizing & Spacing */
  --spacing-xs: 0.25rem;
  --spacing-sm: 0.5rem;
  --spacing-md: 0.75rem;
  --spacing-lg: 1rem;
  --spacing-xl: 1.5rem;
  --spacing-xxl: 2rem;

  /* Borders & Shadows */
  --border-radius-sm: 6px;
  --border-radius-md: 8px;
  --border-radius-lg: 12px;
  --box-shadow-md: 0 4px 12px var(--shadow-color);
  --box-shadow-lg: 0 6px 15px rgba(59, 130, 246, 0.2);

  /* Transitions */
  --transition-speed: 0.3s;
  --transition-timing: ease;

  /* Z-Index */
  --z-index-tooltip: 10;
  --z-index-modal: 1000;
}


* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--background-color);
  color: var(--text-color);
  line-height: var(--line-height-base);
}

.container {
  max-width: 1400px;
  margin: 0 auto;
  padding: var(--spacing-lg);
}

.header {
  text-align: center;
  margin-bottom: var(--spacing-xxl);
  padding: var(--spacing-xl);
  background-color: var(--surface-color);
  border-radius: var(--border-radius-lg);
  box-shadow: var(--box-shadow-md);
  border: 1px solid var(--border-color);
}

.header h1 {
  color: var(--heading-color);
  font-size: 2.5rem;
  font-weight: var(--font-weight-bold);
}

.header p {
  font-size: var(--font-size-lg);
  color: var(--text-color);
}

.header-buttons {
  display: flex;
  justify-content: center;
  gap: var(--spacing-lg);
  margin-top: var(--spacing-lg);
  flex-wrap: wrap;
}

.external-link-button {
  display: inline-block;
  padding: 0.6rem 1.2rem;
  border: 2px solid var(--primary-color);
  border-radius: var(--border-radius-md);
  color: var(--primary-color);
  text-decoration: none;
  font-weight: var(--font-weight-semibold);
  transition: all var(--transition-speed) var(--transition-timing);
  background-color: transparent;
  font-family: var(--font-family);
  font-size: var(--font-size-base);
  cursor: pointer;
}

.external-link-button:hover {
  background-color: var(--primary-color);
  color: var(--white);
}

.main-content {
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: var(--spacing-xxl);
}


/* --- Form Container --- */
.form-container {
  background-color: var(--surface-color);
  padding: var(--spacing-xxl);
  border-radius: var(--border-radius-lg);
  box-shadow: var(--box-shadow-md);
  height: fit-content;
  border: 1px solid var(--border-color);
}

.form-container h2 {
  color: var(--heading-color);
  margin-bottom: var(--spacing-xl);
  text-align: center;
}

.form-group {
  margin-bottom: 1.25rem;
}

.form-group label {
  display: block;
  font-weight: var(--font-weight-semibold);
  color: var(--heading-color);
  margin-bottom: 5px;
}

.form-group input,
.form-group textarea,
.form-group select {
  width: 100%;
  padding: var(--spacing-md);
  border: 1px solid var(--border-color);
  border-radius: var(--border-radius-md);
  font-family: var(--font-family);
  font-size: var(--font-size-base);
  transition: border-color var(--transition-speed), box-shadow var(--transition-speed);
  background-color: #0f172a;
  color: var(--heading-color);
}

.form-group input::placeholder,
.form-group textarea::placeholder {
  color: #475569;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
  outline: none;
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px var(--primary-color-focus);
}

.form-group textarea {
  min-height: 80px;
  resize: vertical;
}

/* --- Checkbox Styling --- */
.checkbox-item {
  display: flex;
  flex-direction: column;
}

.checkbox-label {
  display: flex !important;
  align-items: center;
  gap: 12px;
  cursor: pointer;
  font-weight: var(--font-weight-bold) !important;
  color: var(--heading-color);
  user-select: none;
}

.checkbox-label input[type="checkbox"] {
  width: 20px;
  height: 20px;
  cursor: pointer;
}

.nested-input {
  margin-left: 32px;
  margin-top: 10px;
  padding: 12px;
  background-color: #1a2333;
  border-radius: 6px;
  border: 1px solid var(--border-color);
}

.nested-input label {
  font-size: 0.85rem;
  margin-bottom: 6px;
  color: var(--text-color);
}

.nested-input input {
  padding: 8px;
  font-size: 0.9rem;
  background-color: #0f172a;
}

/* --- Saved Plans List --- */
.saved-plans-container {
  margin-top: 2rem;
  border-top: 2px solid var(--border-color);
  padding-top: 1.5rem;
}

.saved-plans-container h3 {
  margin-bottom: 1rem;
  color: var(--heading-color);
}

.search-input {
  width: 100%;
  padding: 0.6rem;
  border-radius: var(--border-radius-md);
  border: 1px solid var(--border-color);
  margin-bottom: 1rem;
  background-color: #0f172a;
  color: var(--heading-color);
}

.saved-plans-list {
  list-style: none;
  max-height: 400px;
  overflow-y: auto;
}

.saved-plans-list li {
  padding: 0.8rem;
  border-bottom: 1px solid var(--border-color);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: background-color 0.2s;
  border-radius: var(--border-radius-sm);
  margin-bottom: 4px;
}

.saved-plans-list li:hover {
  background-color: #334155;
}

.saved-plans-list li.active {
  background-color: var(--primary-color-light);
  border-left: 3px solid var(--primary-color);
}

.saved-plans-list li.editing {
  background-color: var(--surface-color);
  cursor: default;
  box-shadow: 0 0 0 2px var(--primary-color);
}

.plan-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
  flex: 1;
}

.plan-title {
  font-weight: var(--font-weight-medium);
  color: var(--heading-color);
}

.plan-meta {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.meta-tag {
  font-size: 0.75rem;
  background-color: #334155;
  padding: 2px 6px;
  border-radius: 4px;
  color: var(--text-color-light);
}

.plan-actions {
  display: flex;
  gap: 8px;
  align-items: center;
}

.edit-button-icon {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 1.1rem;
  padding: 4px;
  border-radius: 4px;
  transition: background-color 0.2s;
}

.edit-button-icon:hover {
  background-color: #334155;
}

.delete-button {
  color: var(--error-color);
  background: none;
  border: none;
  cursor: pointer;
  font-size: 1.2rem;
  padding: 4px;
  border-radius: 4px;
  transition: background-color 0.2s;
}

.delete-button:hover {
  background-color: var(--error-color-light);
}

/* --- Editing Form in List --- */
.edit-plan-form {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.edit-row {
  display: flex;
  gap: 8px;
}

.edit-input {
  padding: 6px 10px;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  font-size: 0.9rem;
  background-color: #0f172a;
  color: var(--heading-color);
}

.edit-input-small {
  flex: 1;
  padding: 6px 10px;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  font-size: 0.85rem;
  background-color: #0f172a;
  color: var(--heading-color);
}

.edit-actions {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
}

.save-edit-button {
  background-color: var(--success-color-dark);
  color: white;
  border: none;
  padding: 4px 12px;
  border-radius: 4px;
  font-size: 0.85rem;
  cursor: pointer;
}

.cancel-edit-button {
  background-color: #475569;
  color: white;
  border: none;
  padding: 4px 12px;
  border-radius: 4px;
  font-size: 0.85rem;
  cursor: pointer;
}

/* --- Results --- */
.generate-button {
  width: 100%;
  padding: 0.8rem 1rem;
  background: linear-gradient(45deg, var(--primary-color), var(--secondary-color));
  color: var(--white);
  border: none;
  border-radius: var(--border-radius-md);
  font-size: var(--font-size-lg);
  font-weight: var(--font-weight-semibold);
  cursor: pointer;
  transition: transform var(--transition-speed), box-shadow var(--transition-speed);
  display: flex;
  justify-content: center;
  align-items: center;
}

.generate-button:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: var(--box-shadow-lg);
}

.generate-button:disabled {
  background: var(--disabled-color);
  cursor: not-allowed;
}

.results-container {
  background-color: var(--surface-color);
  padding: var(--spacing-xxl);
  border-radius: var(--border-radius-lg);
  box-shadow: var(--box-shadow-md);
  min-height: 70vh;
  border: 1px solid var(--border-color);
}

.welcome-message h2 {
  color: var(--heading-color);
  margin-bottom: 1rem;
}

.card {
  border-left: 5px solid var(--primary-color);
  padding: var(--spacing-xl);
  margin-bottom: var(--spacing-xl);
  border-radius: 0 var(--border-radius-md) var(--border-radius-md) 0;
  background-color: #1e293b;
  border: 1px solid var(--border-color);
  border-left-width: 5px;
}

.card h3 {
  color: var(--heading-color);
  margin-bottom: 1rem;
}

.card p {
  margin-bottom: 0.5rem;
  color: var(--text-color-light);
}

.card strong {
  color: var(--heading-color);
}

.general-notes-card {
  border-left-color: var(--white);
  background-color: #0f172a;
}

.motivation-card {
  border-left-color: var(--success-color);
  background-color: var(--success-color-light);
}

.consultation-card {
  border-left-color: var(--info-color);
  background-color: var(--info-color-light);
}

.ediary-card {
  border-left-color: var(--secondary-color);
  background-color: var(--primary-color-light);
}

.stage-item {
  margin-bottom: 1rem;
  padding-bottom: 0.5rem;
  border-bottom: 1px solid #334155;
}

.stage-item:last-child {
  border-bottom: none;
}

.stage-item strong {
  display: block;
  margin-bottom: 4px;
  color: var(--heading-color);
}

.stage-item p {
  font-size: 0.95rem;
}

.diary-field {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  background-color: #0f172a;
  padding: 12px;
  border-radius: var(--border-radius-sm);
  border: 1px solid var(--border-color);
  margin-bottom: var(--spacing-sm);
}

.diary-field span {
  color: var(--heading-color);
}

.copy-button {
  background-color: var(--primary-color);
  color: var(--white);
  border: none;
  border-radius: 5px;
  padding: 0.4rem 0.8rem;
  font-size: var(--font-size-sm);
  cursor: pointer;
  transition: all var(--transition-speed);
  min-width: 90px;
}

.copy-button:hover:not(.copied) {
  background-color: var(--primary-color-dark);
}

.copy-button.copied {
  background-color: var(--success-color-dark);
}

/* --- Modal Overlay & Onboarding --- */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(0, 0, 0, 0.75);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: var(--z-index-modal);
  backdrop-filter: blur(4px);
}

.modal-content {
  background-color: var(--surface-color);
  padding: var(--spacing-xxl);
  border-radius: var(--border-radius-lg);
  max-width: 600px;
  width: 90%;
  position: relative;
  border: 1px solid var(--border-color);
}

.onboarding-modal {
  max-width: 700px;
}

.onboarding-header {
  text-align: center;
  margin-bottom: 2rem;
}

.onboarding-header h2 {
  font-size: 1.8rem;
  color: var(--heading-color);
  margin-bottom: 0.5rem;
}

.onboarding-steps {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  margin-bottom: 2rem;
}

.onboarding-step {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
}

.step-number {
  background-color: var(--primary-color);
  color: white;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: bold;
  flex-shrink: 0;
}

.step-text {
  color: var(--text-color-light);
  line-height: 1.4;
}

.step-text strong {
  color: var(--heading-color);
  display: block;
  margin-bottom: 2px;
}

.modal-close-button {
  position: absolute;
  top: 1rem;
  right: 1rem;
  background: none;
  border: none;
  color: var(--text-color);
  font-size: 1.5rem;
  cursor: pointer;
}

.button-primary {
  background-color: var(--primary-color);
  color: white;
  border: none;
  padding: 0.8rem 2rem;
  border-radius: var(--border-radius-md);
  font-weight: var(--font-weight-semibold);
  cursor: pointer;
  display: block;
  width: 100%;
  transition: background-color 0.2s;
}

.button-primary:hover {
  background-color: var(--primary-color-dark);
}

/* --- Error Messages --- */
.error-message {
  background-color: var(--error-color-light);
  color: #ff8080;
  padding: 1rem;
  border-radius: var(--border-radius-md);
  border: 1px solid var(--error-color);
  margin-bottom: 1rem;
  font-weight: 500;
}

/* --- Loading Spinner --- */
.loading-overlay {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    height: 100%;
}

.spinner-large {
  width: 50px;
  height: 50px;
  border: 5px solid var(--border-color);
  border-top-color: var(--primary-color);
  border-radius: 50%;
  animation: spin 1s linear infinite;
  margin-bottom: 15px;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

@media (max-width: 992px) {
  .main-content { grid-template-columns: 1fr; }
}

