  },
  "specialAdvice": "Patarimai integracijai/išvykai",
  "consultationAdvice": "Patarimai dėl iššūkių",
  "motivation": "Padėkos žinutė mokytojui"
}
Atsakyk TIK JSON formatu.`;

  const tryParseJSON = (text: string): LessonPlan | null => {
    try {
      return JSON.parse(text);
    } catch (e) {
      const jsonMatch = text.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        try {
          return JSON.parse(jsonMatch[0]);
        } catch (e2) {}
      }
      return null;
    }
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);
    setGroundingUrls([]);

    const prompt = `
      Sukurk IŠSAMŲ pamokos planą (su įvadu, teorija, praktika, įtvirtinimu, apibendrinimu ir diferenciacija) remdamasis Lietuvos BP:
      - Dalykas: ${subject}, Klasė: ${grade}
      - Tema: ${topic}
      - Pamokos tipas: ${lessonType}
      - Tikslas: ${goal}
      - Veiklos idėjos: ${activities}
      - Vertinimo tipas: ${evaluationType}
      - Iššūkiai: ${consultationChallenges}
      - Integracija: ${isIntegratedInput ? integrationDetails : 'Ne'}
      - Išvyka: ${isOutsideInput ? locationDetails : 'Ne'}

      Rask BP sąsajas per Google Search. Užtikrink loginę pamokos eigą.
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { 
          systemInstruction, 
          responseMimeType: "application/json",
          tools: [{ googleSearch: {} }] 
        },
      });

      const parsedPlan = tryParseJSON(response.text || '');

      if (!parsedPlan) {
        throw new Error("AI sugeneravo netinkamą formatą. Bandykite dar kartą.");
      }

      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const urls: {title: string, uri: string}[] = [];
      chunks.forEach((chunk: any) => {
        if (chunk.web) {
          urls.push({ title: chunk.web.title, uri: chunk.web.uri });
        }
      });
      setGroundingUrls(urls);

      const sanitizedPlan: LessonPlan = {
        ...parsedPlan,
        bpConnections: parsedPlan.bpConnections || 'Informacija apie BP sąsajas nerasta.',
        eDiaryEntry: {
          ...parsedPlan.eDiaryEntry,
          isIntegrated: isIntegratedInput,
          isOutside: isOutsideInput,
          eDiaryLessonType: parsedPlan.eDiaryEntry?.eDiaryLessonType || parsedPlan.lessonType || lessonType || ''
        }
      };

      setLessonPlan(sanitizedPlan);
      setActivePlanId(null);
    } catch (e: any) {
      setError(`Klaida generuojant: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    let textToCopy = text;
    if (field === 'diary-topic') {
      textToCopy = textToCopy
        .replace(/^Temą:\s*/gm, '')
        .replace(/^Klasės darbą:\s*/gm, '')
        .replace(/^Numatomus pasiekimus:\s*/gm, '');
    }

    navigator.clipboard.writeText(textToCopy).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const executeSavePlan = () => {
    if (!lessonPlan) return;
    const newPlan: SavedPlan = {
      id: `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${lessonPlan.lessonOverview.topic}`,
      plan: lessonPlan,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: lessonPlan.lessonType || lessonType,
      groundingUrls
    };
    setSavedPlans([newPlan, ...savedPlans]);
    setActivePlanId(newPlan.id);
    setShowSaveConfirm(false);
  };

  const triggerDelete = (id: string) => {
    setDeletingPlanId(id);
  };

  const handleConfirmDelete = () => {
    if (!deletingPlanId) return;
    setSavedPlans(savedPlans.filter(p => p.id !== deletingPlanId));
    if (activePlanId === deletingPlanId) {
      setLessonPlan(null);
      setActivePlanId(null);
      setGroundingUrls([]);
    }
    setDeletingPlanId(null);
  };

  const handleLoadPlan = (id: string) => {
    if (editingPlanId) return;
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setGroundingUrls(p.groundingUrls || []);
      setActivePlanId(p.id);
      setGrade(p.grade || '');
      setSubject(p.subject || '');
    }
  };

  const startEditing = (e: React.MouseEvent, plan: SavedPlan) => {
    e.stopPropagation();
    setEditingPlanId(plan.id);
    setEditTitle(plan.title);
    setEditSubject(plan.subject || '');
    setEditGrade(plan.grade || '');
  };

  const cancelEditing = (e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingPlanId(null);
  };

  const savePlanEdits = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!editingPlanId) return;
    setSavedPlans(prev => prev.map(p => {
      if (p.id === editingPlanId) {
        return { ...p, title: editTitle, subject: editSubject, grade: editGrade };
      }
      return p;
    }));
    setEditingPlanId(null);
  };

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>Jūsų pagalbininkas kūrybiškoms ir efektyvioms pamokoms</p>
        <div className="header-buttons">
          <button onClick={() => setShowOnboarding(true)} className="external-link-button">Kaip naudotis?</button>
          <a href="https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos" target="_blank" rel="noopener noreferrer" className="external-link-button">BP nuoroda</a>
          <a href="https://classroom.google.com/" target="_blank" rel="noopener noreferrer" className="external-link-button">Google Classroom</a>
          <a href="https://miro.com/app/dashboard/" target="_blank" rel="noopener noreferrer" className="external-link-button">Miro</a>
          <a href="https://www.canva.com/ai" target="_blank" rel="noopener noreferrer" className="external-link-button">Canva</a>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Pamokos informacija</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="pvz., Lietuvių kalba ir literatūra" required />
            </div>
            <div className="form-group">
              <label>Klasė / Grupė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodžio laikai" required />
            </div>
            <div className="form-group">
              <label>Pamokos tipas</label>
              <select value={lessonType} onChange={e => setLessonType(e.target.value as LessonCategory)}>
                <option value="">-- Pasirinkite --</option>
                <option value="Įvadinė">Įvadinė</option>
                <option value="Įtvirtinimo">Įtvirtinimo</option>
                <option value="Apibendrinamoji">Apibendrinamoji</option>
                <option value="Vertinamoji">Vertinamoji</option>
              </select>
            </div>
            <div className="form-group">
              <label>Tikslas (Mokiniai gebės...)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} placeholder="pvz., atpažinti veiksmažodžio laikus..." />
            </div>
            <div className="form-group">
              <label>Papildomos idėjos</label>
              <textarea value={activities} onChange={e => setActivities(e.target.value)} placeholder="pvz., darbas grupėse, interaktyvus žaidimas..." />
            </div>

            <div className="form-group">
              <label>Vertinimas</label>
              <select value={evaluationType} onChange={e => setEvaluationType(e.target.value)}>
                {EVALUATION_TAGS.map(t => <option key={t} value={t}>{t}</option>)}
              </select>
            </div>

            <div className="form-group checkbox-group" style={{display: 'flex', flexDirection: 'column', gap: '20px', borderTop: '1px solid var(--border-color)', paddingTop: '20px', marginBottom: '20px'}}>
              <div className="checkbox-item">
                <label className="checkbox-label">
                  <input type="checkbox" checked={isIntegratedInput} onChange={e => setIsIntegratedInput(e.target.checked)} />
                  Ar tai integruota pamoka?
                </label>
                {isIntegratedInput && (
                  <div className="nested-input">
                    <input type="text" value={integrationDetails} onChange={e => setIntegrationDetails(e.target.value)} placeholder="Su kokiu dalyku, tema?" />
                  </div>
                )}
              </div>

              <div className="checkbox-item">
                <label className="checkbox-label">
                  <input type="checkbox" checked={isOutsideInput} onChange={e => setIsOutsideInput(e.target.checked)} />
                  Ar tai pamoka už mokyklos ribų?
                </label>
                {isOutsideInput && (
                  <div className="nested-input">
                    <input type="text" value={locationDetails} onChange={e => setLocationDetails(e.target.value)} placeholder="Kur vyks pamoka?" />
                  </div>
                )}
              </div>
            </div>

            <button type="submit" disabled={isLoading} className="generate-button">
              {isLoading ? <div className="spinner"></div> : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {savedPlans.filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase())).map(p => (
                <li key={p.id} onClick={() => handleLoadPlan(p.id)} className={`${activePlanId === p.id ? 'active' : ''} ${editingPlanId === p.id ? 'editing' : ''}`}>
                  {editingPlanId === p.id ? (
                    <div className="edit-plan-form" onClick={e => e.stopPropagation()}>
                      <input type="text" value={editTitle} onChange={e => setEditTitle(e.target.value)} className="edit-input" />
                      <div className="edit-actions">
                        <button onClick={savePlanEdits} className="save-edit-button">Išsaugoti</button>
                        <button onClick={cancelEditing} className="cancel-edit-button">Atšaukti</button>
                      </div>
                    </div>
                  ) : (
                    <>
                      <div className="plan-info">
                        <span className="plan-title">{p.title}</span>
                      </div>
                      <div className="plan-actions">
                        <button onClick={e => startEditing(e, p)} className="edit-button-icon">✏️</button>
                        <button onClick={e => { e.stopPropagation(); triggerDelete(p.id); }} className="delete-button">✖</button>
                      </div>
                    </>
                  )}
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && <div className="loading-overlay"><div className="spinner-large"></div><p>Ruošiamas pamokos planas su etapais ir diferenciacija...</p></div>}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !lessonPlan && !error && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Užpildykite formą kairėje. Sukursime loginę pamokos eigą nuo įvado iki apibendrinimo.</p>
            </div>
          )}

          {lessonPlan && (
            <div className="lesson-plan-result">
              <div className="export-container">
                <button onClick={() => setShowSaveConfirm(true)} className="save-button">Išsaugoti planą 💾</button>
              </div>

              <div className="card grounding-card" style={{borderLeftColor: 'var(--info-color)', backgroundColor: 'var(--info-color-light)'}}>
                <h3>📚 Bendrosios programos sąsajos</h3>
                <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.bpConnections}</p>
                {groundingUrls.length > 0 && (
                  <div className="sources-list" style={{marginTop: '15px', borderTop: '1px solid var(--border-color)', paddingTop: '10px'}}>
                    <p style={{fontSize: '0.85rem', fontWeight: 'bold', marginBottom: '5px'}}>Šaltiniai:</p>
                    {groundingUrls.map((u, i) => (
                      <a key={i} href={u.uri} target="_blank" rel="noopener noreferrer" style={{display: 'block', fontSize: '0.8rem', color: 'var(--primary-color)', marginBottom: '3px'}}>
                        🔗 {u.title || u.uri}
                      </a>
                    ))}
                  </div>
                )}
              </div>

              <div className="card lesson-overview-card">
                <h3>📖 Apžvalga ({lessonPlan.lessonType || 'Pamoka'})</h3>
                <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                <p><strong>Tikslas:</strong> {lessonPlan.lessonOverview.goal}</p>
                <p><strong>Gebėjimai:</strong> {lessonPlan.lessonOverview.competencies}</p>
              </div>

              <div className="card lesson-stages-card" style={{borderLeftColor: 'var(--primary-color)'}}>
                <h3>🛤️ Pamokos eiga</h3>
                <div className="stage-item"><strong>🏁 Įvadas:</strong> <p>{lessonPlan.lessonStages.introduction}</p></div>
                <div className="stage-item"><strong>🎓 Teorinė dalis:</strong> <p>{lessonPlan.lessonStages.theory}</p></div>
                <div className="stage-item"><strong>✍️ Praktika:</strong> <p>{lessonPlan.lessonStages.practice}</p></div>
                <div className="stage-item"><strong>🧩 Įtvirtinimas:</strong> <p>{lessonPlan.lessonStages.consolidation}</p></div>
                <div className="stage-item"><strong>🏁 Apibendrinimas:</strong> <p>{lessonPlan.lessonStages.summary}</p></div>
              </div>

              <div className="card lesson-activities-card" style={{borderLeftColor: 'var(--warning-color)'}}>
                <h3>🎨 Diferencijavimas</h3>
                <p><strong>🙂 Bendra:</strong> {lessonPlan.differentiation.general}</p>
                <p><strong>🚀 Gabesniems:</strong> {lessonPlan.differentiation.gifted}</p>
                <p><strong>🌱 Pagalba:</strong> {lessonPlan.differentiation.struggling}</p>
              </div>

              <div className="card ediary-card">
                {[
                  { label: "Tema, darbas, pasiekimai", val: lessonPlan.eDiaryEntry.topicClassworkExpectations, id: 'diary-topic' },
                  { label: "Namų darbai", val: lessonPlan.eDiaryEntry.homework, id: 'diary-hw' },
                ].map(f => (
                  <div key={f.id} className="diary-entry" style={{marginBottom: '15px'}}>
                    <label style={{display: 'block', fontWeight: 'bold', fontSize: '0.85rem', marginBottom: '4px'}}>{f.label}:</label>
                    <div className="diary-field">
                      <span style={{fontSize: '0.95rem', whiteSpace: 'pre-wrap', lineHeight: '1.5'}}>{f.val || '---'}</span>
                      <button onClick={() => handleCopy(f.val, f.id)} className={`copy-button ${copiedField === f.id ? 'copied' : ''}`}>
                        {copiedField === f.id ? "Nukopijuota" : "Kopijuoti"}
                      </button>
                    </div>
                  </div>
                ))}
              </div>

              <div className="card motivation-card">
                <h3>💖 Ačiū TAU, Mokytojau!</h3>
                <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.motivation}</p>
              </div>
            </div>
          )}
        </div>
      </main>

      {showOnboarding && (
        <div className="modal-overlay" onClick={() => setShowOnboarding(false)}>
          <div className="modal-content onboarding-modal" onClick={e => e.stopPropagation()}>
            <button className="modal-close-button" onClick={() => setShowOnboarding(false)}>&times;</button>
            <div className="onboarding-header">
              <h2>Kaip naudotis programėle? 🚀</h2>
            </div>
            <div className="onboarding-steps">
              <div className="onboarding-step"><div className="step-number">1</div><div className="step-text"><strong>Užpildykite formą:</strong> Įveskite duomenis.</div></div>
              <div className="onboarding-step"><div className="step-number">2</div><div className="step-text"><strong>Struktūruotas planas:</strong> DI suformuos etapus nuo įvado iki apibendrinimo.</div></div>
              <div className="onboarding-step"><div className="step-number">3</div><div className="step-text"><strong>Diferenciacija:</strong> Gausite patarimus skirtingų gebėjimų mokiniams.</div></div>
            </div>
            <div className="modal-actions"><button onClick={() => setShowOnboarding(false)} className="button-primary">Supratau</button></div>
          </div>
        </div>
      )}

      {showSaveConfirm && (
        <div className="modal-overlay" onClick={() => setShowSaveConfirm(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2>Patvirtinti išsaugojimą</h2>
            <p style={{marginBottom: '1.5rem', color: 'var(--text-color-light)'}}>
              Ar tikrai norite išsaugoti šį pamokos planą?
            </p>
            <div className="modal-actions" style={{display: 'flex', gap: '1rem', justifyContent: 'flex-end'}}>
              <button onClick={() => setShowSaveConfirm(false)} className="cancel-edit-button" style={{padding: '0.6rem 1.2rem'}}>Atšaukti</button>
              <button onClick={executeSavePlan} className="save-edit-button" style={{padding: '0.6rem 1.2rem', backgroundColor: 'var(--success-color)'}}>Išsaugoti</button>
            </div>
          </div>
        </div>
      )}

      {deletingPlanId && (
        <div className="modal-overlay" onClick={() => setDeletingPlanId(null)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2>Patvirtinti trinimą</h2>
            <p>Ar tikrai norite ištrinti šį planą?</p>
            <div className="modal-actions" style={{display: 'flex', gap: '1rem', justifyContent: 'flex-end', marginTop: '1rem'}}>
              <button onClick={() => setDeletingPlanId(null)} className="cancel-edit-button">Atšaukti</button>
              <button onClick={handleConfirmDelete} className="save-edit-button" style={{backgroundColor: 'var(--error-color)'}}>Ištrinti</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
  eDiaryLessonType: string;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  bpConnections: string;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: string;
  };
  lessonStages: {
    introduction: string;       // Įvadas
    theory: string;             // Teorinis paaiškinimas
    practice: string;           // Praktika
    consolidation: string;      // Įtvirtinimas
    summary: string;            // Apibendrinimas
  };
  differentiation: {
    gifted: string;             // Gabesniems
    general: string;            // Bendra
    struggling: string;         // Pagalba
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  consultationAdvice?: string;
  specialAdvice?: string; 
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
  groundingUrls?: {title: string, uri: string}[];
}

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [consultationChallenges, setConsultationChallenges] = useState('');

  const [isIntegratedInput, setIsIntegratedInput] = useState(false);
  const [integrationDetails, setIntegrationDetails] = useState('');
  const [isOutsideInput, setIsOutsideInput] = useState(false);
  const [locationDetails, setLocationDetails] = useState('');

  const [evaluationType, setEvaluationType] = useState(EVALUATION_TAGS[0]);

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [groundingUrls, setGroundingUrls] = useState<{title: string, uri: string}[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [showOnboarding, setShowOnboarding] = useState(false);
  const [showSaveConfirm, setShowSaveConfirm] = useState(false);

  // Redagavimo būsena sugeneruotam planui
  const [isEditingGeneratedPlan, setIsEditingGeneratedPlan] = useState(false);
  const [editedPlan, setEditedPlan] = useState<LessonPlan | null>(null);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const [editingPlanId, setEditingPlanId] = useState<string | null>(null);
  const [editTitle, setEditTitle] = useState('');
  const [editSubject, setEditSubject] = useState('');
  const [editGrade, setEditGrade] = useState('');

  const [deletingPlanId, setDeletingPlanId] = useState<string | null>(null);

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas, puikiai išmanantis Lietuvos Bendrąsias ugdymo programas (BP). 
Tavo užduotis - sukurti labai išsamų, struktūruotą pamokos planą JSON formatu lietuvių kalba.

SVARBU: Naudok Google Search tool, kad surastum aktualius BP reikalavimus nurodytam dalykui, klasei ir temai.

PAMOKOS EIGOS STRUKTŪRA:
Privalai užpildyti 'lessonStages' objektą:
- 'introduction': Įvadas, sudominimas, tikslų paskelbimas.
- 'theory': Naujos medžiagos aiškinimas, teorinė dalis.
- 'practice': Praktinis darbas, užduočių atlikimas.
- 'consolidation': Žinių įtvirtinimas, grįžtamasis ryšys.
- 'summary': Apibendrinimas, refleksija.

DIFERENCIJAVIMAS:
Užpildyk 'differentiation' objektą su konkrečiomis strategijomis skirtingų gebėjimų mokiniams.

SVARBIOS TAISYKLĖS EL. DIENYNUI:
Lauke 'topicClassworkExpectations' informaciją PRIVALAI pateikti tiksliai tokia struktūra (naudok naujas eilutes \\n):
Temą: [tekstas susijęs su BP temomis]
Klasės darbą: [tekstas su siūlomu darbu]
Numatomus pasiekimus: [tekstas su galimu vertinimu]

Struktūra:
{
  "generalNotes": "Ryškios pasirengimo instrukcijos",
  "lessonType": "Tipas",
  "bpConnections": "Sąsajos su Bendrosiomis ugdymo programomis",
  "lessonOverview": { "topic": "", "goal": "", "competencies": "", "evaluation": "" },
  "lessonStages": {
    "introduction": "...",
    "theory": "...",
    "practice": "...",
    "consolidation": "...",
    "summary": "..."
  },
  "differentiation": {
    "gifted": "...",
    "general": "...",
    "struggling": "..."
  },
  "homework": { "purpose": "...", "gifted": "...", "general": "...", "struggling": "..." },
  "eDiaryEntry": {
    "topicClassworkExpectations": "Temą: ...\\nKlasės darbą: ...\\nNumatomus pasiekimus: ...",
    "homework": "...",
    "individualHomework": "...",
    "notes": "...",
    "isIntegrated": false,
    "isOutside": false,
    "eDiaryLessonType": "..."
  },
  "specialAdvice": "Patarimai integracijai/išvykai",
  "consultationAdvice": "Patarimai dėl iššūkių",
  "motivation": "Padėkos žinutė mokytojui"
}
Atsakyk TIK JSON formatu.`;

  const tryParseJSON = (text: string): LessonPlan | null => {
    try {
      return JSON.parse(text);
    } catch (e) {
      const jsonMatch = text.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        try {
          return JSON.parse(jsonMatch[0]);
        } catch (e2) {}
      }
      return null;
    }
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);
    setGroundingUrls([]);
    setIsEditingGeneratedPlan(false);

    const prompt = `
      Sukurk IŠSAMŲ pamokos planą (su įvadu, teorija, praktiką, įtvirtinimu, apibendrinimu ir diferenciacija) remdamasis Lietuvos BP:
      - Dalykas: ${subject}, Klasė: ${grade}
      - Tema: ${topic}
      - Pamokos tipas: ${lessonType}
      - Tikslas: ${goal}
      - Veiklos idėjos: ${activities}
      - Vertinimo tipas: ${evaluationType}
      - Iššūkiai: ${consultationChallenges}
      - Integracija: ${isIntegratedInput ? integrationDetails : 'Ne'}
      - Išvyka: ${isOutsideInput ? locationDetails : 'Ne'}

      Rask BP sąsajas per Google Search. Užtikrink loginę pamokos eigą.
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { 
          systemInstruction, 
          responseMimeType: "application/json",
          tools: [{ googleSearch: {} }] 
        },
      });

      const parsedPlan = tryParseJSON(response.text || '');

      if (!parsedPlan) {
        throw new Error("AI sugeneravo netinkamą formatą. Bandykite dar kartą.");
      }

      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const urls: {title: string, uri: string}[] = [];
      chunks.forEach((chunk: any) => {
        if (chunk.web) {
          urls.push({ title: chunk.web.title, uri: chunk.web.uri });
        }
      });
      setGroundingUrls(urls);

      const sanitizedPlan: LessonPlan = {
        ...parsedPlan,
        bpConnections: parsedPlan.bpConnections || 'Informacija apie BP sąsajas nerasta.',
        eDiaryEntry: {
          ...parsedPlan.eDiaryEntry,
          isIntegrated: isIntegratedInput,
          isOutside: isOutsideInput,
          eDiaryLessonType: parsedPlan.eDiaryEntry?.eDiaryLessonType || parsedPlan.lessonType || lessonType || ''
        }
      };

      setLessonPlan(sanitizedPlan);
      setEditedPlan(sanitizedPlan);
      setActivePlanId(null);
    } catch (e: any) {
      setError(`Klaida generuojant: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    let textToCopy = text;
    if (field === 'diary-topic') {
      textToCopy = textToCopy
        .replace(/^Temą:\s*/gm, '')
        .replace(/^Klasės darbą:\s*/gm, '')
        .replace(/^Numatomus pasiekimus:\s*/gm, '');
    }

    navigator.clipboard.writeText(textToCopy).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const executeSavePlan = () => {
    const planToSave = editedPlan || lessonPlan;
    if (!planToSave) return;

    const newPlan: SavedPlan = {
      id: `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${planToSave.lessonOverview.topic}`,
      plan: planToSave,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: planToSave.lessonType || lessonType,
      groundingUrls
    };
    setSavedPlans([newPlan, ...savedPlans]);
    setActivePlanId(newPlan.id);
    setShowSaveConfirm(false);
    setLessonPlan(planToSave);
    setIsEditingGeneratedPlan(false);
  };

  const handleUpdateGeneratedPlan = () => {
    if (!editedPlan) return;

    // Jei planas jau išsaugotas, atnaujiname jį sąraše
    if (activePlanId) {
      setSavedPlans(prev => prev.map(p => {
        if (p.id === activePlanId) {
          return { ...p, plan: editedPlan };
        }
        return p;
      }));
    }

    setLessonPlan(editedPlan);
    setIsEditingGeneratedPlan(false);
  };

  const triggerDelete = (id: string) => {
    setDeletingPlanId(id);
  };

  const handleConfirmDelete = () => {
    if (!deletingPlanId) return;
    setSavedPlans(savedPlans.filter(p => p.id !== deletingPlanId));
    if (activePlanId === deletingPlanId) {
      setLessonPlan(null);
      setEditedPlan(null);
      setActivePlanId(null);
      setGroundingUrls([]);
    }
    setDeletingPlanId(null);
  };

  const handleLoadPlan = (id: string) => {
    if (editingPlanId) return;
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setEditedPlan(p.plan);
      setGroundingUrls(p.groundingUrls || []);
      setActivePlanId(p.id);
      setGrade(p.grade || '');
      setSubject(p.subject || '');
      setIsEditingGeneratedPlan(false);
    }
  };

  const startEditing = (e: React.MouseEvent, plan: SavedPlan) => {
    e.stopPropagation();
    setEditingPlanId(plan.id);
    setEditTitle(plan.title);
    setEditSubject(plan.subject || '');
    setEditGrade(plan.grade || '');
  };

  const cancelEditing = (e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingPlanId(null);
  };

  const savePlanEdits = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!editingPlanId) return;
    setSavedPlans(prev => prev.map(p => {
      if (p.id === editingPlanId) {
        return { ...p, title: editTitle, subject: editSubject, grade: editGrade };
      }
      return p;
    }));
    setEditingPlanId(null);
  };

  // Helperis laukų atnaujinimui giliame objekte
  const updateEditedField = (path: string, value: any) => {
    if (!editedPlan) return;
    const newPlan = { ...editedPlan };
    const parts = path.split('.');
    let current: any = newPlan;
    for (let i = 0; i < parts.length - 1; i++) {
      current = current[parts[i]];
    }
    current[parts[parts.length - 1]] = value;
    setEditedPlan(newPlan);
  };

  const currentPlan = isEditingGeneratedPlan ? editedPlan : lessonPlan;

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>Jūsų pagalbininkas kūrybiškoms ir efektyvioms pamokoms</p>
        <div className="header-buttons">
          <button onClick={() => setShowOnboarding(true)} className="external-link-button">Kaip naudotis?</button>
          <a href="https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos" target="_blank" rel="noopener noreferrer" className="external-link-button">BP nuoroda</a>
          <a href="https://classroom.google.com/" target="_blank" rel="noopener noreferrer" className="external-link-button">Google Classroom</a>
          <a href="https://miro.com/app/dashboard/" target="_blank" rel="noopener noreferrer" className="external-link-button">Miro</a>
          <a href="https://www.canva.com/ai" target="_blank" rel="noopener noreferrer" className="external-link-button">Canva</a>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Pamokos informacija</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="pvz., Lietuvių kalba ir literatūra" required />
            </div>
            <div className="form-group">
              <label>Klasė / Grupė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodžio laikai" required />
            </div>
            <div className="form-group">
              <label>Pamokos tipas</label>
              <select value={lessonType} onChange={e => setLessonType(e.target.value as LessonCategory)}>
                <option value="">-- Pasirinkite --</option>
                <option value="Įvadinė">Įvadinė</option>
                <option value="Įtvirtinimo">Įtvirtinimo</option>
                <option value="Apibendrinamoji">Apibendrinamoji</option>
                <option value="Vertinamoji">Vertinamoji</option>
              </select>
            </div>
            <div className="form-group">
              <label>Tikslas (Mokiniai gebės...)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} placeholder="pvz., atpažinti veiksmažodžio laikus..." />
            </div>
            <div className="form-group">
              <label>Papildomos idėjos</label>
              <textarea value={activities} onChange={e => setActivities(e.target.value)} placeholder="pvz., darbas grupėse, interaktyvus žaidimas..." />
            </div>

            <div className="form-group">
              <label>Vertinimas</label>
              <select value={evaluationType} onChange={e => setEvaluationType(e.target.value)}>
                {EVALUATION_TAGS.map(t => <option key={t} value={t}>{t}</option>)}
              </select>
            </div>

            <div className="form-group checkbox-group" style={{display: 'flex', flexDirection: 'column', gap: '20px', borderTop: '1px solid var(--border-color)', paddingTop: '20px', marginBottom: '20px'}}>
              <div className="checkbox-item">
                <label className="checkbox-label">
                  <input type="checkbox" checked={isIntegratedInput} onChange={e => setIsIntegratedInput(e.target.checked)} />
                  Ar tai integruota pamoka?
                </label>
                {isIntegratedInput && (
                  <div className="nested-input">
                    <input type="text" value={integrationDetails} onChange={e => setIntegrationDetails(e.target.value)} placeholder="Su kokiu dalyku, tema?" />
                  </div>
                )}
              </div>

              <div className="checkbox-item">
                <label className="checkbox-label">
                  <input type="checkbox" checked={isOutsideInput} onChange={e => setIsOutsideInput(e.target.checked)} />
                  Ar tai pamoka už mokyklos ribų?
                </label>
                {isOutsideInput && (
                  <div className="nested-input">
                    <input type="text" value={locationDetails} onChange={e => setLocationDetails(e.target.value)} placeholder="Kur vyks pamoka?" />
                  </div>
                )}
              </div>
            </div>

            <button type="submit" disabled={isLoading} className="generate-button">
              {isLoading ? <div className="spinner"></div> : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {savedPlans.filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase())).map(p => (
                <li key={p.id} onClick={() => handleLoadPlan(p.id)} className={`${activePlanId === p.id ? 'active' : ''} ${editingPlanId === p.id ? 'editing' : ''}`}>
                  {editingPlanId === p.id ? (
                    <div className="edit-plan-form" onClick={e => e.stopPropagation()}>
                      <input type="text" value={editTitle} onChange={e => setEditTitle(e.target.value)} className="edit-input" />
                      <div className="edit-actions">
                        <button onClick={savePlanEdits} className="save-edit-button">Išsaugoti</button>
                        <button onClick={cancelEditing} className="cancel-edit-button">Atšaukti</button>
                      </div>
                    </div>
                  ) : (
                    <>
                      <div className="plan-info">
                        <span className="plan-title">{p.title}</span>
                      </div>
                      <div className="plan-actions">
                        <button onClick={e => startEditing(e, p)} className="edit-button-icon">✏️</button>
                        <button onClick={e => { e.stopPropagation(); triggerDelete(p.id); }} className="delete-button">✖</button>
                      </div>
                    </>
                  )}
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && <div className="loading-overlay"><div className="spinner-large"></div><p>Ruošiamas pamokos planas su etapais ir diferenciacija...</p></div>}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !currentPlan && !error && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Užpildykite formą kairėje. Sukursime loginę pamokos eigą nuo įvado iki apibendrinimo.</p>
            </div>
          )}

          {currentPlan && (
            <div className="lesson-plan-result">
              <div className="export-container" style={{display: 'flex', gap: '10px', marginBottom: '20px'}}>
                {!isEditingGeneratedPlan ? (
                  <>
                    <button onClick={() => setShowSaveConfirm(true)} className="save-button">Išsaugoti planą 💾</button>
                    <button onClick={() => setIsEditingGeneratedPlan(true)} className="external-link-button" style={{borderColor: 'var(--warning-color)', color: 'var(--warning-color)'}}>Redaguoti turinį ✏️</button>
                  </>
                ) : (
                  <>
                    <button onClick={handleUpdateGeneratedPlan} className="save-button" style={{backgroundColor: var(--success-color-dark)}}>Baigti redagavimą ✅</button>
                    <button onClick={() => { setIsEditingGeneratedPlan(false); setEditedPlan(lessonPlan); }} className="cancel-edit-button" style={{padding: '0.8rem 1.2rem'}}>Atšaukti pakeitimus ❌</button>
                  </>
                )}
              </div>

              <div className="card grounding-card" style={{borderLeftColor: 'var(--info-color)', backgroundColor: 'var(--info-color-light)'}}>
                <h3>📚 Bendrosios programos sąsajos</h3>
                {isEditingGeneratedPlan ? (
                  <textarea 
                    className="edit-textarea" 
                    value={editedPlan?.bpConnections} 
                    onChange={e => updateEditedField('bpConnections', e.target.value)}
                    style={{width: '100%', minHeight: '100px', background: '#0f172a', color: 'white', padding: '10px', borderRadius: '4px'}}
                  />
                ) : (
                  <p style={{whiteSpace: 'pre-wrap'}}>{currentPlan.bpConnections}</p>
                )}
                {groundingUrls.length > 0 && !isEditingGeneratedPlan && (
                  <div className="sources-list" style={{marginTop: '15px', borderTop: '1px solid var(--border-color)', paddingTop: '10px'}}>
                    <p style={{fontSize: '0.85rem', fontWeight: 'bold', marginBottom: '5px'}}>Šaltiniai:</p>
                    {groundingUrls.map((u, i) => (
                      <a key={i} href={u.uri} target="_blank" rel="noopener noreferrer" style={{display: 'block', fontSize: '0.8rem', color: 'var(--primary-color)', marginBottom: '3px'}}>
                        🔗 {u.title || u.uri}
                      </a>
                    ))}
                  </div>
                )}
              </div>

              <div className="card lesson-overview-card">
                <h3>📖 Apžvalga ({currentPlan.lessonType || 'Pamoka'})</h3>
                <div style={{display: 'flex', flexDirection: 'column', gap: '10px'}}>
                  <div>
                    <strong>Tema:</strong> 
                    {isEditingGeneratedPlan ? (
                      <input className="edit-input" value={editedPlan?.lessonOverview.topic} onChange={e => updateEditedField('lessonOverview.topic', e.target.value)} style={{width: '100%', marginTop: '5px'}} />
                    ) : (
                      <span> {currentPlan.lessonOverview.topic}</span>
                    )}
                  </div>
                  <div>
                    <strong>Tikslas:</strong> 
                    {isEditingGeneratedPlan ? (
                      <textarea className="edit-textarea" value={editedPlan?.lessonOverview.goal} onChange={e => updateEditedField('lessonOverview.goal', e.target.value)} style={{width: '100%', marginTop: '5px', minHeight: '60px'}} />
                    ) : (
                      <span> {currentPlan.lessonOverview.goal}</span>
                    )}
                  </div>
                  <div>
                    <strong>Gebėjimai:</strong> 
                    {isEditingGeneratedPlan ? (
                      <textarea className="edit-textarea" value={editedPlan?.lessonOverview.competencies} onChange={e => updateEditedField('lessonOverview.competencies', e.target.value)} style={{width: '100%', marginTop: '5px', minHeight: '60px'}} />
                    ) : (
                      <span> {currentPlan.lessonOverview.competencies}</span>
                    )}
                  </div>
                </div>
              </div>

              <div className="card lesson-stages-card" style={{borderLeftColor: 'var(--primary-color)'}}>
                <h3>🛤️ Pamokos eiga</h3>
                {[
                  { id: 'introduction', label: '🏁 Įvadas' },
                  { id: 'theory', label: '🎓 Teorinė dalis' },
                  { id: 'practice', label: '✍️ Praktika' },
                  { id: 'consolidation', label: '🧩 Įtvirtinimas' },
                  { id: 'summary', label: '🏁 Apibendrinimas' }
                ].map(stage => (
                  <div key={stage.id} className="stage-item">
                    <strong>{stage.label}:</strong>
                    {isEditingGeneratedPlan ? (
                      <textarea 
                        className="edit-textarea" 
                        value={(editedPlan?.lessonStages as any)?.[stage.id]} 
                        onChange={e => updateEditedField(`lessonStages.${stage.id}`, e.target.value)} 
                        style={{width: '100%', marginTop: '5px', minHeight: '80px'}} 
                      />
                    ) : (
                      <p>{(currentPlan.lessonStages as any)?.[stage.id]}</p>
                    )}
                  </div>
                ))}
              </div>

              <div className="card lesson-activities-card" style={{borderLeftColor: 'var(--warning-color)'}}>
                <h3>🎨 Diferencijavimas</h3>
                {[
                  { id: 'general', label: '🙂 Bendra' },
                  { id: 'gifted', label: '🚀 Gabesniems' },
                  { id: 'struggling', label: '🌱 Pagalba' }
                ].map(diff => (
                  <div key={diff.id} style={{marginBottom: '10px'}}>
                    <strong>{diff.label}:</strong>
                    {isEditingGeneratedPlan ? (
                      <textarea 
                        className="edit-textarea" 
                        value={(editedPlan?.differentiation as any)?.[diff.id]} 
                        onChange={e => updateEditedField(`differentiation.${diff.id}`, e.target.value)} 
                        style={{width: '100%', marginTop: '5px', minHeight: '60px'}} 
                      />
                    ) : (
                      <p>{(currentPlan.differentiation as any)?.[diff.id]}</p>
                    )}
                  </div>
                ))}
              </div>

              <div className="card ediary-card">
                <h3>✍️ El. dienyno įrašai</h3>
                {[
                  { label: "Tema, darbas, pasiekimai", path: "eDiaryEntry.topicClassworkExpectations", id: 'diary-topic' },
                  { label: "Namų darbai", path: "eDiaryEntry.homework", id: 'diary-hw' },
                ].map(f => (
                  <div key={f.id} className="diary-entry" style={{marginBottom: '15px'}}>
                    <label style={{display: 'block', fontWeight: 'bold', fontSize: '0.85rem', marginBottom: '4px'}}>{f.label}:</label>
                    {isEditingGeneratedPlan ? (
                      <textarea 
                        className="edit-textarea" 
                        value={f.path.split('.').reduce((o, i) => (o as any)[i], editedPlan) as string} 
                        onChange={e => updateEditedField(f.path, e.target.value)} 
                        style={{width: '100%', minHeight: '80px', background: '#0f172a', color: 'white', padding: '10px', borderRadius: '4px'}} 
                      />
                    ) : (
                      <div className="diary-field">
                        <span style={{fontSize: '0.95rem', whiteSpace: 'pre-wrap', lineHeight: '1.5'}}>
                          { (f.path.split('.').reduce((o, i) => (o as any)[i], currentPlan) as string) || '---'}
                        </span>
                        <button onClick={() => handleCopy(f.path.split('.').reduce((o, i) => (o as any)[i], currentPlan) as string, f.id)} className={`copy-button ${copiedField === f.id ? 'copied' : ''}`}>
                          {copiedField === f.id ? "Nukopijuota" : "Kopijuoti"}
                        </button>
                      </div>
                    )}
                  </div>
                ))}
              </div>

              <div className="card motivation-card">
                <h3>💖 Ačiū TAU, Mokytojau!</h3>
                {isEditingGeneratedPlan ? (
                  <textarea 
                    className="edit-textarea" 
                    value={editedPlan?.motivation} 
                    onChange={e => updateEditedField('motivation', e.target.value)} 
                    style={{width: '100%', minHeight: '80px', background: 'transparent', color: 'inherit', border: '1px solid rgba(255,255,255,0.2)'}} 
                  />
                ) : (
                  <p style={{whiteSpace: 'pre-wrap'}}>{currentPlan.motivation}</p>
                )}
              </div>
            </div>
          )}
        </div>
      </main>

      {showOnboarding && (
        <div className="modal-overlay" onClick={() => setShowOnboarding(false)}>
          <div className="modal-content onboarding-modal" onClick={e => e.stopPropagation()}>
            <button className="modal-close-button" onClick={() => setShowOnboarding(false)}>&times;</button>
            <div className="onboarding-header">
              <h2>Kaip naudotis programėle? 🚀</h2>
            </div>
            <div className="onboarding-steps">
              <div className="onboarding-step"><div className="step-number">1</div><div className="step-text"><strong>Užpildykite formą:</strong> Įveskite duomenis.</div></div>
              <div className="onboarding-step"><div className="step-number">2</div><div className="step-text"><strong>Struktūruotas planas:</strong> DI suformuos etapus nuo įvado iki apibendrinimo.</div></div>
              <div className="onboarding-step"><div className="step-number">3</div><div className="step-text"><strong>Diferenciacija:</strong> Gausite patarimus skirtingų gebėjimų mokiniams.</div></div>
              <div className="onboarding-step"><div className="step-number">4</div><div className="step-text"><strong>Redagavimas:</strong> Paspaudę „Redaguoti turinį“, galite pataisyti bet kurią plano dalį.</div></div>
            </div>
            <div className="modal-actions"><button onClick={() => setShowOnboarding(false)} className="button-primary">Supratau</button></div>
          </div>
        </div>
      )}

      {showSaveConfirm && (
        <div className="modal-overlay" onClick={() => setShowSaveConfirm(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2>Patvirtinti išsaugojimą</h2>
            <p style={{marginBottom: '1.5rem', color: 'var(--text-color-light)'}}>
              Ar tikrai norite išsaugoti šį pamokos planą?
            </p>
            <div className="modal-actions" style={{display: 'flex', gap: '1rem', justifyContent: 'flex-end'}}>
              <button onClick={() => setShowSaveConfirm(false)} className="cancel-edit-button" style={{padding: '0.6rem 1.2rem'}}>Atšaukti</button>
              <button onClick={executeSavePlan} className="save-edit-button" style={{padding: '0.6rem 1.2rem', backgroundColor: 'var(--success-color)'}}>Išsaugoti</button>
            </div>
          </div>
        </div>
      )}

      {deletingPlanId && (
        <div className="modal-overlay" onClick={() => setDeletingPlanId(null)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2>Patvirtinti trinimą</h2>
            <p>Ar tikrai norite ištrinti šį planą?</p>
            <div className="modal-actions" style={{display: 'flex', gap: '1rem', justifyContent: 'flex-end', marginTop: '1rem'}}>
              <button onClick={() => setDeletingPlanId(null)} className="cancel-edit-button">Atšaukti</button>
              <button onClick={handleConfirmDelete} className="save-edit-button" style={{backgroundColor: 'var(--error-color)'}}>Ištrinti</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

